-- Part 4: Hindi Translations (Swami Ramsukhdas & Swami Tejomayananda: 1,402 Records)
INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('9f3cc0ca-be6e-5e21-a259-2cb6930da155'::uuid, '8908c144-8a4f-5da6-b251-50dff0115c0d'::uuid, 'ramsukhdas', 'hindi', '।।1.1।। धृतराष्ट्र बोले - हे संजय! धर्मभूमि कुरुक्षेत्र में युद्ध की इच्छा से इकट्ठे हुए मेरेे और पाण्डु के पुत्रों ने भी क्या किया?'),
('e2758858-5fc3-506d-b189-da7d463300c3'::uuid, '8908c144-8a4f-5da6-b251-50dff0115c0d'::uuid, 'tejomayananda', 'hindi', '

।।1.1।।धृतराष्ट्र ने कहा -- हे संजय ! धर्मभूमि कुरुक्षेत्र में एकत्र हुए युद्ध के इच्छुक (युयुत्सव:) मेरे और पाण्डु के पुत्रों ने क्या किया?




 '),
('40f9dc0f-19d1-55af-ba99-d7e8748d9ada'::uuid, '39650053-34a7-522a-9ced-97f638529efc'::uuid, 'ramsukhdas', 'hindi', '।।1.2।। संजय बोले - उस समय वज्रव्यूह-से खड़ी हुई पाण्डव-सेना को देखकर राजा दुर्योधन द्रोणाचार्य के पास जाकर यह वचन बोला।'),
('a7c7302b-09c2-5757-b731-4b384e0a1c65'::uuid, '39650053-34a7-522a-9ced-97f638529efc'::uuid, 'tejomayananda', 'hindi', '।।1.2।।संजय ने कहा -- पाण्डव-सैन्य की व्यूह रचना देखकर राजा दुर्योधन ने आचार्य द्रोण के पास जाकर ये वचन कहे।


 '),
('55cd9e5b-da5f-5c16-8a59-9bb0f4927c9a'::uuid, '48576bc0-f366-5487-9fed-7a05c6319892'::uuid, 'ramsukhdas', 'hindi', '।।1.3।। हे आचार्य! आपके बुद्धिमान् शिष्य द्रुपदपुत्र धृष्टद्युम्न के द्वारा व्यूहरचना से खड़ी की हुई पाण्डवों की इस बड़ी भारी सेना को देखिये'),
('78498707-7481-561d-b48d-6bddb845efd6'::uuid, '48576bc0-f366-5487-9fed-7a05c6319892'::uuid, 'tejomayananda', 'hindi', '।।1.3।।हे आचार्य ! आपके बुद्धिमान शिष्य द्रुपदपुत्र (धृष्टद्द्युम्न) द्वारा व्यूहाकार खड़ी की गयी पाण्डु पुत्रों की इस महती सेना को देखिये।


 '),
('93cb1d46-18da-51da-9790-a531623e658c'::uuid, 'be79d223-ef7f-5266-affb-9d69c3cdb9ed'::uuid, 'ramsukhdas', 'hindi', '।।1.4 -- 1.6।। यहाँ (पाण्डवों की सेना में) बड़े-बड़े शूरवीर हैं, जिनके बहुत बड़े-बड़े धनुष हैं तथा जो युद्ध में भीम और अर्जुनके समान हैं। उनमें युयुधान (सात्यकि), राजा विराट और महारथी द्रुपद भी हैं। धृष्टकेतु और चेकितान तथा पराक्रमी काशिराज भी हैं। पुरुजित् और कुन्तिभोज--ये दोनों भाई तथा मनुष्योंमें श्रेष्ठ शैब्य भी हैं। पराक्रमी युधामन्यु और पराक्रमी उत्तमौजा भी हैं। सुभद्रापुत्र अभिमन्यु और द्रौपदी के पाँचों पुत्र भी हैं। ये सब-के-सब महारथी हैं।'),
('fe6c606a-c025-5a76-97a2-0eef15c648cf'::uuid, 'be79d223-ef7f-5266-affb-9d69c3cdb9ed'::uuid, 'tejomayananda', 'hindi', '।।1.4।।इस सेना में महान् धनुर्धारी शूर योद्धा है ,  जो युद्ध में भीम और अर्जुन के समान हैं , जैसे --  युयुधान, विराट तथा महारथी राजा द्रुपद।


 '),
('af96dcae-1fdf-5880-b28d-0352db2595e4'::uuid, '6c0143e3-a069-591b-b363-d4223275d69f'::uuid, 'ramsukhdas', 'hindi', '।।1.4 -- 1.6।। यहाँ (पाण्डवों की सेना में) बड़े-बड़े शूरवीर हैं, जिनके बहुत बड़े-बड़े धनुष हैं तथा जो युद्ध में भीम और अर्जुनके समान हैं। उनमें युयुधान (सात्यकि), राजा विराट और महारथी द्रुपद भी हैं। धृष्टकेतु और चेकितान तथा पराक्रमी काशिराज भी हैं। पुरुजित् और कुन्तिभोज--ये दोनों भाई तथा मनुष्योंमें श्रेष्ठ शैब्य भी हैं। पराक्रमी युधामन्यु और पराक्रमी उत्तमौजा भी हैं। सुभद्रापुत्र अभिमन्यु और द्रौपदी के पाँचों पुत्र भी हैं। ये सब-के-सब महारथी हैं।'),
('ffa9ef43-3da2-5dde-b05a-da97146b829b'::uuid, '6c0143e3-a069-591b-b363-d4223275d69f'::uuid, 'tejomayananda', 'hindi', '।।1.5।।धृष्टकेतु, चेकितान, बलवान काशिराज,  पुरुजित्, कुन्तिभोज और मनुष्यों में श्रेष्ठ शैब्य।


 '),
('20bd2ed8-3914-5aa4-b3dd-19df19f14801'::uuid, '521460fd-2273-5364-b2e1-c888e6f7fa2f'::uuid, 'ramsukhdas', 'hindi', '।।1.4 -- 1.6।। यहाँ (पाण्डवों की सेना में) बड़े-बड़े शूरवीर हैं, जिनके बहुत बड़े-बड़े धनुष हैं तथा जो युद्ध में भीम और अर्जुनके समान हैं। उनमें युयुधान (सात्यकि), राजा विराट और महारथी द्रुपद भी हैं। धृष्टकेतु और चेकितान तथा पराक्रमी काशिराज भी हैं। पुरुजित् और कुन्तिभोज--ये दोनों भाई तथा मनुष्योंमें श्रेष्ठ शैब्य भी हैं। पराक्रमी युधामन्यु और पराक्रमी उत्तमौजा भी हैं। सुभद्रापुत्र अभिमन्यु और द्रौपदी के पाँचों पुत्र भी हैं। ये सब-के-सब महारथी हैं।'),
('d9d547da-251b-56c7-9939-00d55cb5f38d'::uuid, '521460fd-2273-5364-b2e1-c888e6f7fa2f'::uuid, 'tejomayananda', 'hindi', '।।1.6।।पराक्रमी युधामन्यु,  बलवान् उत्तमौजा,  सुभद्रापुत्र (अभिमन्यु) और द्रोपदी के पुत्र -- ये सब महारथी हैं।


 '),
('3ae8820e-1fd9-5c47-91ce-843459cc9b01'::uuid, 'fa01897d-be77-5757-a521-f758ae4ff33e'::uuid, 'ramsukhdas', 'hindi', '।।1.7।। हे द्विजोत्तम! हमारे पक्ष में भी जो मुख्य हैं, उनपर भी आप ध्यान दीजिये। आपको याद दिलाने के लिये मेरी सेना के जो नायक हैं, उनको मैं कहता हूँ।'),
('2a5f2a6e-40d1-529f-8946-ec99f9e6b40b'::uuid, 'fa01897d-be77-5757-a521-f758ae4ff33e'::uuid, 'tejomayananda', 'hindi', '।।1.7।।हे द्विजोत्तम ! हमारे पक्ष में भी जो विशिष्ट योद्धागण हैं , उनको आप जान लीजिये; आपकी जानकारी के लिये अपनी सेना के नायकों के नाम मैं आपको बताता हूँ।


 '),
('289fee14-c192-5555-af86-206d3198191f'::uuid, 'bed96014-9b78-5203-a88b-31adcd509694'::uuid, 'ramsukhdas', 'hindi', '।।1.8।। आप (द्रोणाचार्य) और पितामह भीष्म तथा कर्ण और संग्रामविजयी कृपाचार्य तथा वैसे ही अश्वत्थामा, विकर्ण और सोमदत्त का पुत्र भूरिश्रवा।'),
('3b93d3c8-c4f2-516a-b2a5-eca71c092b9d'::uuid, 'bed96014-9b78-5203-a88b-31adcd509694'::uuid, 'tejomayananda', 'hindi', '।।1.8।।एक तो स्वयं आप, भीष्म, कर्ण, और युद्ध विजयी कृपाचार्य तथा अश्वत्थामा, विकर्ण और सोमदत्त का पुत्र है।


 '),
('0f5f68b3-d1ea-5b2e-b734-4d908f317fe1'::uuid, '54ae0136-fbd5-55cf-be65-d290f409c47e'::uuid, 'ramsukhdas', 'hindi', '।।1.9।। इनके अतिरिक्त बहुत-से शूरवीर हैं, जिन्होंने मेरे लिये अपने जीने की इच्छा का भी त्याग कर दिया है और जो अनेक प्रकार के शस्त्र-अस्त्रों को चलानेवाले हैं तथा जो सब-के-सब युद्धकला में अत्यन्त चतुर हैं।'),
('1e628531-71dd-57ec-b3e6-d0aca4f867eb'::uuid, '54ae0136-fbd5-55cf-be65-d290f409c47e'::uuid, 'tejomayananda', 'hindi', '।।1.9।।मेरे लिए प्राण त्याग करने के लिए तैयार, अनेक प्रकार के शस्त्रास्त्रों से सुसज्जित तथा युद्ध में कुशल और भी अनेक शूर वीर हैं।




 '),
('0242f6a4-f619-5771-b6b5-b82d54cfdbd4'::uuid, '1addcdad-fc61-53ce-9566-fe7967dc78ac'::uuid, 'ramsukhdas', 'hindi', '।।1.10।। वह हमारी सेना पाण्डवों पर विजय करने में अपर्याप्त है, असमर्थ है; क्योंकि उसके संरक्षक (उभयपक्षपाती) भीष्म हैं। परन्तु इन पाण्डवों की सेना हमारे पर विजय करने में पर्याप्त है, समर्थ है; क्योंकि इसके संरक्षक (निजसेनापक्षपाती) भीमसेन हैं।'),
('4ae1d9c7-28f4-5430-b7f9-810d40014bf5'::uuid, '1addcdad-fc61-53ce-9566-fe7967dc78ac'::uuid, 'tejomayananda', 'hindi', '।।1.10।।भीष्म के द्वारा हमारी रक्षित सेना अपर्याप्त है; किन्तु भीम द्वारा रक्षित उनकी सेना पर्याप्त है अथवा, भीष्म के द्वारा रक्षित हमारी सेना अपरिमित है किन्तु भीम के द्वारा रक्षित उनकी सेना परिमित ही है।


 '),
('e01534a1-0f46-5418-a7ef-df75055dd0d9'::uuid, '9463be70-e124-5030-a110-47b1c54f3638'::uuid, 'ramsukhdas', 'hindi', '।।1.11।। आप सब-के-सब लोग सभी मोर्चों पर अपनी-अपनी जगह दृढ़ता से स्थित रहते हुए ही पितामह भीष्म की चारों ओर से रक्षा करें।'),
('aca77e90-75f1-5210-a775-9bdf30aeb05b'::uuid, '9463be70-e124-5030-a110-47b1c54f3638'::uuid, 'tejomayananda', 'hindi', '।।1.11।।विभिन्न मोर्चों पर अपने-अपने स्थान पर स्थित रहते हुए आप सब लोग भीष्म पितामह की ही सब ओर से रक्षा करें।


 '),
('dae78e29-1ef8-58a9-ac8f-29d4e1c72570'::uuid, 'cb447a08-1645-5d32-80cb-d298aa07d91a'::uuid, 'ramsukhdas', 'hindi', '।।1.12।। दुर्योधन के हृदय में हर्ष उत्पन्न करते हुए कुरुवृद्ध प्रभावशाली पितामह भीष्म ने सिंह के समान गरज कर जोर से शंख बजाया।'),
('088deaf2-3e80-5722-bd42-db4d8027926f'::uuid, 'cb447a08-1645-5d32-80cb-d298aa07d91a'::uuid, 'tejomayananda', 'hindi', '।।1.12।।उस समय कौरवों में वृद्ध, प्रतापी पितामह भीष्म ने उस (दुर्योधन) के हृदय में हर्ष उत्पन्न करते हुये उच्च स्वर में गरज कर शंखध्वनि की।


 '),
('7193d83c-4c73-5f13-a441-66ec14d72bcf'::uuid, '0acbd4d6-a413-517e-8017-5d8d14ed599a'::uuid, 'ramsukhdas', 'hindi', '।।1.13।। उसके बाद शंख, भेरी (नगाड़े), ढोल, मृदङ्ग और नरसिंघे बाजे एक साथ बज उठे। उनका वह शब्द बड़ा भयंकर हुआ।'),
('80d25565-cdf9-5717-a2c7-9c31eb794baa'::uuid, '0acbd4d6-a413-517e-8017-5d8d14ed599a'::uuid, 'tejomayananda', 'hindi', '।।1.13।।तत्पश्चात् शंख, नगारे, ढोल व शृंगी आदि वाद्य एक साथ ही बज उठे, जिनका बड़ा भयंकर शब्द हुआ।


 '),
('e0c7f264-33ec-5600-9811-57059a3fe356'::uuid, '81751ab9-f902-5dee-bad9-6267d9e1c66f'::uuid, 'ramsukhdas', 'hindi', '।।1.14।। उसके बाद सफेद घोड़ों से युक्त महान् रथ पर बैठे हुए लक्ष्मीपति भगवान् श्रीकृष्ण और पाण्डुपुत्र अर्जुन ने दिव्य शंखों को बड़े जोर से बजाया।'),
('69e77c2b-2010-50a2-82ad-bd95e4714a27'::uuid, '81751ab9-f902-5dee-bad9-6267d9e1c66f'::uuid, 'tejomayananda', 'hindi', '।।1.14।।इसके उपरान्त श्वेत अश्वों से युक्त भव्य रथ में बैठे हुये माधव (श्रीकृष्ण) और पाण्डुपुत्र अर्जुन ने भी अपने दिव्य शंख बजाये।


 '),
('ed4f2b22-6e39-5c3b-a3da-ef86a4451bde'::uuid, 'a20e47f4-e0c2-582d-841c-b9addbae304b'::uuid, 'ramsukhdas', 'hindi', '।।1.15।। अन्तर्यामी भगवान् श्रीकृष्ण ने पाञ्चजन्य नामक तथा धनञ्जय अर्जुन ने देवदत्त नामक शंख बजाया; और भयानक कर्म करनेवाले वृकोदर भीम ने पौण्ड्र नामक महाशंख बजाया।'),
('f9bbed34-454c-5954-9f63-33301b7ce5a6'::uuid, 'a20e47f4-e0c2-582d-841c-b9addbae304b'::uuid, 'tejomayananda', 'hindi', '।।1.15।।भगवान् हृषीकेश ने पांचजन्य, धनंजय (अर्जुन) ने देवदत्त तथा भयंकर कर्म करने वाले भीम ने पौण्डू नामक महाशंख बजाया।


 '),
('1e7225a6-210a-562a-a8cb-0746aa0ff5eb'::uuid, 'f85c985e-f0da-5880-8f00-998c8b738624'::uuid, 'ramsukhdas', 'hindi', '।।1.16।। कुन्तीपुत्र राजा युधिष्ठिर ने अनन्तविजय नामक शंख बजाया तथा नकुल और सहदेव ने सुघोष और मणिपुष्पक नामक शंख बजाये।'),
('71592728-c27c-5bba-a4ed-1c784f1a38e3'::uuid, 'f85c985e-f0da-5880-8f00-998c8b738624'::uuid, 'tejomayananda', 'hindi', '।।1.16।।कुन्तीपुत्र राजा युधिष्ठिर ने अनन्त विजय नामक शंख और नकुल व सहदेव ने क्रमश:  सुघोष और मणिपुष्पक नामक शंख बजाये।


 '),
('73665622-d726-5519-8f08-8611031ef63c'::uuid, 'f9244a40-9286-5b1b-b4b2-f2ab518f9ddc'::uuid, 'ramsukhdas', 'hindi', '।।1.17 -- 1.18।। हे राजन्! श्रेष्ठ धनुषवाले काशिराज और महारथी शिखण्डी तथा धृष्टद्युम्न एवं राजा विराट और अजेय सात्यकि, राजा द्रुपद और द्रौपदी के पाँचों पुत्र तथा लम्बी-लम्बी भुजाओंवाले सुभद्रा-पुत्र अभिमन्यु - इन सभी ने सब ओर से अलग-अलग (अपने-अपने) शंख बजाये।'),
