 '),
('e506914f-a19f-5e30-aecb-0ca84a1d2892'::uuid, 'e4a9e229-f38b-5f05-90f3-08a9771f13cf'::uuid, 'ramsukhdas', 'hindi', '।।1.31।। हे केशव! मैं लक्षणों  - (शकुनों) को भी विपरीत देख रहा हूँ और युद्ध में स्वजनोंको मारकर श्रेय (लाभ) भी नहीं देख रहा हूँ।'),
('4e9a377c-f70f-53ec-8d3d-0f7f2da178bd'::uuid, 'e4a9e229-f38b-5f05-90f3-08a9771f13cf'::uuid, 'tejomayananda', 'hindi', '।।1.31।।हे केशव ! मैं शकुनों को भी विपरीत ही देख रहा हूँ और युद्ध में (आहवे) अपने स्वजनों को मारकर कोई कल्याण भी नहीं देखता हूँ।


 '),
('73123be6-496b-5900-9593-eb0bcac1318e'::uuid, '08511b51-a3d1-531a-a59c-78284db5da1c'::uuid, 'ramsukhdas', 'hindi', '।।1.32।। हे कृष्ण! मैं न तो विजय चाहता हूँ, न राज्य चाहता हूँ और न सुखों को ही चाहता हूँ। हे गोविन्द! हमलोगों को राज्य से क्या लाभ? भोगों से क्या लाभ? अथवा जीने से भी क्या लाभ?'),
('93b79b4c-6bb1-565c-955a-d15efd0b50ce'::uuid, '08511b51-a3d1-531a-a59c-78284db5da1c'::uuid, 'tejomayananda', 'hindi', '।।1.32।।हे कृष्ण ! मैं न विजय चाहता हूँ, न राज्य और न सुखों को ही चाहता हूँ। हे गोविन्द ! हमें राज्य से अथवा भोगों से और जीने से भी क्या प्रयोजन है?।


 '),
('3f31a014-bd00-59a4-be5b-c7e146897d84'::uuid, '15ccce4b-d3fd-5030-a9f9-7453f30bb2c7'::uuid, 'ramsukhdas', 'hindi', '।।1.33।। जिनके लिये हमारी राज्य, भोग और सुखकी इच्छा है, वे ही ये सब अपने प्राणों की और धन की आशा का त्याग करके युद्ध में खड़े हैं।'),
('3cba9a3f-4fe8-5d95-a5aa-ae7ab89f65b1'::uuid, '15ccce4b-d3fd-5030-a9f9-7453f30bb2c7'::uuid, 'tejomayananda', 'hindi', '।।1.33।।हमें जिनके लिये राज्य,  भोग और सुखादि की इच्छा है,  वे ही लोग धन और जीवन की आशा को त्यागकर युद्ध में खड़े हैं।


 '),
('585bfbd0-526b-5135-88ee-567e980c17ee'::uuid, '05dc2578-7055-5593-aaae-281f754b7ead'::uuid, 'ramsukhdas', 'hindi', '।।1.34 -- 1.35।। आचार्य, पिता, पुत्र और उसी प्रकार पितामह, मामा, ससुर, पौत्र, साले तथा अन्य जितने भी सम्बन्धी हैं, मुझ पर प्रहार करने पर भी मैं इनको मारना नहीं चाहता, और हे मधुसूदन! मुझे त्रिलोकी का राज्य मिलता हो, तो भी मैं इनको मारना नहीं चाहता, फिर पृथ्वी के लिये तो (मैं इनको मारूँ ही) क्या?'),
('c7aa2a0c-e86c-50b1-acdb-3c978108e025'::uuid, '05dc2578-7055-5593-aaae-281f754b7ead'::uuid, 'tejomayananda', 'hindi', '।।1.34।।वे लोग गुरुजन,  ताऊ,  चाचा,  पुत्र,  पितामह,   श्वसुर,  पोते,  श्यालक तथा अन्य सम्बन्धी हैं।


 '),
('a6023ffa-0915-5837-9200-606a93e8085c'::uuid, '95f96233-748b-54e1-85c9-da49c51dc0ad'::uuid, 'ramsukhdas', 'hindi', '।।1.34 -- 1.35।। आचार्य, पिता, पुत्र और उसी प्रकार पितामह, मामा, ससुर, पौत्र, साले तथा अन्य जितने भी सम्बन्धी हैं, मुझपर प्रहार करने पर भी मैं इनको मारना नहीं चाहता, और हे मधुसूदन! मुझे त्रिलोकी का राज्य मिलता हो, तो भी मैं इनको मारना नहीं चाहता, फिर पृथ्वीके लिये तो (मैं इनको मारूँ ही) क्या?'),
('f324173e-3c49-58de-a21b-21e40f6a230c'::uuid, '95f96233-748b-54e1-85c9-da49c51dc0ad'::uuid, 'tejomayananda', 'hindi', '।।1.35।।हे मधुसूदन !  इनके मुझे मारने पर अथवा त्रैलोक्य के राज्य के लिये भी मैं इनको मारना नहीं चाहता,  फिर पृथ्वी के लिए कहना ही क्या है।


 '),
('4e0009cd-af43-5b0d-8afa-7d4d3ddb0bab'::uuid, '19bcf343-fe9f-5d8b-9345-ac87f32830b7'::uuid, 'ramsukhdas', 'hindi', '।।1.36।। हे जनार्दन! इन धृतराष्ट्र-सम्बन्धियों को मारकर हमलोगों को क्या प्रसन्नता होगी? इन आततायियों को मारने से तो हमें पाप ही लगेगा।'),
('9bd4471b-4f31-5a83-a3ae-d5a8857fcc77'::uuid, '19bcf343-fe9f-5d8b-9345-ac87f32830b7'::uuid, 'tejomayananda', 'hindi', '।।1.36।।हे जनार्दन ! धृतराष्ट्र के पुत्रों की हत्या करके हमें क्या प्रसन्नता होगी?  इन आततायियों को मारकर तो हमें केवल पाप ही लगेगा।


 '),
('0ad3e44c-df2d-572b-8997-9dea55f14f0f'::uuid, '034ac013-6f5d-58d7-bc33-0f726dd77f58'::uuid, 'ramsukhdas', 'hindi', '।।1.37।। इसलिये अपने बान्धव इन धृतराष्ट्र-सम्बन्धियों को मारने के लिये हम योग्य नहीं हैं; क्योंकि हे माधव! अपने कुटुम्बियों को मारकर हम कैसे सुखी होंगे?'),
('8cbc20e9-ed58-58d2-b661-74a14791654d'::uuid, '034ac013-6f5d-58d7-bc33-0f726dd77f58'::uuid, 'tejomayananda', 'hindi', '।।1.37।।हे माधव  !  इसलिये अपने बान्धव धृतराष्ट्र के पुत्रों को मारना हमारे लिए योग्य नहीं है,  क्योंकि स्वजनों को मारकर हम कैसे सुखी होंगे।


 '),
('86f0a824-c0ee-59bc-9642-1215931fa471'::uuid, '767aba6c-fd8e-5d01-929a-c6b29b44164e'::uuid, 'ramsukhdas', 'hindi', '।।1.38 -- 1.39।। यद्यपि लोभ के कारण जिनका विवेक-विचार लुप्त हो गया है, ऐसे ये (दुर्योधन आदि) कुल का नाश करने से होनेवाले दोष को और मित्रों के साथ द्वेष करने से होनेवाले पाप को नहीं देखते, (तो भी) हे जनार्दन! कुल का नाश करने से होनेवाले दोष को ठीक-ठीक जाननेवाले हमलोग इस पाप से निवृत्त होने का विचार क्यों न करें?'),
('1649e24c-20f2-5edd-a406-e686161f40a4'::uuid, '767aba6c-fd8e-5d01-929a-c6b29b44164e'::uuid, 'tejomayananda', 'hindi', '।।1.38।।यद्यपि लोभ से भ्रष्टचित्त हुये ये लोग कुलनाशकृत दोष और मित्र द्रोह में पाप नहीं देखते हैं।


 '),
('09c8eff7-f7b9-5cca-a777-e937b10465f6'::uuid, '70e1c57c-7e35-5802-a24b-29af36a87d2c'::uuid, 'ramsukhdas', 'hindi', '।।1.38 -- 1.39।। यद्यपि लोभ के कारण जिनका विवेक-विचार लुप्त हो गया है, ऐसे ये (दुर्योधन आदि) कुल का नाश करने से होनेवाले दोष को और मित्रों के साथ द्वेष करने से होनेवाले पाप को नहीं देखते, (तो भी) हे जनार्दन! कुल का नाश करने से होनेवाले दोष को ठीक-ठीक जाननेवाले हमलोग इस पाप से निवृत्त होनेका विचार क्यों न करें?'),
('6c876f55-1692-568c-85f6-ecc7921bc0f4'::uuid, '70e1c57c-7e35-5802-a24b-29af36a87d2c'::uuid, 'tejomayananda', 'hindi', '।।1.39।।परन्तु,  हेे जनार्दन !  कुलक्षय से होने वाले दोष को जानने वाले हम लोगों को इस पाप से विरत होने के लिए क्यों नहीं सोचना चाहिये।


 '),
('452dba2b-54f6-5440-91da-261a4b8cd94b'::uuid, '37083537-b98a-53eb-ae1d-6417c2b978ae'::uuid, 'ramsukhdas', 'hindi', '।।1.40।। कुल का क्षय होने पर सदा से चलते आये कुलधर्म नष्ट हो जाते हैं और धर्म का नाश होनेपर (बचे हुए) सम्पूर्ण कुल को अधर्म दबा लेता है।'),
('6fc3b6d8-a0cb-5f7d-bb27-8680531e09c5'::uuid, '37083537-b98a-53eb-ae1d-6417c2b978ae'::uuid, 'tejomayananda', 'hindi', '।।1.40।।कुल के नष्ट होने से सनातन धर्म नष्ट हो जाते हैं। धर्म नष्ट होने पर सम्पूर्ण कुल को अधर्म (पाप) दबा लेता है।


 '),
('f9206b26-66f5-5f1a-990c-a213ab90a1aa'::uuid, '4d3b7f28-2042-59e2-bef8-7308ace03d9a'::uuid, 'ramsukhdas', 'hindi', '।।1.41।। हे कृष्ण! अधर्म के अधिक बढ़ जाने से कुल की स्त्रियाँ दूषित हो जाती हैं; (और) हे वार्ष्णेय! स्त्रियों के दूषित होने पर वर्णसंकर पैदा हो जाते हैं।'),
('ee771c7e-14fa-552c-b72d-4dfb989df093'::uuid, '4d3b7f28-2042-59e2-bef8-7308ace03d9a'::uuid, 'tejomayananda', 'hindi', '।।1.41।।हे कृष्ण ! पाप के अधिक बढ़ जाने से कुल की स्त्रियां दूषित हो जाती हैं,  और हे वार्ष्णेय ! स्त्रियों के दूषित होने पर वर्णसंकर उत्पन्न होता है।


 '),
('b1dd5e32-9473-5127-af5b-28de41de3f45'::uuid, 'c35b1179-bfe6-595d-aa16-96b82d818384'::uuid, 'ramsukhdas', 'hindi', '।।1.42।। वर्णसंकर कुलघातियों को और कुल को नरक में ले जानेवाला ही होता है। श्राद्ध और तर्पण न मिलने से इन- (कुलघातियों-) के पितर भी अपने स्थान से गिर जाते हैं।'),
('966ec4c7-b10d-5df5-b55f-c0b6e4974a53'::uuid, 'c35b1179-bfe6-595d-aa16-96b82d818384'::uuid, 'tejomayananda', 'hindi', '।।1.42।।वह वर्णसंकर कुलघातियों को और कुल को नरक में ले जाने का कारण बनता है। पिण्ड और जलदान की क्रिया से वंचित इनके पितर भी नरक में गिर जाते हैं।


 '),
('29422ceb-58ea-5421-9b1f-c2857df0ff16'::uuid, 'c9e2cec8-f68f-555d-83d3-e00463413f80'::uuid, 'ramsukhdas', 'hindi', '।।1.43।। इन वर्णसंकर पैदा करनेवाले दोषोंसे कुलघातियों के सदा से चलते आये कुलधर्म और जातिधर्म नष्ट हो जाते हैं।'),
('710f96cf-ce9e-59b4-802b-cbe9bbd72936'::uuid, 'c9e2cec8-f68f-555d-83d3-e00463413f80'::uuid, 'tejomayananda', 'hindi', '।।1.43।।इन वर्णसंकर कारक दोषों से कुलघाती दोषों से सनातन कुलधर्म और जातिधर्म नष्ट हो जाते हैं।


 '),
('e37129c6-0a44-539e-9ced-bf570e9d9cdc'::uuid, '4bb871c1-9cdb-55e2-aeb3-2e231713ab6a'::uuid, 'ramsukhdas', 'hindi', '।।1.44।। हे जनार्दन! जिनके कुलधर्म नष्ट हो जाते हैं, उन मनुष्यों का बहुत काल तक नरकों में वापस होता है, ऐसा हम सुनते आये हैं।'),
('31604166-4492-578d-93c9-2ad80ac02a63'::uuid, '4bb871c1-9cdb-55e2-aeb3-2e231713ab6a'::uuid, 'tejomayananda', 'hindi', '।।1.44।।हे जनार्दन !  हमने सुना है कि जिनके यहां कुल धर्म नष्ट हो जाता है,  उन मनुष्यों का अनियत काल तक नरक में वास होता है।


 '),
('30f2338c-4e6e-5983-b89c-fd97c4b35215'::uuid, '31d28f6e-b44c-5a53-a501-104f7d5e516c'::uuid, 'ramsukhdas', 'hindi', '।।1.45।। यह बड़े आश्चर्य और खेद की बात है कि हमलोग बड़ा भारी पाप करने का निश्चय कर बैठे हैं, जो कि राज्य और सुख के लोभ से अपने स्वजनों को मारने के लिये तैयार हो गये हैं!'),
('ee93e98b-1506-5c0c-b0bc-bddfa6ddde3e'::uuid, '31d28f6e-b44c-5a53-a501-104f7d5e516c'::uuid, 'tejomayananda', 'hindi', '।।1.45।।अहो  !  शोक है कि हम लोग बड़ा भारी पाप करने का निश्चय कर बैठे हैं,  जो कि इस राज्यसुख के लोभ से अपने कुटुम्ब का नाश करने के लिये तैयार हो गये हैं।


 '),
('a47a4784-2efe-517e-b2c8-7720a16b1d28'::uuid, '40d929a8-d7d2-537f-aad9-6bb98c26abdf'::uuid, 'ramsukhdas', 'hindi', '।।1.46।। अगर ये हाथों में शस्त्र-अस्त्र लिये हुए धृतराष्ट्र के पक्षपाती लोग युद्धभूमि में सामना न करनेवाले तथा शस्त्ररहित मुझ को मार भी दें, तो वह मेरे लिये बड़ा ही हितकारक होगा।'),
('80609d4a-d17b-523f-8682-f2bc3582e60d'::uuid, '40d929a8-d7d2-537f-aad9-6bb98c26abdf'::uuid, 'tejomayananda', 'hindi', '।।1.46।।यदि मुझ शस्त्ररहित और प्रतिकार न करने वाले को ये शस्त्रधारी कौरव रण में मारें,  तो भी वह मेरे लिये कल्याणकारक होगा।


 '),
('6936f672-3e37-5bc3-8a3c-c3ef60597f34'::uuid, '70e2c09e-3b24-51ed-bb9a-0b42fb7f0717'::uuid, 'ramsukhdas', 'hindi', '।।1.47।। संजय बोले - ऐसा कहकर शोकाकुल मनवाले अर्जुन बाणसहित धनुष का त्याग करके युद्धभूमि में रथके मध्यभाग में बैठ गये।'),
('b5eae62c-74ae-5e28-a0c8-c9bf0f1e0d60'::uuid, '70e2c09e-3b24-51ed-bb9a-0b42fb7f0717'::uuid, 'tejomayananda', 'hindi', '।।1.47।।संजय ने कहा  --  रणभूमि (संख्ये) में शोक से उद्विग्न मनवाला अर्जुन इस प्रकार कहकर बाणसहित धनुष को त्याग कर रथ के पिछले भाग में बैठ गया।

 '),
('b520ecde-df4a-5745-a222-fa960de2fe05'::uuid, 'a61fd754-fbef-590c-9db2-3ffda51d5c95'::uuid, 'ramsukhdas', 'hindi', '।।2.1।। संजय बोले - वैसी कायरता से आविष्ट उन अर्जुन के प्रति, जो कि विषाद कर रहे हैं और आँसुओं के कारण जिनके नेत्रों की देखने की शक्ति अवरुद्ध हो रही है, भगवान् मधुसूदन ये (आगे कहे जानेवाले) वचन बोले।'),
('7e78e70c-207c-5b6a-8274-a9b6d4d5f6d0'::uuid, 'a61fd754-fbef-590c-9db2-3ffda51d5c95'::uuid, 'tejomayananda', 'hindi', '।।2.1।। संजय ने कहा -- इस प्रकार करुणा और विषाद से अभिभूत,  अश्रुपूरित नेत्रों वाले आकुल अर्जुन से मधुसूदन ने यह वाक्य कहा।।
 '),
('7cbd6825-8fb0-5d97-bcaf-d849170d17a3'::uuid, 'defcd45d-a454-5b6d-b4e3-b0ede64eb705'::uuid, 'ramsukhdas', 'hindi', '।।2.2।। श्रीभगवान् बोले - हे अर्जुन! इस विषम अवसरपर तुम्हें यह कायरता कहाँसे प्राप्त हुई, जिसका कि श्रेष्ठ पुरुष सेवन नहीं करते, जो स्वर्गको देनेवाली नहीं है और कीर्ति करनेवाली भी नहीं है।'),
('001935f5-1395-58b6-84a1-fc0477e0476c'::uuid, 'defcd45d-a454-5b6d-b4e3-b0ede64eb705'::uuid, 'tejomayananda', 'hindi', '।।2.2।। श्री भगवान् ने कहा -- हे अर्जुन ! तुमको इस विषम स्थल में यह मोह कहाँ से उत्पन्न हुआ?  यह आर्य आचरण के विपरीत न तो स्वर्ग प्राप्ति का साधन ही है और न कीर्ति कराने वाला ही है।।
 '),
('af0d1fca-2893-5e39-83b5-e98ce601a540'::uuid, '92802525-e007-5583-8e5c-aee82ac9beda'::uuid, 'ramsukhdas', 'hindi', '।।2.3।। हे पृथानन्दन अर्जुन ! इस नपुंसकताको मत प्राप्त हो; क्योंकि तुम्हारेमें यह उचित नहीं है। हे परंतप ! हृदयकी इस तुच्छ दुर्बलताका त्याग करके युद्धके लिये खड़े हो जाओ।'),
('d87b68ff-6912-56ed-b83f-9c27347dded0'::uuid, '92802525-e007-5583-8e5c-aee82ac9beda'::uuid, 'tejomayananda', 'hindi', '।।2.3।। हे पार्थ क्लीव (कायर) मत बनो। यह तुम्हारे लिये अशोभनीय है, हे ! परंतप हृदय की क्षुद्र दुर्बलता को त्यागकर खड़े हो जाओ।।
 ')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('8311b59f-3442-50bf-9116-e117d21f28bc'::uuid, 'f0490d06-ce14-5594-9ea7-ef36ca55e8e2'::uuid, 'ramsukhdas', 'hindi', '।।2.4।। अर्जुन बोले - हे मधुसूदन! मैं रणभूमिमें भीष्म और द्रोणके साथ बाणोंसे युद्ध कैसे करूँ? क्योंकि हे अरिसूदन! ये दोनों ही पूजाके योग्य हैं।'),
('1cf5f1ea-f6b2-51cb-bc7b-1dcd875f6cac'::uuid, 'f0490d06-ce14-5594-9ea7-ef36ca55e8e2'::uuid, 'tejomayananda', 'hindi', '।।2.4।। अर्जुन ने कहा -- हे मधुसूदन ! मैं रणभूमि में किस प्रकार भीष्म और द्रोण के साथ बाणों से युद्ध करूँगा। हे अरिसूदन, वे दोनों ही पूजनीय हैं।।
 '),
('24f7cbdb-01c1-5614-9d3b-1e3121f5ccc8'::uuid, 'eef450fc-9f59-5cef-bd4f-43577d81641d'::uuid, 'ramsukhdas', 'hindi', '।।2.5।। महानुभाव गुरुजनोंको न मारकर इस लोकमें मैं भिक्षाका अन्न खाना भी श्रेष्ठ समझता हूँ।  क्योंकि गुरुजनोंको मारकर यहाँ रक्तसे सने हुए तथा धनकी कामनाकी मुख्यतावाले भोगोंको ही तो भोगूँगा!'),
('87abfde6-4e25-56a5-b1ba-4e26dc34bfa8'::uuid, 'eef450fc-9f59-5cef-bd4f-43577d81641d'::uuid, 'tejomayananda', 'hindi', '।।2.5।। इन महानुभाव गुरुजनों को मारने से इस लोक में भिक्षा का अन्न भी ग्रहण करना अधिक कल्याण कारक है, क्योंकि गुरुजनों को मारकर मैं इस लोक में रक्तरंजित अर्थ और काम रूप भोगों को ही भोगूँगा।।
 '),
('7aac299d-d2b6-5f71-9728-f544d971d8e3'::uuid, '916fdaee-856b-5a0a-bf94-5f3859c1c581'::uuid, 'ramsukhdas', 'hindi', '।।2.6।। हम यह भी नहीं जानते कि हमलोगोंके लिये युद्ध करना और न करना - इन दोनोंमेंसे कौन-सा अत्यन्त श्रेष्ठ है; और हमें इसका भी पता नहीं है कि हम उन्हें जीतेंगे अथवा वे हमें जीतेंगे। जिनको मारकर हम जीना भी नहीं चाहते, वे ही धृतराष्ट्रके सम्बन्धी हमारे सामने खड़े हैं।'),
('6695781d-9d4f-509b-b7e8-a961cb4a953b'::uuid, '916fdaee-856b-5a0a-bf94-5f3859c1c581'::uuid, 'tejomayananda', 'hindi', '।।2.6।। हम नहीं जानते कि हमें क्या करना उचित है। हम यह भी नहीं जानते कि हम जीतेंगे, या वे हमको जीतेंगे, जिनको मारकर हम जीवित नहीं रहना चाहते वे ही धृतराष्ट्र के पुत्र हमारे सामने युद्ध के लिए खड़े हैं।।
 '),
('07dee9e0-c0b5-54e7-b920-9c90bad60c0f'::uuid, '81ce4613-6e7c-55b1-a344-8187e2487d59'::uuid, 'ramsukhdas', 'hindi', '।।2.7।। कायरतारूप दोषसे तिरस्कृत स्वभाववाला और धर्मके विषयमें मोहित अन्तःकरणवाला मैं आपसे पूछता हूँ कि जो निश्चित कल्याण करनेवाली हो, वह मेरे लिये कहिये। मैं आपका शिष्य हूँ। आपके शरण हुए मुझे शिक्षा दीजिये।'),
('3db771c9-a9c5-5a6a-b511-d24d81e9c071'::uuid, '81ce4613-6e7c-55b1-a344-8187e2487d59'::uuid, 'tejomayananda', 'hindi', '।।2.7।। करुणा के कलुष से अभिभूत और कर्तव्यपथ पर संभ्रमित हुआ मैं आपसे पूछता हूँ, कि मेरे लिये जो श्रेयष्कर हो, उसे आप निश्चय करके कहिये, क्योंकि मैं आपका शिष्य हूँ; शरण में आये मुझको आप उपदेश दीजिये।।
 '),
('68efbcff-c1bf-5979-bdc1-e70560699468'::uuid, '3a3d2062-56d0-591e-9f19-9f851796f379'::uuid, 'ramsukhdas', 'hindi', '।।2.8।। पृथ्वीपर धन-धान्य-समृद्ध और शत्रुरहित राज्य तथा स्वर्गमें देवताओंका आधिपत्य मिल जाय तो भी इन्द्रियोंको सुखानेवाला मेरा जो शोक है, वह दूर हो जाय - ऐसा मैं नहीं देखता हूँ।'),
('c1af39d8-6493-53f7-98ac-98c3ac9d6553'::uuid, '3a3d2062-56d0-591e-9f19-9f851796f379'::uuid, 'tejomayananda', 'hindi', '।।2.8।। पृथ्वी पर निष्कण्टक समृद्ध राज्य को और देवताओं के स्वामित्व को प्राप्त होकर भी मैं उस उपाय को नहीं देखता हूँ, जो मेरी इन्द्रियों को सुखाने वाले इस शोक को दूर कर सके।।
 '),
('d8af6921-d446-5b82-aba7-776958743d10'::uuid, '3755d567-5ea4-5c64-a2da-0978ae8fd352'::uuid, 'ramsukhdas', 'hindi', '।।2.9।। संजय बोले - हे शत्रुतापन धृतराष्ट्र! ऐसा कहकर निद्राको जीतनेवाले अर्जुन अन्तर्यामी भगवान् गोविन्दसे ''मैं युद्ध नहीं करूँगा'' ऐसा साफ-साफ कहकर चुप हो गये।'),
('31235157-a111-5fdb-bc97-41a4bacda7bd'::uuid, '3755d567-5ea4-5c64-a2da-0978ae8fd352'::uuid, 'tejomayananda', 'hindi', '।।2.9।। संजय ने कहा -- इस प्रकार गुडाकेश परंतप अर्जुन भगवान् हृषीकेश से यह कहकर कि हे गोविन्द "मैं युद्ध नहीं करूँगा" चुप हो गया।।
 '),
('03dfc2a3-8480-5bdb-8d5b-6d3577528e54'::uuid, '7ab3810b-a7d6-5180-b577-86f672f8aada'::uuid, 'ramsukhdas', 'hindi', '।।2.10।। हे भरतवंशोद्भव धृतराष्ट्र! दोनों सेनाओंके मध्यभागमें विषाद करते हुए उस अर्जुनके प्रति हँसते हुए-से भगवान् हृषीकेश यह (आगे कहे जानेवाले) वचन बोले।'),
('84f82d02-6a4c-5955-a6d4-02e1396c361b'::uuid, '7ab3810b-a7d6-5180-b577-86f672f8aada'::uuid, 'tejomayananda', 'hindi', '।।2.10।। हे भारत (धृतराष्ट्र) ! दोनों सेनाओं के बीच में उस शोकमग्न अर्जुन को भगवान् हृषीकेश ने हँसते हुए से यह वचन कहे।।
 '),
('97d0cbbe-72f5-5729-bdb0-614d7dc8da28'::uuid, '13597f0a-05bd-509e-9c11-d140bc70d763'::uuid, 'ramsukhdas', 'hindi', '।।2.11।। श्रीभगवान् बोले - तुमने शोक न करनेयोग्यका शोक किया है और  पण्डिताईकी बातें कह रहे हो; परन्तु जिनके प्राण चले गये हैं, उनके लिये और जिनके प्राण नहीं गये हैं, उनके लिये पण्डितलोग शोक नहीं करते।'),
('b4fb756a-0900-5645-8738-d4bcbc430754'::uuid, '13597f0a-05bd-509e-9c11-d140bc70d763'::uuid, 'tejomayananda', 'hindi', '।।2.11।। श्री भगवान् ने कहा -- (अशोच्यान्) जिनके लिये शोक करना उचित नहीं है, उनके लिये तुम शोक करते हो और ज्ञानियों के से वचनों को कहते हो, परन्तु ज्ञानी पुरुष मृत (गतासून्) और जीवित (अगतासून्) दोनों के लिये शोक नहीं करते हैं।।
 '),
('8c575ced-bb4e-5faa-915a-cf983b11114a'::uuid, 'cc4f4cc6-529c-5f5a-8760-6e29f7051672'::uuid, 'ramsukhdas', 'hindi', '।।2.12।। किसी कालमें मैं नहीं था और तू नहीं था तथा ये राजालोग नहीं थे, यह बात भी नहीं है; और इसके बाद (भविष्य में) मैं, तू और राजलोग - हम सभी नहीं रहेंगे, यह बात भी नहीं है।'),
('20581cf2-0e78-5240-9042-dc2c9937bb6f'::uuid, 'cc4f4cc6-529c-5f5a-8760-6e29f7051672'::uuid, 'tejomayananda', 'hindi', '।।2.12।। वास्तव में न तो ऐसा ही है कि मैं किसी काल में नहीं था अथवा तुम नहीं थे अथवा ये राजालोग नहीं थे और न ऐसा ही है कि इससे आगे हम सब नहीं रहेंगे।।
 '),
('f72d524d-0f1a-588e-a33c-091182869f0f'::uuid, 'ab6be0cb-4af4-5f9a-83da-c51c03f3f724'::uuid, 'ramsukhdas', 'hindi', '।।2.13।। देहधारीके इस मनुष्यशरीरमें जैसे बालकपन, जवानी और वृद्धावस्था होती है, ऐसे ही देहान्तरकी प्राप्ति होती है। उस विषयमें धीर मनुष्य मोहित नहीं होता।'),
('c91b8c06-8156-5049-91f5-57ae21501392'::uuid, 'ab6be0cb-4af4-5f9a-83da-c51c03f3f724'::uuid, 'tejomayananda', 'hindi', '।।2.13।। जैसे इस देह में देही जीवात्मा की कुमार, युवा और वृद्धावस्था होती है, वैसे ही उसको अन्य शरीर की प्राप्ति होती है;  धीर पुरुष इसमें मोहित नहीं होता है।।
 '),
('e553f094-663d-54d6-8a14-ec70415680bf'::uuid, 'bfe8c250-40de-5d96-96e6-5a9ff9254bdb'::uuid, 'ramsukhdas', 'hindi', '।।2.14।। हे कुन्तीनन्दन! इन्द्रियोंके जो विषय (जड पदार्थ) हैं, वो तो शीत (अनुकूलता) और उष्ण (प्रतिकूलता) - के द्वारा सुख और दुःख देनेवाले हैं तथा आने-जानेवाले और अनित्य हैं। हे भरतवंशोद्भव अर्जुन! उनको तुम सहन करो।'),
('eb02032e-1d5d-53f0-bf15-fe4493b5d586'::uuid, 'bfe8c250-40de-5d96-96e6-5a9ff9254bdb'::uuid, 'tejomayananda', 'hindi', '।।2.14।। हे कुन्तीपुत्र ! शीत और उष्ण और सुख दुख को देने वाले इन्द्रिय और विषयों के संयोग का प्रारम्भ और अन्त होता है;  वे अनित्य हैं,  इसलिए,  हे भारत ! उनको तुम सहन करो।।
 '),
('88baed21-a58c-5153-b3c8-0f0bd759c935'::uuid, '1c4ad91c-c459-50a3-900b-19ee502de13a'::uuid, 'ramsukhdas', 'hindi', '।।2.15।। कारण कि हे पुरुषोंमें श्रेष्ठ अर्जुन! सुख-दुःखमें सम रहनेवाले जिस धीर मनुष्यको ये मात्रास्पर्श (पदार्थ) व्यथित (सुखी-दुःखी) नहीं कर पाते, वह अमर होनेमें समर्थ हो जाता है अर्थात् वह अमर हो जाता है।'),
('73d2d161-a551-5c66-ae98-f95aa7c3079d'::uuid, '1c4ad91c-c459-50a3-900b-19ee502de13a'::uuid, 'tejomayananda', 'hindi', '।।2.15।। हे पुरुषश्रेष्ठ ! दुख और सुख में समान भाव से रहने वाले जिस धीर पुरुष को ये व्यथित नहीं कर सकते हैं वह अमृतत्व (मोक्ष) का अधिकारी होता है।।
 '),
('6be9ba9b-e66c-52ea-9bac-a7b814fb4f03'::uuid, '08510c75-32d1-55a0-b544-59c7ad4d044a'::uuid, 'ramsukhdas', 'hindi', '।।2.16।। असत् का तो भाव (सत्ता) विद्यमान नहीं है और सत् का अभाव विद्यमान नहीं है, तत्त्वदर्शी महापुरुषोंने इन दोनोंका ही अन्त अर्थात् तत्त्व देखा है।'),
('a9902f6e-e96e-58e7-8995-603ddb20b85a'::uuid, '08510c75-32d1-55a0-b544-59c7ad4d044a'::uuid, 'tejomayananda', 'hindi', '।।2.16।। असत् वस्तु का तो अस्तित्व नहीं है और सत् का कभी अभाव नहीं है। इस प्रकार इन दोनों का ही तत्त्व,  तत्त्वदर्शी ज्ञानी पुरुषों के द्वारा देखा गया है।।
 '),
('b0f34edc-11e4-5621-af14-f58fa6d573b4'::uuid, '4a31496f-7694-5eab-9ddf-8e90f5875d77'::uuid, 'ramsukhdas', 'hindi', '।।2.17।। अविनाशी तो उसको जान, जिससे यह सम्पूर्ण संसार व्याप्त है। इस अविनाशीका विनाश कोई भी नहीं कर सकता।'),
('36b7bc7f-0216-59eb-89ed-53f9be9f7988'::uuid, '4a31496f-7694-5eab-9ddf-8e90f5875d77'::uuid, 'tejomayananda', 'hindi', '।।2.17।। उस वस्तु को तुम अविनाशी जानों,  जिससे यह सम्पूर्ण जगत् व्याप्त है। इस अव्यय का नाश करने में कोई भी समर्थ नहीं है।।
 '),
('389f8d7a-ec52-52a5-a03d-8d16b3cd786b'::uuid, '9d67746c-f135-5715-b502-8ac5e9e34105'::uuid, 'ramsukhdas', 'hindi', '।।2.18।। अविनाशी, अप्रमेय और नित्य रहनेवाले इस शरीरी के ये देह अन्तवाले कहे गये हैं। इसलिये हे अर्जुन! तुम युद्ध करो।'),
('136c3b0c-4fab-56c2-9f30-552b043f111d'::uuid, '9d67746c-f135-5715-b502-8ac5e9e34105'::uuid, 'tejomayananda', 'hindi', '।।2.18।। इस नाशरहित अप्रमेय नित्य देही आत्मा के ये सब शरीर नाशवान् कहे गये हैं। इसलिये हे भारत ! तुम युद्ध करो।।
 '),
('fa3355b1-5a17-5397-a20c-d8e1ae21ec39'::uuid, 'e9a90dec-e7b5-56ec-9462-d0f292246aef'::uuid, 'ramsukhdas', 'hindi', '।।2.19।। जो मनुष्य इस अविनाशी शरीरीको मारनेवाला मानता है और जो मनुष्य इसको मरा मानता है, वे दोनों ही इसको नहीं जानते; क्योंकि यह न मारता है और न मारा जाता है।'),
('cd839f8a-5a4a-517e-9565-57376f5d82e4'::uuid, 'e9a90dec-e7b5-56ec-9462-d0f292246aef'::uuid, 'tejomayananda', 'hindi', '।।2.19।। जो इस आत्मा को मारने वाला समझता है और जो इसको मरा समझता है वे दोनों ही नहीं जानते हैं,  क्योंकि यह आत्मा न मरता है और न मारा जाता है।।
 '),
('3f112f0f-a70d-5c83-ada2-d8fa6e60f625'::uuid, '5fe9a354-b762-5b22-ae2c-adefa6126069'::uuid, 'ramsukhdas', 'hindi', '।।2.20।। यह शरीरी न कभी जन्मता है और न मरता है तथा यह उत्पन्न होकर फिर होनेवाला नहीं है। यह जन्मरहित, नित्य-निरन्तर रहनेवाला, शाश्वत और पुराण (अनादि) है। शरीरके मारे जानेपर भी यह नहीं मारा जाता।'),
('8d038bdd-40eb-530e-97bb-5727ae58e091'::uuid, '5fe9a354-b762-5b22-ae2c-adefa6126069'::uuid, 'tejomayananda', 'hindi', '।।2.20।। यह आत्मा किसी काल में भी न जन्मता है और न मरता है और न यह एक बार होकर फिर अभावरूप होने वाला है। यह आत्मा अजन्मा, नित्य, शाश्वत और पुरातन है,  शरीर के नाश होने पर भी इसका नाश नहीं होता।।
 '),
('3b715e51-c107-548c-91c5-e0b0653991fb'::uuid, 'aa95bf09-a8d9-5dc1-9478-e941c36656cf'::uuid, 'ramsukhdas', 'hindi', '।।2.21।। हे पृथानन्दन! जो मनुष्य इस शरीरीको अविनाशी, नित्य, जन्मरहित और अव्यय जानता है, वह कैसे किसको मारे और कैसे किसको मरवाये?'),
('f8580879-7f10-5082-8388-1de5638950b3'::uuid, 'aa95bf09-a8d9-5dc1-9478-e941c36656cf'::uuid, 'tejomayananda', 'hindi', '।।2.21।। हे पार्थ ! जो पुरुष इस आत्मा को अविनाशी,  नित्य और अव्ययस्वरूप जानता है,  वह कैसे किसको मरवायेगा और कैसे किसको मारेगा?
 '),
('10622729-b101-5d34-848c-34630d3e6f60'::uuid, '4ffc5d3e-8c4c-5fa3-89b0-c4e7d71b6b43'::uuid, 'ramsukhdas', 'hindi', '।।2.22।। मनुष्य जैसे पुराने कपड़ोंको छोड़कर दूसरे नये कपड़े धारण कर लेता है, ऐसे ही देही पुराने शरीरोंको छोड़कर दूसरे नये शरीरोंमें चला जाता है।'),
('e8b112ed-8377-5f19-b980-b6af0f33858c'::uuid, '4ffc5d3e-8c4c-5fa3-89b0-c4e7d71b6b43'::uuid, 'tejomayananda', 'hindi', '।।2.22।। जैसे मनुष्य जीर्ण वस्त्रों को त्यागकर दूसरे नये वस्त्रों को धारण करता है, वैसे ही देही जीवात्मा पुराने शरीरों को त्याग कर दूसरे नए शरीरों को प्राप्त होता है।।
 '),
('1077df63-a2f2-5e55-8f2e-0701e09a91ba'::uuid, '0253ec8e-7e72-5e7c-aa1d-869d069a99b4'::uuid, 'ramsukhdas', 'hindi', '।।2.23।। शस्त्र इस शरीरीको काट नहीं सकते, अग्नि इसको जला नहीं सकती, जल इसको गीला नहीं कर सकता और वायु इसको सुखा नहीं सकती।'),
('c6d52239-00bb-56a0-821f-ee99b5549ca8'::uuid, '0253ec8e-7e72-5e7c-aa1d-869d069a99b4'::uuid, 'tejomayananda', 'hindi', '।।2.23।। इस आत्मा को शस्त्र काट नहीं सकते और न अग्नि इसे जला सकती है ; जल इसे गीला नहीं कर सकता और वायु इसे सुखा नहीं सकती।।
 '),
('ae2c3a2f-541c-5534-95ef-fd0e45b4545c'::uuid, '8ab6a31f-8e4c-5499-9d8b-67a78ceb8f8a'::uuid, 'ramsukhdas', 'hindi', '।।2.24।। यह शरीरी काटा नहीं जा सकता, यह जलाया नहीं जा सकता, यह गीला नहीं किया जा सकता और यह सुखाया भी नहीं जा सकता। कारण कि यह नित्य रहनेवाला सबमें परिपूर्ण, अचल, स्थिर स्वभाववाला और अनादि है।'),
('4fbaf29e-f34a-5e67-9e34-53e0c64c308a'::uuid, '8ab6a31f-8e4c-5499-9d8b-67a78ceb8f8a'::uuid, 'tejomayananda', 'hindi', '।।2.24।। क्योंकि यह आत्मा अच्छेद्य (काटी नहीं जा सकती),  अदाह्य (जलाई नहीं जा सकती),  अक्लेद्य (गीली नहीं हो सकती ) और अशोष्य (सुखाई नहीं जा सकती) है;  यह नित्य,  सर्वगत,  स्थाणु (स्थिर),  अचल और सनातन है।।
 '),
('e9e5ede3-8570-51fa-b31c-99ae2add6687'::uuid, '4d9a74d3-12e7-5108-bb0a-2b00fc1293bc'::uuid, 'ramsukhdas', 'hindi', '।।2.25।। यह देही प्रत्यक्ष नहीं दीखता, यह चिन्तनका विषय नहीं है और यह निर्विकार कहा जाता है। अतः इस देहीको ऐसा जानकर शोक नहीं करना चाहिये।'),
('fb306bfd-0def-59e0-a1b6-75da0706e86e'::uuid, '4d9a74d3-12e7-5108-bb0a-2b00fc1293bc'::uuid, 'tejomayananda', 'hindi', '।।2.25।। यह आत्मा अव्यक्त,  अचिन्त्य और अविकारी कहा जाता है;  इसलिए इसको इस प्रकार जानकर तुमको शोक करना उचित नहीं है।।
 '),
('2704cb89-93ed-5de9-aa75-3ce29674121d'::uuid, 'f9c60e3d-cb6e-5d71-9d36-207f3906c2da'::uuid, 'ramsukhdas', 'hindi', '।।2.26।। हे महाबाहो ! अगर तुम इस देहीको नित्य पैदा होनेवाला अथवा नित्य मरनेवाला भी मानो, तो भी तुम्हें इस प्रकार शोक नहीं करना चाहिये।'),
('d1f879e8-d38c-51b6-ad5c-dca9b454a89d'::uuid, 'f9c60e3d-cb6e-5d71-9d36-207f3906c2da'::uuid, 'tejomayananda', 'hindi', '।।2.26।। और यदि तुम आत्मा को नित्य जन्मने और नित्य मरने वाला मानो तो भी,  हे महाबाहो !  इस प्रकार शोक करना तुम्हारे लिए उचित नहीं है।।
 '),
('42ba5b5b-9ba2-5f28-b75d-97ab0c6a232b'::uuid, 'd5d967a2-295c-53cf-927e-62390ef3b10d'::uuid, 'ramsukhdas', 'hindi', '।।2.27।। क्योंकि पैदा हुएकी जरूर मृत्यु होगी और मरे हुएका जरूर जन्म होगा। इस (जन्म-मरण-रूप परिवर्तन के प्रवाह) का परिहार अर्थात् निवारण नहीं हो सकता। अतः इस विषयमें तुम्हें शोक नहीं करना चाहिये।'),
('0b7b09f4-38a6-5cbc-9dd1-e2e65226afa7'::uuid, 'd5d967a2-295c-53cf-927e-62390ef3b10d'::uuid, 'tejomayananda', 'hindi', '।।2.27।। जन्मने वाले की मृत्यु निश्चित है और मरने वाले का जन्म निश्चित है;  इसलिए जो अटल है अपरिहार्य - है उसके विषय में तुमको शोक नहीं करना चाहिये।।
 '),
('e37f38bd-dd21-5de1-a215-03b903f2af6f'::uuid, '4310266d-3207-5b04-a7f8-31f0ae72c9ab'::uuid, 'ramsukhdas', 'hindi', '।।2.28।। हे भारत ! सभी प्राणी जन्मसे पहले अप्रकट थे और मरनेके बाद अप्रकट हो जायँगे, केवल बीचमें ही प्रकट दीखते हैं। अतः इसमें शोक करनेकी बात ही क्या है?'),
('02562a68-4b41-52fc-9bfe-2a2b3a5765a1'::uuid, '4310266d-3207-5b04-a7f8-31f0ae72c9ab'::uuid, 'tejomayananda', 'hindi', '।।2.28।। हे भारत ! समस्त प्राणी जन्म से पूर्व और मृत्यु के बाद अव्यक्त अवस्था में रहते हैं और बीच में व्यक्त होते हैं। फिर उसमें चिन्ता या शोक की क्या बात है ?'),
('030f4253-c342-5a53-a132-4cc011294dc4'::uuid, 'ccfec810-54c0-5e1a-92e0-071aeb0ada0d'::uuid, 'ramsukhdas', 'hindi', '।।2.29।। कोई इस शरीरीको आश्चर्यकी तरह देखता है और वैसे ही अन्य कोई इसका आश्चर्यकी तरह वर्णन करता है तथा अन्य कोई इसको आश्चर्यकी तरह सुनता है; और इसको सुनकर भी कोई नहीं जानता। अर्थात यह शरीरी दुर्विज्ञेय है।'),
('c743d410-344e-5f95-9a6b-15d5b8d5fe07'::uuid, 'ccfec810-54c0-5e1a-92e0-071aeb0ada0d'::uuid, 'tejomayananda', 'hindi', '।।2.29।। कोई इसे आश्चर्य के समान देखता है;  कोई इसके विषय में आश्चर्य के समान कहता है;  और कोई अन्य पुरुष इसे आश्चर्य के समान सुनता है;  और फिर कोई सुनकर भी नहीं जानता।।
 '),
('2bbd1f7c-9907-50aa-981a-77896296a208'::uuid, '7082d70a-857e-5855-be33-e2390c031f79'::uuid, 'ramsukhdas', 'hindi', '।।2.30।। हे भरतवंशोद्भव अर्जुन! सबके देहमें यह देही नित्य ही अवध्य है। इसलिये सम्पूर्ण प्राणियोंके लिये अर्थात् किसी भी प्राणीके लिये तुम्हें शोक नहीं करना चाहिये।'),
('ce517ba9-2ebc-5efc-a7fa-fb259a945026'::uuid, '7082d70a-857e-5855-be33-e2390c031f79'::uuid, 'tejomayananda', 'hindi', '।।2.30।। हे भारत ! यह देही आत्मा सबके शरीर में सदा ही अवध्य है, इसलिए समस्त प्राणियों के लिए तुम्हें शोक करना उचित नहीं।।
 '),
('2f8741f8-b0a3-5fbb-b88e-e55028b5bb83'::uuid, 'ec4c3d46-e1a6-577c-b22b-78c915abb994'::uuid, 'ramsukhdas', 'hindi', '।।2.31।। अपने स्वधर्म (क्षात्रधर्म) को देखकर भी तुम्हें विकम्पित अर्थात् कर्तव्य-कर्मसे विचलित नहीं होना चाहिये; क्योंकि धर्ममय युद्धसे बढ़कर क्षत्रियके लिये दूसरा कोई कल्याणकारक कर्म नहीं है।'),
('de937a2f-815a-5e21-bb3a-ab912f56229c'::uuid, 'ec4c3d46-e1a6-577c-b22b-78c915abb994'::uuid, 'tejomayananda', 'hindi', '।।2.31।। और स्वधर्म को भी देखकर तुमको विचलित होना उचित नहीं है,  क्योंकि धर्मयुक्त युद्ध से बढ़कर दूसरा कोई कल्याणकारक कर्त्तव्य क्षत्रिय के लिये नहीं है।।
 '),
('027b35ee-3207-56cb-b025-568e1e6395ce'::uuid, '3cc08a8f-422d-53bd-bdec-198a5c9e8612'::uuid, 'ramsukhdas', 'hindi', '।।2.32।। अपने-आप प्राप्त हुआ युद्ध खुला हुआ स्वर्गका दरवाजा भी है। हे पृथानन्दन ! वे क्षत्रिय बड़े सुखी (भाग्यशाली) हैं, जिनको ऐसा युद्ध प्राप्त होता है।'),
('3a672603-389e-5289-805b-ea1c14a138f7'::uuid, '3cc08a8f-422d-53bd-bdec-198a5c9e8612'::uuid, 'tejomayananda', 'hindi', '।।2.32।। और हे पार्थ ! अपने आप प्राप्त हुए और स्वर्ग के लिए खुले हुए द्वाररूप इस प्रकार के युद्ध को भाग्यवान क्षत्रिय लोग ही पाते हैं।।
 '),
('5fb06fab-c423-502f-8917-c0f03cc907fa'::uuid, '83eef5a7-6c26-5154-ac48-42c2d61a3653'::uuid, 'ramsukhdas', 'hindi', '।।2.33।। अब अगर तू यह धर्ममय युद्ध नहीं करेगा,  तो अपने धर्म और कीर्तिका त्याग करके पापको प्राप्त होगा।'),
('e45f5f4a-94b6-5715-83c9-ddcb85a63bf6'::uuid, '83eef5a7-6c26-5154-ac48-42c2d61a3653'::uuid, 'tejomayananda', 'hindi', '।।2.33।। और यदि तुम इस धर्मयुद्ध को स्वीकार नहीं करोगे,  तो स्वधर्म और कीर्ति को खोकर पाप को प्राप्त करोगे।।
 '),
('50bc654d-420f-5aee-b600-5884fb427a83'::uuid, '4122cefe-1b37-5e9c-a1f5-a86584adb835'::uuid, 'ramsukhdas', 'hindi', '।।2.34।। और सब प्राणी भी तेरी सदा रहनेवाली अपकीर्तिका कथन अर्थात निंदा करेंगे। वह अपकीर्ति सम्मानित मनुष्यके लिये मृत्युसे भी बढ़कर दुःखदायी होती है।'),
('78b43af9-4f69-59b0-8e03-0c76b905b5e2'::uuid, '4122cefe-1b37-5e9c-a1f5-a86584adb835'::uuid, 'tejomayananda', 'hindi', '।।2.34।। और सब लोग तुम्हारी बहुत काल तक रहने वाली अपकीर्ति को भी कहते रहेंगे;  और सम्मानित पुरुष के लिए अपकीर्ति मरण से भी अधिक होती है।।
 '),
('81521ab3-251e-59bf-a5dc-187f3d083bb8'::uuid, 'fae5c1bf-e1c7-5dda-bfef-ebef66f8a681'::uuid, 'ramsukhdas', 'hindi', '।।2.35।।  महारथीलोग तुझे भयके कारण युद्धसे उपरत (हटा) हुआ मानेंगे। जिनकी धारणामें तू बहुमान्य हो चुका है, उनकी दृष्टिमें तू लघुताको प्राप्त हो जायगा।'),
('88d754fe-850f-5db5-a583-87500e77b819'::uuid, 'fae5c1bf-e1c7-5dda-bfef-ebef66f8a681'::uuid, 'tejomayananda', 'hindi', '।।2.35।। और जिनके लिए तुम बहुत माननीय हो उनके लिए अब तुम तुच्छता को प्राप्त होओगे,  वे महारथी लोग तुम्हें भय के कारण युद्ध से निवृत्त हुआ मानेंगे।।
 '),
('0ee63187-3161-5280-8af4-4ee1dc4e28e7'::uuid, '22cae4a9-e3ac-57b6-a406-e9787335fbf9'::uuid, 'ramsukhdas', 'hindi', '।।2.36।। तेरे शत्रुलोग तेरी सार्मथ्यकी निन्दा करते हुए न कहनेयोग्य बहुत-से वचन भी कहेंगे। उससे बढ़कर और दुःखकी बात क्या होगी?'),
('b32c1470-db2f-5966-9677-b01bb3be5058'::uuid, '22cae4a9-e3ac-57b6-a406-e9787335fbf9'::uuid, 'tejomayananda', 'hindi', '।।2.36।। तुम्हारे शत्रु तुम्हारे सार्मथ्य की निन्दा करते हुए बहुत से अकथनीय वचनों को कहेंगे,  फिर उससे अधिक दु:ख क्या होगा ?
 '),
('47f4dae5-f8eb-5ffe-abe2-8d98a175b0e4'::uuid, '674a2fd3-81ef-55fa-9e53-0579f267d756'::uuid, 'ramsukhdas', 'hindi', '।।2.37।। अगर युद्धमें तू मारा जायगा तो तुझे स्वर्गकी प्राप्ति होगी और अगर युद्धमें तू जीत जायगा तो पृथ्वीका राज्य भोगेगा। अतः हे कुन्तीनन्दन! तू युद्धके लिये निश्चय करके खड़ा हो जा।'),
('2d6b1f12-a2bf-5e90-89a0-f39c9fe2dc21'::uuid, '674a2fd3-81ef-55fa-9e53-0579f267d756'::uuid, 'tejomayananda', 'hindi', '।।2.37।। युद्ध में मरकर तुम स्वर्ग प्राप्त करोगे या जीतकर पृथ्वी को भोगोगे;  इसलिय, हे कौन्तेय ! युद्ध का निश्चय कर तुम खड़े हो जाओ।।
 '),
('5998f522-c601-515b-a625-eaf9c7d45f9a'::uuid, 'c71f94a0-4fe7-5e9b-9e77-8a23e49605f9'::uuid, 'ramsukhdas', 'hindi', '।।2.38।। जय-पराजय, लाभ-हानि और सुख-दुःखको समान करके फिर युद्धमें लग जा। इस प्रकार युद्ध करनेसे तू पापको प्राप्त नहीं होगा।'),
('f23859d2-6c98-5186-8cb9-4ad15d6267cd'::uuid, 'c71f94a0-4fe7-5e9b-9e77-8a23e49605f9'::uuid, 'tejomayananda', 'hindi', '।।2.38।। सुख-दु:ख,  लाभ-हानि और जय-पराजय को समान करके युद्ध के लिये तैयार हो जाओ;  इस प्रकार तुमको पाप नहीं होगा।।
 '),
('00fe3225-403c-55d2-b6df-a1500edf6e2f'::uuid, 'fb8f93f0-8242-5372-b2b5-5f3251423258'::uuid, 'ramsukhdas', 'hindi', '।।2.39।। हे पार्थ! यह समबुद्धि तेरे लिए पहले सांख्ययोगमें कही गयी, अब तू इसको कर्मयोगके विषयमें सुन; जिस समबुद्धिसे युक्त हुआ तू कर्मबन्धनका त्याग कर देगा।'),
('7a1f5f52-82c9-50c4-a26c-63e4f6b80e96'::uuid, 'fb8f93f0-8242-5372-b2b5-5f3251423258'::uuid, 'tejomayananda', 'hindi', '।।2.39।। हे पार्थ ! तुम्हें सांख्य विषयक ज्ञान कहा गया और अब इस (कर्म) योग से सम्बन्धित ज्ञान को सुनो जिस ज्ञान से युक्त होकर तुम कर्मबन्ध का नाश कर सकोगे।।
 '),
('b5a8ce61-c7c1-5379-a457-8239f7476815'::uuid, '438ed540-7e2e-529e-b534-fa076fe5cc87'::uuid, 'ramsukhdas', 'hindi', '।।2.40।। मनुष्यलोकमें इस समबुद्धिरूप धर्मके आरम्भका नाश नहीं होता, इसके अनुष्ठानका उलटा फल भी नहीं होता और इसका थोड़ासा भी अनुष्ठान (जन्म-मरणरूप) महान् भयसे रक्षा कर लेता है।'),
('5df42467-bf62-5cad-a0a4-403f671b2839'::uuid, '438ed540-7e2e-529e-b534-fa076fe5cc87'::uuid, 'tejomayananda', 'hindi', '।।2.40।। इसमें क्रमनाश और प्रत्यवाय दोष नहीं है। इस धर्म (योग) का अल्प अभ्यास भी महान् भय से रक्षण करता है।।
 '),
('bdd29077-847f-561b-8995-a46d6b28454a'::uuid, '0d68b441-418b-5d03-a0a0-c74927298c48'::uuid, 'ramsukhdas', 'hindi', '।।2.41।। हे कुरुनन्दन! इस समबुद्धिकी प्राप्तिके विषयमें व्यवसायात्मिका बुद्धि एक ही होती है। अव्यवसायी मनुष्योंकी बुद्धियाँ अनन्त और बहुशाखाओंवाली ही होती हैं।'),
('2dcc4f64-9762-5001-b2ab-288514d4eff1'::uuid, '0d68b441-418b-5d03-a0a0-c74927298c48'::uuid, 'tejomayananda', 'hindi', '।।2.41।। हे कुरुनन्दन ! इस (विषय) में निश्चयात्मक बुद्धि एक ही है, अज्ञानी पुरुषों की बुद्धियां (संकल्प) बहुत भेदों वाली और अनन्त होती हैं।।
 '),
('8e09c408-8cad-5629-aa81-0da6f6c8179c'::uuid, '54d98493-fbad-57f3-84ab-3ab4d8cad2ef'::uuid, 'ramsukhdas', 'hindi', '।।2.42 -- 2.43।। हे पृथानन्दन ! जो कामनाओंमें तन्मय हो रहे हैं, स्वर्गको ही श्रेष्ठ माननेवाले हैं, वेदोंमें कहे हुए सकाम कर्मोंमें प्रीति रखनेवाले हैं, भोगोंके सिवाय और कुछ है ही नहीं - ऐसा कहनेवाले हैं, वे अविवेकी मनुष्य इस प्रकारकी जिस पुष्पित (दिखाऊ शोभायुक्त) वाणीको कहा करते हैं, जो कि जन्मरूपी कर्मफलको देनेवाली है तथा भोग और ऐश्वर्यकी प्राप्तिके लिये बहुतसी क्रियाओंका वर्णन करनेवाली है।'),
('d91fb382-edc6-5f40-8a1d-0991763b425c'::uuid, '54d98493-fbad-57f3-84ab-3ab4d8cad2ef'::uuid, 'tejomayananda', 'hindi', '।।2.42।। हे पार्थ  अविवेकी पुरुष वेदवाद में रमते हुये जो यह पुष्पिता (दिखावटी शोभा की) वाणी बोलते हैं? इससे (स्वर्ग से) बढ़कर और कुछ नहीं है।।।'),
('dcf2da27-509d-58e5-a7f0-2ea2416c1f5f'::uuid, '07c67223-61c4-5b7f-9170-2b794a5321bd'::uuid, 'ramsukhdas', 'hindi', '।।2.42 -- 2.43।। हे पृथानन्दन ! जो कामनाओंमें तन्मय हो रहे हैं, स्वर्गको ही श्रेष्ठ माननेवाले हैं, वेदोंमें कहे हुए सकाम कर्मोंमें प्रीति रखनेवाले हैं, भोगोंके सिवाय और कुछ है ही नहीं - ऐसा कहनेवाले हैं, वे अविवेकी मनुष्य इस प्रकारकी जिस पुष्पित (दिखाऊ शोभायुक्त) वाणीको कहा करते हैं, जो कि जन्मरूपी कर्मफलको देनेवाली है तथा भोग और ऐश्वर्यकी प्राप्तिके लिये बहुतसी क्रियाओंका वर्णन करनेवाली है।'),
('dcf24abd-000a-547a-9e8e-32812d4527ae'::uuid, '07c67223-61c4-5b7f-9170-2b794a5321bd'::uuid, 'tejomayananda', 'hindi', '।।2.43।। कामनाओं से युक्त? स्वर्ग को ही श्रेष्ठ मानने वाले लोग भोग और ऐश्वर्य को प्राप्त कराने वाली अनेक क्रियाओं को बताते हैं जो (वास्तव में) जन्मरूप कर्मफल को देने वाली होती हैं।।'),
('4ec2123a-5552-500b-893d-adf50d628123'::uuid, 'e56a4507-80c7-5726-8608-49750de85282'::uuid, 'ramsukhdas', 'hindi', '।।2.44।। उस पुष्पित वाणीसे जिसका अन्तःकरण हर लिया गया है अर्थात् भोगोंकी तरफ खिंच गया है और जो भोग तथा ऐश्वर्यमें अत्यन्त आसक्त हैं, उन मनुष्योंकी परमात्मामें निश्चयात्मिका बुद्धि नहीं होती।'),
('c46cec90-4e67-503c-abca-ec94e3099bfc'::uuid, 'e56a4507-80c7-5726-8608-49750de85282'::uuid, 'tejomayananda', 'hindi', '।।2.44।।उससे जिनका चित्त हर लिया गया है ऐसे भोग और एश्र्वर्य‌ मॆ आसक्ति रखने वाले पुरुषों के अन्तकरण मे निश्चयात्मक् बुद्धि नही हॊती अर्थात वे ध्यान का अभ्यास करने योग्य‌ नही होते।'),
('9c62a578-c626-5f76-8c1b-f659c326b623'::uuid, '728e922b-fecd-5162-8980-670240463820'::uuid, 'ramsukhdas', 'hindi', '।।2.45।। वेद तीनों गुणोंके कार्यका ही वर्णन करनेवाले हैं; हे अर्जुन! तू तीनों गुणोंसे रहित हो जा, निर्द्वन्द्व हो जा, निरन्तर नित्य वस्तु परमात्मा में स्थित हो जा, योगक्षेमकी चाहना भी मत रख और परमात्मपरायण हो जा।'),
('7d6357c9-1795-53e8-987b-2db1a9762f97'::uuid, '728e922b-fecd-5162-8980-670240463820'::uuid, 'tejomayananda', 'hindi', '।।2.45।। हे अर्जुन  वेदों का विषय तीन गुणों से सम्बन्धित (संसार से) है  तुम त्रिगुणातीत? निर्द्वन्द्व? नित्य सत्त्व (शुद्धता) में स्थित? योगक्षेम से रहित और आत्मवान् बनो।।'),
('fe96e7da-640d-51f3-a497-4c5f0691df38'::uuid, '67628f79-9ca9-576d-8f66-1e2dc4e33ae9'::uuid, 'ramsukhdas', 'hindi', '।।2.46।। सब तरफसे परिपूर्ण महान् जलाशयके प्राप्त होनेपर छोटे गड्ढों में भरे जल में मनुष्यका जितना प्रयोजन रहता है अर्थात् कुछ भी प्रयोजन नहीं रहता, वेदों और शास्त्रोंको तत्त्वसे जाननेवाले ब्रह्मज्ञानीका सम्पूर्ण वेदोंमें उतना ही प्रयोजन रहता है अर्थात् कुछ भी प्रयोजन नहीं रहता।'),
('8efc5829-5ca3-5c59-882b-663930e980d4'::uuid, '67628f79-9ca9-576d-8f66-1e2dc4e33ae9'::uuid, 'tejomayananda', 'hindi', '।।2.46।। सब ओर से परिपूर्ण जलराशि के होने पर मनुष्य का छोटे जलाशय में जितना प्रयोजन रहता है? आत्मज्ञानी ब्राह्मण का सभी वेदों में उतना ही प्रयोजन रहता है।।'),
('d5a51078-5534-56d8-bd7c-432aa4db1af2'::uuid, '171fcfe7-c27d-52d2-b6f0-399f559554a9'::uuid, 'ramsukhdas', 'hindi', '।।2.47।। कर्तव्य-कर्म करनेमें ही तेरा अधिकार है, फलोंमें कभी नहीं। अतः तू कर्मफलका हेतु भी मत बन और तेरी अकर्मण्यतामें भी आसक्ति न हो।'),
('a0818f9b-6925-51a0-a51d-b7f35d407e03'::uuid, '171fcfe7-c27d-52d2-b6f0-399f559554a9'::uuid, 'tejomayananda', 'hindi', '।।2.47।। कर्म करने मात्र में तुम्हारा अधिकार है? फल में कभी नहीं। तुम कर्मफल के हेतु वाले मत होना और अकर्म में भी तुम्हारी आसक्ति न हो।।'),
('773ca18e-52a2-5301-a9a3-35485eac1e35'::uuid, '0e0b1b2e-6a84-5712-a371-214ea1800637'::uuid, 'ramsukhdas', 'hindi', '।।2.48।। हे धनञ्जय ! तू आसक्तिका त्याग करके सिद्धि-असिद्धिमें सम होकर योगमें स्थित हुआ कर्मोंको कर; क्योंकि समत्व ही योग कहा जाता है।'),
('7cb6c17b-3118-528f-824e-6e42eeac3787'::uuid, '0e0b1b2e-6a84-5712-a371-214ea1800637'::uuid, 'tejomayananda', 'hindi', '।।2.48।। हे धनंजय  आसक्ति को त्याग कर तथा सिद्धि और असिद्धि में समभाव होकर योग में स्थित हुये तुम कर्म करो। यह समभाव ही योग कहलाता है।।'),
('26392175-3106-56f7-ac5f-02e3205605f7'::uuid, 'b21f9548-9ec4-51c1-a594-5b328b45e15c'::uuid, 'ramsukhdas', 'hindi', '।।2.49।। बुद्धियोग-(समता) की अपेक्षा सकामकर्म दूरसे (अत्यन्त) ही निकृष्ट है। अतः हे धनञ्जय ! तू बुद्धि (समता) का आश्रय ले; क्योंकि फलके हेतु बननेवाले अत्यन्त दीन हैं।'),
('e551c4d6-85e8-5bb4-850a-3e661531824d'::uuid, 'b21f9548-9ec4-51c1-a594-5b328b45e15c'::uuid, 'tejomayananda', 'hindi', '।।2.49।। इस बुद्धियोग की तुलना में(सकाम) कर्म अत्यन्त निकृष्ट हैं? इसलिये हे धनंजय  तुम बद्धि की शरण लो फल की इच्छा करनेवाले कृपण (दीन) हैं।।'),
('52613ef1-82c5-5cb3-a332-afe76d15f0de'::uuid, 'a7ef20f0-8141-500e-947b-fc122959469d'::uuid, 'ramsukhdas', 'hindi', '।।2.50।। बुद्धि-(समता) से युक्त मनुष्य यहाँ जीवित अवस्थामें ही पुण्य और पाप दोनोंका त्याग कर देता है। अतः तू योग-(समता-) में लग जा, क्योंकि योग ही कर्मोंमें कुशलता है।'),
('26171e65-4177-5bea-bdeb-a953ea9e9c31'::uuid, 'a7ef20f0-8141-500e-947b-fc122959469d'::uuid, 'tejomayananda', 'hindi', '।।2.50।। समत्वबुद्धि युक्त पुरुष यहां (इस जीवन में) पुण्य और पाप इन दोनों कर्मों को त्याग देता है? इसलिये तुम योग से युक्त हो जाओ। कर्मों में कुशलता योग है।।'),
('539260ad-1292-508b-a36b-91068451f8f2'::uuid, '83376527-d732-5ea5-b0bd-5951f95aeeea'::uuid, 'ramsukhdas', 'hindi', '।।2.51।। समतायुक्त मनीषी साधक कर्मजन्य फलका त्याग करके जन्मरूप बन्धनसे मुक्त होकर निर्विकार पदको प्राप्त हो जाते हैं।'),
('a3816a58-f219-551a-96cc-4468be3a6404'::uuid, '83376527-d732-5ea5-b0bd-5951f95aeeea'::uuid, 'tejomayananda', 'hindi', '।।2.51।। बुद्धियोग युक्त मनीषी लोग कर्मजन्य फलों को त्यागकर जन्मरूप बन्धन से मुक्त हुये अनामय अर्थात् निर्दोष पद को प्राप्त होते हैं।।'),
('ed869b4a-f997-5d25-8794-7a032cf2536e'::uuid, '204c7772-8eaf-5806-b490-e18d24631a17'::uuid, 'ramsukhdas', 'hindi', '।।2.52।। जिस समय तेरी बुद्धि मोहरूपी दलदलको तर जायगी, उसी समय तू सुने हुए और सुननेमें आनेवाले भोगोंसे वैराग्यको प्राप्त हो जायगा।'),
('0f3cd00f-7c08-5f45-a1c5-d353cb6524d3'::uuid, '204c7772-8eaf-5806-b490-e18d24631a17'::uuid, 'tejomayananda', 'hindi', '।।2.52।। जब तुम्हारी बुद्धि मोहरूप दलदल (कलिल) को तर जायेगी तब तुम उन सब वस्तुओं से निर्वेद (वैराग्य) को प्राप्त हो जाओगे? जो सुनने योग्य और सुनी हुई हैं।।'),
('d6c2edc5-cf0a-5be0-9ed8-ef7f901b3b8a'::uuid, 'f6ffb97a-9871-5c92-af83-c58d73e50beb'::uuid, 'ramsukhdas', 'hindi', '।।2.53।। जिस कालमें शास्त्रीय मतभेदोंसे विचलित हुई तेरी बुद्धि निश्चल हो जायगी और परमात्मामें अचल हो जायगी, उस कालमें तू योगको प्राप्त हो जायगा।'),
('8f1ee39f-5a54-59f1-b194-5f774d0f9eb1'::uuid, 'f6ffb97a-9871-5c92-af83-c58d73e50beb'::uuid, 'tejomayananda', 'hindi', '।।2.53।। जब अनेक प्रकार के विषयों को सुनने से विचलित हुई तुम्हारी बुद्धि आत्मस्वरूप में अचल और स्थिर हो जायेगी तब तुम (परमार्थ) योग को प्राप्त करोगे।।')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('6108aee8-8401-5419-a73a-060728d93b16'::uuid, '48da304c-7d2f-59bf-9165-e8ef0a658aa0'::uuid, 'ramsukhdas', 'hindi', '।।2.54।। अर्जुन बोले - हे केशव ! परमात्मामें स्थित स्थिर बुद्धिवाले मनुष्यके क्या लक्षण होते हैं? वह स्थिर बुद्धिवाला मनुष्य कैसे बोलता है, कैसे बैठता है और कैसे चलता है?'),
('4474b032-e9ee-58d6-a0eb-2b1bc6f6b159'::uuid, '48da304c-7d2f-59bf-9165-e8ef0a658aa0'::uuid, 'tejomayananda', 'hindi', '।।2.54।। अर्जुन ने कहा -- हे केशव  समाधि में स्थित स्थिर बुद्धि वाले पुरुष का क्या लक्षण है स्थिर बुद्धि पुरुष कैसे बोलता है कैसे बैठता है  कैसे चलता है'),
('a3f6384f-4e13-546b-9a4e-ddea8ea236aa'::uuid, 'ba58cbf1-a87f-595d-a200-942017edb805'::uuid, 'ramsukhdas', 'hindi', '।।2.55।। श्रीभगवान् बोले - हे पृथानन्दन ! जिस कालमें साधक मनोगत सम्पूर्ण कामनाओंका अच्छी तरह त्याग कर देता है और अपने-आपसे अपने-आपमें ही सन्तुष्ट रहता है, उस कालमें वह स्थितप्रज्ञ कहा जाता है।'),
('437c71bb-7df1-5704-8879-e04dc6ef02e0'::uuid, 'ba58cbf1-a87f-595d-a200-942017edb805'::uuid, 'tejomayananda', 'hindi', '।।2.55।। श्री भगवान् ने कहा -- हे पार्थ? जिस समय पुरुष मन में स्थित सब कामनाओं को त्याग देता है और आत्मा से ही आत्मा में सन्तुष्ट रहता है? उस समय वह स्थितप्रज्ञ कहलाता है।।'),
('693b760f-cc76-5d4c-b94b-b8a97cbd3314'::uuid, 'a449720e-f078-52b6-8bc9-90e5a7ca665b'::uuid, 'ramsukhdas', 'hindi', '।।2.56।। दुःखोंकी प्राप्ति होनेपर जिसके मनमें उद्वेग नहीं होता और सुखोंकी प्राप्ति होनेपर जिसके मनमें स्पृहा नहीं होती तथा जो राग, भय और क्रोधसे सर्वथा रहित हो गया है, वह मननशील मनुष्य स्थिरबुद्धि कहा जाता है।'),
('ed006f70-5527-5d67-ac66-508dcad95334'::uuid, 'a449720e-f078-52b6-8bc9-90e5a7ca665b'::uuid, 'tejomayananda', 'hindi', '।।2.56।। दुख में जिसका मन उद्विग्न नहीं होता सुख में जिसकी स्पृहा निवृत्त हो गयी है? जिसके मन से राग? भय और क्रोध नष्ट हो गये हैं? वह मुनि स्थितप्रज्ञ कहलाता है।।'),
('ff0ece10-5edd-5223-a506-987684793f06'::uuid, 'f093da7c-c9dd-5059-b8cf-1f51d7f63464'::uuid, 'ramsukhdas', 'hindi', '।।2.57।। सब जगह आसक्तिरहित हुआ जो मनुष्य उस-उस शुभ-अशुभको प्राप्त करके न तो अभिनन्दित होता है और न द्वेष करता है, उसकी बुद्धि प्रतिष्ठित है।'),
('1f120417-bd17-5068-acce-3e9369045d3c'::uuid, 'f093da7c-c9dd-5059-b8cf-1f51d7f63464'::uuid, 'tejomayananda', 'hindi', '।।2.57।। जो सर्वत्र अति स्नेह से रहित हुआ उन शुभ तथा अशुभ वस्तुओं को प्राप्त कर न प्रसन्न होता है और न द्वेष करता है? उसकी प्रज्ञा प्रतिष्ठित (स्थिर) है।।'),
('d5784728-0446-5e79-8f37-bbcab0b51e0f'::uuid, 'f6f6b1ba-77f8-5359-956d-1b13817da029'::uuid, 'ramsukhdas', 'hindi', '।।2.58।। जिस तरह कछुआ अपने अङ्गोंको सब ओरसे समेट लेता है, ऐसे ही जिस कालमें यह कर्मयोगी इन्द्रियोंके विषयोंसे इन्द्रियोंको सब प्रकारसे समेट लेता (हटा लेता) है, तब उसकी बुद्धि प्रतिष्ठित हो जाती है।'),
('c3750135-f708-5eb5-91e1-311c6762f902'::uuid, 'f6f6b1ba-77f8-5359-956d-1b13817da029'::uuid, 'tejomayananda', 'hindi', '।।2.58।। कछुवा अपने अंगों को जैसे समेट लेता है वैसे ही यह पुरुष जब सब ओर से अपनी इन्द्रियों को इन्द्रियों के विषयों से परावृत्त कर लेता है? तब उसकी बुद्धि स्थिर होती है।।'),
('da805ae4-2635-5281-9253-0e9115f83ba0'::uuid, '8ba4b3c6-4719-5eba-b3b8-25d05d952d5b'::uuid, 'ramsukhdas', 'hindi', '।।2.59।। निराहारी (इन्द्रियोंको विषयोंसे हटानेवाले) मनुष्यके भी विषय तो निवृत्त हो जाते हैं, पर रस निवृत्त नहीं होता। परन्तु इस स्थितप्रज्ञ मनुष्यका तो रस भी परमात्मतत्त्वका अनुभव होनेसे निवृत्त हो जाता है।'),
('fa0b3932-1513-50c5-a7ac-ed625dbfb910'::uuid, '8ba4b3c6-4719-5eba-b3b8-25d05d952d5b'::uuid, 'tejomayananda', 'hindi', '।।2.59।। निराहारी देही पुरुष से विषय तो निवृत्त (दूर) हो जाते हैं? परन्तु (उनके प्रति) राग नहीं  परम तत्व को देखने पर इस (पुरुष) का राग भी निवृत्त हो जाता है।।'),
('d29e9c7c-2381-5eff-879c-31ed3e830dcf'::uuid, '82994df3-345e-54c7-8495-6eb8efae7a35'::uuid, 'ramsukhdas', 'hindi', '।।2.60।। हे कुन्तीनन्दन! (रसबुद्धि रहनेसे) यत्न करते हुए विद्वान् मनुष्यकी भी प्रमथनशील इन्द्रियाँ उसके मनको बलपूर्वक हर लेती हैं।'),
('99635629-a2c3-598e-92c2-f2d294245189'::uuid, '82994df3-345e-54c7-8495-6eb8efae7a35'::uuid, 'tejomayananda', 'hindi', '।।2.60।। हे कौन्तेय  (संयम का) प्रयत्न करते हुए बुद्धिमान (विपश्चित) पुरुष के भी मन को ये इन्द्रियां बलपूर्वक हर लेती हैं।।'),
('16b1c946-cd8a-5573-9de8-18525fa48cb7'::uuid, '4ab5cad6-0867-574b-b68b-e9db11d0a633'::uuid, 'ramsukhdas', 'hindi', '।।2.61।। कर्मयोगी साधक उन सम्पूर्ण इन्द्रियोंको वशमें करके मेरे परायण होकर बैठे; क्योंकि जिसकी इन्द्रियाँ वशमें हैं, उसकी बुद्धि प्रतिष्ठित है।'),
('1b9a066f-7665-5dbe-aecb-cf46c700aeb1'::uuid, '4ab5cad6-0867-574b-b68b-e9db11d0a633'::uuid, 'tejomayananda', 'hindi', '।।2.61।। उन सब इन्द्रियों को संयमित कर युक्त और मत्पर होवे। जिस पुरुष की इन्द्रियां वश में होती हैं? उसकी प्रज्ञा प्रतिष्ठित होती है।।'),
('2820e67b-b65e-593d-bdf9-ef1d4a89d66c'::uuid, '6cde0a0c-ad48-5de1-8cea-c6158bf8708f'::uuid, 'ramsukhdas', 'hindi', '।।2.62 -- 2.63।। विषयोंका चिन्तन करनेवाले मनुष्यकी उन विषयोंमें आसक्ति पैदा हो जाती है। आसक्तिसे कामना पैदा होती है। कामनासे क्रोध पैदा होता है। क्रोध होनेपर सम्मोह (मूढ़भाव) हो जाता है। सम्मोहसे स्मृति भ्रष्ट हो जाती है। स्मृति भ्रष्ट होनेपर बुद्धिका नाश हो जाता है। बुद्धिका नाश होनेपर मनुष्यका पतन हो जाता है।'),
('ed5604b6-c410-5962-bfe2-e3ef6d9fca81'::uuid, '6cde0a0c-ad48-5de1-8cea-c6158bf8708f'::uuid, 'tejomayananda', 'hindi', '।।2.62।। विषयों का चिन्तन करने वाले पुरुष की उसमें आसक्ति हो जाती है? आसक्ति से इच्छा और इच्छा से क्रोध उत्पन्न होता है।।'),
('70db70d1-cc95-5739-a8cc-e880529ec34d'::uuid, '17e4dd97-7fef-5671-8a06-f261cc089cd6'::uuid, 'ramsukhdas', 'hindi', '।।2.62 -- 2.63।। विषयोंका चिन्तन करनेवाले मनुष्यकी उन विषयोंमें आसक्ति पैदा हो जाती है। आसक्तिसे कामना पैदा होती है। कामनासे क्रोध पैदा होता है। क्रोध होनेपर सम्मोह (मूढ़भाव) हो जाता है। सम्मोहसे स्मृति भ्रष्ट हो जाती है। स्मृति भ्रष्ट होनेपर बुद्धिका नाश हो जाता है। बुद्धिका नाश होनेपर मनुष्यका पतन हो जाता है।'),
('1bbe97cf-8503-5531-bf56-9a872826471e'::uuid, '17e4dd97-7fef-5671-8a06-f261cc089cd6'::uuid, 'tejomayananda', 'hindi', '।।2.63।। क्रोध से उत्पन्न होता है मोह और मोह से स्मृति विभ्रम। स्मृति के भ्रमित होने पर बुद्धि का नाश होता है और बुद्धि के नाश होने से वह मनुष्य नष्ट हो जाता है।।'),
('6b2d4058-15fa-5197-82fc-f6c44ed0cf18'::uuid, '51cb2cd0-9a71-54c9-ad94-c1c5b9671e3e'::uuid, 'ramsukhdas', 'hindi', '।।2.64 -- 2.65।। वशीभूत अन्तःकरणवाला कर्मयोगी साधक रागद्वेषसे रहित अपने वशमें की हुई इन्द्रियोंके द्वारा विषयोंका सेवन करता हुआ अन्तःकरणकी निर्मलता को प्राप्त हो जाता है। निर्मलता प्राप्त होनेपर साधकके सम्पूर्ण दुःखोंका नाश हो जाता है और ऐसे शुद्ध चित्तवाले साधककी बुद्धि निःसन्देह बहुत जल्दी परमात्मामें स्थिर हो जाती है।'),
('1f2207c0-4ceb-5ee3-b331-36a12559f3a0'::uuid, '51cb2cd0-9a71-54c9-ad94-c1c5b9671e3e'::uuid, 'tejomayananda', 'hindi', '।।2.64।। आत्मसंयमी (विधेयात्मा) पुरुष रागद्वेष से रहित अपने वश में की हुई (आत्मवश्यै) इन्द्रियों द्वारा विषयों को भोगता हुआ प्रसन्नता (प्रस्ेााद) प्राप्त करता है।।'),
('df51af21-a1a4-57ce-9b16-067bcbccb4a5'::uuid, '16572170-4087-5539-a220-b91708ae1b68'::uuid, 'ramsukhdas', 'hindi', '।।2.64 -- 2.65।। वशीभूत अन्तःकरणवाला कर्मयोगी साधक रागद्वेषसे रहित अपने वशमें की हुई इन्द्रियोंके द्वारा विषयोंका सेवन करता हुआ अन्तःकरणकी निर्मलता को प्राप्त हो जाता है। निर्मलता प्राप्त होनेपर साधकके सम्पूर्ण दुःखोंका नाश हो जाता है और ऐसे शुद्ध चित्तवाले साधककी बुद्धि निःसन्देह बहुत जल्दी परमात्मामें स्थिर हो जाती है।'),
('9a7a6369-27af-5223-9ac7-33fb1d20d4c0'::uuid, '16572170-4087-5539-a220-b91708ae1b68'::uuid, 'tejomayananda', 'hindi', '।।2.65।। प्रसाद के होने पर सम्पूर्ण दुखों का अन्त हो जाता है और प्रसन्नचित्त पुरुष की बुद्धि ही शीघ्र ही स्थिर हो जाती है।।'),
('ca8aebcd-44a1-5fb8-826c-230336b2e0ac'::uuid, '7cc34c3c-32d2-5834-9ff0-052dde4d971a'::uuid, 'ramsukhdas', 'hindi', '।।2.66।। जिसके मन-इन्द्रियाँ संयमित नहीं हैं, ऐसे मनुष्यकी व्यवसायात्मिका बुद्धि नहीं होती और व्यवसायात्मिका बुद्धि न होनेसे उसमें कर्तव्यपरायणताकी भावना नहीं होती। ऐसी भावना न होनेसे उसको शान्ति नहीं मिलती। फिर शान्तिरहित मनुष्यको सुख कैसे मिल सकता है?'),
('a8f8146e-623e-5f56-8f9b-994797f412ce'::uuid, '7cc34c3c-32d2-5834-9ff0-052dde4d971a'::uuid, 'tejomayananda', 'hindi', '।।2.66।। (संयमरहित) अयुक्त पुरुष को (आत्म) ज्ञान नहीं होता और अयुक्त को भावना और ध्यान की क्षमता नहीं होती भावना रहित पुरुष को शान्ति नहीं मिलती अशान्त पुरुष को सुख कहाँ '),
('ba93acdd-f7f0-51f5-b126-ad49eeb99a3f'::uuid, '772d15da-2bfc-5c9e-9b86-9b7a5afd91d7'::uuid, 'ramsukhdas', 'hindi', '।।2.67।। अपने-अपने विषयोंमें विचरती हुई इन्द्रियोंमेंसे एक ही इन्द्रिय जिस मनको अपना अनुगामी बना लेती है, वह अकेला मन जलमें नौकाको वायुकी तरह इसकी बुद्धिको हर लेता है।'),
('948f95bd-1ff5-5618-ae1e-55976234648d'::uuid, '772d15da-2bfc-5c9e-9b86-9b7a5afd91d7'::uuid, 'tejomayananda', 'hindi', '।।2.67।। जल में वायु जैसे नाव को हर लेता है वैसे ही विषयों में विरचती हुई इन्द्रियों के बीच में जिस इन्द्रिय का अनुकरण मन करता है? वह एक ही इन्द्रिय इसकी प्रज्ञा को हर लेती है।।'),
('226b23e7-a5d3-555a-b754-f15f70256702'::uuid, 'ff3e1ded-4ed7-5227-af39-8120764eac46'::uuid, 'ramsukhdas', 'hindi', '।।2.68।। इसलिये हे महाबाहो ! जिस मनुष्यकी इन्द्रियाँ इन्द्रियोंके विषयोंसे सर्वथा निगृहीत (वशमें की हुई) हैं, उसकी बुद्धि स्थिर है।'),
('734a7289-6437-58f2-a1be-760c0481c594'::uuid, 'ff3e1ded-4ed7-5227-af39-8120764eac46'::uuid, 'tejomayananda', 'hindi', '।।2.68।। इसलिये? हे महाबाहो  जिस पुरुष की इन्द्रियाँ सब प्रकार इन्द्रियों के विषयों के वश में की हुई होती हैं? उसकी बुद्धि स्थिर होती है।।'),
('4a260448-3429-58e4-bcfd-8d704d2c8510'::uuid, 'f7156de3-e067-532d-a977-e9b11a843925'::uuid, 'ramsukhdas', 'hindi', '।।2.69।। सम्पूर्ण प्राणियों की जो रात (परमात्मासे विमुखता) है, उसमें संयमी मनुष्य जागता है, और जिसमें सब प्राणी जागते हैं (भोग और संग्रहमें लगे रहते हैं), वह तत्त्वको जाननेवाले मुनिकी दृष्टिमें रात है।'),
('845b3367-b3ff-529e-8d0b-75eeb8cd71c2'::uuid, 'f7156de3-e067-532d-a977-e9b11a843925'::uuid, 'tejomayananda', 'hindi', '।।2.69।। सब प्रणियों के लिए जो रात्रि है? उसमें संयमी पुरुष जागता है और जहाँ सब प्राणी जागते हैं? वह (तत्त्व को) देखने वाले मुनि के लिए रात्रि है।।'),
('fe28385f-7f98-513e-9fc7-4a43cb8a5189'::uuid, '4d95e69a-b998-5628-9eb2-f4885bd63d1a'::uuid, 'ramsukhdas', 'hindi', '।।2.70।। जैसे सम्पूर्ण नदियोंका जल चारों ओरसे जलद्वारा परिपूर्ण समुद्रमें आकर मिलता है, पर समुद्र अपनी मर्यादामें अचल प्रतिष्ठित रहता है ऐसे ही सम्पूर्ण भोग-पदार्थ जिस संयमी मनुष्य को विकार उत्पन्न किये बिना ही उसको प्राप्त होते हैं, वही मनुष्य परमशान्तिको प्राप्त होता है, भोगोंकी कामनावाला नहीं।'),
('9e3b0276-1e28-5086-8d86-1ad78aba8282'::uuid, '4d95e69a-b998-5628-9eb2-f4885bd63d1a'::uuid, 'tejomayananda', 'hindi', '।।2.70।। जैसे सब ओर से परिपूर्ण अचल प्रतिष्ठा वाले समुद्र में (अनेक नदियों के) जल (उसे विचलित किये बिना) समा जाते हैं? वैसे ही जिस पुरुष के प्रति कामनाओं के विषय उसमें (विकार उत्पन्न किये बिना) समा जाते हैं? वह पुरुष शान्ति प्राप्त करता है? न कि भोगों की कामना करने वाला पुरुष।।'),
('081ec05c-5ce6-5178-a29a-4c2e792f1905'::uuid, '84ce9535-31d1-511a-8a9c-f42ce6b49dd5'::uuid, 'ramsukhdas', 'hindi', '।।2.71।। जो मनुष्य सम्पूर्ण कामनाओंका त्याग करके स्पृहारहित, ममतारहित और अहंकाररहित होकर आचरण करता है, वह शान्तिको प्राप्त होता है।'),
('2b832e74-c3be-5775-be5e-e91c61945fa9'::uuid, '84ce9535-31d1-511a-8a9c-f42ce6b49dd5'::uuid, 'tejomayananda', 'hindi', '।।2.71।। जो पुरुष सब कामनाओं को त्यागकर स्पृहारहित? ममभाव रहित और निरहंकार हुआ विचरण करता है? वह शान्ति प्राप्त करता है।।'),
('c36c4759-2e9c-5ab0-bcce-3f7ff6cfa5d5'::uuid, '90350f08-a6d4-5dec-abc5-e67e0e307d43'::uuid, 'ramsukhdas', 'hindi', '।।2.72।। हे पृथानन्दन ! यह ब्राह्मी स्थिति है। इसको प्राप्त होकर कभी कोई मोहित नहीं होता। इस स्थितिमें यदि अन्तकालमें भी स्थित हो जाय, तो निर्वाण (शान्त) ब्रह्मकी प्राप्ति हो जाती है।'),
('7537b235-a808-5a44-9d7b-b82b195269ab'::uuid, '90350f08-a6d4-5dec-abc5-e67e0e307d43'::uuid, 'tejomayananda', 'hindi', '।।2.72।। हे पार्थ  यह ब्राह्मी स्थिति है। इसे प्राप्त कर पुरुष मोहित नहीं होता। अन्तकाल में भी इस निष्ठा में स्थित होकर ब्रह्मनिर्वाण (ब्रह्म के साथ एकत्व) को प्राप्त होता है।।'),
('7884ed29-8fce-56ae-8205-06d2e2ae631e'::uuid, '642345b9-6cd6-53fd-a745-898ff599b660'::uuid, 'ramsukhdas', 'hindi', '।।3.1 -- 3.2।। अर्जुन बोले -- हे जनार्दन! अगर आप कर्मसे बुद्धि- (ज्ञान-) को श्रेष्ठ मानते हैं, तो फिर हे केशव ! मुझे घोर कर्ममें क्यों लगाते हैं ? आप अपने मिले हुए-से वचनोंसे मेरी बुद्धिको मोहित-सी कर रहे हैं। अतः आप निश्चय करके उस एक बात को कहिये, जिससे मैं कल्याणको प्राप्त हो जाऊँ।'),
('61ccf430-6d5a-5e25-b8ca-39b64ba4110d'::uuid, '642345b9-6cd6-53fd-a745-898ff599b660'::uuid, 'tejomayananda', 'hindi', '।।3.1।। हे जनार्दन  यदि आपको यह मान्य है कि कर्म से ज्ञान श्रेष्ठ है तो फिर हे केशव  आप मुझे इस भयंकर कर्म में क्यों प्रवृत्त करते हैं'),
('395bd19c-ccdb-5f0e-a96c-0a19b9ba0b34'::uuid, 'a05cd567-8f51-5734-a55e-cf88e2c8bb67'::uuid, 'ramsukhdas', 'hindi', '।।3.1 -- 3.2।। अर्जुन बोले -- हे जनार्दन! अगर आप कर्मसे बुद्धि- (ज्ञान-) को श्रेष्ठ मानते हैं, तो फिर हे केशव! मुझे घोर कर्ममें क्यों लगाते हैं ? आप अपने मिले हुए-से वचनोंसे मेरी बुद्धिको मोहित-सी कर रहे हैं। अतः आप निश्चय करके एक बात को कहिये, जिससे मैं कल्याणको प्राप्त हो जाऊँ।'),
('f59c9294-4c8d-5539-a5e7-99abddb846f5'::uuid, 'a05cd567-8f51-5734-a55e-cf88e2c8bb67'::uuid, 'tejomayananda', 'hindi', '।।3.2।। आप इस मिश्रित वाक्य से मेरी बुद्धि को मोहितसा करते हैं अत आप उस एक (मार्ग) को निश्चित रूप से कहिये जिससे मैं परम श्रेय को प्राप्त कर सकूँ।।'),
('a0e76f61-0659-5a8a-bef8-0d638b48dec2'::uuid, '0fdee932-dce7-51d5-8585-e8abe7edcf99'::uuid, 'ramsukhdas', 'hindi', '।।3.3।। श्रीभगवान् बोले - हे निष्पाप अर्जुन! इस मनुष्यलोकमें दो प्रकारसे होनेवाली निष्ठा मेरे द्वारा पहले कही गयी है। उनमें ज्ञानियोंकी निष्ठा ज्ञानयोगसे और योगियोंकी निष्ठा कर्मयोगसे होती है।'),
('422685ab-b4f5-52e3-8649-427ba4fcdf6d'::uuid, '0fdee932-dce7-51d5-8585-e8abe7edcf99'::uuid, 'tejomayananda', 'hindi', '।।3.3।। श्री भगवान् ने कहा  हे निष्पाप (अनघ) अर्जुन  इस श्लोक में दो प्रकार की निष्ठा मेरे द्वारा पहले कही गयी है ज्ञानियों की (सांख्यानां) ज्ञानयोग से और योगियों की कर्मयोग से।।'),
('c565033d-36b7-5ad9-864c-753664a5e4fc'::uuid, 'dc57ccd7-d9b7-537b-8c0c-5238994d6325'::uuid, 'ramsukhdas', 'hindi', '।।3.4।। मनुष्य न तो कर्मोंका आरम्भ किये बिना निष्कर्मताको प्राप्त होता है और न कर्मोंके त्यागमात्रसे सिद्धिको ही प्राप्त होता है।'),
('f34ad791-21e9-51f3-977e-5f0a4bf53595'::uuid, 'dc57ccd7-d9b7-537b-8c0c-5238994d6325'::uuid, 'tejomayananda', 'hindi', '।।3.4।। कर्मों के न करने से मनुष्य नैर्ष्कम्य को प्राप्त नहीं होता और न कर्मों के संन्यास से ही वह सिद्धि (पूर्णत्व) प्राप्त करता है।।'),
('da042789-b3c7-5de8-aff4-9c18cde20f4e'::uuid, '694b87d1-7dc9-55c3-8020-a358e1d8e014'::uuid, 'ramsukhdas', 'hindi', '।।3.5।। कोई भी मनुष्य किसी भी अवस्थामें क्षणमात्र भी कर्म किये बिना नहीं रह सकता; क्योंकि (प्रकृतिके) परवश हुए सब प्राणियोंसे प्रकृतिजन्य गुण कर्म कराते हैं।'),
('3313b6a9-a80d-56b3-9a0c-44542fdf67e0'::uuid, '694b87d1-7dc9-55c3-8020-a358e1d8e014'::uuid, 'tejomayananda', 'hindi', '।।3.5।। कोई भी पुरुष कभी क्षणमात्र भी बिना कर्म किए नहीं रह सकता क्योंकि प्रकृति से उत्पन्न गुणों के द्वारा अवश हुए सब (पुरुषों) से कर्म करवा लिया जाता है।।'),
('e37eb4bb-fa8f-51ce-b260-e33f0ee9338c'::uuid, 'c75a64bd-71b5-5e3f-892b-0ced0b633dd2'::uuid, 'ramsukhdas', 'hindi', '।।3.6।। जो कर्मेन्द्रियों- (सम्पूर्ण इन्द्रियों-) को हठपूर्वक रोककर मनसे इन्द्रियोंके विषयोंका चिन्तन करता रहता है, वह मूढ़ बुद्धिवाला मनुष्य मिथ्याचारी (मिथ्या आचरण करनेवाला) कहा जाता है।'),
('5260fead-ab0e-5bec-af4f-1ef0e7a3d9f3'::uuid, 'c75a64bd-71b5-5e3f-892b-0ced0b633dd2'::uuid, 'tejomayananda', 'hindi', '।।3.6।। जो मूढ बुद्धि पुरुष कर्मेन्द्रियों का निग्रह कर इन्द्रियों के भोगों का मन से स्मरण (चिन्तन) करता रहता है वह मिथ्याचारी (दम्भी) कहा जाता है।।'),
('7438d047-d454-5b00-acce-4856a583b5f9'::uuid, 'bb8ff35c-911b-5e58-ab5b-780a9cd158a3'::uuid, 'ramsukhdas', 'hindi', '।।3.7।। हे अर्जुन! जो मनुष्य मनसे इन्द्रियोंपर नियन्त्रण करके आसक्तिरहित होकर (निष्काम भावसे) समस्त इन्द्रियोंके द्वारा कर्मयोगका आचरण करता है, वही श्रेष्ठ है।'),
('2116679e-105e-58f8-b782-40bcdfc4da7c'::uuid, 'bb8ff35c-911b-5e58-ab5b-780a9cd158a3'::uuid, 'tejomayananda', 'hindi', '।।3.7।। परन्तु हे अर्जुन  जो पुरुष मन से इन्द्रियों को वश में करके अनासक्त हुआ कर्मेंन्द्रियों से कर्मयोग का आचरण करता है वह श्रेष्ठ है।।'),
('464ff6bc-2177-5035-992f-198470408a4c'::uuid, 'da0afc0f-2bc2-5875-accb-5f40204e5bc7'::uuid, 'ramsukhdas', 'hindi', '।।3.8।। तू शास्त्रविधिसे नियत किये हुए कर्तव्य-कर्म कर; क्योंकि कर्म न करनेकी अपेक्षा कर्म करना श्रेष्ठ है तथा कर्म न करनेसे तेरा शरीर-निर्वाह भी सिद्ध नहीं होगा।'),
('8c881ef3-442e-5f77-8260-4b423e6fd0f8'::uuid, 'da0afc0f-2bc2-5875-accb-5f40204e5bc7'::uuid, 'tejomayananda', 'hindi', '।।3.8।। तुम (अपने) नियत (कर्तव्य) कर्म करो क्योंकि अकर्म से श्रेष्ठ कर्म है। तुम्हारे अकर्म होने से (तुम्हारा) शरीर निर्वाह भी नहीं सिद्ध होगा।।'),
('688628ba-a058-5898-87d3-b79837e38ac7'::uuid, '51171b67-ae21-551a-b660-a9234c980200'::uuid, 'ramsukhdas', 'hindi', '।।3.9।। यज्ञ (कर्तव्यपालन) के लिये किये जानेवाले कर्मोंसे अन्यत्र (अपने लिये किये जानेवाले) कर्मोंमें लगा हुआ यह मनुष्य-समुदाय कर्मोंसे बँधता है, इसलिये हे कुन्तीनन्दन ! तू आसक्ति-रहित होकर उस यज्ञके लिये ही कर्तव्य-कर्म कर।'),
('056af921-4b84-552a-b16b-b045d2369244'::uuid, '51171b67-ae21-551a-b660-a9234c980200'::uuid, 'tejomayananda', 'hindi', '।।3.9।। यज्ञ के लिये किये हुए कर्म के अतिरिक्त अन्य कर्म में प्रवृत्त हुआ यह पुरुष कर्मों द्वारा बंधता है इसलिए हे कौन्तेय आसक्ति को त्यागकर यज्ञ के निमित्त ही कर्म का सम्यक् आचरण करो।।'),
('9aef0cd5-5655-528f-a4c6-15dd92bda5fb'::uuid, 'b4d64f6f-10e9-594b-980c-c1fc6091425c'::uuid, 'ramsukhdas', 'hindi', '।।3.10 -- 3.11।। प्रजापति ब्रह्माजीने सृष्टिके आदिकालमें कर्तव्य-कर्मोंके विधानसहित प्रजा-(मनुष्य आदि-) की रचना करके उनसे (प्रधानतया मनुष्योंसे) कहा कि तुमलोग इस कर्तव्यके द्वारा सबकी वृद्धि करो और वह कर्तव्य-कर्म-रूप यज्ञ तुमलोगोंको कर्तव्य-पालनकी आवश्यक सामग्री प्रदान करनेवाला हो। अपने कर्तव्य-कर्मके द्वारा तुमलोग देवताओंको उन्नत करो और वे देवतालोग अपने कर्तव्यके द्वारा तुमलोगोंको उन्नत करें। इस प्रकार एक-दूसरेको उन्नत करते हुए तुमलोग परम कल्याणको प्राप्त हो जाओगे।'),
('e6a3ab0e-cf50-52d6-b6a6-9e9627893f69'::uuid, 'b4d64f6f-10e9-594b-980c-c1fc6091425c'::uuid, 'tejomayananda', 'hindi', '।।3.10।। प्रजापति (सृष्टिकर्त्ता) ने (सृष्टि के) आदि में यज्ञ सहित प्रजा का निर्माण कर कहा इस यज्ञ द्वारा तुम वृद्धि को प्राप्त हो और यह यज्ञ तुम्हारे लिये इच्छित कामनाओं को पूर्ण करने वाला (इष्टकामधुक्) होवे।।'),
('65e8443d-6950-586e-b4ff-864cf139d391'::uuid, '6535e4a9-946a-5236-8f88-6f5663fa44b3'::uuid, 'ramsukhdas', 'hindi', '।।3.10 -- 3.11।। प्रजापति ब्रह्माजीने सृष्टिके आदिकालमें कर्तव्य-कर्मोंके विधानसहित प्रजा-(मनुष्य आदि-) की रचना करके (उनसे, प्रधानतया मनुष्योंसे) कहा कि तुमलोग इस कर्तव्यके द्वारा सबकी वृद्धि करो और वह कर्तव्य-कर्म-रूप यज्ञ तुमलोगोंको कर्तव्य-पालनकी आवश्यक सामग्री प्रदान करनेवाला हो। अपने कर्तव्य-कर्मके द्वारा तुमलोग देवताओंको उन्नत करो और वे देवतालोग अपने कर्तव्यके द्वारा तुमलोगोंको उन्नत करें। इस प्रकार एक-दूसरेको उन्नत करते हुए तुमलोग परम कल्याणको प्राप्त हो जाओगे।'),
('6d8a2394-1ca8-52d1-9d85-683e728d36c6'::uuid, '6535e4a9-946a-5236-8f88-6f5663fa44b3'::uuid, 'tejomayananda', 'hindi', '।।3.11।। तुम लोग इस यज्ञ द्वारा देवताओं की उन्नति करो और वे देवतागण तुम्हारी उन्नति करें। इस प्रकार परस्पर उन्नति करते हुये परम श्रेय को तुम प्राप्त होगे।।'),
('d9a7c624-9b3e-5db2-ad28-76f6d873d059'::uuid, 'd8648255-5bda-5733-876c-74994b2ec9cc'::uuid, 'ramsukhdas', 'hindi', '।।3.12।। यज्ञसे भावित (पुष्ट) हुए देवता भी तुमलोगोंको (बिना माँगे ही) कर्तव्य-पालनकी आवश्यक सामग्री देते रहेंगे। इस प्रकार उन देवताओंसे प्राप्त हुई सामग्रीको दूसरोंकी सेवामें लगाये बिना जो मनुष्य स्वयं ही उसका उपभोग करता है, वह चोर ही है।'),
('56a8b9d3-549d-5405-b55c-bc1366a89dca'::uuid, 'd8648255-5bda-5733-876c-74994b2ec9cc'::uuid, 'tejomayananda', 'hindi', '।।3.12।। यज्ञ द्वारा पोषित देवतागण तुम्हें इष्ट भोग प्रदान करेंगे। उनके द्वारा दिये हुये भोगों को जो पुरुष उनको दिये बिना ही भोगता है वह निश्चय ही चोर है।।'),
('ac07dc8b-695a-5593-800b-46c65ca3d1d2'::uuid, '30dcdf09-d955-5bc0-a1ec-00e65b42aac3'::uuid, 'ramsukhdas', 'hindi', '।।3.13।। यज्ञशेष- (योग-) का अनुभव करनेवाले श्रेष्ठ मनुष्य सम्पूर्ण पापोंसे मुक्त हो जाते हैं। परन्तु जो केवल अपने लिये ही पकाते अर्थात् सब कर्म करते हैं, वे पापीलोग तो पापका ही भक्षण करते हैं।'),
('443d03a3-b81a-5507-9666-ccdcd354ca23'::uuid, '30dcdf09-d955-5bc0-a1ec-00e65b42aac3'::uuid, 'tejomayananda', 'hindi', '।।3.13।। यज्ञ के अवशिष्ट अन्न को खाने वाले श्रेष्ठ पुरुष सब पापों से मुक्त हो जाते हैं किन्तु जो लोग केवल स्वयं के लिये ही पकाते हैं वे तो पापों को ही खाते हैं।।'),
('86f95b6e-5f36-58b1-9e92-b193bcc29c92'::uuid, 'e70eda3d-179a-5302-8cc8-faf33f91be49'::uuid, 'ramsukhdas', 'hindi', '।।3.14 -- 3.15।। सम्पूर्ण प्राणी अन्नसे उत्पन्न होते हैं। अन्न  वर्षासे होती है। वर्षा यज्ञसे होती है। यज्ञ कर्मोंसे निष्पन्न होता है। कर्मोंको तू वेदसे उत्पन्न जान और वेदको अक्षरब्रह्मसे प्रकट हुआ जान। इसलिये वह सर्वव्यापी परमात्मा यज्ञ (कर्तव्य-कर्म) में नित्य प्रतिष्ठित है।'),
('23833ec3-bb5c-546d-8357-72ef2774845b'::uuid, 'e70eda3d-179a-5302-8cc8-faf33f91be49'::uuid, 'tejomayananda', 'hindi', '।।3.14।। समस्त प्राणी अन्न से उत्पन्न होते हैं अन्न की उत्पत्ति पर्जन्य से। पर्जन्य की उत्पत्ति यज्ञ से और यज्ञ कर्मों से उत्पन्न होता है।।'),
('568c891f-e1ce-58c4-8d0b-8100547dadc8'::uuid, '5c3ddb00-90a4-5c8c-ac9b-978fecca99e1'::uuid, 'ramsukhdas', 'hindi', '।।3.14 -- 3.15।। सम्पूर्ण प्राणी अन्नसे उत्पन्न होते हैं। अन्न  वर्षासे होती है। वर्षा यज्ञसे होती है। यज्ञ कर्मोंसे निष्पन्न होता है। कर्मोंको तू वेदसे उत्पन्न जान और वेदको अक्षरब्रह्मसे प्रकट हुआ जान। इसलिये वह सर्वव्यापी परमात्मा यज्ञ (कर्तव्य-कर्म) में नित्य प्रतिष्ठित है।'),
('5715eaca-ea7c-52be-b8bc-7770e17cf48c'::uuid, '5c3ddb00-90a4-5c8c-ac9b-978fecca99e1'::uuid, 'tejomayananda', 'hindi', '।।3.15।। कर्म की उत्पत्ति ब्रह्माजी से होती है और ब्रह्माजी अक्षर तत्त्व से व्यक्त होते हैं। इसलिये सर्व व्यापी ब्रह्म सदा ही यज्ञ में प्रतिष्ठित है।।'),
('92564fd7-dbe0-5931-a422-6c61c360db5a'::uuid, '6943c13a-442c-5fda-9280-1efde3c2789f'::uuid, 'ramsukhdas', 'hindi', '।।3.16।। हे पार्थ! जो मनुष्य इस लोकमें इस प्रकार परम्परासे प्रचलित सृष्टिचक्रके अनुसार नहीं चलता, वह इन्द्रियोंके द्वारा भोगोंमें रमण करनेवाला अघायु (पापमय जीवन बितानेवाला) मनुष्य संसारमें व्यर्थ ही जीता है।'),
('15b2632c-3e66-5f40-ba81-7d52b6735b86'::uuid, '6943c13a-442c-5fda-9280-1efde3c2789f'::uuid, 'tejomayananda', 'hindi', '।।3.16।। जो पुरुष यहाँ इस प्रकार प्रवर्तित हुए चक्र का अनुवर्तन नहीं करता हे पार्थ इंन्द्रियों में रमने वाला वह पाप आयु पुरुष व्यर्थ ही जीता है।।'),
('8bd76de3-0ac7-5149-86d6-8db68f3942dd'::uuid, 'bccb8135-facd-5266-8567-729951c1bfe8'::uuid, 'ramsukhdas', 'hindi', '।।3.17।।  जो मनुष्य अपने-आपमें ही रमण करनेवाला और अपने-आपमें ही तृप्त तथा अपने-आपमें ही संतुष्ट है, उसके लिये कोई कर्तव्य नहीं है।'),
('a54cd1cb-854a-51ad-ab74-5c6f68d6c944'::uuid, 'bccb8135-facd-5266-8567-729951c1bfe8'::uuid, 'tejomayananda', 'hindi', '।।3.17।। परन्तु जो मनुष्य आत्मा में ही रमने वाला आत्मा में ही तृप्त तथा आत्मा में ही सन्तुष्ट हो उसके लिये कोई कर्तव्य नहीं रहता।।'),
('889b9a19-2f74-5200-9aa1-4c003570fa82'::uuid, '51c4f40f-993e-5226-a4d2-d3beba3277e7'::uuid, 'ramsukhdas', 'hindi', '।।3.18।। उस (कर्मयोगसे सिद्ध हुए) महापुरुषका इस संसारमें न तो कर्म करनेसे कोई प्रयोजन रहता है, और न कर्म न करनेसे ही कोई प्रयोजन रहता है, तथा सम्पूर्ण प्राणियोंमें (किसी भी प्राणीके साथ) इसका किञ्चिन्मात्र भी स्वार्थका सम्बन्ध नहीं रहता।'),
('fc1689f4-f5af-5022-b588-35741c16850e'::uuid, '51c4f40f-993e-5226-a4d2-d3beba3277e7'::uuid, 'tejomayananda', 'hindi', '।।3.18।। इस जगत् में उस पुरुष का कृत और अकृत से कोई प्रयोजन नहीं है और न वह किसी वस्तु के लिये भूतमात्र पर आश्रित होता है।।'),
('90ff0332-3e2c-5b49-b618-e77f6ba898d8'::uuid, '06fd4067-6275-53e0-b76b-d63746b83f6c'::uuid, 'ramsukhdas', 'hindi', '।।3.19।। इसलिये तू निरन्तर आसक्तिरहित होकर कर्तव्य-कर्मका भलीभाँति आचरण कर; क्योंकि आसक्तिरहित होकर कर्म करता हुआ मनुष्य परमात्माको प्राप्त हो जाता है।'),
('0dbb7d36-cb36-5f38-9c16-ffa610429707'::uuid, '06fd4067-6275-53e0-b76b-d63746b83f6c'::uuid, 'tejomayananda', 'hindi', '।।3.19।। इसलिए,  तुम अनासक्त होकर सदैव कर्तव्य कर्म का सम्यक् आचरण करो;  क्योकि,  अनासक्त पुरुष कर्म करता हुआ परमात्मा को प्राप्त होता है।।
 '),
('ec5184d6-c4db-56f3-a5bc-4d2f37c01705'::uuid, 'd2b07086-689c-5cab-9436-6428fc4eb543'::uuid, 'ramsukhdas', 'hindi', '।।3.20।। राजा जनक-जैसे अनेक महापुरुष भी कर्मके द्वारा ही परमसिद्धिको प्राप्त हुए हैं। इसलिये लोकसंग्रहको देखते हुए भी तू (निष्कामभावसे) कर्म करनेके योग्य है।'),
('0bba8b68-29cf-5c2a-bc82-0ee93d29c0d0'::uuid, 'd2b07086-689c-5cab-9436-6428fc4eb543'::uuid, 'tejomayananda', 'hindi', '।।3.20।। जनकादि (ज्ञानी जन) भी कर्म द्वारा ही संसिद्धि को प्राप्त हुये लोक संग्रह (लोक रक्षण) को भी देखते हुये;  तुम कर्म करने योग्य हो।।
 '),
('e4d29d94-b7b8-50b0-9b70-f481ebe43833'::uuid, '487bbb4e-9745-5da9-a56f-30bdf521760a'::uuid, 'ramsukhdas', 'hindi', '।।3.21।। श्रेष्ठ मनुष्य जो-जो आचरण करता है, दूसरे मनुष्य वैसा-वैसा ही आचरण करते हैं। वह जो कुछ प्रमाण  देता है,  दूसरे मनुष्य उसीके अनुसार आचरण करते हैं।'),
('1aa5ac76-181f-56d3-96d4-43093e37dd10'::uuid, '487bbb4e-9745-5da9-a56f-30bdf521760a'::uuid, 'tejomayananda', 'hindi', '।।3.21।। श्रेष्ठ पुरुष जैसा आचरण करता है, अन्य लोग भी वैसा ही अनुकरण करते हैं; वह पुरुष जो कुछ प्रमाण कर देता है, लोग भी उसका अनुसरण करते हैं।।
 '),
('cd28fda8-4699-5d9b-858b-7a58370b3008'::uuid, 'f8b9d024-8589-59d1-b5d5-b61c65cbb222'::uuid, 'ramsukhdas', 'hindi', '।।3.22।। हे पार्थ! मुझे तीनों लोकोंमें न तो कुछ कर्तव्य है और न कोई प्राप्त करनेयोग्य वस्तु अप्राप्त है, फिर भी मैं कर्तव्यकर्ममें ही लगा रहता हूँ।'),
('8e5a5cba-5f6d-5d13-a7cd-f5d19e7d28a4'::uuid, 'f8b9d024-8589-59d1-b5d5-b61c65cbb222'::uuid, 'tejomayananda', 'hindi', '।।3.22।। यद्यपि मुझे त्रैलोक्य में कुछ भी कर्तव्य नहीं हैं तथा किंचित भी प्राप्त होने योग्य (अवाप्तव्यम्) वस्तु अप्राप्त नहीं है, तो भी मैं कर्म में ही बर्तता हूँ।।
 '),
('c34608e7-8742-5ed8-8610-48b2a4bc454e'::uuid, '2f047970-ab62-50fb-8ec3-f956feea766b'::uuid, 'ramsukhdas', 'hindi', '।।3.23 -- 3.24।।  हे पार्थ! अगर मैं किसी समय सावधान होकर कर्तव्यकर्म न करूँ तो बड़ी हानि हो जाय; क्योंकि मनुष्य सब प्रकारसे मेरे ही मार्गका अनुसरण करते हैं। यदि मैं कर्म न करूँ, तो ये सब मनुष्य नष्ट-भ्रष्ट हो जायँ और मैं वर्णसंकरताको करनेवाला होऊँ तथा इस समस्त प्रजाको नष्ट करनेवाला बनूँ।'),
('334c2c5e-92d0-5afb-932f-cb7a516978c0'::uuid, '2f047970-ab62-50fb-8ec3-f956feea766b'::uuid, 'tejomayananda', 'hindi', '।।3.23।। यदि मैं सावधान हुआ (अतन्द्रित:) कदाचित कर्म में न लगा रहूँ तो, हे पार्थ ! सब प्रकार से मनुष्य मेरे मार्ग (र्वत्म) का अनुसरण करेंगे।।
 '),
('993f5134-908b-5d6a-b248-91b995a5cc13'::uuid, 'ce3f62ec-89d5-553f-9050-6e695bbec4c2'::uuid, 'ramsukhdas', 'hindi', '।।3.23 -- 3.24।।  हे पार्थ ! अगर मैं किसी समय सावधान होकर कर्तव्य-कर्म न करूँ (तो बड़ी हानि हो जाय; क्योंकि) मनुष्य सब प्रकारसे मेरे ही मार्गका अनुसरण करते हैं। यदि मैं कर्म न करूँ, तो ये सब मनुष्य नष्ट-भ्रष्ट हो जायँ और मैं वर्णसंकरताको करनेवाला  तथा इस समस्त प्रजाको नष्ट करनेवाला बनूँ।'),
('81177e18-08f9-5b51-860b-73fca6f8fb12'::uuid, 'ce3f62ec-89d5-553f-9050-6e695bbec4c2'::uuid, 'tejomayananda', 'hindi', '।।3.24।। यदि मैं कर्म न करूँ, तो ये समस्त लोक नष्ट हो जायेंगे; और मैं वर्णसंकर का कर्ता तथा इस प्रजा का हनन करने वाला होऊँगा।।
 '),
('54a7bbad-843b-5005-8cf3-ff6677cbd78a'::uuid, '1e24e90b-ece3-5e16-aeed-f6d687699003'::uuid, 'ramsukhdas', 'hindi', '।।3.25 -- 3.26।। हे भरतवंशोद्भव अर्जुन! कर्ममें आसक्त हुए अज्ञानीजन जिस प्रकार कर्म करते हैं, आसक्तिरहित विद्वान भी लोकसंग्रह करना चाहता हुआ उसी प्रकार कर्म करे।  तत्त्वज्ञ महापुरुष कर्मोंमें आसक्तिवाले अज्ञानी मनुष्योंकी बुद्धिमें भ्रम उत्पन्न न करे, प्रत्युत स्वयं समस्त कर्मोंको अच्छी तरहसे करता हुआ उनसे भी वैसे ही करवाये।'),
('cffcb052-b81b-5f40-8a2b-2663af865da4'::uuid, '1e24e90b-ece3-5e16-aeed-f6d687699003'::uuid, 'tejomayananda', 'hindi', '।।3.25।। हे भारत ! कर्म में आसक्त हुए अज्ञानीजन जैसे कर्म करते हैं वैसे ही विद्वान् पुरुष अनासक्त होकर, लोकसंग्रह (लोक कल्याण) की इच्छा से कर्म करे।।
 '),
('0af370f9-d4ca-5a04-9f0c-f7df3f6d2fae'::uuid, '9d743f97-ca3b-56f5-9dd5-71b39a53b737'::uuid, 'ramsukhdas', 'hindi', '।।3.25 -- 3.26।। हे भरतवंशोद्भव अर्जुन! कर्ममें आसक्त हुए अज्ञानीजन जिस प्रकार कर्म करते हैं आसक्तिरहित विद्वान भी लोकसंग्रह करना चाहता हुआ उसी प्रकार कर्म करे। सावधान तत्त्वज्ञ महापुरुष कर्मोंमें आसक्तिवाले अज्ञानी मनुष्योंकी बुद्धिमें भ्रम उत्पन्न न करे, प्रत्युत स्वयं समस्त कर्मोंको अच्छी तरहसे करता हुआ उनसे भी वैसे ही करवाये।'),
('188495d7-9ffd-5dc9-879b-eaf738518f77'::uuid, '9d743f97-ca3b-56f5-9dd5-71b39a53b737'::uuid, 'tejomayananda', 'hindi', '।।3.26।। ज्ञानी पुरुष, कर्मों में आसक्त अज्ञानियों की बुद्धि में भ्रम उत्पन्न न करे, स्वयं (भक्ति से) युक्त होकर कर्मों का सम्यक् आचरण कर, उनसे भी वैसा ही कराये।।
 '),
('5ead0a6b-cea4-54f3-88ac-b5f057f2dd9e'::uuid, '27a68d79-5e98-53c9-9d2b-1ffc15078dc1'::uuid, 'ramsukhdas', 'hindi', '।।3.27।। सम्पूर्ण कर्म सब प्रकारसे प्रकृतिके गुणोंद्वारा किये जाते हैं; परन्तु अहंकारसे मोहित अन्तःकरणवाला अज्ञानी मनुष्य ''मैं कर्ता हूँ'' -- ऐसा मानता है।'),
('e867700a-5b1c-5791-a7a2-a0a54092e052'::uuid, '27a68d79-5e98-53c9-9d2b-1ffc15078dc1'::uuid, 'tejomayananda', 'hindi', '।।3.27।। सम्पूर्ण कर्म प्रकृति के गुणों द्वारा किये जाते हैं, अहंकार से मोहित हुआ पुरुष,  "मैं कर्ता हूँ"  ऐसा मान लेता है।।
 '),
('633851ec-fb3a-564f-b81a-341e355c2b17'::uuid, '99499fef-d15b-5d8d-888d-60bd828020cc'::uuid, 'ramsukhdas', 'hindi', '।।3.28।।  हे महाबाहो! गुण-विभाग और कर्म-विभागको तत्त्वसे जाननेवाला महापुरुष ''सम्पूर्ण गुण ही गुणोंमें बरत रहे हैं'' --  ऐसा मानकर उनमें आसक्त नहीं होता।'),
('bba07d41-ec06-59e8-ac40-bff8df414c88'::uuid, '99499fef-d15b-5d8d-888d-60bd828020cc'::uuid, 'tejomayananda', 'hindi', '।।3.28।। परन्तु हे महाबाहो ! गुण और कर्म के विभाग के सत्य (तत्त्व)को जानने वाला ज्ञानी पुरुष यह जानकर कि "गुण गुणों में बर्तते हैं" (कर्म में) आसक्त नहीं होता।।
 '),
('5ada6ad9-dab3-5f64-ac2f-dadacf0fcfde'::uuid, '71a43934-b14f-5993-9477-a132180f2d5e'::uuid, 'ramsukhdas', 'hindi', '।।3.29।। प्रकृतिजन्य गुणोंसे अत्यन्त मोहित हुए अज्ञानी मनुष्य गुणों और कर्मोंमें आसक्त रहते हैं। उन पूर्णतया न समझनेवाले मन्दबुद्धि अज्ञानियोंको पूर्णतया जाननेवाला ज्ञानी मनुष्य विचलित न करे।'),
('4baf8bcd-c5e7-53f9-82ec-2f97f6748aa9'::uuid, '71a43934-b14f-5993-9477-a132180f2d5e'::uuid, 'tejomayananda', 'hindi', '।।3.29।। प्रकृति के गुणों से मोहित हुए पुरुष गुण और कर्म में आसक्त होते हैं, उन अपूर्ण ज्ञान वाले (अकृत्स्नविद:) मंदबुद्धि पुरुषों को पूर्ण ज्ञान प्राप्त पुरुष विचलित न करे।।
 '),
('8702e261-f633-5f79-a591-208ffcbba2b7'::uuid, '7a4eed63-0cc5-5860-afea-c9976b6dd369'::uuid, 'ramsukhdas', 'hindi', '।।3.30।। तू विवेकवती बुद्धिके द्वारा सम्पूर्ण कर्तव्य-कर्मोंको मेरे अर्पण करके कामना, ममता और संताप-रहित होकर युद्धरूप कर्तव्य-कर्मको कर।'),
('de4a38e1-54b5-5e7a-a0f4-9f5a6f78a3b1'::uuid, '7a4eed63-0cc5-5860-afea-c9976b6dd369'::uuid, 'tejomayananda', 'hindi', '।।3.30।। सम्पूर्ण कर्मों का मुझ में संन्यास करके,  आशा और ममता से रहित होकर,  संतापरहित हुए तुम युद्ध करो।।
 '),
('80ef8cd7-0cdb-54de-b176-bda9e79708be'::uuid, '6fec3a2f-5ba3-5a6c-9b51-b9aab858c5a9'::uuid, 'ramsukhdas', 'hindi', '।।3.31।। जो मनुष्य दोष-दृष्टिसे रहित होकर श्रद्धापूर्वक मेरे इस (पूर्वश्लोकमें वर्णित) मतका सदा अनुसरण करते हैं, वे भी कर्मोंके बन्धनसे मुक्त हो जाते हैं।'),
('113280c7-162d-5a82-b738-2b253cdf4000'::uuid, '6fec3a2f-5ba3-5a6c-9b51-b9aab858c5a9'::uuid, 'tejomayananda', 'hindi', '।।3.31।। जो मनुष्य दोष बुद्धि से रहित (अनसूयन्त:) और श्रद्धा से युक्त हुए सदा मेरे इस मत (उपदेश) का अनुष्ठानपूर्वक पालन करते हैं, वे कर्मों से (बन्धन से) मुक्त हो जाते हैं।।
 ')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('359db010-d674-5851-8d58-947b528a4dfa'::uuid, '43030554-33cf-5162-9640-65a7baf17b2a'::uuid, 'ramsukhdas', 'hindi', '।।3.32।। परन्तु जो मनुष्य मेरे इस मतमें दोष-दृष्टि करते हुए इसका अनुष्ठान नहीं करते, उन सम्पूर्ण ज्ञानोंमें मोहित और अविवेकी मनुष्योंको नष्ट हुए ही समझो।'),
('16c3c3c5-d5e8-59de-959a-90dcf494fce0'::uuid, '43030554-33cf-5162-9640-65a7baf17b2a'::uuid, 'tejomayananda', 'hindi', '।।3.32।। परन्तु जो दोष दृष्टि वाले मूढ़ लोग इस मेरे मत का पालन नहीं करते, उन सब ज्ञानों में मोहित चित्तवालों को नष्ट हुये ही तुम समझो।।
 '),
('db2b5a28-f5ca-56d3-ae14-4a4fdb7b7aca'::uuid, 'f8cd7d2c-d38e-5ffc-873d-e50ff9b5891e'::uuid, 'ramsukhdas', 'hindi', '।।3.33।। सम्पूर्ण प्राणी प्रकृतिको प्राप्त होते हैं। ज्ञानी महापुरुष भी अपनी प्रकृतिके अनुसार चेष्टा करता है। फिर इसमें किसीका हठ क्या करेगा?'),
('c7a6db8b-0f7f-5d29-961f-2d7cd873162e'::uuid, 'f8cd7d2c-d38e-5ffc-873d-e50ff9b5891e'::uuid, 'tejomayananda', 'hindi', '।।3.33।। ज्ञानवान् पुरुष भी अपनी प्रकृति के अनुसार चेष्टा करता है। सभी प्राणी अपनी प्रकृति पर ही जाते हैं, फिर इनमें (किसी का) निग्रह क्या करेगा।।
 '),
('6ff28408-7335-5633-9ed7-bb393efa7c42'::uuid, 'c203770a-c9c0-5c1b-bf34-7c48182df501'::uuid, 'ramsukhdas', 'hindi', '।।3.34।। इन्द्रिय-इन्द्रियके अर्थमें (प्रत्येक इन्द्रियके प्रत्येक विषयमें) मनुष्यके राग और द्वेष व्यवस्थासे (अनुकूलता और प्रतिकूलताको लेकर) स्थित हैं। मनुष्यको उन दोनोंके वशमें नहीं होना चाहिये; क्योंकि वे दोनों ही इसके (पारमार्थिक मार्गमें विघ्न डालनेवाले) शत्रु हैं।'),
('e63bd159-fca1-536c-9449-85e7f5e52f3d'::uuid, 'c203770a-c9c0-5c1b-bf34-7c48182df501'::uuid, 'tejomayananda', 'hindi', '।।3.34।। इन्द्रियइन्द्रिय (अर्थात् प्रत्येक इन्द्रिय) के विषय के प्रति (मन में) रागद्वेष रहते हैं;  मनुष्य को चाहिये कि वह उन दोनों के वश में न हो;  क्योंकि वे इसके (मनुष्य के) शत्रु हैं।।
 '),
('3046dc91-b249-52b3-9761-37d2e7909600'::uuid, '432ea4cf-676a-5296-9a2f-6df02ebe358c'::uuid, 'ramsukhdas', 'hindi', '।।3.35।। अच्छी तरह आचरणमें लाये हुए दूसरेके धर्मसे गुणोंकी कमीवाला अपना धर्म श्रेष्ठ है। अपने धर्ममें तो मरना भी कल्याणकारक है और दूसरेका धर्म भयको देनेवाला है।'),
('72819730-40ee-5966-8f1d-b9f2fa3b8763'::uuid, '432ea4cf-676a-5296-9a2f-6df02ebe358c'::uuid, 'tejomayananda', 'hindi', '।।3.35।। सम्यक् प्रकार से अनुष्ठित परधर्म की अपेक्षा गुणरहित स्वधर्म का पालन श्रेयष्कर है;  स्वधर्म में मरण कल्याणकारक है (किन्तु) परधर्म भय को देने वाला है।।
 '),
('6b45956f-e19c-585c-b720-aee103ef929e'::uuid, 'd7ec16ba-f4e9-5da1-8155-61b20bde7c85'::uuid, 'ramsukhdas', 'hindi', '।।3.36।। अर्जुन बोले - हे वार्ष्णेय ! फिर यह मनुष्य न चाहता हुआ भी जबर्दस्ती लगाये हुएकी तरह किससे प्रेरित होकर पापका आचरण करता है?'),
('f1e8d526-d299-52bc-8bca-4d6155d495f9'::uuid, 'd7ec16ba-f4e9-5da1-8155-61b20bde7c85'::uuid, 'tejomayananda', 'hindi', '।।3.36।। अर्जुन ने कहा -- हे वार्ष्णेय ! फिर यह पुरुष बलपूर्वक बाध्य किये हुये के समान अनिच्छा होते हुये भी किसके द्वारा प्रेरित होकर पाप का आचरण करता है?
 '),
('0f130a12-b91c-52e1-9559-5dacd31b047d'::uuid, '6251b0cf-367a-529c-a138-8b6cf7af8dcc'::uuid, 'ramsukhdas', 'hindi', '।।3.37।। श्रीभगवान् बोले - रजोगुणसे उत्पन्न हुआ  यह काम ही क्रोध  है। यह बहुत खानेवाला और महापापी है। इस विषयमें तू इसको ही वैरी जान।'),
('1e5929ea-3a3f-532e-afac-20ffe3ac862c'::uuid, '6251b0cf-367a-529c-a138-8b6cf7af8dcc'::uuid, 'tejomayananda', 'hindi', '।।3.37।। श्रीभगवान् ने कहा -- रजोगुण में उत्पन्न हुई यह ''कामना'' है,  यही क्रोध है; यह महाशना (जिसकी भूख बड़ी हो) और महापापी है, इसे ही तुम यहाँ (इस जगत् में) शत्रु जानो।।
 '),
('1c418c41-d437-5b54-bd7a-ac61abb5d16e'::uuid, '057a729b-56e7-52c4-9d1b-9248c2b16c52'::uuid, 'ramsukhdas', 'hindi', '।।3.38।। जैसे धुएँसे अग्नि और मैलसे दर्पण ढक जाता है तथा जैसे जेरसे गर्भ ढका रहता है, ऐसे ही उस कामके द्वारा यह ज्ञान ( विवेक) ढका हुआ है।'),
('b2744a2a-8aed-5685-b36c-f98b85cd5ead'::uuid, '057a729b-56e7-52c4-9d1b-9248c2b16c52'::uuid, 'tejomayananda', 'hindi', '।।3.38।। जैसे धुयें से अग्नि और धूलि से दर्पण ढक जाता है तथा जैसे भ्रूण गर्भाशय से ढका रहता है, वैसे उस (काम) के द्वारा यह (ज्ञान) आवृत होता है।।
 '),
('255c9a5a-9491-540d-b000-9cb146e563f7'::uuid, '3c625eeb-bfe5-5fec-a08a-48eef5d22088'::uuid, 'ramsukhdas', 'hindi', '।।3.39।। और हे कुन्तीनन्दन ! इस अग्निके समान कभी तृप्त न होनेवाले और विवेकियोंके नित्य वैरी इस कामके द्वारा मनुष्यका विवेक ढका हुआ है।'),
('9a9461db-ed48-553d-a6a3-24933c66c8b0'::uuid, '3c625eeb-bfe5-5fec-a08a-48eef5d22088'::uuid, 'tejomayananda', 'hindi', '।।3.39।। हे कौन्तेय ! अग्नि के समान जिसको तृप्त करना कठिन है ऐसे कामरूप,  ज्ञानी के इस नित्य शत्रु द्वारा ज्ञान आवृत है।।
 '),
('b2395279-e43c-5261-8b00-da0a566ed5b9'::uuid, '79be0cb4-8de4-506f-9a4f-38d327b321de'::uuid, 'ramsukhdas', 'hindi', '।।3.40।। इन्द्रियाँ, मन और बुद्धि इस कामके वास-स्थान कहे गये हैं। यह काम इन- (इन्द्रियाँ, मन और बुद्धि-) के द्वारा ज्ञानको ढककर देहाभिमानी मनुष्यको मोहित करता है।'),
('c7fd353a-97f8-586e-9a80-e54b944d7c88'::uuid, '79be0cb4-8de4-506f-9a4f-38d327b321de'::uuid, 'tejomayananda', 'hindi', '।।3.40।। इन्द्रियाँ,  मन और बुद्धि इसके निवास स्थान कहे जाते हैं;  यह काम इनके द्वारा ही ज्ञान को आच्छादित करके देही पुरुष को मोहित करता है।।
 '),
('dc54685a-aec0-54d4-b4ba-d9db9ad3b9bd'::uuid, '69bf7957-a5d4-51ce-abcd-dcf34d852aff'::uuid, 'ramsukhdas', 'hindi', '।।3.41।। इसलिये हे भरतवंशियोंमें श्रेष्ठ अर्जुन ! तू सबसे पहले इन्द्रियोंको वशमें करके इस ज्ञान और विज्ञानका नाश करनेवाले महान् पापी कामको अवश्य ही बलपूर्वक मार डाल।'),
('8b676a4b-7794-5a7f-932e-c4e9f8755c56'::uuid, '69bf7957-a5d4-51ce-abcd-dcf34d852aff'::uuid, 'tejomayananda', 'hindi', '।।3.41।। इसलिये, हे अर्जुन ! तुम पहले इन्द्रियों को वश में करके, ज्ञान और विज्ञान के नाशक इस कामरूप पापी को नष्ट करो।।
 '),
('caddde1b-1a1a-56ab-91de-6d8521c0edb7'::uuid, 'b6321639-cf22-543a-a757-f9c18509a2e8'::uuid, 'ramsukhdas', 'hindi', '।।3.42 -- 3.43।। इन्द्रियोंको (स्थूलशरीरसे) पर (श्रेष्ठ, सबल, प्रकाशक, व्यापक तथा सूक्ष्म) कहते हैं। इन्द्रियोंसे पर मन है, मनसे भी पर बुद्धि है औऱ जो बुद्धिसे भी पर है, वह (काम) है। इस तरह बुद्धिसे पर - (काम-) को जानकर अपने द्वारा अपने-आपको वशमें करके हे महाबाहो ! तू इस कामरूप दुर्जय शत्रुको मार डाल।'),
('24bdff0f-e2a4-5381-80b3-913897c9f14d'::uuid, 'b6321639-cf22-543a-a757-f9c18509a2e8'::uuid, 'tejomayananda', 'hindi', '।।3.42।। (शरीर से) परे (श्रेष्ठ) इन्द्रियाँ कही जाती हैं;  इन्द्रियों से परे मन है और मन से परे बुद्धि है, और जो बुद्धि से भी परे है, वह है आत्मा।।
 '),
('9d1e79e7-a63c-5402-a49c-879f6647497d'::uuid, '6ee651c8-2e09-500c-8363-9edb89a9f914'::uuid, 'ramsukhdas', 'hindi', '।।3.42 -- 3.43।। इन्द्रियोंको (स्थूलशरीरसे) पर (श्रेष्ठ, सबल, प्रकाशक, व्यापक तथा सूक्ष्म) कहते हैं। इन्द्रियोंसे पर मन है, मनसे भी पर बुद्धि है औऱ जो बुद्धिसे भी पर है वह (काम) है। इस तरह बुद्धिसे पर - (काम-) को जानकर अपने द्वारा अपने-आपको वशमें करके हे महाबाहो ! तू इस कामरूप दुर्जय शत्रुको मार डाल।'),
('35013b9c-1dba-58a8-8e7e-298b15f5914c'::uuid, '6ee651c8-2e09-500c-8363-9edb89a9f914'::uuid, 'tejomayananda', 'hindi', '।।3.43।। इस प्रकार बुद्धि से परे (शुद्ध) आत्मा को जानकर आत्मा (बुद्धि) के द्वारा आत्मा (मन) को वश में करके, हे महाबाहो ! तुम इस दुर्जेय (दुरासदम्) कामरूप शत्रु को मारो।।
 '),
('ce2614f2-1f48-52e2-86f8-3088ef5fd18b'::uuid, '58b673ae-10fe-5838-994e-4ca18a3a8254'::uuid, 'ramsukhdas', 'hindi', '।।4.1।। श्रीभगवान् बोले - मैंने इस अविनाशी योगको सूर्यसे कहा था। फिर सूर्यने (अपने पुत्र) वैवस्वत मनुसे कहा और मनुने (अपने पुत्र) राजा इक्ष्वाकुसे कहा।'),
('db67605b-2f27-50c6-a7f5-f240e46db177'::uuid, '58b673ae-10fe-5838-994e-4ca18a3a8254'::uuid, 'tejomayananda', 'hindi', '।।4.1।। श्रीभगवान् ने कहा ---  मैंने इस अविनाशी योग को विवस्वान् (सूर्य देवता) से कहा (सिखाया);  विवस्वान् ने मनु से कहा;  मनु ने इक्ष्वाकु से कहा।।
 '),
('993607cd-bef5-5257-aaa4-fb7c2a4ad38b'::uuid, 'a6324ec2-34f0-50d8-96de-e96c15274f85'::uuid, 'ramsukhdas', 'hindi', '।।4.2।। हे परंतप ! इस तरह परम्परासे प्राप्त इस कर्मयोग को राजर्षियोंने जाना। परन्तु बहुत समय बीत जानेके कारण वह योग इस मनुष्यलोकमें लुप्तप्राय हो गया।'),
('96b9c4ec-cea0-5126-9aea-eb4f27221ca9'::uuid, 'a6324ec2-34f0-50d8-96de-e96c15274f85'::uuid, 'tejomayananda', 'hindi', '।।4.2।। इस प्रकार परम्परा से प्राप्त हुये इस योग को राजर्षियों ने जाना, (परन्तु) हे परन्तप ! वह योग बहुत काल (के अन्तराल) से यहाँ (इस लोक में) नष्टप्राय हो गया।।
 '),
('1f0e0118-1d6c-5743-b13a-4d9e703f4252'::uuid, 'cd822b2a-fdb6-582b-b06f-a0b134f1dda7'::uuid, 'ramsukhdas', 'hindi', '।।4.3।। तू मेरा भक्त और प्रिय सखा है, इसलिये वही यह पुरातन योग आज मैंने तुझसे कहा है; क्योंकि यह बड़ा उत्तम रहस्य है।'),
('96d5b8b9-e9b8-538d-a0d3-3f2535c873db'::uuid, 'cd822b2a-fdb6-582b-b06f-a0b134f1dda7'::uuid, 'tejomayananda', 'hindi', '।।4.3।। वह ही यह पुरातन योग आज मैंने तुम्हें कहा (सिखाया) क्योंकि तुम मेरे भक्त और मित्र हो। यह उत्तम रहस्य है।।'),
('33790274-5371-58be-8b9c-76d5f4a379f2'::uuid, '0406722a-08cd-5cec-a0f5-9cba4e5aac9a'::uuid, 'ramsukhdas', 'hindi', '।।4.4।। अर्जुन बोले - आपका जन्म तो अभीका है और सूर्यका जन्म बहुत पुराना है; अतः आपने ही सृष्टिके आदिमें सूर्यसे यह योग कहा था - यह बात मैं कैसे समझूँ?'),
('3a5bc7d0-6a89-5262-9ed2-b4962390180c'::uuid, '0406722a-08cd-5cec-a0f5-9cba4e5aac9a'::uuid, 'tejomayananda', 'hindi', '।।4.4।। अर्जुन ने कहा -- आपका जन्म अपर अर्थात् पश्चात का है और विवस्वान् का जन्म (आपके) पूर्व का है, इसलिये यह मैं कैसे जानूँ कि (सृष्टि के) आदि में आपने (इस योग को) कहा था?'),
('a4c5113c-4674-5ee3-87e5-066304ec726a'::uuid, '04f116d4-7eb9-58bd-97b6-7418ef1cf10d'::uuid, 'ramsukhdas', 'hindi', '।।4.5।। श्रीभगवान् बोले -- हे परन्तप अर्जुन ! मेरे और तेरे बहुत-से जन्म हो चुके हैं। उन सबको मैं जानता हूँ, पर तू नहीं जानता।'),
('26b940f4-ff1d-536f-9fa1-e10ea613d8f7'::uuid, '04f116d4-7eb9-58bd-97b6-7418ef1cf10d'::uuid, 'tejomayananda', 'hindi', '।।4.5।। श्रीभगवान् ने कहा -- हे अर्जुन ! मेरे और तुम्हारे बहुत से जन्म हो चुके हैं, (परन्तु) हे परन्तप ! उन सबको मैं जानता हूँ और तुम नहीं जानते।।
 '),
('8b2885c6-9be1-566b-923d-04c30e6165d1'::uuid, 'cbc51231-994a-5664-83e0-3cecc2d04992'::uuid, 'ramsukhdas', 'hindi', '।।4.6।। मैं अजन्मा और अविनाशी-स्वरूप होते हुए भी तथा सम्पूर्ण प्राणियोंका ईश्वर होते हुए भी अपनी प्रकृतिको अधीन करके अपनी योगमायासे प्रकट होता हूँ।'),
('aec766ec-2e15-58b3-be9e-444f11cddc2a'::uuid, 'cbc51231-994a-5664-83e0-3cecc2d04992'::uuid, 'tejomayananda', 'hindi', '।।4.6।। यद्यपि मैं अजन्मा और अविनाशी स्वरूप हूँ और भूतमात्र का ईश्वर हूँ (तथापि) अपनी प्रकृति को अपने अधीन रखकर (अधिष्ठाय) मैं अपनी माया से जन्म लेता हूँ।।'),
('f24deb27-a82f-504e-a764-5c10102a131c'::uuid, 'a2d25b2f-d1e9-5927-8648-5ed81c80ef3a'::uuid, 'ramsukhdas', 'hindi', '।।4.7।। हे भरतवंशी अर्जुन! जब-जब धर्मकी हानि और अधर्मकी वृद्धि होती है, तब-तब ही मैं अपने-आपको साकाररूपसे प्रकट करता हूँ।'),
('bde39c53-4048-56b6-be44-80b63aebcb5e'::uuid, 'a2d25b2f-d1e9-5927-8648-5ed81c80ef3a'::uuid, 'tejomayananda', 'hindi', '।।4.7।। हे भारत ! जब-जब धर्म की हानि और अधर्म की वृद्धि होती है,  तब-तब मैं स्वयं को प्रकट करता हूँ।।
 '),
('6010e78d-d1d8-5274-b36d-13ff3b1cbb55'::uuid, '7f287d89-3364-59e5-b82a-506f77271cd8'::uuid, 'ramsukhdas', 'hindi', '।।4.8।। साधुओं-(भक्तों-) की रक्षा करनेके लिये, पापकर्म करनेवालोंका विनाश करनेके लिये और धर्मकी भलीभाँति स्थापना करनेके लिये मैं युग-युगमें प्रकट हुआ करता हूँ।'),
('1cbad420-86af-5b36-ae6f-e578879571c4'::uuid, '7f287d89-3364-59e5-b82a-506f77271cd8'::uuid, 'tejomayananda', 'hindi', '।।4.8।। साधु पुरुषों के रक्षण,  दुष्कृत्य करने वालों के नाश,  तथा धर्म संस्थापना के लिये,  मैं प्रत्येक युग में प्रगट होता हूँ।।
 '),
('e38479b9-02af-5329-9452-4b7182f6c027'::uuid, '3b25fea4-d31a-5046-800a-30555c85dfed'::uuid, 'ramsukhdas', 'hindi', '।।4.9।। हे अर्जुन ! मेरे जन्म और कर्म दिव्य हैं। इस प्रकार (मेरे जन्म और कर्मको) जो मनुष्य तत्त्वसे जान लेता अर्थात् दृढ़तापूर्वक मान लेता है, वह शरीरका त्याग करके पुनर्जन्मको प्राप्त नहीं होता, प्रत्युत मुझे प्राप्त होता है।'),
('722704fe-ae6d-5956-b15d-633ca2ee5359'::uuid, '3b25fea4-d31a-5046-800a-30555c85dfed'::uuid, 'tejomayananda', 'hindi', '।।4.9।। हे अर्जुन ! मेरा जन्म और कर्म दिव्य है,  इस प्रकार जो पुरुष तत्त्वत:  जानता है, वह शरीर को त्यागकर फिर जन्म को नहीं प्राप्त होता;  वह मुझे ही प्राप्त होता है।।
 '),
('ab2221f6-1c0e-550e-a731-baae3caa9e91'::uuid, '649d2bb9-2a09-56da-8dcc-a2ea1aed3b40'::uuid, 'ramsukhdas', 'hindi', '।।4.10।। राग, भय और क्रोधसे सर्वथा रहित, मेरेमें ही तल्लीन, मेरे ही आश्रित तथा ज्ञानरूप तपसे पवित्र हुए बहुत-से भक्त मेरे भाव- (स्वरूप-) को प्राप्त हो चुके हैं।'),
('76405ec1-935d-53ea-8b12-8359718d513c'::uuid, '649d2bb9-2a09-56da-8dcc-a2ea1aed3b40'::uuid, 'tejomayananda', 'hindi', '।।4.10।। राग भय और क्रोध से रहित मनमय मेरे शरण हुए बहुत से पुरुष ज्ञान रुप तप से पवित्र‌ हुए मेरे स्वरुप को प्राप्त हुए हैं।।
 '),
('a60b843e-9b88-513f-b4ff-f47b0ada9052'::uuid, '0c21c7ba-8a37-5a2a-babd-8fa261b8d120'::uuid, 'ramsukhdas', 'hindi', '।।4.11।। हे पृथानन्दन ! जो भक्त जिस प्रकार मेरी शरण लेते हैं, मैं उन्हें उसी प्रकार आश्रय देता हूँ; क्योंकि सभी मनुष्य सब प्रकारसे मेरे मार्गका अनुकरण करते हैं।'),
('5092d4bf-ca80-5b95-8788-37d5a2f90fba'::uuid, '0c21c7ba-8a37-5a2a-babd-8fa261b8d120'::uuid, 'tejomayananda', 'hindi', '।।4.11।। जो मुझे जैसे भजते हैं,  मैं उन पर वैसे ही अनुग्रह करता हूँ;  हे पार्थ सभी मनुष्य सब प्रकार से, मेरे ही मार्ग का अनुवर्तन करते हैं।।
 '),
('3e11aa8e-fc4e-5917-bbfb-d621b6418c6c'::uuid, 'c1c95996-41f2-54ee-92c1-1964e0ff6c05'::uuid, 'ramsukhdas', 'hindi', '।।4.12।। कर्मोंकी सिद्धि (फल) चाहनेवाले मनुष्य देवताओंकी उपासना किया करते हैं; क्योंकि इस मनुष्यलोकमें कर्मोंसे उत्पन्न होनेवाली सिद्धि जल्दी मिल जाती है।'),
('619dceff-bd72-5c49-9e7c-9259032d05c6'::uuid, 'c1c95996-41f2-54ee-92c1-1964e0ff6c05'::uuid, 'tejomayananda', 'hindi', '।।4.12।। (सामान्य मनुष्य) यहाँ (इस लोक में) कर्मों के फल को चाहते हुये देवताओं को पूजते हैं;  क्योंकि मनुष्य लोक में कर्मों के फल शीघ्र ही प्राप्त होते हैं।।
 '),
('f97169ea-2f4e-5a04-b2e8-dccdca02810a'::uuid, '96c72b16-b8cd-51e8-b4b6-b49d277a2206'::uuid, 'ramsukhdas', 'hindi', '।।4.13 -- 4.14।। मेरे द्वारा गुणों और कर्मोंके विभागपूर्वक चारों वर्णोंकी रचना की गयी है। उस-(सृष्टि-रचना आदि-) का कर्ता होनेपर भी मुझ अव्यय रमेश्वरको तू अकर्ता जान। कारण कि कर्मोंके फलमें मेरी स्पृहा नहीं है, इसलिये मुझे कर्म लिप्त नहीं करते। इस प्रकार जो मुझे तत्त्वसे जान लेता है, वह भी कर्मोंसे नहीं बँधता।'),
('a2c795e6-145b-58db-b868-8ac519220fd1'::uuid, '96c72b16-b8cd-51e8-b4b6-b49d277a2206'::uuid, 'tejomayananda', 'hindi', '।।4.13।। गुण और कर्मों के विभाग से चातुर्वण्य मेरे द्वारा रचा गया है। यद्यपि मैं उसका कर्ता हूँ, तथापि तुम मुझे अकर्ता और अविनाशी जानो।।
 '),
('2c7ad31a-c612-5a06-ac1e-b45f74f496b0'::uuid, '70f614a9-4c4d-5428-ab24-7f3d6778f704'::uuid, 'ramsukhdas', 'hindi', '।।4.13 -- 4.14।। मेरे द्वारा गुणों और कर्मोंके विभागपूर्वक चारों वर्णोंकी रचना की गयी है। उस-(सृष्टि-रचना आदि-) का कर्ता होनेपर भी मुझ अव्यय परमेश्वरको तू अकर्ता जान। कारण कि कर्मोंके फलमें मेरी स्पृहा नहीं है, इसलिये मुझे कर्म लिप्त नहीं करते। इस प्रकार जो मुझे तत्त्वसे जान लेता है, वह भी कर्मोंसे नहीं बँधता।'),
('2e64fec7-3c4d-590e-8580-61f92d8411f0'::uuid, '70f614a9-4c4d-5428-ab24-7f3d6778f704'::uuid, 'tejomayananda', 'hindi', '।।4.14।। कर्म मुझे लिप्त नहीं करते;  न मुझे कर्मफल में स्पृहा है। इस प्रकार मुझे जो जानता है, वह भी कर्मों से नहीं बन्धता है।।
 '),
('dbb9349c-481c-5516-8414-c208ded07ab4'::uuid, '0498534f-e85a-5216-8c8b-146f6dbae8c3'::uuid, 'ramsukhdas', 'hindi', '।।4.15।। पूर्वकालके मुमुक्षुओंने भी इस प्रकार जानकर कर्म किये हैं, इसलिये तू भी पूर्वजोंके द्वारा सदासे किये जानेवाले कर्मोंको ही (उन्हींकी तरह) कर।'),
('cf66b206-843b-5d16-8e39-ed0639fce193'::uuid, '0498534f-e85a-5216-8c8b-146f6dbae8c3'::uuid, 'tejomayananda', 'hindi', '।।4.15।। पूर्व के मुमुक्ष पुरुषों द्वारा भी इस प्रकार जानकर ही कर्म किया गया है;  इसलिये तुम भी पूर्वजों द्वारा सदा से किये हुए कर्मों को ही करो।।
 '),
('2a10e1d9-369f-5cfd-9bc7-b21d8537165b'::uuid, '1f99e228-6b42-55d8-9e60-417f413927c6'::uuid, 'ramsukhdas', 'hindi', '।।4.16।। कर्म क्या है और अकर्म क्या है -- इस प्रकार इस विषयमें विद्वान् भी मोहित हो जाते हैं। अतः वह कर्म-तत्त्व मैं तुम्हें भलीभाँति कहूँगा, जिसको जानकर तू अशुभ- (संसार-बन्धन-) से मुक्त हो जायगा।'),
('96a0fadf-f050-5780-9b19-670c3448c0a1'::uuid, '1f99e228-6b42-55d8-9e60-417f413927c6'::uuid, 'tejomayananda', 'hindi', '।।4.16।। कर्म क्या है और अकर्म क्या है? इस विषय में बुद्धिमान पुरुष भी भ्रमित हो जाते हैं। इसलिये मैं तुम्हें कर्म कहूँगा,  (अर्थात् कर्म और अकर्म का स्वरूप समझाऊँगा) जिसको जानकर तुम अशुभ (संसार बन्धन) से मुक्त हो जाओगे।।
 '),
('4e7493b2-6eb5-57c2-9fd5-ce2bd76c7f1d'::uuid, '9b46f2d0-d829-514d-85cf-068dc3ef5b02'::uuid, 'ramsukhdas', 'hindi', '।।4.17।। कर्मका तत्त्व भी जानना चाहिये और अकर्मका तत्त्व भी जानना चाहिये तथा विकर्मका तत्त्व भी जानना चाहिये; क्योंकि कर्मकी गति गहन है।'),
('c9b6ae1c-8a8f-557f-9ddd-103fda4f6ca9'::uuid, '9b46f2d0-d829-514d-85cf-068dc3ef5b02'::uuid, 'tejomayananda', 'hindi', '।।4.17।। कर्म का (स्वरूप) जानना चाहिये और विकर्म का (स्वरूप) भी जानना चाहिये ; (बोद्धव्यम्) तथा अकर्म का भी (स्वरूप) जानना चाहिये (क्योंकि) कर्म की गति गहन है।।
 '),
('c4c4133e-9ca7-5fd6-8725-c809f452611f'::uuid, 'b3848acf-7137-51c6-811d-417d0555f728'::uuid, 'ramsukhdas', 'hindi', '।।4.18।। जो मनुष्य कर्ममें अकर्म देखता है और जो अकर्ममें कर्म देखता है, वह मनुष्योंमें बुद्धिमान् है,  योगी है और सम्पूर्ण कर्मोंको करनेवाला  है।'),
('e8c21c2d-9c35-57cb-88ed-9cb590915dbd'::uuid, 'b3848acf-7137-51c6-811d-417d0555f728'::uuid, 'tejomayananda', 'hindi', '।।4.18।। जो पुरुष कर्म में अकर्म और अकर्म में कर्म देखता है,  वह मनुष्यों में बुद्धिमान है,  वह योगी सम्पूर्ण कर्मों को करने वाला है।।
 '),
('a4f956bf-e9b5-579f-9e47-9725eea5b312'::uuid, 'eeff6e02-b5df-5085-9658-fb76a1ecbd70'::uuid, 'ramsukhdas', 'hindi', '।।4.19।। जिसके सम्पूर्ण कर्मोंके आरम्भ संकल्प और कामनासे रहित हैं तथा जिसके सम्पूर्ण कर्म ज्ञानरूपी अग्निसे जल गये हैं, उसको ज्ञानिजन भी पण्डित (बुद्धिमान्) कहते हैं।'),
('ca65e75c-4952-5190-96c9-c768496554b9'::uuid, 'eeff6e02-b5df-5085-9658-fb76a1ecbd70'::uuid, 'tejomayananda', 'hindi', '।।4.19।। जिसके समस्त कार्य कामना और संकल्प से रहित हैं,  ऐसे उस ज्ञानरूप अग्नि के द्वारा भस्म हुये कर्मों वाले पुरुष को ज्ञानीजन पण्डित कहते हैं।।
 '),
('915f594d-6076-5c9d-85c6-0f9d98bd5e44'::uuid, 'b969ae28-b184-5622-9dd6-d807b65459c0'::uuid, 'ramsukhdas', 'hindi', '।।4.20।। जो कर्म और फलकी आसक्तिका त्याग करके आश्रयसे रहित और सदा तृप्त है, वह कर्मोंमें अच्छी तरह लगा हुआ भी वास्तवमें कुछ भी नहीं करता।'),
('7cb9dbea-3e7d-5f1d-ba46-2eea66a8ec3f'::uuid, 'b969ae28-b184-5622-9dd6-d807b65459c0'::uuid, 'tejomayananda', 'hindi', '।।4.20।। जो पुरुष,  कर्मफलासक्ति को त्यागकर,  नित्यतृप्त और सब आश्रयों से रहित है वह कर्म में प्रवृत्त होते हुए भी (वास्तव में) कुछ भी नहीं करता है।।
 '),
('b46e647c-d963-500a-a999-5e53822784d4'::uuid, 'd302664b-254b-5530-b3cf-053ba95ccf81'::uuid, 'ramsukhdas', 'hindi', '।।4.21।। जिसका शरीर और अन्तःकरण अच्छी तरहसे वशमें किया हुआ है, जिसने सब प्रकारके संग्रहका परित्याग कर दिया है, ऐसा आशारहित कर्मयोगी केवल शरीर-सम्बन्धी कर्म करता हुआ भी पापको प्राप्त नहीं होता।'),
('03a09460-7d65-5902-b845-93f4a0468e1d'::uuid, 'd302664b-254b-5530-b3cf-053ba95ccf81'::uuid, 'tejomayananda', 'hindi', '।।4.21।। जो आशा रहित है तथा जिसने चित्त और आत्मा (शरीर) को संयमित किया है,  जिसने सब परिग्रहों का त्याग किया है,  ऐसा पुरुष शारीरिक कर्म करते हुए भी पाप को नहीं प्राप्त होता है।।
 '),
('d726b602-ef77-5daf-be1c-c1d64b7f4be1'::uuid, 'c73d34bb-3e4d-5522-ae02-b950ddfdfa47'::uuid, 'ramsukhdas', 'hindi', '।।4.22।। जो (कर्मयोगी) फल की इच्छा के बिना, अपने-आप जो कुछ मिल जाय, उसमें सन्तुष्ट रहता है और जो ईर्ष्यासे रहित, द्वन्द्वोंसे अतीत तथा सिद्धि और असिद्धिमें सम है, वह कर्म करते हुए भी उससे नहीं बँधता।'),
('26684795-f2c7-51e7-84ad-f00ca20134f1'::uuid, 'c73d34bb-3e4d-5522-ae02-b950ddfdfa47'::uuid, 'tejomayananda', 'hindi', '।।4.22।। यदृच्छया (अपने आप) जो कुछ प्राप्त हो उसमें ही सन्तुष्ट रहने वाला,  द्वन्द्वों से अतीत तथा मत्सर से रहित,  सिद्धि व असिद्धि में समभाव वाला पुरुष कर्म करके भी नहीं बन्धता है।।
 '),
('63f41e85-360d-5eb3-81a0-b3f3b695a966'::uuid, '5f306b8e-2fc6-5ea9-accc-5bf7fe5617f6'::uuid, 'ramsukhdas', 'hindi', '।।4.23।। जिसकी आसक्ति सर्वथा मिट गयी है, जो मुक्त हो गया है, जिसकी बुद्धि स्वरूपके ज्ञानमें स्थित है, ऐसे केवल यज्ञके लिये कर्म करनेवाले मनुष्यके सम्पूर्ण कर्म विलीन हो जाते हैं।'),
('95516f9c-4f22-59c6-b81c-8f00f5a3acdf'::uuid, '5f306b8e-2fc6-5ea9-accc-5bf7fe5617f6'::uuid, 'tejomayananda', 'hindi', '।।4.23।। जो आसक्तिरहित और मुक्त है,  जिसका चित्त ज्ञान में स्थित है,  यज्ञ के लिये आचरण करने वाले ऐसे पुरुष के समस्त कर्म लीन हो जाते हैं।।
 '),
('fdf72498-05f5-588c-a175-07ff973eb530'::uuid, 'e8ba1b49-91a4-5bf4-bc5b-b80444de40cb'::uuid, 'ramsukhdas', 'hindi', '।।4.24।। जिस यज्ञमें अर्पण भी ब्रह्म है, हवी भी ब्रह्म है और ब्रह्मरूप कर्ताके द्वारा ब्रह्मरूप अग्निमें आहुति देनारूप क्रिया भी ब्रह्म है, (ऐसे यज्ञको करनेवाले) जिस मनुष्यकी ब्रह्ममें ही कर्म-समाधि हो गयी है, उसके द्वारा प्राप्त करनेयोग्य फल भी ब्रह्म ही है।'),
('b2bd32ca-c3e4-5a42-bbf5-e3f90e0af617'::uuid, 'e8ba1b49-91a4-5bf4-bc5b-b80444de40cb'::uuid, 'tejomayananda', 'hindi', '।।4.24।। अर्पण (अर्थात् अर्पण करने का साधन श्रुवा) ब्रह्म है और हवि (शाकल्य अथवा हवन करने योग्य द्रव्य) भी ब्रह्म है;  ब्रह्मरूप अग्नि में ब्रह्मरूप कर्ता के द्वारा जो हवन किया गया है,  वह भी ब्रह्म ही है। इस प्रकार ब्रह्मरूप कर्म में समाधिस्थ पुरुष का गन्तव्य भी ब्रह्म ही है।।
 '),
('ba231813-5c53-5606-a5a8-a8337be2191a'::uuid, '104895bd-f569-5105-81b0-8d3e7cc84df1'::uuid, 'ramsukhdas', 'hindi', '।।4.25।। अन्य योगीलोग भगवदर्पणरूप यज्ञका ही अनुष्ठान करते हैं और दूसरे योगीलोग ब्रह्मरूप अग्निमें विचाररूप यज्ञके द्वारा ही जीवात्मारूप यज्ञका हवन करते हैं।'),
('94b85b51-f29b-5c49-953d-6c535b5c5e2f'::uuid, '104895bd-f569-5105-81b0-8d3e7cc84df1'::uuid, 'tejomayananda', 'hindi', '।।4.25।। कोई योगीजन देवताओं के पूजनरूप यज्ञ को ही करते हैं ; और दूसरे (ज्ञानीजन) ब्रह्मरूप अग्नि में यज्ञ के द्वारा यज्ञ को हवन करते हैं।।
 '),
('0de3a472-e91c-5fe6-a65b-c6c8b1b8711d'::uuid, '2b552f15-26f6-5644-920e-36342604c17d'::uuid, 'ramsukhdas', 'hindi', '।।4.26।। अन्य योगीलोग श्रोत्रादि समस्त इन्द्रियोंका संयमरूप अग्नियोंमें हवन किया करते हैं और दूसरे योगीलोग शब्दादि विषयोंका इन्द्रियरूप अग्नियोंमें हवन किया करते हैं।'),
('25a5df2d-13f5-5045-8d88-cc6c6e020450'::uuid, '2b552f15-26f6-5644-920e-36342604c17d'::uuid, 'tejomayananda', 'hindi', '।।4.26।। अन्य (योगीजन) श्रोत्रादिक सब इन्द्रियों को संयमरूप अग्नि में हवन करते हैं,  और अन्य (लोग) शब्दादिक विषयों को इन्द्रियरूप अग्नि में हवन करते हैं।।
 '),
('3646d4d0-4809-50aa-ac93-04d3af9ebe9e'::uuid, '72692d8c-3f9a-5902-80b7-da86df99965c'::uuid, 'ramsukhdas', 'hindi', '।।4.27।। अन्य योगीलोग सम्पूर्ण इन्द्रियोंकी क्रियाओंको और प्राणोंकी क्रियाओंको ज्ञानसे प्रकाशित आत्मसंयमयोगरूप अग्निमें हवन किया करते हैं।'),
('fff70bd4-f9e3-5422-9feb-779e44748232'::uuid, '72692d8c-3f9a-5902-80b7-da86df99965c'::uuid, 'tejomayananda', 'hindi', '।।4.27।। दूसरे (योगीजन) सम्पूर्ण इन्द्रियों के तथा प्राणों के कर्मों को ज्ञान से प्रकाशित आत्मसंयमयोगरूप अग्नि में हवन करते हैं।।
 '),
('4060546c-f31b-5960-b3fa-cf8025951804'::uuid, '9184e73e-fc34-5504-8f17-4873c2b4e7af'::uuid, 'ramsukhdas', 'hindi', '।।4.28।। दूसरे कितने ही तीक्ष्ण व्रत करनेवाले प्रयत्नशील साधक द्रव्य-सम्बन्धी यज्ञ करनेवाले हैं, और कितने ही तपोयज्ञ करनेवाले हैं, और दूसरे कितने ही योगयज्ञ करनेवाले हैं, तथा कितने ही स्वाध्यायरूप ज्ञानयज्ञ करनेवाले हैं।'),
('4193cf8b-6261-5d86-af2f-e0433a68dc18'::uuid, '9184e73e-fc34-5504-8f17-4873c2b4e7af'::uuid, 'tejomayananda', 'hindi', '।।4.28।। कुछ (साधक) द्रव्ययज्ञ, तपयज्ञ और योगयज्ञ करने वाले होते हैं;  और दूसरे कठिन व्रत करने वाले स्वाध्याय और ज्ञानयज्ञ करने वाले योगीजन होते हैं।।
 '),
('e881af90-9fee-5095-9313-c22500cac52d'::uuid, '7022a1c2-a13e-5e73-9993-43cbe12bbc39'::uuid, 'ramsukhdas', 'hindi', '।।4.29 -- 4.30।। दूसरे कितने ही प्राणायामके परायण हुए योगीलोग अपानमें प्राणका पूरक करके, प्राण और अपानकी गति रोककर फिर प्राणमें अपानका हवन करते हैं; तथा अन्य कितने ही नियमित आहार करनेवाले प्राणोंका प्राणोंमें हवन किया करते हैं। ये सभी साधक यज्ञोंद्वारा पापोंका नाश करनेवाले और यज्ञोंको जाननेवाले हैं।'),
('5c854d7d-6d45-5540-b7d0-f5d5cac2212f'::uuid, '7022a1c2-a13e-5e73-9993-43cbe12bbc39'::uuid, 'tejomayananda', 'hindi', '।।4.29।। अन्य (योगीजन) अपानवायु में प्राणवायु को हवन करते हैं,  तथा प्राण में अपान की आहुति देते हैं,  प्राण और अपान की गति को रोककर,  वे प्राणायाम के ही समलक्ष्य समझने वाले होते हैं।।
 '),
('b891febd-fae9-5168-a73a-fe3bf67804cc'::uuid, 'c2611989-3b6e-53c4-9989-f827000e5004'::uuid, 'ramsukhdas', 'hindi', '।।4.29 -- 4.30।। दूसरे कितने ही प्राणायामके परायण हुए योगीलोग अपानमें प्राणका पूरक करके, प्राण और अपानकी गति रोककर फिर प्राणमें अपानका हवन करते हैं; तथा अन्य कितने ही नियमित आहार करनेवाले प्राणोंका प्राणोंमें हवन किया करते हैं। ये सभी साधक यज्ञोंद्वारा पापोंका नाश करनेवाले और यज्ञोंको जाननेवाले हैं।'),
('5d53179f-82d0-5814-b4d7-f9c40849cbf2'::uuid, 'c2611989-3b6e-53c4-9989-f827000e5004'::uuid, 'tejomayananda', 'hindi', '।।4.30।। दूसरे नियमित आहार करने वाले (साधक जन) प्राणों को प्राणों में हवन करते हैं। ये सभी यज्ञ को जानने वाले हैं, जिनके पाप यज्ञ के द्वारा नष्ट हो चुके हैं।।
 '),
('2c1b17d4-100c-534e-a45c-0eee77853c8c'::uuid, '9f0fd21e-56a6-5418-8b24-da01d8de5f39'::uuid, 'ramsukhdas', 'hindi', '।।4.31।। हे कुरुवंशियोंमें श्रेष्ठ अर्जुन ! यज्ञसे बचे हुए अमृतका अनुभव करनेवाले सनातन परब्रह्म परमात्माको प्राप्त होते हैं। यज्ञ न करनेवाले मनुष्यके लिये यह मनुष्यलोक भी सुखदायक नहीं है, फिर परलोक कैसे सुखदायक होगा?'),
('1cdbbe07-1479-5373-bc7a-26278028b361'::uuid, '9f0fd21e-56a6-5418-8b24-da01d8de5f39'::uuid, 'tejomayananda', 'hindi', '।।4.31।। हे कुरुश्रेष्ठ ! यज्ञ के अवशिष्ट अमृत को भोगने वाले पुरुष सनातन ब्रह्म को प्राप्त होते हैं। यज्ञ रहित पुरुष को यह लोक भी नहीं मिलता,  फिर परलोक कैसे मिलेगा?
 '),
('212fb63d-f6fd-5f69-81f8-3f834774becf'::uuid, '06e9020f-ce3e-51b2-8c7c-712f40d199ad'::uuid, 'ramsukhdas', 'hindi', '।।4.32।। इस प्रकार और भी बहुत तरहके यज्ञ वेदकी वाणीमें विस्तारसे कहे गये हैं। उन सब यज्ञोंको तू कर्मजन्य जान। इस प्रकार जानकर यज्ञ करनेसे तू (कर्मबन्धनसे) मुक्त हो जायगा।'),
('234c0afe-b9d3-5dc5-ad08-23c4ef0dd40a'::uuid, '06e9020f-ce3e-51b2-8c7c-712f40d199ad'::uuid, 'tejomayananda', 'hindi', '।।4.32।। ऐसे अनेक प्रकार के यज्ञों का ब्रह्मा के मुख अर्थात् वेदों में प्रसार है अर्थात् वर्णित हैं। उन सब को कर्मों से उत्पन्न हुए जानो;  इस प्रकार जानकर तुम मुक्त हो जाओगे।।
 '),
('c63896cf-06b5-5ac3-9789-af08723b59ed'::uuid, 'ca89e9f8-4826-59b8-9d7c-6b7c24b0078e'::uuid, 'ramsukhdas', 'hindi', '।।4.33।। हे परन्तप अर्जुन ! द्रव्यमय यज्ञसे ज्ञानयज्ञ श्रेष्ठ है। सम्पूर्ण कर्म और पदार्थ ज्ञान-(तत्त्वज्ञान-) में समाप्त हो जाते हैं।'),
('33146559-4a49-5613-9c63-960dc0ea0d64'::uuid, 'ca89e9f8-4826-59b8-9d7c-6b7c24b0078e'::uuid, 'tejomayananda', 'hindi', '।।4.33।। हे परन्तप ! द्रव्यों से सम्पन्न होने वाले यज्ञ की अपेक्षा ज्ञानयज्ञ श्रेष्ठ है। हे पार्थ ! सम्पूर्ण अखिल कर्म ज्ञान में समाप्त होते हैं,  अर्थात् ज्ञान उनकी पराकाष्ठा है।।
 '),
('22d8b41e-3c48-5c1f-9813-d2ea0324fc98'::uuid, '78099d40-23f3-5cc3-a699-9d0c715e5be9'::uuid, 'ramsukhdas', 'hindi', '।।4.34।। उस- (तत्त्वज्ञान-) को (तत्त्वदर्शी ज्ञानी महापुरुषोंके पास जाकर) समझ। उनको साष्टाङ्ग दण्डवत् प्रणाम करनेसे, उनकी सेवा करनेसे और सरलतापूर्वक प्रश्न करनेसे वे तत्त्वदर्शी ज्ञानी महापुरुष तुझे उस तत्त्वज्ञानका उपदेश देंगे।'),
('def2b95b-3062-5286-90fa-9ce6344f4de4'::uuid, '78099d40-23f3-5cc3-a699-9d0c715e5be9'::uuid, 'tejomayananda', 'hindi', '।।4.34।। उस (ज्ञान) को (गुरु के समीप जाकर) साष्टांग प्रणिपात,  प्रश्न तथा सेवा करके जानो;  ये तत्त्वदर्शी ज्ञानी पुरुष तुम्हें ज्ञान का उपदेश करेंगे।।
 '),
('1eb50c5b-10a6-5232-99de-e4b95e81fe69'::uuid, '35475557-6f1f-52d3-bceb-e87eb3e21f08'::uuid, 'ramsukhdas', 'hindi', '।।4.35।। जिस- (तत्त्वज्ञान-) का अनुभव करनेके बाद तू फिर इस प्रकार मोहको नहीं प्राप्त होगा, और हे अर्जुन ! जिस- (तत्त्वज्ञान-) से तू सम्पूर्ण प्राणियोंको निःशेषभावसे पहले अपनेमें और उसके बाद मुझ सच्चिदानन्दघन परमात्मामें देखेगा।'),
('9ad059aa-22b7-5e0e-b11a-0361c6387bd4'::uuid, '35475557-6f1f-52d3-bceb-e87eb3e21f08'::uuid, 'tejomayananda', 'hindi', '।।4.35।। जिसको जानकर तुम पुन इस प्रकार मोह को नहीं प्राप्त होगे,  और हे पाण्डव ! जिसके द्वारा तुम भूतमात्र को अपने आत्मस्वरूप में तथा मुझमें भी देखोगे।।
 '),
('6f948ef0-2f82-594a-b9a5-aba304eb01d0'::uuid, '807330e6-c4f2-501e-95dd-7a8f16ceaa35'::uuid, 'ramsukhdas', 'hindi', '।।4.36।। अगर तू सब पापियोंसे भी अधिक पापी है, तो भी तू ज्ञानरूपी नौकाके द्वारा निःसन्देह सम्पूर्ण पापसमुद्रसे अच्छी तरह तर जायगा।'),
('62c3a7e0-fc03-5439-8799-4ea2ea32a2ac'::uuid, '807330e6-c4f2-501e-95dd-7a8f16ceaa35'::uuid, 'tejomayananda', 'hindi', '।।4.36।। यदि तुम सब पापियों से भी अधिक पाप करने वाले हो,  तो भी ज्ञानरूपी नौका द्वारा,  निश्चय ही सम्पूर्ण पापों का तुम संतरण कर जाओगे।।
 '),
('543bee3b-fadc-5daf-a46d-35fb169c8dcf'::uuid, 'b007c082-879b-54b7-9e6e-837da9dd19f4'::uuid, 'ramsukhdas', 'hindi', '।।4.37।। हे अर्जुन ! जैसे प्रज्वलित अग्नि ईंधनोंको सर्वथा भस्म कर देती है, ऐसे ही ज्ञानरूपी अग्नि सम्पूर्ण कर्मोंको सर्वथा भस्म कर देती है।'),
('4e451240-b429-568b-8aaa-9eccd83013f7'::uuid, 'b007c082-879b-54b7-9e6e-837da9dd19f4'::uuid, 'tejomayananda', 'hindi', '।।4.37।। जैसे प्रज्जवलित अग्नि ईन्धन को भस्मसात् कर देती है,  वैसे ही,  हे अर्जुन ! ज्ञानरूपी अग्नि सम्पूर्ण कर्मों को भस्मसात् कर देती है।।
 '),
('53f64049-3e23-551a-9b1c-78034728fc1e'::uuid, '8bcec931-e765-587d-8aff-36369bd1b5d6'::uuid, 'ramsukhdas', 'hindi', '।।4.38।। इस मनुष्यलोकमें ज्ञानके समान पवित्र करनेवाला निःसन्देह दूसरा कोई साधन नहीं है। जिसका योग भली-भाँति सिद्ध हो गया है, वह (कर्मयोगी) उस तत्त्वज्ञानको अवश्य ही स्वयं अपने-आपमें पा लेता है।'),
('69eda9be-5f10-5bcf-b34b-ee3d8842e3cd'::uuid, '8bcec931-e765-587d-8aff-36369bd1b5d6'::uuid, 'tejomayananda', 'hindi', '।।4.38।। इस लोक में ज्ञान के समान पवित्र करने वाला,  निसंदेह,  कुछ भी नहीं है। योग में संसिद्ध पुरुष स्वयं ही उसे (उचित) काल में आत्मा में प्राप्त करता है।।
 ')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('f3304c84-6d86-56c2-8458-998fd503dcc3'::uuid, '929471c5-5cd7-554f-999c-3dd3cc1a041e'::uuid, 'ramsukhdas', 'hindi', '।।4.39।। जो जितेन्द्रिय तथा साधन-परायण है, ऐसा श्रद्धावान् मनुष्य ज्ञानको प्राप्त होता है और ज्ञानको प्राप्त होकर वह तत्काल परम शान्तिको प्राप्त हो जाता है।'),
('9017ddd3-b5f9-513e-88d2-697d2a0b7168'::uuid, '929471c5-5cd7-554f-999c-3dd3cc1a041e'::uuid, 'tejomayananda', 'hindi', '।।4.39।। श्रद्धावान्,  तत्पर और जितेन्द्रिय पुरुष ज्ञान प्राप्त करता है। ज्ञान को प्राप्त करके शीघ्र ही वह परम शान्ति को प्राप्त होता है।।
 '),
('75512c3e-d27e-548c-8659-18c596abcdb5'::uuid, '939bac97-0ce4-51bb-a5e9-0b2a669eea51'::uuid, 'ramsukhdas', 'hindi', '।।4.40।। विवेकहीन और श्रद्धारहित संशयात्मा मनुष्यका पतन हो जाता है। ऐसे संशयात्मा मनुष्यके लिये न यह लोक  है न परलोक है और न सुख ही है।'),
('1f06a735-3e35-5fdf-a320-a12a3d569679'::uuid, '939bac97-0ce4-51bb-a5e9-0b2a669eea51'::uuid, 'tejomayananda', 'hindi', '।।4.40।। अज्ञानी तथा श्रद्धारहित और संशययुक्त पुरुष नष्ट हो जाता है,  (उनमें भी) संशयी पुरुष के लिये न यह लोक है,  न परलोक और न सुख।।
 '),
('33198bdc-8f1c-5b8c-b956-b58dc3dde1c9'::uuid, '1ddda8f6-3172-5749-83ed-9cf594fb9c4d'::uuid, 'ramsukhdas', 'hindi', '।।4.41।। हे धनञ्जय ! योग- (समता-) के द्वारा जिसका सम्पूर्ण कर्मोंसे सम्बन्ध-विच्छेद हो गया है और ज्ञानके द्वारा जिसके सम्पूर्ण संशयोंका नाश हो गया है, ऐसे स्वरूप-परायण मनुष्यको कर्म नहीं बाँधते।'),
('5993d7d9-d038-5296-99f7-e367e913b8dc'::uuid, '1ddda8f6-3172-5749-83ed-9cf594fb9c4d'::uuid, 'tejomayananda', 'hindi', '।।4.41।। जिसने योगद्वारा कर्मों का संन्यास किया है,  ज्ञानद्वारा जिसके संशय नष्ट हो गये हैं,  ऐसे आत्मवान् पुरुष को,  हे धनंजय ! कर्म नहीं बांधते हैं।।
 '),
('a56569b6-828d-56c1-a2e7-3e1b2980e40c'::uuid, '5678cecb-0ad5-592a-bce6-67ff1f34755b'::uuid, 'ramsukhdas', 'hindi', '।।4.42।। इसलिये हे भरतवंशी अर्जुन ! हृदयमें स्थित इस अज्ञानसे उत्पन्न अपने संशयका ज्ञानरूप तलवारसे छेदन करके योग -(समता-) में स्थित हो जा, (और युद्धके लिये) खड़ा हो जा।'),
('1fd5b622-4791-57e0-8eca-212588c5d841'::uuid, '5678cecb-0ad5-592a-bce6-67ff1f34755b'::uuid, 'tejomayananda', 'hindi', '।।4.42।। इसलिये अपने हृदय में स्थित अज्ञान से उत्पन्न आत्मविषयक संशय को ज्ञान खड्ग से काटकर,  हे भारत ! योग का आश्रय लेकर खड़े हो जाओ।।
 '),
('7f9d1da9-e6b9-57b6-896d-82480bf751bb'::uuid, '88f4d63b-a852-5707-bc0b-f9c1ed0d7c0c'::uuid, 'ramsukhdas', 'hindi', '।।5.1।। अर्जुन बोले -- हे कृष्ण ! आप कर्मोंका स्वरूपसे त्याग करनेकी और फिर कर्मयोगकी प्रशंसा करते हैं। अतः इन दोनों साधनोंमें जो एक निश्चितरूपसे कल्याणकारक हो, उसको मेरे लिये कहिये।'),
('83c39b17-daf1-54f8-b12a-cc08ef4216b1'::uuid, '88f4d63b-a852-5707-bc0b-f9c1ed0d7c0c'::uuid, 'tejomayananda', 'hindi', '।।5.1।। अर्जुन ने कहा हे --  कृष्ण ! आप कर्मों के संन्यास की और फिर योग (कर्म के आचरण) की प्रशंसा करते हैं। इन दोनों में एक जो निश्चय पूर्वक श्रेयस्कर है, उसको मेरे लिए कहिये।।
 '),
('fce62818-7bd9-5882-be8a-658eb06480ca'::uuid, '6d8df0dd-5159-5002-bf70-97e4fa98808d'::uuid, 'ramsukhdas', 'hindi', '।।5.2।। श्रीभगवान् बोले -- संन्यास (सांख्ययोग) और कर्मयोग दोनों ही कल्याण करनेवाले हैं। परन्तु उन दोनोंमें भी कर्मसंन्यास- (सांख्ययोग-) से कर्मयोग श्रेष्ठ है।'),
('93cae30e-2215-5ba4-adb6-8e7cce053a49'::uuid, '6d8df0dd-5159-5002-bf70-97e4fa98808d'::uuid, 'tejomayananda', 'hindi', '।।5.2।। श्रीभगवान् ने कहा --  कर्मसंन्यास और कर्मयोग ये दोनों ही परम कल्याणकारक हैं;  परन्तु उन दोनों में कर्मसंन्यास से कर्मयोग श्रेष्ठ है।।
 '),
('2a265403-574d-56d2-b731-eb6352c6dec4'::uuid, 'f655713a-0a3a-5cb5-aa91-07bc0a0b076f'::uuid, 'ramsukhdas', 'hindi', '।।5.3।। हे महाबाहो ! जो मनुष्य न किसीसे द्वेष करता है और न किसीकी आकाङ्क्षा करता है; वह (कर्मयोगी) सदा संन्यासी समझनेयोग्य है; क्योंकि द्वन्द्वोंसे रहित मनुष्य सुखपूर्वक संसार-बन्धनसे मुक्त हो जाता है।'),
('a7255238-7988-52f3-8c35-c0987eac3747'::uuid, 'f655713a-0a3a-5cb5-aa91-07bc0a0b076f'::uuid, 'tejomayananda', 'hindi', '।।5.3।। जो पुरुष न किसी से द्वेष करता है और न किसी की आकांक्षा,  वह सदा संन्यासी ही समझने योग्य है;  क्योंकि,  हे महाबाहो ! द्वन्द्वों से रहित पुरुष सहज ही बन्धन मुक्त हो जाता है।।
 '),
('dae169c9-ce4b-5d27-a4fd-84a96a689f42'::uuid, '2931a370-49a7-5de0-a3e3-17427394a2b0'::uuid, 'ramsukhdas', 'hindi', '।।5.4।। बेसमझ लोग सांख्ययोग और कर्मयोगको अलग-अलग फलवाले कहते हैं, न कि पण्डितजन; क्योंकि इन दोनोंमेंसे एक साधनमें भी अच्छी तरहसे स्थित मनुष्य दोनोंके फलरूप परमात्माको प्राप्त कर लेता है।'),
('8a65963c-58e1-5998-ab95-748fa51d1afe'::uuid, '2931a370-49a7-5de0-a3e3-17427394a2b0'::uuid, 'tejomayananda', 'hindi', '।।5.4।। बालक अर्थात् बालबुद्धि के लोग सांख्य (संन्यास) और योग को परस्पर भिन्न समझते हैं;  किसी एक में भी सम्यक् प्रकार से स्थित हुआ पुरुष दोनों के फल को प्राप्त कर लेता है।।
 '),
('ff42dbf4-d3f9-5778-abdf-fec73098489e'::uuid, '83bca8da-0437-5180-9274-1511fad6b9a2'::uuid, 'ramsukhdas', 'hindi', '।।5.5।। सांख्ययोगियोंके द्वारा जो तत्त्व प्राप्त किया जाता है, कर्मयोगियोंके द्वारा भी वही प्राप्त किया जाता है। अतः जो मनुष्य सांख्ययोग और कर्मयोगको (फलरूपमें) एक देखता है, वही ठीक देखता है।'),
('33c35dc3-bb15-56f7-853a-a69e29b9c4e6'::uuid, '83bca8da-0437-5180-9274-1511fad6b9a2'::uuid, 'tejomayananda', 'hindi', '।।5.5।। जो स्थान ज्ञानियों द्वारा प्राप्त किया जाता है,  उसी स्थान पर कर्मयोगी भी पहुँचते हैं। इसलिए जो पुरुष सांख्य और योग को (फलरूप से) एक ही देखता है,  वही (वास्तव में) देखता है।।
 '),
('115a87d2-94d3-5bdf-a691-d5df3ece6ba3'::uuid, 'd606c05f-ad99-5ded-9efa-883cc09de097'::uuid, 'ramsukhdas', 'hindi', '।।5.6।।  परन्तु हे महाबाहो ! कर्मयोगके बिना संन्यास सिद्ध होना कठिन है। मननशील कर्मयोगी शीघ्र ही ब्रह्मको प्राप्त हो जाता है।'),
('44769fb4-0fbd-57b3-81e2-37ae5cf672ae'::uuid, 'd606c05f-ad99-5ded-9efa-883cc09de097'::uuid, 'tejomayananda', 'hindi', '।।5.6।। परन्तु,  हे महाबाहो ! योग के बिना संन्यास प्राप्त होना कठिन है;  योगयुक्त मननशील पुरुष परमात्मा को शीघ्र ही प्राप्त होता है।।
 '),
('9750425b-0388-5789-ac2a-be3f9cf0be71'::uuid, '106aff34-3def-560a-8582-65ef9fb1d2ca'::uuid, 'ramsukhdas', 'hindi', '।।5.7।। जिसकी इन्द्रियाँ अपने वशमें हैं, जिसका अन्तःकरण निर्मल है, जिसका शरीर अपने वशमें है और सम्पूर्ण प्राणियोंकी आत्मा ही जिसकी आत्मा है, ऐसा कर्मयोगी कर्म करते हुए भी लिप्त नहीं होता।'),
('36951dfe-b139-58ef-b4de-03544b57520f'::uuid, '106aff34-3def-560a-8582-65ef9fb1d2ca'::uuid, 'tejomayananda', 'hindi', '।।5.7।। जो पुरुष योगयुक्त, विशुद्ध अन्तकरण वाला, शरीर को वश में किये हुए, जितेन्द्रिय तथा भूतमात्र में स्थित आत्मा के साथ एकत्व अनुभव किये हुए है वह कर्म करते हुए भी उनसे लिप्त नहीं होता।।
 '),
('08ed06c5-719b-5232-aade-28e90a20470e'::uuid, '12b34c1a-6b73-5d37-9344-a19d3850f08a'::uuid, 'ramsukhdas', 'hindi', '।।5.8 -- 5.9।। तत्त्वको जाननेवाला सांख्ययोगी देखता, सुनता, छूता, सूँघता, खाता, चलता, ग्रहण करता, बोलता, मल-मूत्र का त्याग करता, सोता, श्वास लेता तथा आँखें खोलता और मूँदता भी सम्पूर्ण इन्द्रियाँ इन्द्रियोंके विषयोंमें बरत रही हैं'' -- ऐसा समझकर ''मैं (स्वयं) कुछ भी नहीं करता हूँ'' -- ऐसा माने।'),
('ee5bb455-9670-5972-9438-db53c186b1ed'::uuid, '12b34c1a-6b73-5d37-9344-a19d3850f08a'::uuid, 'tejomayananda', 'hindi', '।।5.8।। तत्त्ववित् युक्त पुरुष यह सोचेगा (अर्थात् जानता है) कि  "मैं किंचित् मात्र कर्म नहीं करता हूँ"  देखता हुआ, सुनता हुआ, स्पर्श करता हुआ, सूंघता हुआ, खाता हुआ, चलता हुआ, सोता हुआ, श्वास लेता हुआ,।।
 '),
('a2462a76-c8bb-5f07-99e4-7cff7ca23146'::uuid, '73bffac7-e17a-57aa-860d-7c08511d7b0c'::uuid, 'ramsukhdas', 'hindi', '।।5.8 -- 5.9।। तत्त्वको जाननेवाला सांख्ययोगी देखता, सुनता, छूता, सूँघता, खाता, चलता, ग्रहण करता, बोलता, मल-मूत्र का त्याग करता, सोता हुआ, श्वास लेता तथा आँखें खोलता और मूँदता हुआ भी ''सम्पूर्ण इन्द्रियाँ इन्द्रियोंके विषयोंमें बरत रही हैं'' -- ऐसा समझकर ''मैं (स्वयं) कुछ भी नहीं करता हूँ'' -- ऐसा माने।'),
('01e120ec-08cf-5962-a356-58eaca60bf2e'::uuid, '73bffac7-e17a-57aa-860d-7c08511d7b0c'::uuid, 'tejomayananda', 'hindi', '।।5.9।। बोलता हुआ,  त्यागता हुआ,  ग्रहण करता हुआ  तथा आँखों को खोलता और बन्द करता हुआ (वह) निश्चयात्मक रूप से जानता है कि सब इन्द्रियाँ अपने-अपने विषयों में विचरण कर रही हैं।।
 '),
('374f4d28-d19d-5104-aa69-706196e48874'::uuid, '9673c10a-f5d5-5191-9c94-5966c2bb7e43'::uuid, 'ramsukhdas', 'hindi', '।।5.10।। जो (भक्तियोगी) सम्पूर्ण कर्मोंको भगवान् में अर्पण करके और आसक्तिका त्याग करके कर्म करता है, वह जलसे कमलके पत्तेकी तरह पापसे लिप्त नहीं होता।'),
('bece7371-8345-525f-8f29-1443bdbf325f'::uuid, '9673c10a-f5d5-5191-9c94-5966c2bb7e43'::uuid, 'tejomayananda', 'hindi', '।।5.10।। जो पुरुष सब कर्म ब्रह्म में अर्पण करके और आसक्ति को त्यागकर करता है,  वह पुरुष कमल के पत्ते के सदृश पाप से लिप्त नहीं होता।।
 '),
('3376de08-6624-5159-a983-9cb33f3a9e2b'::uuid, '74bd969b-e672-5bd7-b84d-3011028aa3e1'::uuid, 'ramsukhdas', 'hindi', '।।5.11।। कर्मयोगी आसक्तिका त्याग करके केवल (ममतारहित) इन्द्रियाँ-शरीर-मन-बुद्धि के द्वारा केवल अन्तःकरणकी शुद्धिके लिये ही कर्म करते हैं।'),
('550e1eaa-29e7-5d3e-81df-d9d984c24ae8'::uuid, '74bd969b-e672-5bd7-b84d-3011028aa3e1'::uuid, 'tejomayananda', 'hindi', '।।5.11।। योगीजन, शरीर, मन, बुद्धि और इन्द्रियों द्वारा आसक्ति को त्याग कर आत्मशुद्धि (चित्तशुद्धि) के लिए कर्म करते हैं।।
 '),
('3465a773-dd75-51a0-babc-f36d0c29be28'::uuid, 'aeecaaad-b559-5646-a1d3-223424f083c4'::uuid, 'ramsukhdas', 'hindi', '।।5.12।। कर्मयोगी कर्मफलका त्याग करके नैष्ठिकी शान्तिको प्राप्त होता है। परन्तु सकाम मनुष्य कामनाके कारण फलमें आसक्त होकर बँध जाता है।'),
('e3895375-f6d6-5832-b405-7d46f079f083'::uuid, 'aeecaaad-b559-5646-a1d3-223424f083c4'::uuid, 'tejomayananda', 'hindi', '।।5.12।। युक्त पुरुष कर्मफल का त्याग करके परम शान्ति को प्राप्त होता है;  और अयुक्त पुरुष फल में आसक्त हुआ कामना के द्वारा बँधता है।।
 '),
('c5e2a4ca-5634-5809-8ae3-373f74210f81'::uuid, 'e18dcd79-638e-5289-a871-cd53654cfd82'::uuid, 'ramsukhdas', 'hindi', '।।5.13।। जिसकी इन्द्रियाँ और मन वशमें हैं, ऐसा देहधारी पुरुष नौ द्वारोंवाले शरीररूपी पुरमें सम्पूर्ण कर्मोंका विवेकपूर्वक मनसे त्याग करके निःसन्देह न करता हुआ और न करवाता हुआ सुखपूर्वक (अपने स्वरूपमें) स्थित रहता है।'),
('1400da04-bc86-593d-b129-8b150957f286'::uuid, 'e18dcd79-638e-5289-a871-cd53654cfd82'::uuid, 'tejomayananda', 'hindi', '।।5.13।। सब कर्मों का मन से संन्यास करके संयमी पुरुष नवद्वार वाली शरीर रूप नगरी में सुख से रहता हुआ न कर्म करता है और न करवाता है।।
 '),
('68af8a69-67b7-533a-88ad-92f191689365'::uuid, 'a0cd9f97-0972-5fd6-8e4b-08c0b8bfe688'::uuid, 'ramsukhdas', 'hindi', '।।5.14।। परमेश्वर मनुष्योंके न कर्तापनकी, न कर्मोंकी और न कर्मफलके साथ संयोगकी रचना करते हैं; किन्तु स्वभाव ही बरत रहा है।'),
('5b8a8c31-7fce-5e6b-8ecd-feeb49e5e178'::uuid, 'a0cd9f97-0972-5fd6-8e4b-08c0b8bfe688'::uuid, 'tejomayananda', 'hindi', '।।5.14।। लोकमात्र के लिए प्रभु (ईश्वर) न कर्तृत्व, न कर्म और न कर्मफल के संयोग को रचता है। परन्तु प्रकृति (सब कुछ) करती है।।
 '),
('1d628e03-5f43-52ea-b71d-d7fcb7a1d63f'::uuid, 'b1c614d1-62aa-56e0-a81a-49b8b7e9f6ab'::uuid, 'ramsukhdas', 'hindi', '।।5.15।। सर्वव्यापी परमात्मा न किसीके पापकर्मको और न शुभकर्मको ही ग्रहण करता है; किन्तु अज्ञानसे ज्ञान ढका हुआ है, उसीसे सब जीव मोहित हो रहे हैं।'),
('5fe6214c-c71b-5eab-9d35-fa8af0cef5be'::uuid, 'b1c614d1-62aa-56e0-a81a-49b8b7e9f6ab'::uuid, 'tejomayananda', 'hindi', '।।5.15।। विभु परमात्मा न किसी के पापकर्म को और न पुण्यकर्म को ही ग्रहण करता है;  (किन्तु) अज्ञान से ज्ञान ढका हुआ है,  इससे सब जीव मोहित होते हैं।।
 '),
('eb6afeca-1630-514a-ac27-669fc88e1ffe'::uuid, 'c43cb171-1e2c-54ae-b567-5f768543c49c'::uuid, 'ramsukhdas', 'hindi', '।।5.16।। परन्तु जिन्होंने अपने जिस ज्ञान-(विवक-) के द्वारा उस अज्ञानका नाश कर दिया है, उनका वह ज्ञान सूर्यकी तरह परमतत्त्व परमात्माको प्रकाशित कर देता है।'),
('d68e3e0b-fff6-5091-bf65-2052eebd8a5d'::uuid, 'c43cb171-1e2c-54ae-b567-5f768543c49c'::uuid, 'tejomayananda', 'hindi', '।।5.16।। परन्तु जिनका वह अज्ञान आत्मज्ञान से नष्ट हो जाता है,  उनके लिए वह ज्ञान,  सूर्य के सदृश,  परमात्मा को प्रकाशित करता है।।
 '),
('56c18ce1-5f3f-5ac4-8f09-5821d2db3d30'::uuid, '81460644-56a1-55ec-a4c7-1ef46e137b3c'::uuid, 'ramsukhdas', 'hindi', '।।5.17।। जिनकी बुद्धि तदाकार हो रही है, जिनका मन तदाकार हो रहा है, जिनकी स्थिति परमात्मतत्वमें है, ऐसे परमात्मपरायण साधक ज्ञानके द्वारा पापरहित होकर अपुनरावृत्ति (परमगति) को प्राप्त होते हैं।'),
('45536e98-3b66-544c-9815-ab5516b7d0a5'::uuid, '81460644-56a1-55ec-a4c7-1ef46e137b3c'::uuid, 'tejomayananda', 'hindi', '।।5.17।। जिनकी बुद्धि उस (परमात्मा) में स्थित है,  जिनका मन तद्रूप हुआ है,  उसमें ही जिनकी निष्ठा है,  वह (ब्रह्म) ही जिनका परम लक्ष्य है,  ज्ञान के द्वारा पापरहित पुरुष अपुनरावृत्ति को प्राप्त होते हैं,  अर्थात् उनका पुनर्जन्म नहीं होता है।।
 '),
('714d441b-e759-5a2b-987a-d88a4ed7f5c9'::uuid, '60d4f4f7-0f08-51e9-8c73-206e7ea48bfe'::uuid, 'ramsukhdas', 'hindi', '।।5.18।। ज्ञानी महापुरुष विद्या-विनययुक्त ब्राह्मणमें और चाण्डालमें तथा गाय, हाथी एवं कुत्तेमें भी समरूप परमात्माको देखनेवाले होते हैं।'),
('13d142b7-38b7-5e75-a7b7-98a237082775'::uuid, '60d4f4f7-0f08-51e9-8c73-206e7ea48bfe'::uuid, 'tejomayananda', 'hindi', '।।5.18।। (ऐसे वे) ज्ञानीजन विद्या और विनय से सम्पन्न ब्राह्मण,  तथा गाय,  हाथी,  श्वान और चाण्डाल में भी सम तत्त्व को देखते हैं।।
 '),
('45d938da-ef0a-561f-a9d4-c6ed96003c44'::uuid, 'c55d2e32-cfa3-508e-b624-eb3adea5d69f'::uuid, 'ramsukhdas', 'hindi', '।।5.19।। जिनका अन्तःकरण समतामें स्थित है, उन्होंने इस जीवित-अवस्थामें ही सम्पूर्ण संसारको जीत लिया है; ब्रह्म निर्दोष और सम है, इसलिये वे ब्रह्ममें ही स्थित हैं।'),
('8283846c-b871-5c65-88b6-c8496d19e446'::uuid, 'c55d2e32-cfa3-508e-b624-eb3adea5d69f'::uuid, 'tejomayananda', 'hindi', '।।5.19।। जिनका मन समत्वभाव में स्थित है,  उनके द्वारा यहीं पर यह सर्ग जीत लिया जाता है; क्योंकि ब्रह्म निर्दोष और सम है इसलिये वे ब्रह्म में ही स्थित हैं।।
 '),
('1a2e87a0-b459-513f-a90f-cc5bed1b9cb0'::uuid, '11d5bf6f-c012-5737-84fe-adadfc2a9841'::uuid, 'ramsukhdas', 'hindi', '।।5.20।। जो प्रियको प्राप्त होकर हर्षित न हो और अप्रियको प्राप्त होकर उद्विग्न न हो, वह स्थिर बुद्धिवाला, मूढ़तारहित तथा ब्रह्मको जाननेवाला मनुष्य ब्रह्ममें स्थित है।'),
('13107d7f-9b2e-5d2a-8ec0-3acfddb46806'::uuid, '11d5bf6f-c012-5737-84fe-adadfc2a9841'::uuid, 'tejomayananda', 'hindi', '।।5.20।। जो स्थिरबुद्धि,  संमोहरहित ब्रह्मवित् पुरुष ब्रह्म में स्थित है,  वह प्रिय वस्तु को प्राप्त होकर हर्षित नहीं होता और अप्रिय को पाकर उद्विग्न नहीं होता।।
 '),
('70ace0f5-15ea-5a35-8dee-a9cc16a5917f'::uuid, '31b4cea4-4406-5adc-8790-6fd1e215b3d7'::uuid, 'ramsukhdas', 'hindi', '।।5.21।। बाह्यस्पर्शमें आसक्तिरहित अन्तःकरणवाला साधक आत्मामें जो सुख है, उसको प्राप्त होता है। फिर वह ब्रह्ममें अभिन्नभावसे स्थित मनुष्य अक्षय सुखका अनुभव करता है।'),
('44833ca3-c347-5096-b127-94861a979c45'::uuid, '31b4cea4-4406-5adc-8790-6fd1e215b3d7'::uuid, 'tejomayananda', 'hindi', '।।5.21।। बाह्य विषयों में आसक्तिरहित अन्त:करण वाला पुरुष आत्मा में ही सुख प्राप्त करता है;  ब्रह्म के ध्यान में समाहित चित्त वाला पुरुष अक्षय सुख प्राप्त करता है।।
 '),
('69f581f9-3dc3-5b73-acc3-0d439f4833d9'::uuid, '529b2022-6c47-5fa1-a58e-0cf3882b509d'::uuid, 'ramsukhdas', 'hindi', '।।5.22।। क्योंकि हे कुन्तीनन्दन ! जो इन्द्रियों और विषयोंके संयोगसे पैदा होनेवाले भोग (सुख) हैं, वे आदि-अन्तवाले और दुःखके ही कारण हैं। अतः विवेकशील मनुष्य उनमें रमण नहीं करता।'),
('aba9fa51-6985-5e4a-8e39-87e53f9f8ed8'::uuid, '529b2022-6c47-5fa1-a58e-0cf3882b509d'::uuid, 'tejomayananda', 'hindi', '।।5.22।। हे कौन्तेय (इन्द्रिय तथा विषयों के) संयोग से उत्पन्न होने वाले जो भोग हैं वे दु:ख के ही हेतु हैं, क्योंकि वे आदि-अन्त वाले हैं। बुद्धिमान् पुरुष उनमें नहीं रमता।।
 '),
('7046523e-1d7e-502b-ac54-e883bc9caddb'::uuid, '1f28dbbf-1d29-5042-bba7-93a4ac3bc8bc'::uuid, 'ramsukhdas', 'hindi', '।।5.23।। इस मनुष्य-शरीरमें जो कोई (मनुष्य) शरीर छूटनेसे पहले ही काम-क्रोधसे उत्पन्न होनेवाले वेगको सहन करनेमें समर्थ होता है, वह नर योगी है और वही सुखी है।'),
('a579a3d1-01b4-54a1-9767-35a5f3bbbd67'::uuid, '1f28dbbf-1d29-5042-bba7-93a4ac3bc8bc'::uuid, 'tejomayananda', 'hindi', '।।5.23।। जो मनुष्य इसी लोक में शरीर त्यागने के पूर्व ही काम और क्रोध से उत्पन्न हुए वेग को सहन करने में समर्थ है,  वह योगी (युक्त) और सुखी मनुष्य है।।
 '),
('f3e06d83-6a73-5db1-a742-978fee46cb02'::uuid, 'b710e44d-77bd-5428-9bc3-0a376e233f3c'::uuid, 'ramsukhdas', 'hindi', '।।5.24।। जो मनुष्य केवल परमात्मामें सुखवाला है और केवल परमात्मामें रमण करनेवाला है तथा जो केवल परमात्मामें ज्ञानवाला है, वह ब्रह्ममें अपनी स्थितिका अनुभव करनेवाला सांख्ययोगी निर्वाण ब्रह्मको प्राप्त होता है।'),
('33ba2455-37d2-54ca-a66f-3a6ff55a1c1c'::uuid, 'b710e44d-77bd-5428-9bc3-0a376e233f3c'::uuid, 'tejomayananda', 'hindi', '।।5.24।। जो पुरुष अन्तरात्मा में ही सुख वाला,  आत्मा में ही आराम वाला तथा आत्मा में ही ज्ञान वाला है,  वह योगी ब्रह्मरूप बनकर ब्रह्मनिर्वाण अर्थात् परम मोक्ष को प्राप्त होता है।।
 '),
('e2b4bbba-cec1-5166-9a9b-7afee234634a'::uuid, '7c8e84c8-a1d3-54cc-b52b-99fe9e0e2875'::uuid, 'ramsukhdas', 'hindi', '।।5.25।। जिनका शरीर मन-बुद्धि-इन्द्रियोंसहित वशमें है, जो सम्पूर्ण प्राणियोंके हितमें रत हैं, जिनके सम्पूर्ण संशय मिट गये हैं, जिनके सम्पूर्ण कल्मष (दोष) नष्ट हो गये हैं, वे विवेकी साधक निर्वाण ब्रह्मको प्राप्त होते हैं।'),
('fce66a63-31d1-552b-810e-442aebf38f2e'::uuid, '7c8e84c8-a1d3-54cc-b52b-99fe9e0e2875'::uuid, 'tejomayananda', 'hindi', '।।5.25।। वे ऋषिगण मोक्ष को प्राप्त होते हैं - जिनके पाप नष्ट हो गये हैं, जो छिन्नसंशय, संयमी और भूतमात्र के हित में रमने वाले हैं।।
 '),
('41acbdfa-e771-5cfb-834b-d52e81c09ef5'::uuid, '8d38c1ba-87cf-567d-840a-f33720be0df7'::uuid, 'ramsukhdas', 'hindi', '।।5.26।। काम-क्रोधसे सर्वथा रहित,  जीते हुए मनवाले और स्वरूपका साक्षात्कार किये हुए सांख्ययोगियोंके लिये दोनों ओरसे--शरीरके रहते हुए अथवा शरीर छूटनेके बाद) निर्वाण ब्रह्म परिपूर्ण है।'),
('87e0d398-57c8-5705-aa1f-b514860a17c1'::uuid, '8d38c1ba-87cf-567d-840a-f33720be0df7'::uuid, 'tejomayananda', 'hindi', '।।5.26।। काम और क्रोध से रहित,  संयतचित्त वाले तथा आत्मा को जानने वाले यतियों के लिए सब ओर मोक्ष (या ब्रह्मानन्द) विद्यमान रहता है।।
 '),
('58563b35-9a2e-508e-a5f9-0b738d240f90'::uuid, '1d69920b-0742-5f35-b0e8-4c22499d3ecd'::uuid, 'ramsukhdas', 'hindi', '।।5.27 -- 5.28।। बाह्य पदार्थोंको बाहर ही छोड़कर और नेत्रोंकी दृष्टिको भौंहोंके बीचमें स्थित करके तथा नासिकामें विचरनेवाले प्राण और अपान वायुको सम करके जिसकी इन्द्रियाँ, मन और बुद्धि अपने वशमें हैं, जो मोक्ष-परायण है तथा जो इच्छा, भय और क्रोधसे सर्वथा रहित है, वह मुनि सदा मुक्त ही है।'),
('ac4536d0-e43e-5948-8df6-651ba66f7cf3'::uuid, '1d69920b-0742-5f35-b0e8-4c22499d3ecd'::uuid, 'tejomayananda', 'hindi', '।।5.27।। बाह्य विषयों को बाहर ही रखकर नेत्रों की दृष्टि को भृकुटि के बीच में स्थित करके तथा नासिका में विचरने वाले प्राण और अपानवायु को सम करके,।।
 '),
('c3559f1a-5376-5770-9f71-6bbbc987521a'::uuid, 'e6ba17fb-83ba-58dc-a5ff-37987d0fd908'::uuid, 'ramsukhdas', 'hindi', '।।5.27 -- 5.28।। बाह्य पदार्थोंको बाहर ही छोड़कर और नेत्रोंकी दृष्टिको भौंहोंके बीचमें स्थित करके तथा नासिकामें विचरनेवाले प्राण और अपान वायुको सम करके जिसकी इन्द्रियाँ, मन और बुद्धि अपने वशमें हैं, जो मोक्ष-परायण है तथा जो इच्छा, भय और क्रोधसे सर्वथा रहित है, वह मुनि सदा मुक्त ही है।'),
('c470a3b2-61a1-5eac-b844-4e454cbe7dee'::uuid, 'e6ba17fb-83ba-58dc-a5ff-37987d0fd908'::uuid, 'tejomayananda', 'hindi', '।।5.28।। जिस पुरुष की इन्द्रियाँ,  मन और बुद्धि संयत हैं, ऐसा मोक्ष परायण मुनि इच्छा, भय और क्रोध से रहित है, वह सदा मुक्त ही है।।
 '),
('6804d512-0478-53b5-a4cc-eefeda7a7533'::uuid, '4d1ae98b-bc01-59fd-b45c-3243afdab166'::uuid, 'ramsukhdas', 'hindi', '।।5.29।। भक्त मुझे सब यज्ञों और तपोंका भोक्ता, सम्पूर्ण लोकोंका महान् ईश्वर तथा सम्पूर्ण प्राणियोंका सुहृद् (स्वार्थरहित दयालु और प्रेमी) जानकर शान्तिको प्राप्त हो जाता है।'),
('e307b110-c955-5f3c-8cc7-d729fb111a79'::uuid, '4d1ae98b-bc01-59fd-b45c-3243afdab166'::uuid, 'tejomayananda', 'hindi', '।।5.29।। (साधक भक्त) मुझे यज्ञ और तपों का भोक्ता और सम्पूर्ण लोकों का महान् ईश्वर तथा भूतमात्र का सुहृद् (मित्र) जानकर शान्ति को प्राप्त होता है।।
 '),
('2be65f5b-a409-5141-a47b-0a5bbfdaaab6'::uuid, '864cc8d0-15d0-5a2a-8284-8b135cf8bcdd'::uuid, 'ramsukhdas', 'hindi', '।।6.1।। श्रीभगवान् बोले -- कर्मफलका आश्रय न लेकर जो कर्तव्यकर्म करता है, वही संन्यासी तथा योगी है; और केवल अग्निका त्याग करनेवाला संन्यासी नहीं होता तथा केवल क्रियाओंका त्याग करनेवाला योगी नहीं होता।'),
('2714e4c9-169f-58d5-93bb-b3a2efeaa881'::uuid, '864cc8d0-15d0-5a2a-8284-8b135cf8bcdd'::uuid, 'tejomayananda', 'hindi', '।।6.1।। श्रीभगवान् ने कहा -- जो पुरुष कर्मफल पर आश्रित न होकर कर्तव्य कर्म करता है, वह संन्यासी और योगी है, न कि वह जिसने केवल अग्नि का और क्रियायों का त्याग किया है।।
 '),
('b8379f47-bf20-5af0-90b3-2f6ae39bc0fd'::uuid, '0e8ed7c9-b3af-5d30-92f2-0a53e163acf5'::uuid, 'ramsukhdas', 'hindi', '।।6.2।। हे अर्जुन ! लोग जिसको संन्यास कहते हैं, उसीको तुम योग समझो; क्योंकि संकल्पोंका त्याग किये बिना मनुष्य कोई-सा भी योगी नहीं हो सकता।'),
('0078ce34-7a0f-537b-a66b-695ba059ed0d'::uuid, '0e8ed7c9-b3af-5d30-92f2-0a53e163acf5'::uuid, 'tejomayananda', 'hindi', '।।6.2।। हे पाण्डव ! जिसको (शास्त्रवित्) संन्यास कहते हैं, उसी को तुम योग समझो; क्योंकि संकल्पों को न त्यागने वाला कोई भी पुरुष योगी नहीं होता।।
 '),
('43632cca-a43e-59a2-8ab2-e61c08f82b13'::uuid, 'f60c0376-e228-5e81-af7f-a5dddf436e75'::uuid, 'ramsukhdas', 'hindi', '।।6.3।। जो योग-(समता-) में आरूढ़ होना चाहता है, ऐसे मननशील योगीके लिये कर्तव्य-कर्म करना कारण कहा गया है और उसी योगारूढ़ मनुष्यका शम (शान्ति) परमात्मप्राप्तिमें कारण कहा गया है।'),
('33c0660c-6c91-5112-8887-41ff8bd9d898'::uuid, 'f60c0376-e228-5e81-af7f-a5dddf436e75'::uuid, 'tejomayananda', 'hindi', '।।6.3।। योग में आरूढ़ होने की इच्छा वाले मुनि के लिए कर्म करना ही हेतु (साधन) कहा है और योगारूढ़ हो जाने पर उसी पुरुष के लिए शम को (शांति, संकल्पसंन्यास) साधन कहा गया है।।
 '),
('6d893906-356b-5ff5-9aa5-de8a0df94208'::uuid, '5f1c5aad-0792-5748-84c2-872edbe85785'::uuid, 'ramsukhdas', 'hindi', '।।6.4।। जिस समय न इन्द्रियोंके भोगोंमें तथा न कर्मोंमें ही आसक्त होता है, उस समय वह सम्पूर्ण संकल्पोंका त्यागी मनुष्य योगारूढ़ कहा जाता है।'),
('d195895e-cf93-526d-9468-8119b6f34274'::uuid, '5f1c5aad-0792-5748-84c2-872edbe85785'::uuid, 'tejomayananda', 'hindi', '।।6.4।। जब (साधक) न इन्द्रियों के विषयों में और न कर्मों में आसक्त होता है तब सर्व संकल्पों के संन्यासी को योगारूढ़ कहा जाता है।।
 '),
('1a2c4f16-cfce-5a25-8b6a-c7bb9bf5bdb3'::uuid, '8a32a1b6-0601-5909-bffc-40b00a4a12ec'::uuid, 'ramsukhdas', 'hindi', '।।6.5।। अपने द्वारा अपना उद्धार करे, अपना पतन न करे; क्योंकि आप ही अपना मित्र है और आप ही अपना शत्रु है।'),
('f2f14d74-2f69-5a2b-9572-e80dfae49e40'::uuid, '8a32a1b6-0601-5909-bffc-40b00a4a12ec'::uuid, 'tejomayananda', 'hindi', '।।6.5।। मनुष्य को अपने द्वारा अपना उद्धार करना चाहिये और अपना अध: पतन नहीं करना चाहिये; क्योंकि आत्मा ही आत्मा का मित्र है और आत्मा (मनुष्य स्वयं) ही आत्मा का (अपना) शत्रु है।।
 '),
('1b276939-1708-52f3-b4fe-9caaba2b3ad8'::uuid, '45aa7457-b6e9-5e06-a8c4-08222d237067'::uuid, 'ramsukhdas', 'hindi', '।।6.6।। जिसने अपने-आपसे अपने-आपको जीत लिया है, उसके लिये आप ही अपना बन्धु है और जिसने अपने-आपको नहीं जीता है, ऐसे अनात्माका आत्मा ही शत्रुतामें शत्रुकी तरह बर्ताव करता है।'),
('cfb4f48c-28e2-5f1d-8f2d-e4b9ea1576d3'::uuid, '45aa7457-b6e9-5e06-a8c4-08222d237067'::uuid, 'tejomayananda', 'hindi', '।।6.6।। जिसने आत्मा (इंद्रियों,आदि) को आत्मा के द्वारा जीत लिया है, उस पुरुष का आत्मा उसका मित्र होता है, परन्तु अजितेन्द्रिय के लिए आत्मा शत्रु के समान स्थित होता है।।
 '),
('a1b34972-6a4b-54fd-99c4-b2a16305d5c6'::uuid, '317f9788-47c0-558d-91ab-cb75b8a47d34'::uuid, 'ramsukhdas', 'hindi', '।।6.7।। जिसने अपने-आपपर अपनी विजय कर ली है, उस शीत-उष्ण (अनुकूलता-प्रतिकूलता) सुख-दुःख तथा मान-अपमानमें निर्विकार मनुष्यको परमात्मा नित्यप्राप्त हैं।'),
('68104c3f-4cad-5820-8570-52e721825924'::uuid, '317f9788-47c0-558d-91ab-cb75b8a47d34'::uuid, 'tejomayananda', 'hindi', '।।6.7।। शीत-उष्ण, सुख-दु:ख तथा मान-अपमान में जो प्रशान्त रहता है, ऐसे जितात्मा पुरुष के लिये परमात्मा सम्यक् प्रकार से स्थित है, अर्थात्, आत्मरूप से विद्यमान है।।
 '),
('af62fd99-5f8e-5c1f-8e97-ab59ca42553a'::uuid, 'ec9f2e90-33eb-548d-bea8-18ce2e9b5d10'::uuid, 'ramsukhdas', 'hindi', '।।6.8।। जिसका अन्तःकरण ज्ञान-विज्ञानसे तृप्त है, जो कूटकी तरह निर्विकार है, जितेन्द्रिय है और मिट्टीके ढेले, पत्थर तथा स्वर्णमें समबुद्धिवाला है -- ऐसा योगी युक्त (योगारूढ़) कहा जाता है।'),
('19cb4d77-b722-57a9-9374-b3f56f5936a2'::uuid, 'ec9f2e90-33eb-548d-bea8-18ce2e9b5d10'::uuid, 'tejomayananda', 'hindi', '।।6.8।। जो योगी ज्ञान और विज्ञान से तृप्त है, जो विकार रहित (कूटस्थ) और जितेन्द्रिय है, जिसको मिट्टी, पाषाण और कंचन समान है, वह (परमात्मा से) युक्त कहलाता है।।
 '),
('690b4952-5ce7-571a-a640-532677dc2f0c'::uuid, '2d87ad62-9496-5fe9-bd7f-1d54acc8dd10'::uuid, 'ramsukhdas', 'hindi', '।।6.9।। सुहृद्, मित्र, वैरी, उदासीन, मध्यस्थ, द्वेष्य और सम्बन्धियोंमें तथा साधु-आचरण करनेवालोंमें और पाप-आचरण करनेवालोंमें भी समबुद्धिवाला मनुष्य श्रेष्ठ है।'),
('dd10aad9-f260-5d38-800b-3dde163539ce'::uuid, '2d87ad62-9496-5fe9-bd7f-1d54acc8dd10'::uuid, 'tejomayananda', 'hindi', '।।6.9।। जो पुरुष सुहृद्, मित्र, शत्रु, उदासीन, मध्यस्थ, द्वेषी और बान्धवों में तथा धर्मात्माओं में और पापियों में भी समान भाव वाला है, वह श्रेष्ठ है।।
 '),
('bb9eed2d-e30b-5a01-af66-6e02682dab1f'::uuid, 'b690b975-ea06-5027-b3af-7f6afbeba90f'::uuid, 'ramsukhdas', 'hindi', '।।6.10।। भोगबुद्धिसे संग्रह न करनेवाला, इच्छारहित और अन्तःकरण तथा शरीरको वशमें रखनेवाला योगी अकेला एकान्तमें स्थित होकर मनको निरन्तर परमात्मामें लगाये।'),
('42503dcb-dd5f-5557-b05c-5a77adb77da4'::uuid, 'b690b975-ea06-5027-b3af-7f6afbeba90f'::uuid, 'tejomayananda', 'hindi', '।।6.10।। शरीर और मन को संयमित किया हुआ योगी एकान्त स्थान पर अकेला रहता हुआ आशा और परिग्रह से मुक्त होकर निरन्तर मन को आत्मा में स्थिर करे।।
 '),
('bf6a53ed-25d4-5d61-8e53-00be58ab3ea4'::uuid, '4d9b3f97-da7a-5e71-a4d4-9d6263238e9f'::uuid, 'ramsukhdas', 'hindi', '।।6.11।। शुद्ध भूमिपर, जिसपर क्रमशः कुश, मृगछाला और वस्त्र बिछे हैं, जो न अत्यन्त ऊँचा है और न अत्यन्त नीचा, ऐसे अपने आसनको स्थिरस्थापन करके।'),
('93de3555-8a30-57dd-a08f-eb38708515f1'::uuid, '4d9b3f97-da7a-5e71-a4d4-9d6263238e9f'::uuid, 'tejomayananda', 'hindi', '।।6.11।। शुद्ध (स्वच्छ) भूमि में कुश, मृगशाला और उस पर वस्त्र रखा हो ऐसे अपने आसन को न अति ऊँचा और न अति नीचा स्थिर स्थापित करके....৷৷.।।
 '),
('03e640d1-7d85-54a8-95f0-e19870f35152'::uuid, 'ab1fa93d-b564-5961-9051-e807bdb7cdfe'::uuid, 'ramsukhdas', 'hindi', '।।6.12।। उस आसनपर बैठकर चित्त और इन्द्रियोंकी क्रियाओंको वशमें रखते हुए मनको एकाग्र करके अन्तःकरणकी शुद्धिके लिये योगका अभ्यास करे।'),
('a6781b7c-3bf5-5d4f-b204-f305e2881bc5'::uuid, 'ab1fa93d-b564-5961-9051-e807bdb7cdfe'::uuid, 'tejomayananda', 'hindi', '।।6.12।। वहाँ (आसन में बैठकर) मन को एकाग्र करके, चित्त और इन्द्रियों की क्रियाओं को वश में किये हुये आत्मशुद्धि के लिए योग का अभ्यास करे।।
 '),
('23a8c078-e27f-5894-9c37-d2f545514a8b'::uuid, '8c40219d-a0c1-5019-8ab1-b65eb51e6af2'::uuid, 'ramsukhdas', 'hindi', '।।6.13।। काया, शिर और ग्रीवाको सीधे अचल धारण करके तथा दिशाओंको न देखकर केवल अपनी नासिकाके अग्रभागको देखते हुए स्थिर होकर बैठे।'),
('9842a3ee-b553-5163-b980-8269325efee7'::uuid, '8c40219d-a0c1-5019-8ab1-b65eb51e6af2'::uuid, 'tejomayananda', 'hindi', '।।6.13।। काया, सिर और ग्रीवा को समान और अचल धारण किये हुए स्थिर होकर अपनी नासिका के अग्र भाग को देखकर अन्य दिशाओं को न देखता हुआ।।
 '),
('94595ff3-4f8b-5860-9c87-61315153a712'::uuid, '899b7c59-072f-54dc-afdf-66ae22c9f133'::uuid, 'ramsukhdas', 'hindi', '।।6.14।। जिसका अन्तःकरण शान्त है, जो भय-रहित है और जो ब्रह्मचारिव्रतमें स्थित है, ऐसा सावधान योगी मनका संयम करके मेरेमें चित्त लगाता हुआ मेरे परायण होकर बैठे।'),
('aeb07a37-c0fe-50fc-bb59-c88f1759001b'::uuid, '899b7c59-072f-54dc-afdf-66ae22c9f133'::uuid, 'tejomayananda', 'hindi', '।।6.14।। (साधक को) प्रशान्त अन्त:करण, निर्भय और ब्रह्मचर्य ब्रत में स्थित होकर, मन को संयमित करके चित्त को मुझमें लगाकर मुझे ही परम लक्ष्य समझकर बैठना चाहिए।।
 '),
('09e26848-ebe1-5afe-a189-4c32ce7ec1e1'::uuid, '3f36ebe7-5494-5f14-8ec8-dfb10b391511'::uuid, 'ramsukhdas', 'hindi', '।।6.15।। नियत  मनवाला योगी मनको इस तरहसे सदा परमात्मामें लगाता हुआ मेरेमें सम्यक् स्थितिवाली जो निर्वाणपरमा शान्ति है, उसको प्राप्त हो जाता है।'),
('168f1791-52ba-5139-9f79-49e835bc714a'::uuid, '3f36ebe7-5494-5f14-8ec8-dfb10b391511'::uuid, 'tejomayananda', 'hindi', '।।6.15।। इस प्रकार सदा मन को स्थिर करने का प्रयास करता हुआ संयमित मन का योगी मुझमें स्थित परम निर्वाण (मोक्ष) स्वरूप शांति को प्राप्त होता है।।'),
('a71a4b93-bdbd-5245-866c-931cfdc58998'::uuid, '14a21db0-98ad-5fb8-87e2-03033a6b2ea7'::uuid, 'ramsukhdas', 'hindi', '।।6.16।। हे अर्जुन ! यह योग न तो अधिक खानेवालेका और न बिलकुल न खानेवालेका तथा न अधिक सोनेवालेका और न बिलकुल न सोनेवालेका ही सिद्ध होता है।'),
('71c9138f-2ca6-5781-81ba-07ba61960791'::uuid, '14a21db0-98ad-5fb8-87e2-03033a6b2ea7'::uuid, 'tejomayananda', 'hindi', '।।6.16।। परन्तु, हे अर्जुन ! यह योग उस पुरुष के लिए सम्भव नहीं होता, जो अधिक खाने वाला है या बिल्कुल न खाने वाला है तथा जो अधिक सोने वाला है या सदा जागने वाला है।।
 '),
('e1b8a110-20de-54e9-9b80-f43dd5a72658'::uuid, 'faf664c7-c7cf-5613-b51e-f61862db4266'::uuid, 'ramsukhdas', 'hindi', '।।6.17।। दुःखोंका नाश करनेवाला योग तो यथायोग्य आहार और विहार करनेवालेका, कर्मोंमें यथायोग्य चेष्टा करनेवालेका तथा यथायोग्य सोने और जागनेवालेका ही सिद्ध होता है।'),
('6e1b7a41-e694-5af4-9d0d-57c5dcb8f534'::uuid, 'faf664c7-c7cf-5613-b51e-f61862db4266'::uuid, 'tejomayananda', 'hindi', '।।6.17।। उस पुरुष के लिए योग दु:खनाशक होता है, जो युक्त आहार और विहार करने वाला है, यथायोग्य चेष्टा करने वाला है और परिमित शयन और जागरण करने वाला है।।
 ')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('29c08c9a-d809-538d-b55b-98b8cf4a97e0'::uuid, 'fadb8f4a-df29-5233-96e7-0c092e197e20'::uuid, 'ramsukhdas', 'hindi', '।।6.18।। वशमें किया हुआ चित्त जिस कालमें अपने स्वरूपमें ही स्थित हो जाता है और स्वयं सम्पूर्ण पदार्थोंसे निःस्पृह हो जाता है, उस कालमें वह योगी है - ऐसा कहा जाता है।'),
('a7625020-4759-5d86-916b-60b535789583'::uuid, 'fadb8f4a-df29-5233-96e7-0c092e197e20'::uuid, 'tejomayananda', 'hindi', '।।6.18।। वश में किया हुआ चित्त जिस कालमें अपने स्वरुपमें ही स्थित हो जाता है और स्वयं सम्पूर्ण पदार्थों नि: स्पृह हो जाता है, उस कालमें वह योगी कहा जाता है।
 '),
('70e09f40-f629-56e8-82c7-76a6d6a565bd'::uuid, '1d61291d-21ea-5ba9-a2f8-9436b7990adc'::uuid, 'ramsukhdas', 'hindi', '।।6.19।। जैसे स्पन्दनरहित वायुके स्थानमें स्थित दीपककी लौ चेष्टारहित हो जाती है, योगका अभ्यास करते हुए वश में किए हुए चित्तवाले योगीके चित्तकी वैसी ही उपमा कही गयी है।'),
('67c5f871-a64b-56e9-a208-afe057634baf'::uuid, '1d61291d-21ea-5ba9-a2f8-9436b7990adc'::uuid, 'tejomayananda', 'hindi', '।।6.19।। जैसे स्पन्दनरहित वायुके स्थानमें स्थित दीपककी लौ चेष्टारहित हो जाती है, योगका अभ्यास करते हुए यतचित्तवाले योगीके चित्तकी वैसी ही उपमा कही गयी है।।
 '),
('e072fbce-6bc8-5f44-88b2-e59c297c03a5'::uuid, '4883b50b-39dc-59ad-833f-71d2f1ce68e7'::uuid, 'ramsukhdas', 'hindi', '।।6.20।। योगका सेवन करनेसे जिस अवस्थामें निरुद्ध चित्त उपराम हो जाता है तथा जिस अवस्थामें स्वयं अपने-आप से अपने-आपको देखता हुआ अपने-आपमें ही सन्तुष्ट हो जाता है।'),
('8c2efb31-1f08-582e-ba94-9297b5f7cf7a'::uuid, '4883b50b-39dc-59ad-833f-71d2f1ce68e7'::uuid, 'tejomayananda', 'hindi', '।।6.20।। योगका सेवन करनेसे जिस अवस्थामें निरुध्द चित्त उपराम हो जाता है तथा जिस अवस्थामें स्वयं अपने-आपमें अपने-आपको देखता हुआ अपने-आपमें सन्तुष्ट हो जाता है।।
 '),
('2eb1c4ca-1037-52f2-9d65-ce4b10336c5d'::uuid, 'fa6207f9-73d7-5fd2-b9c5-eee887d9169a'::uuid, 'ramsukhdas', 'hindi', '।।6.21।। जो सुख आत्यन्तिक, अतीन्द्रिय और बुद्धिग्राह्य है, उस सुखका जिस अवस्थामें अनुभव करता है और जिस सुखमें स्थित हुआ यह ध्यानयोगी फिर कभी तत्त्वसे विचलित नहीं होता।'),
('ac67bf4b-d74a-5020-bf06-4ee69de1fe4b'::uuid, 'fa6207f9-73d7-5fd2-b9c5-eee887d9169a'::uuid, 'tejomayananda', 'hindi', '।।6.21।। जो सुख आत्यन्तिक, अतीन्द्रिय और बुध्दिग्राह्म है, उस सुखका जिस अवस्थामें अनुभव करता है और जिस सुखमें स्थित हुआ यह ध्यानयोगी फिर कभी तत्वसे विचलित नहीं होता है।।
 '),
('ba30383f-9e08-5f26-a8be-b5090d6786ab'::uuid, 'c71e647a-a852-5f28-a03f-18af441e86e9'::uuid, 'ramsukhdas', 'hindi', '।।6.22।। जिस लाभकी प्राप्ति होनेपर उससे अधिक कोई दूसरा लाभ उसके माननेमें भी नहीं आता और जिसमें स्थित होनेपर वह बड़े भारी दुःखसे भी विचलित नहीं किया जा सकता।'),
('5631efb6-96f8-5fc7-a581-eab4413905fd'::uuid, 'c71e647a-a852-5f28-a03f-18af441e86e9'::uuid, 'tejomayananda', 'hindi', '।।6.22।। जिस लाभकी प्राप्ति होनेपर उससे अधिक कोई दूसरा लाभ उसके माननेमें भी नहीं आता और जिसमें स्थित होनेपर वह बड़े भारी दु:ख से भी विचलित नहीं होता है।।
 '),
('4e6684c5-5024-5745-ac47-4c6e8e7ec8ae'::uuid, 'd9c58c9f-f181-5d83-8f21-6b1498f7085d'::uuid, 'ramsukhdas', 'hindi', '।।6.23।। जिसमें दुःखोंके संयोगका ही वियोग है, उसीको ''योग'' नामसे जानना चाहिये। (वह योग जिस ध्यानयोगका लक्ष्य है,) उस ध्यानयोगका अभ्यास न उकताये हुए चित्तसे निश्चयपूर्वक करना चाहिये।'),
('247c1bf2-860d-580a-9e59-dfa20b193d38'::uuid, 'd9c58c9f-f181-5d83-8f21-6b1498f7085d'::uuid, 'tejomayananda', 'hindi', '।।6.23।। दु:ख के संयोग से वियोग है, उसीको ''योग'' नामसे जानना चाहिये । (वह योग जिस ध्यानयोग लक्ष्य है,) उस ध्यानयोका अभ्यास न उकताये हुए चित्तसे   निश्चयपूर्वक करना चाहिये।।
 '),
('83ce418c-b932-568b-b264-45e8501f3ec7'::uuid, '87bc1125-fd57-58c5-a004-530fe0cafd4f'::uuid, 'ramsukhdas', 'hindi', '।।6.24।। संकल्पसे उत्पन्न होनेवाली सम्पूर्ण कामनाओंका सर्वथा त्याग करके और मनसे ही इन्द्रिय-समूहको सभी ओरसे हटाकर।'),
('1adc7789-56ab-5c1a-bb86-21bfd59d8fae'::uuid, '87bc1125-fd57-58c5-a004-530fe0cafd4f'::uuid, 'tejomayananda', 'hindi', '।।6.24।। संकल्प से उत्पन्न समस्त कामनाओं को नि:शेष रूप से परित्याग कर मन के द्वारा इन्द्रिय समुदाय को सब ओर से सम्यक् प्रकार वश में करके।।
 '),
('7d4d7849-3523-5022-98ab-be0f8689a5fe'::uuid, '27a37edb-8993-5c61-9dbd-dfe32eee5327'::uuid, 'ramsukhdas', 'hindi', '।।6.25।। धैर्ययुक्त बुद्धिके द्वारा संसारसे धीरे-धीरे उपराम हो जाय और परमात्मस्वरूपमें मन-(बुद्धि-) को सम्यक् प्रकारसे स्थापन करके फिर कुछ भी चिन्तन न करे।'),
('5c08effa-0944-5f0d-9ca3-c0907433bcad'::uuid, '27a37edb-8993-5c61-9dbd-dfe32eee5327'::uuid, 'tejomayananda', 'hindi', '।।6.25।। शनै: शनै: धैर्ययुक्त बुद्धि के द्वारा (योगी) उपरामता (शांति) को प्राप्त होवे;  मन को आत्मा में स्थित करके फिर अन्य कुछ भी चिन्तन न करे।।
 '),
('c61b0749-bc06-5ad4-9502-4d5acd0c1d84'::uuid, 'fe5b1f4b-1bbf-5e74-b441-b0037176a6cf'::uuid, 'ramsukhdas', 'hindi', '।।6.26।। यह अस्थिर और चञ्चल मन जहाँ-जहाँ विचरण करता है, वहाँ-वहाँसे हटाकर इसको एक परमात्मामें ही  लगाये।'),
('aaff2248-8f93-5d70-acdc-c734f8bfca09'::uuid, 'fe5b1f4b-1bbf-5e74-b441-b0037176a6cf'::uuid, 'tejomayananda', 'hindi', '।।6.26।। यह चंचल और अस्थिर मन जिन कारणों से (विषयों में) विचरण करता है, उनसे संयमित करके उसे आत्मा के ही वश में लावे अर्थात् आत्मा में स्थिर करे।।
 '),
('04732c1a-626c-5ca8-9bac-437084ec65f2'::uuid, '49493824-8eb5-5a77-8636-42c9da3db8e5'::uuid, 'ramsukhdas', 'hindi', '।।6.27।। जिसके सब पाप नष्ट हो गये हैं, जिसका रजोगुण तथा मन सर्वथा शान्त(निर्मल) हो गया है, ऐसे इस ब्रह्मस्वरूप योगीको निश्चित ही उत्तम (सात्त्विक) सुख प्राप्त होता है।'),
('c391121a-68ee-5468-982b-7690d9250a7d'::uuid, '49493824-8eb5-5a77-8636-42c9da3db8e5'::uuid, 'tejomayananda', 'hindi', '।।6.27।। जिसका मन प्रशान्त है, जो पापरहित (अकल्मषम्) है और जिसका रजोगुण (विक्षेप) शांत हुआ है, ऐसे ब्रह्मरूप हुए इस योगी को उत्तम सुख प्राप्त होता है।।
 '),
('eedaee95-d57f-5208-9dfa-c795bca0e043'::uuid, '58fe1c3a-b266-5640-afae-a7cb73e106d7'::uuid, 'ramsukhdas', 'hindi', '।।6.28।। इस प्रकार अपने-आपको सदा परमात्मामें लगाता हुआ पापरहित योगी सुखपूर्वक ब्रह्मप्राप्तिरूप अत्यन्त सुखको प्राप्त हो जाता है।'),
('beafad46-dad7-56f1-8683-d7fb9cd36f0a'::uuid, '58fe1c3a-b266-5640-afae-a7cb73e106d7'::uuid, 'tejomayananda', 'hindi', '।।6.28।। इस प्रकार मन को सदा आत्मा में स्थिर करने का योग करने वाला पापरहित योगी सुखपूर्वक ब्रह्मसंस्पर्श का परम सुख प्राप्त करता है।।'),
('423b3737-e6b8-5f73-9608-8e0c6f539e93'::uuid, '56c7b080-ae70-587a-b5be-aad478085982'::uuid, 'ramsukhdas', 'hindi', '।।6.29।। सब जगह अपने स्वरूपको देखनेवाला और ध्यानयोगसे युक्त अन्तःकरणवाला योगा अपने स्वरूपको सम्पूर्ण प्राणियोंमें स्थित देखता है और सम्पूर्ण प्राणियोंको अपने स्वरूपमें देखता है।'),
('fa0a05a0-d94e-53b1-a385-8f0a8f34418f'::uuid, '56c7b080-ae70-587a-b5be-aad478085982'::uuid, 'tejomayananda', 'hindi', '।।6.29।। योगयुक्त अन्त:करण वाला और सर्वत्र समदर्शी योगी आत्मा को सब भूतों में और भूतमात्र को आत्मा में देखता है।।
 '),
('38e66d97-7208-5b43-8b0b-fc3e18333666'::uuid, '260fdbf3-65b5-5f44-9658-e75e8d88c87e'::uuid, 'ramsukhdas', 'hindi', '।।6.30।। जो सबमें मुझे देखता है और सबको मुझमें देखता है, उसके लिये मैं अदृश्य नहीं होता और वह मेरे लिये अदृश्य नहीं होता।'),
('a96d54b0-17e7-5e42-8ac7-139d85f8c80e'::uuid, '260fdbf3-65b5-5f44-9658-e75e8d88c87e'::uuid, 'tejomayananda', 'hindi', '।।6.30।। जो पुरुष मुझे सर्वत्र देखता है और सबको मुझमें देखता है, उसके लिए मैं नष्ट नहीं होता (अर्थात् उसके लिए मैं दूर नहीं होता) और वह मुझसे वियुक्त नहीं होता।।
 '),
('8a518dfd-f8e8-5b27-aa0d-7f534e6470e5'::uuid, 'ee9bf745-feea-5bbb-acd0-8afe95af047e'::uuid, 'ramsukhdas', 'hindi', '।।6.31।। मेरेमें एकीभावसे स्थित हुआ जो योगी सम्पूर्ण प्राणियोंमें स्थित मेरा भजन करता है, वह सब कुछ बर्ताव करता हुआ भी मेरेमें ही बर्ताव कर रहा है अर्थात् वह सर्वथा मेरेमें ही स्थित है।'),
('7eb473c6-b023-523d-bdab-dd05e51eb5fe'::uuid, 'ee9bf745-feea-5bbb-acd0-8afe95af047e'::uuid, 'tejomayananda', 'hindi', '।।6.31।। जो पुरुष एकत्वभाव मंे स्थित हुआ सम्पूर्ण भूतों में स्थित मुझे भजता है, वह योगी सब प्रकार से वर्तता हुआ (रहता हुआ) मुझमें स्थित रहता है।।
 '),
('9c4db276-bffd-506c-a5dd-6243bfab471c'::uuid, '031f5ada-08b1-51d9-afb6-1017e7fd850a'::uuid, 'ramsukhdas', 'hindi', '।।6.32।। हे अर्जुन ! जो (ध्यानयुक्त ज्ञानी महापुरुष) अपने शरीरकी उपमासे सब जगह अपनेको समान देखता है और सुख अथवा दुःखको भी समान देखता है, वह परम योगी माना गया है।'),
('9985bde7-7590-56cd-95fc-a504dceef3e1'::uuid, '031f5ada-08b1-51d9-afb6-1017e7fd850a'::uuid, 'tejomayananda', 'hindi', '।।6.32।। हे अर्जुन ! जो पुरुष अपने समान सर्वत्र सम देखता है, चाहे वह सुख हो या दु:ख, वह परम योगी माना गया है।।
 '),
('5ecd41d8-f22d-53d5-9606-374a8d5a4eff'::uuid, '7238b5af-337c-51c4-b370-3db2806e8f09'::uuid, 'ramsukhdas', 'hindi', '।।6.33।। अर्जुन बोले -- हे मधुसूदन ! आपने समतापूर्वक जो यह योग कहा है, मनकी चञ्चलताके कारण मैं इस योगकी स्थिर स्थिति नहीं देखता हूँ।'),
('8c00f6fc-ae2a-5040-ab1d-e1daf9562835'::uuid, '7238b5af-337c-51c4-b370-3db2806e8f09'::uuid, 'tejomayananda', 'hindi', '।।6.33।। अर्जुन ने कहा --  हे मधुसूदन ! जो यह साम्य योग आपने कहा, मैं मन के चंचल होने से इसकी चिरस्थायी स्थिति को नहीं देखता हूं।।
 '),
('de78e1fd-edf5-5a6c-931f-d3ae94b0f7db'::uuid, 'b04c045b-41f2-5e66-bd5b-f68952f3bf01'::uuid, 'ramsukhdas', 'hindi', '।।6.34।। क्योंकि हे कृष्ण ! मन बड़ा ही चञ्चल, प्रमथनशील, दृढ़ (जिद्दी) और बलवान् है। उसका निग्रह करना मैं वायुकी तरह अत्यन्त कठिन मानता हूँ।'),
('2dfe3975-a1e7-5f82-8329-622457372145'::uuid, 'b04c045b-41f2-5e66-bd5b-f68952f3bf01'::uuid, 'tejomayananda', 'hindi', '।।6.34।। क्योंकि हे कृष्ण ! यह मन चंचल और प्रमथन स्वभाव का तथा बलवान् और दृढ़ है; उसका निग्रह करना मैं वायु के समान अति दुष्कर मानता हूँ ।।
 '),
('97c2b6c4-5779-5b8f-ac93-c740a1be9a58'::uuid, '5f42b2da-ef86-5863-a7cf-d621adb0f4cf'::uuid, 'ramsukhdas', 'hindi', '।।6.35।। श्रीभगवान् बोले -- हे महाबाहो ! यह मन बड़ा चञ्चल है और इसका निग्रह करना भी बड़ा कठिन है -- यह तुम्हारा कहना बिलकुल ठीक है। परन्तु हे कुन्तीनन्दन ! अभ्यास और वैराग्यके द्वारा इसका निग्रह किया जाता है।'),
('8d667db2-4138-5dd0-84c5-62b3703a335b'::uuid, '5f42b2da-ef86-5863-a7cf-d621adb0f4cf'::uuid, 'tejomayananda', 'hindi', '।।6.35।। श्रीभगवान् कहते हैं --  हे महबाहो ! नि:सन्देह मन चंचल और कठिनता से वश में होने वाला है; परन्तु, हे कुन्तीपुत्र ! उसे अभ्यास और वैराग्य के द्वारा वश में किया जा सकता है।।
 '),
('0ecbb83f-2d87-52b7-bbe5-ffc8ab36c1e1'::uuid, 'a489f5bc-cb32-598d-a09f-e43fb4b03902'::uuid, 'ramsukhdas', 'hindi', '।।6.36।। जिसका मन पूरा वशमें नहीं है, उसके द्वारा योग प्राप्त होना कठिन है। परन्तु उपायपूर्वक यत्न करनेवाले वश्यात्माको योग प्राप्त हो सकता है, ऐसा मेरा मत है।'),
('55c9f21c-4936-52ef-a0ea-36bfbf82dbc4'::uuid, 'a489f5bc-cb32-598d-a09f-e43fb4b03902'::uuid, 'tejomayananda', 'hindi', '।।6.36।। असंयत मन के पुरुष द्वारा योग प्राप्त होना कठिन है, परन्तु स्वाधीन मन वाले प्रयत्नशील पुरुष द्वारा उपाय से योग प्राप्त होना संभव है, यह मेरा मत है।।
 '),
('127938c0-e717-530f-89bb-e34ff3e3053c'::uuid, 'ce61bf06-b5d5-52b4-ac03-d3a7ba994502'::uuid, 'ramsukhdas', 'hindi', '।।6.37।। अर्जुन बोले - हे कृष्ण ! जिसकी साधनमें श्रद्धा है, पर जिसका प्रयत्न शिथिल है, वह अन्तसमयमें अगर योगसे विचलितमना हो जाय, तो वह योगसिद्धिको प्राप्त न करके किस गतिको चला जाता है?'),
('23b7c277-caff-5a63-a8f9-dc802ee7af1c'::uuid, 'ce61bf06-b5d5-52b4-ac03-d3a7ba994502'::uuid, 'tejomayananda', 'hindi', '।।6.37।। अर्जुन ने कहा -- हे कृष्ण ! जिसका मन योग से चलायमान हो गया है, ऐसा अपूर्ण प्रयत्न वाला (अयति) श्रद्धायुक्त पुरुष योग की सिद्धि को न प्राप्त होकर किस गति को प्राप्त होता है?
 '),
('d585332c-8e09-5cb6-93b5-f17d2632f9a4'::uuid, '302e1229-4854-50d2-a71b-4cf3ec09afc2'::uuid, 'ramsukhdas', 'hindi', '।।6.38।। हे महाबाहो ! संसारके आश्रयसे रहित और परमात्मप्राप्तिके मार्गमें मोहित अर्थात् विचलित -- इस तरह दोनों ओरसे भ्रष्ट हुआ साधक क्या छिन्न-भिन्न बादलकी तरह नष्ट तो नहीं हो जाता ?'),
('4fcf773d-79df-52f2-8140-6082a9aad24c'::uuid, '302e1229-4854-50d2-a71b-4cf3ec09afc2'::uuid, 'tejomayananda', 'hindi', '।।6.38।। हे महबाहो ! क्या वह ब्रह्म के मार्ग में मोहित तथा आश्रयरहित पुरुष छिन्न-भिन्न मेघ के समान दोनों ओर से भ्रष्ट हुआ नष्ट तो नहीं हो जाता है?
 '),
('fa913d63-b18f-5b98-b2a9-5a24efdcdc95'::uuid, 'ace846c5-c503-58d6-85f6-aff050afda32'::uuid, 'ramsukhdas', 'hindi', '।।6.39।। हे कृष्ण! मेरे इस सन्देहका सर्वथा छेदन करनेके लिये आप ही योग्य हैं; क्योंकि इस संशयका छेदन करनेवाला आपके सिवाय दूसरा कोई हो नहीं सकता।'),
('77acc21b-f171-53c7-9837-149c96564991'::uuid, 'ace846c5-c503-58d6-85f6-aff050afda32'::uuid, 'tejomayananda', 'hindi', '।।6.39।। हे कृष्ण ! मेरे इस संशय को नि:शेष रूप से छेदन (निराकरण) करने के लिए आप ही योग्य है; क्योंकि आपके अतिरिक्त अन्य कोई इस संशय का छेदन करन वाला (छेत्ता) मिलना संभव नहीं है।।
 '),
('063c85db-eabb-5c0c-9c53-fc99013d1b67'::uuid, 'ca921481-2feb-532d-b50e-d9aa96359701'::uuid, 'ramsukhdas', 'hindi', '।।6.40।। श्रीभगवान् बोले -- हे पृथानन्दन ! उसका न तो इस लोकमें और न परलोकमें ही विनाश होता है; क्योंकि हे प्यारे ! कल्याणकारी काम करनेवाला कोई भी मनुष्य दुर्गतिको प्राप्त नहीं जाता।'),
('ac680de8-b423-5130-a37a-e285cf83b6ce'::uuid, 'ca921481-2feb-532d-b50e-d9aa96359701'::uuid, 'tejomayananda', 'hindi', '।।6.40।। श्रीभगवान् ने कहा -- हे पार्थ ! उस पुरुष का, न तो इस लोक में और न ही परलोक में ही नाश होता है; हे तात ! कोई भी शुभ कर्म करने वाला दुर्गति को नहीं प्राप्त होता है।।
 '),
('6ffc9fb3-e03d-5b4e-a129-a94f76c3f99f'::uuid, 'd6064d04-1043-5b8c-a002-06280cff8981'::uuid, 'ramsukhdas', 'hindi', '।।6.41।। वह योगभ्रष्ट पुण्यकर्म करनेवालोंके लोकोंको प्राप्त होकर और वहाँ बहुत वर्षोंतक रहकर फिर यहाँ शुद्ध  श्रीमानोंके घरमें जन्म लेता है।'),
('a37acc9e-5ff4-5d7b-88c6-145640d86fb2'::uuid, 'd6064d04-1043-5b8c-a002-06280cff8981'::uuid, 'tejomayananda', 'hindi', '।।6.41।। योगभ्रष्ट पुरुष पुण्यवानों के लोकों को प्राप्त होकर वहाँ दीर्घकाल तक वास करके शुद्ध आचरण वाले श्रीमन्त (धनवान) पुरुषों के घर में जन्म लेता है।।'),
('1ec7fb5a-7fdd-5c19-b8b6-cafed329bf21'::uuid, '1a3077a1-7689-5741-b475-06fca087f1e0'::uuid, 'ramsukhdas', 'hindi', '।।6.42।। अथवा (वैराग्यवान्) योगभ्रष्ट ज्ञानवान् योगियोंके कुलमें ही जन्म लेता है। इस प्रकारका जो यह जन्म है, यह संसारमें बहुत ही दुर्लभ है।'),
('2159a96e-eb5f-554c-b436-aaf2a0bb39d8'::uuid, '1a3077a1-7689-5741-b475-06fca087f1e0'::uuid, 'tejomayananda', 'hindi', '।।6.42।। अथवा, (साधक) ज्ञानवान् योगियों के ही कुल में जन्म लेता है, परन्तु इस प्रकार का जन्म इस लोक में नि:संदेह अति दुर्लभ है।।
 '),
('a6054b7f-6c03-5193-818c-1b9e0a688a67'::uuid, 'c6fba463-edde-5804-924c-a1d60b3ab5d1'::uuid, 'ramsukhdas', 'hindi', '।।6.43।। हे कुरुनन्दन ! वहाँपर उसको पूर्वजन्मकृत साधन-सम्पत्ति अनायास ही प्राप्त हो जाती है। फिर उससे वह साधनकी सिद्धिके विषयमें पुनः विशेषतासे यत्न करता है।'),
('572c15a3-c5fd-52d3-a0ff-bd65e9c0e923'::uuid, 'c6fba463-edde-5804-924c-a1d60b3ab5d1'::uuid, 'tejomayananda', 'hindi', '।।6.43।। हे कुरुनन्दन ! वह पुरुष वहाँ पूर्व देह में प्राप्त किये गये ज्ञान से सम्पन्न होकर योगसंसिद्धि के लिए उससे भी अधिक प्रयत्न करता है।।
 '),
('3ca9e575-3c3e-5ce5-98f9-ea2e45bb87b4'::uuid, 'eeb9ac72-6ad2-5b3e-ac46-27fc8da01508'::uuid, 'ramsukhdas', 'hindi', '।।6.44।। वह (श्रीमानोंके घरमें जन्म लेनेवाला योगभ्रष्ट मनुष्य) भोगोंके परवश होता हुआ भी पूर्वजन्ममें किये हुए अभ्यास-(साधन-) के कारण ही परमात्माकी तरफ खिंच जाता है; क्योंकि योग-(समता-) का जिज्ञासु भी वेदोंमें कहे हुए सकाम कर्मोंका अतिक्रमण कर जाता है।'),
('d7e72835-8681-5a9a-96ca-2efa68aa11a6'::uuid, 'eeb9ac72-6ad2-5b3e-ac46-27fc8da01508'::uuid, 'tejomayananda', 'hindi', '।।6.44।। उसी पूर्वाभ्यास के कारण वह अवश हुआ योग की ओर आकर्षित होता है। योग का जो केवल जिज्ञासु है वह शब्दब्रह्म का अतिक्रमण करता है।।'),
('406c3da7-4aa0-586e-8f6d-b517a717b987'::uuid, '0b0736fb-02cb-5b75-a22e-9a6e5c24154a'::uuid, 'ramsukhdas', 'hindi', '।।6.45।। परन्तु जो योगी प्रयत्नपूर्वक यत्न करता है और जिसके पाप नष्ट हो गये हैं तथा जो अनेक जन्मोंसे सिद्ध हुआ है, वह योगी फिर परमगतिको प्राप्त हो जाता है।'),
('bc3493ab-88b8-5b5c-8ff1-470d53bfa5f1'::uuid, '0b0736fb-02cb-5b75-a22e-9a6e5c24154a'::uuid, 'tejomayananda', 'hindi', '।।6.45।। परन्तु प्रयत्नपूर्वक अभ्यास करने वाला योगी सम्पूर्ण पापों से शुद्ध होकर अनेक जन्मों से (शनै: शनै:) सिद्ध होता हुआ, तब परम गति को प्राप्त होता है।।
 '),
('dfd1c22c-61f6-55b9-9f9a-cc09102ad2d3'::uuid, '911b439e-8d0f-544a-9272-0582dde7ff34'::uuid, 'ramsukhdas', 'hindi', '।।6.46।। (सकामभाववाले) तपस्वियोंसे भी योगी श्रेष्ठ है, ज्ञानियोंसे भी योगी श्रेष्ठ है और कर्मियोंसे भी योगी श्रेष्ठ है -- ऐसा मेरा मत है। अतः हे अर्जुन ! तू योगी हो जा।'),
('148b21c1-78a7-59fb-9fee-2de88f060e36'::uuid, '911b439e-8d0f-544a-9272-0582dde7ff34'::uuid, 'tejomayananda', 'hindi', '।।6.46।। क्योंकि योगी तपस्वियों से श्रेष्ठ है और (केवल शास्त्र के) ज्ञान वालों से भी श्रेष्ठ माना गया है तथा कर्म करने वालों से भी योगी श्रेष्ठ है, इसलिए हे अर्जुन तुम योगी बनो।।
 '),
('e1471ff4-7b95-5c6f-8e57-efb663263176'::uuid, '9ff91195-318c-582c-91a9-5dc720e1d8bc'::uuid, 'ramsukhdas', 'hindi', '।।6.47।। सम्पूर्ण योगियोंमें भी जो श्रद्धावान् भक्त मुझमें तल्लीन हुए मनसे मेरा भजन करता है, वह मेरे मतमें सर्वश्रेष्ठ योगी है।'),
('d7e2d095-92dd-5f17-9bc5-d63d0a31147f'::uuid, '9ff91195-318c-582c-91a9-5dc720e1d8bc'::uuid, 'tejomayananda', 'hindi', '।।6.47।। समस्त योगियों में जो भी श्रद्धावान् योगी मुझ में युक्त हुये अन्तरात्मा से (अर्थात् एकत्व भाव से मुझे भजता है, वह मुझे युक्ततम (सर्वश्रेष्ठ) मान्य है।।
 '),
('58f9b1f3-00fb-518c-b321-de344c8594b2'::uuid, '3857fad2-c141-5c9b-8a2e-a9ea92bd6617'::uuid, 'ramsukhdas', 'hindi', '।।7.1।। श्रीभगवान् बोले -- हे पृथानन्दन ! मुझमें आसक्त मनवाला, मेरे आश्रित होकर योगका अभ्यास करता हुआ तू मेरे समग्ररूपको निःसन्देह जैसा जानेगा, उसको सुन।'),
('8f98f43e-1b01-5976-816f-ced16c8934e7'::uuid, '3857fad2-c141-5c9b-8a2e-a9ea92bd6617'::uuid, 'tejomayananda', 'hindi', '।।7.1।। हे पार्थ ! मुझमें असक्त हुए मन वाले तथा मदाश्रित होकर योग का अभ्यास करते हुए जिस प्रकार तुम मुझे समग्ररूप से, बिना किसी संशय के, जानोगे वह सुनो।।
 '),
('b036b554-3a12-584b-b545-5f87774fc198'::uuid, 'c59ebaaa-4cad-5a24-b61a-63b45113e007'::uuid, 'ramsukhdas', 'hindi', '।।7.2।। तेरे लिये मैं विज्ञानसहित ज्ञान सम्पूर्णतासे कहूँगा, जिसको जाननेके बाद फिर यहाँ कुछ भी जानना बाकी नहीं रहेगा।'),
('d551e777-e531-59a0-a9dc-1297d207b0b1'::uuid, 'c59ebaaa-4cad-5a24-b61a-63b45113e007'::uuid, 'tejomayananda', 'hindi', '।।7.2।। मैं तुम्हारे लिए विज्ञान सहित इस ज्ञान को अशेष रूप से कहूँगा जिसको जानकर यहाँ (जगत् में) फिर और कुछ जानने योग्य (ज्ञातव्य) शेष नहीं रह जाता है।।'),
('8e3b942b-1280-5f5b-ac4c-fd983eed067a'::uuid, '8a7c9bb0-7762-5d86-b4ca-3bafe4883617'::uuid, 'ramsukhdas', 'hindi', '।।7.3।। हजारों मनुष्योंमें कोई एक वास्तविक सिद्धिके लिये यत्न करता है और उन यत्न करनेवाले सिद्धोंमें कोई एक ही मुझे तत्त्वसे जानता है।'),
('46be6c66-079a-597a-a538-0e8167c21c6c'::uuid, '8a7c9bb0-7762-5d86-b4ca-3bafe4883617'::uuid, 'tejomayananda', 'hindi', '।।7.3।। सहस्रों मनुष्यों में कोई ही मनुष्य पूर्णत्व की सिद्धि के लिए प्रयत्न करता है और उन प्रयत्नशील साधकों में भी कोई ही पुरुष मुझे तत्त्व से जानता है।।'),
('7b328f47-b76d-5782-8521-b8538c53f943'::uuid, '8e33ba3b-74b3-5655-9413-3bdbf30af51d'::uuid, 'ramsukhdas', 'hindi', '।।7.4 -- 7.5।।  पृथ्वी, जल, तेज, वायु, आकाश -- ये पञ्चमहाभूत और मन, बुद्धि तथा अहंकार -- यह आठ प्रकारके भेदोंवाली मेरी ''अपरा'' प्रकृति है। हे महाबाहो ! इस अपरा प्रकृतिसे भिन्न जीवरूप बनी हुई मेरी ''परा'' प्रकृतिको जान, जिसके द्वारा यह जगत् धारण किया जाता है।'),
('cdb902aa-32d8-517f-a691-b9a81a02f6d3'::uuid, '8e33ba3b-74b3-5655-9413-3bdbf30af51d'::uuid, 'tejomayananda', 'hindi', '।।7.4।। पृथ्वी, जल, अग्नि, वायु और आकाश तथा मन, बुद्धि और अहंकार - यह आठ प्रकार से विभक्त हुई मेरी प्रकृति है।।
 '),
('5b044af9-06b0-5b90-9c2c-87167f3c092c'::uuid, '50cb55eb-fe26-5ff0-b8e9-05af6bd0eddb'::uuid, 'ramsukhdas', 'hindi', '।।7.4 -- 7.5।।  पृथ्वी, जल, तेज, वायु, आकाश -- ये पञ्चमहाभूत और मन, बुद्धि तथा अहंकार -- यह आठ प्रकारके भेदोंवाली मेरी अपरा प्रकृति है। हे महाबाहो ! इस ''अपरा'' प्रकृतिसे भिन्न मेरी जीवरूपा बनी हुुई मेरी ''परा'' प्रकृतिको जान, जिसके द्वारा यह जगत् धारण किया जाता है।'),
('7c27f1c5-cb8f-57b4-89ba-6bcc636965fd'::uuid, '50cb55eb-fe26-5ff0-b8e9-05af6bd0eddb'::uuid, 'tejomayananda', 'hindi', '।।7.5।। हे महाबाहो ! यह अपरा प्रकृति है। इससे भिन्न मेरी जीवरूपी पराप्रकृति को जानो, जिससे यह जगत् धारण किया जाता है।।
 '),
('0f9cb4ac-4afc-5114-903a-6503f5c1c6fa'::uuid, 'a1dcf370-e869-5adb-bf77-8e08bdee035c'::uuid, 'ramsukhdas', 'hindi', '।।7.6।। अपरा और परा -- इन दोनों प्रकृतियोंके संयोगसे ही सम्पूर्ण प्राणी उत्पन्न होते हैं, ऐसा तुम समझो। मैं सम्पूर्ण जगत् का प्रभव तथा प्रलय हूँ।'),
('5a813a26-f17d-55c8-a731-8ad829a4bde4'::uuid, 'a1dcf370-e869-5adb-bf77-8e08bdee035c'::uuid, 'tejomayananda', 'hindi', '।।7.6।। यह जानो कि समम्पूर्ण भूत इन दोनों प्रकृतियों से उत्पत्ति वाले हैं। (अत:) मैं सम्पूर्ण जगत् का उत्पत्ति तथा प्रलय स्थान हूँ।।
 '),
('440dfb0a-8324-541a-8fde-47235e93ce8f'::uuid, '29bc17bd-599a-5c8a-8b06-942b190fe6c1'::uuid, 'ramsukhdas', 'hindi', '।।7.7।। हे धनञ्जय ! मेरे बढ़कर (इस जगत् का) दूसरा कोई किञ्चिन्मात्र भी कारण नहीं है। जैसे सूतकी मणियाँ सूतके धागेमें पिरोयी हुई होती हैं, ऐसे ही यह सम्पूर्ण जगत् मेरेमें ही ओत-प्रोत है।'),
('21bfb460-850c-5029-9c36-f1ed324c8e5d'::uuid, '29bc17bd-599a-5c8a-8b06-942b190fe6c1'::uuid, 'tejomayananda', 'hindi', '।।7.7।। हे धनंजय ! मुझसे श्रेष्ठ (परे) अन्य किचिन्मात्र वस्तु नहीं है। यह सम्पूर्ण जगत् सूत्र में मणियों के सदृश मुझमें पिरोया हुआ है।।
 '),
('a2cddfc3-a2ec-5d41-a7c3-57c15c1f8bf2'::uuid, '5a408a70-84dd-5a72-a746-528fac13942e'::uuid, 'ramsukhdas', 'hindi', '।।7.8।। हे कुन्तीनन्दन ! जलोंमें रस मैं हूँ, चन्द्रमा और सूर्यमें प्रभा (प्रकाश) मैं हूँ, सम्पूर्ण वेदोंमें प्रणव (ओंकार) मैं हूँ, आकाशमें शब्द और मनुष्योंमें पुरुषार्थ मैं हूँ।'),
('eab0d56b-8d65-5293-b4e1-229d3a065de7'::uuid, '5a408a70-84dd-5a72-a746-528fac13942e'::uuid, 'tejomayananda', 'hindi', '।।7.8।। हे कौन्तेय ! जल में मैं रस हूँ, चन्द्रमा और सूर्य में प्रकाश हूँ, सब वेदों में प्रणव (ँ़कार) हूँ तथा आकाश में शब्द और पुरुषों में पुरुषत्व हूँ।।
 '),
('70a4400c-fb1b-51c7-b11b-51cdbeb46884'::uuid, '85f39e76-284a-56a2-8104-0b6fbc08bf97'::uuid, 'ramsukhdas', 'hindi', '।।7.9।। पृथ्वीमें पवित्र गन्ध मैं हूँ, और अग्निमें तेज मैं हूँ, तथा सम्पूर्ण प्राणियोंमें जीवनीशक्ति मैं हूँ और तपस्वियोंमें तपस्या मैं हूँ।'),
('9f4bd9cd-e633-5867-93c9-3a09c451ed80'::uuid, '85f39e76-284a-56a2-8104-0b6fbc08bf97'::uuid, 'tejomayananda', 'hindi', '।।7.9।। पृथ्वी में पवित्र गन्ध हूँ और अग्नि में तेज हूँ; सम्पूर्ण भूतों में जीवन हूँ और तपस्वियों में मैं तप हूँ।।
 '),
('43f2b66d-b975-5dd0-8cfc-f1ce49fe11c5'::uuid, '1ec52b38-4a62-5228-836e-8228c38468a5'::uuid, 'ramsukhdas', 'hindi', '।।7.10।। हे पृथानन्दन ! सम्पूर्ण प्राणियोंका अनादि बीज मुझे जान। बुद्धिमानोंमें बुद्धि और तेजस्वियोंमें तेज मैं हूँ।'),
('c67739ca-a601-5966-8a78-9ec717c8643a'::uuid, '1ec52b38-4a62-5228-836e-8228c38468a5'::uuid, 'tejomayananda', 'hindi', '।।7.10।। हे पार्थ ! सम्पूर्ण भूतों का सनातन बीज (कारण) मुझे ही जानो; मैं बुद्धिमानों की बुद्धि और तेजस्वियों का तेज हूँ।।
 '),
('f57203ef-e202-5d2f-9660-43f675998e64'::uuid, '0da6d08b-3273-5f28-bde6-f90f9177817b'::uuid, 'ramsukhdas', 'hindi', '।।7.11।। हे भरतवंशियोंमें श्रेष्ठ अर्जुन ! बलवालोंमें काम और रागसे रहित बल मैं हूँ। मनुषयोंमें धर्मसे अविरुद्ध (धर्मयुक्त) काम मैं हूँ।'),
('29f1225a-c2bb-5558-b555-abe98df2e537'::uuid, '0da6d08b-3273-5f28-bde6-f90f9177817b'::uuid, 'tejomayananda', 'hindi', '।।7.11।। हे भरत श्रेष्ठ ! मैं बलवानों का कामना तथा आसक्ति से रहित बल हूँ और सब भूतों में धर्म के अविरुद्ध अर्थात् अनुकूल काम हूँ।।
 '),
('dd0635ac-4012-5376-9c2a-411d7c368536'::uuid, '9f835ba3-7827-5cdc-b515-916bd5fbe546'::uuid, 'ramsukhdas', 'hindi', '।।7.12।। (और तो क्या कहूँ)  जितने भी सात्त्विक, राजस और तामस भाव हैं, वे सब मुझ से ही होते हैं -- ऐसा समझो। पर मैं उनमें और वे मेरेमें नहीं हैं।'),
('7d6f1a8c-c944-5222-8bfa-951bb4b7ce81'::uuid, '9f835ba3-7827-5cdc-b515-916bd5fbe546'::uuid, 'tejomayananda', 'hindi', '।।7.12।। जो भी सात्त्विक (शुद्ध), राजसिक (क्रियाशील) और तामसिक (जड़) भाव हैं, उन सबको तुम मेरे से उत्पन्न हुए जानो; तथापि मैं उनमें नहीं हूँ, वे मुझमें हैं।।
 '),
('fa393b8e-25ab-5aa3-9356-5913701abbaa'::uuid, '853bbd9d-e54a-558a-8767-4d2cc1f6d2d7'::uuid, 'ramsukhdas', 'hindi', '।।7.13।। किन्तु - इन तीनों गुणरूप भावोंसे मोहित यह सब जगत् इन गुणोंसे अतीत अविनाशी मुझे नहीं जानता।'),
('29a4c291-f18f-5895-bb01-b28a1730a6ac'::uuid, '853bbd9d-e54a-558a-8767-4d2cc1f6d2d7'::uuid, 'tejomayananda', 'hindi', '।।7.13।। त्रिगुणों से उत्पन्न इन भावों (विकारों) से सम्पूर्ण जगत् (लोग) मोहित हुआ इन (गुणों) से परे अव्यय स्वरूप मुझे नहीं जानता है।।'),
('7cb7bb7f-963c-5948-ae57-503ab9181996'::uuid, 'b418621f-440b-5fdd-bde2-4698c1cde91d'::uuid, 'ramsukhdas', 'hindi', '।।7.14।। क्योंकि मेरी यह गुणमयी दैवी माया बड़ी दुरत्यय है अर्थात् इससे पार पाना बड़ा कठिन है। जो केवल मेरे ही शरण होते हैं, वे इस मायाको तर जाते हैं।'),
('e832359e-eb19-59f4-ba0a-8c4f881faa37'::uuid, 'b418621f-440b-5fdd-bde2-4698c1cde91d'::uuid, 'tejomayananda', 'hindi', '।।7.14।। यह दैवी त्रिगुणमयी मेरी माया बड़ी दुस्तर है। परन्तु जो मेरी शरण में आते हैं, वे इस माया को पार कर जाते हैं।।
 '),
('f7116551-3269-5b24-84d8-e7c3fa0cc1e7'::uuid, '32363d86-b2bb-5b43-a5be-27d4793dca46'::uuid, 'ramsukhdas', 'hindi', '।।7.15।।   मायाके द्वारा अपहृत ज्ञानवाले, आसुर भावका आश्रय लेनेवाले और मनुष्योंमें महान् नीच तथा पाप-कर्म करनेवाले मूढ़ मनुष्य मेरे शरण नहीं होते।९'),
('d86f7d22-2a66-502b-bf73-a3323d0712b5'::uuid, '32363d86-b2bb-5b43-a5be-27d4793dca46'::uuid, 'tejomayananda', 'hindi', '।।7.15।। दुष्कृत्य करने वाले, मूढ, नराधम पुरुष मुझे नहीं भजते हैं; माया के द्वारा जिनका ज्ञान हर लिया गया है, वे आसुरी भाव को धारण किये रहते हैं।।
 '),
('1c3f8e75-f826-5e80-9f9d-b960aeb11c74'::uuid, '4562982b-eb43-5eec-9758-5654fe1ed26a'::uuid, 'ramsukhdas', 'hindi', '।।7.16।। हे भरतवंशियोंमें श्रेष्ठ अर्जुनव ! पवित्र कर्म करनेवाले अर्थार्थी, आर्त, जिज्ञासु और ज्ञानी अर्थात् प्रेमी -- ये चार प्रकारके मनुष्य मेरा भजन करते हैं अर्थात् मेरे शरण होते हैं।'),
('38ec7cdb-afed-5d9d-8b22-e737a43a5cfe'::uuid, '4562982b-eb43-5eec-9758-5654fe1ed26a'::uuid, 'tejomayananda', 'hindi', '।।7.16।। हे भरत श्रेष्ठ अर्जुन ! उत्तम कर्म करने वाले (सुकृतिन:) आर्त, जिज्ञासु, अर्थार्थी और ज्ञानी ऐसे चार प्रकार के लोग मुझे भजते हैं।।
 '),
('b3cae611-49f4-541d-9394-fdaf092a395c'::uuid, 'cbdd8f03-c774-56cf-a43c-6941686fac3d'::uuid, 'ramsukhdas', 'hindi', '।।7.17।। उन चार भक्तोंमें मेरेमें निरन्तर लगा हुआ, अनन्यभक्तिवाला ज्ञानी अर्थात् प्रेमी भक्त श्रेष्ठ है; क्योंकि ज्ञानी भक्तको मैं अत्यन्त प्रिय हूँ और वह भी मेरेको अत्यन्त प्रिय है।'),
('9f1c5b09-dba1-5aa7-895b-e57ae19595a8'::uuid, 'cbdd8f03-c774-56cf-a43c-6941686fac3d'::uuid, 'tejomayananda', 'hindi', '।।7.17।। उनमें भी मुझ से नित्ययुक्त, अनन्य भक्ति वाला ज्ञानी श्रेष्ठ है, क्योंकि ज्ञानी को मैं अत्यन्त प्रिय हूँ और वह मुझे अत्यन्त प्रिय है।।
 '),
('5945ce9f-f5c6-50d0-9627-cfa9503ef4d3'::uuid, 'a1f7ac7a-69f8-5d04-9988-2ef5c7f1c886'::uuid, 'ramsukhdas', 'hindi', '।।7.18।। पहले कहे हुए सब-के-सब भक्त बड़े उदार (श्रेष्ठ भाववाले) हैं। परन्तु ज्ञानी (प्रेमी) तो मेरा स्वरूप ही है -- ऐसा मेरा मत है। कारण कि वह युक्तात्मा है और जिससे श्रेष्ठ दूसरी कोई गति नहीं है, ऐसे मेरेमें ही दृढ़ आस्थावाला है।'),
('bef8d9eb-eea7-523a-a697-d38254b7f50f'::uuid, 'a1f7ac7a-69f8-5d04-9988-2ef5c7f1c886'::uuid, 'tejomayananda', 'hindi', '।।7.18।। (यद्यपि) ये सब उत्कृष्ट हैं, परन्तु ज्ञानी तो मेरा स्वरूप ही है ऐसा मेरा मत है, क्योंकि वह स्थिर बुद्धि ज्ञानी अति उत्तम गतिस्वरूप मुझमें अच्छी प्रकार स्थित है।।
 '),
('2604ed90-d1e0-5eff-b94f-b487cde03b9d'::uuid, '1da4ce04-8aad-515b-a48f-79b1d63fa868'::uuid, 'ramsukhdas', 'hindi', '।।7.19।। बहुत जन्मोंके अन्तमें अर्थात् मनुष्यजन्ममें ''सब कुछ परमात्मा ही है'', ऐसा जो ज्ञानवान् मेरे शरण होता है, वह महात्मा अत्यन्त दुर्लभ है।'),
('b517c322-2af5-54b7-bbe7-c03be865389f'::uuid, '1da4ce04-8aad-515b-a48f-79b1d63fa868'::uuid, 'tejomayananda', 'hindi', '।।7.19।। बहुत जन्मों के अन्त में (किसी एक जन्म विशेष में) ज्ञान को प्राप्त होकर कि ''यह सब वासुदेव है'' ज्ञानी भक्त मुझे प्राप्त होता है; ऐसा महात्मा अति दुर्लभ है।।
 '),
('659fb0bc-378d-585d-982c-15e2f815345c'::uuid, 'a2f515f5-e089-5d1e-a8c0-752632982add'::uuid, 'ramsukhdas', 'hindi', '।।7.20।। उन-उन कामनाओंसे जिनका ज्ञान अपहृत हो गया है, ऐसे वे मनुष्य अपनी-अपनी प्रकृतिसे नियन्त्रित होकर (देवताओंके) उन-उन नियमोंको धारण करते हुए उन-उन देवताओंके शरण हो जाते हैं।'),
('8d965075-f40b-5e25-890f-f73fbe70ef7d'::uuid, 'a2f515f5-e089-5d1e-a8c0-752632982add'::uuid, 'tejomayananda', 'hindi', '।।7.20।। भोगविशेष की कामना से जिनका ज्ञान हर लिया गया है, ऐसे पुरुष अपने स्वभाव से प्रेरित हुए अन्य देवताओं को विशिष्ट नियम का पालन करते हुए भजते हैं।।
 ')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('95fbd9dd-d230-568c-9f53-a71b6f0e5d8d'::uuid, 'a44ddd08-c380-5af6-a5fb-1a2a516026f4'::uuid, 'ramsukhdas', 'hindi', '।।7.21।। जो-जो भक्त जिस-जिस देवताका श्रद्धापूर्वक पूजन करना चाहता है, उस-उस देवताके प्रति मैं उसकी श्रद्धाको दृढ़ कर देता हूँ।'),
('94ff2d1f-ad23-59c5-9943-d1f73337edb6'::uuid, 'a44ddd08-c380-5af6-a5fb-1a2a516026f4'::uuid, 'tejomayananda', 'hindi', '।।7.21।। जो-जो (सकामी) भक्त जिस-जिस (देवता के) रूप को श्रद्धा से पूजना चाहता है, उस-उस (भक्त) की मैं उस ही देवता के प्रति श्रद्धा को स्थिर करता हूँ।।
 '),
('85608bb6-066d-5466-945a-fee65a4d3975'::uuid, '7537b9a0-5472-516c-9191-818afcab5983'::uuid, 'ramsukhdas', 'hindi', '।।7.22।। उस (मेरे द्वारा दृढ़ की हुई) श्रद्धासे युक्त होकर वह मनुष्य (सकामभावपूर्वक) उस देवताकी उपासना करता है और उसकी वह कामना पूरी भी होती है; परन्तु वह कामना-पूर्ति मेरे द्वारा  विहित की हुई होती है।'),
('68144b10-3e15-56a9-b987-2b70084d1ea3'::uuid, '7537b9a0-5472-516c-9191-818afcab5983'::uuid, 'tejomayananda', 'hindi', '।।7.22।। वह (भक्त) उस श्रद्धा से युक्त होकर उस देवता का पूजन करता है और उससे मेरे द्वारा विधान किये हुये इच्छित भोगों को नि:सन्देह प्राप्त करता है।।
 '),
('74089bfb-874a-5249-a4b6-e755ae0e39ec'::uuid, '563bcb8f-dde1-5a35-b908-7430724dbce4'::uuid, 'ramsukhdas', 'hindi', '।।7.23।। परन्तु उन अल्पबुद्धिवाले मनुष्योंको उन देवताओंकी आराधनाका फल अन्तवाला (नाशवान्) ही मिलता है। देवताओंका पूजन करनेवाले देवताओंको प्राप्त होते हैं और मेरे भक्त मेरे ही प्राप्त होते हैं।'),
('7d4a79f1-a6c3-53da-b0e1-282b9422a8d9'::uuid, '563bcb8f-dde1-5a35-b908-7430724dbce4'::uuid, 'tejomayananda', 'hindi', '।।7.23।। परन्तु उन अल्प बुद्धि पुरुषों का वह फल नाशवान् होता है। देवताओं के पूजक देवताओं को प्राप्त होते हैं और मेरे भक्त मुझे ही प्राप्त होते हैं।।'),
('3abc4023-6700-5302-838e-39ab08d8bb65'::uuid, '322e38cb-afc4-5c75-8d95-23bbe3ebdc49'::uuid, 'ramsukhdas', 'hindi', '।।7.24।। बुद्धिहीन मनुष्य मेरे सर्वश्रेष्ठ अविनाशी परमभावको न जानते हुए अव्यक्त (मन-इन्द्रियोंसे पर) मुझ सच्चिदानन्दघन परमात्माको मनुष्यकी तरह ही शरीर धारण करनेवाला मानते हैं।'),
('cb448b9a-d5c3-5b22-90c1-b475535e71d0'::uuid, '322e38cb-afc4-5c75-8d95-23bbe3ebdc49'::uuid, 'tejomayananda', 'hindi', '।।7.24।। बुद्धिहीन पुरुष मेरे अनुत्तम (सर्वोत्तम) अव्यय परम भाव को न जानते हुए मुझ अव्यक्त को व्यक्त मानते हैं।।'),
('9b0f5d70-55c9-566c-91f9-3c1c578aaa99'::uuid, '1a58b77f-d488-5c8b-ab98-485a7b163c4b'::uuid, 'ramsukhdas', 'hindi', '।।7.25।। जो मूढ़ मनुष्य मेरेको अज और अविनाशी ठीक तरहसे नहीं जानते (मानते), उन सबके सामने योगमायासे अच्छी तरहसे आवृत हुआ मैं प्रकट नहीं होता।'),
('edc20b08-9e0c-50df-8b4e-ccbedf9cb683'::uuid, '1a58b77f-d488-5c8b-ab98-485a7b163c4b'::uuid, 'tejomayananda', 'hindi', '।।7.25।। अपनी योगमाया से आवृत्त मैं सबको प्रत्यक्ष नहीं होता हूँ। यह मोहित लोक (मनुष्य) मुझ जन्मरहित, अविनाशी को नहीं जानता है।।
 '),
('251af0b6-4236-57fd-b7f0-69a963e1b5ed'::uuid, '4f1502b6-26a5-5f34-84b9-0897905ec7b8'::uuid, 'ramsukhdas', 'hindi', '।।7.26।। हे अर्जुन ! जो प्राणी भूतकालमें हो चुके हैं, तथा जो वर्तमानमें हैं और जो भविष्यमें होंगे, उन सब प्राणियोंको तो मैं जानता हूँ; परन्तु मेरेको कोई (मूढ़ मनुष्य) नहीं जानता।'),
('b1fb0a94-6ea5-523c-bca9-ffcde040b375'::uuid, '4f1502b6-26a5-5f34-84b9-0897905ec7b8'::uuid, 'tejomayananda', 'hindi', '।।7.26।। हे अर्जुन ! पूर्व में व्यतीत हुए और वर्तमान में स्थित तथा भविष्य में होने वाले भूतमात्र को मैं जानता हूँ, परन्तु मुझे कोई भी पुरुष नहीं जानता हैं।।
 '),
('caebdd90-8340-5ce4-8572-1bc81b6a0be3'::uuid, 'c6cae0e3-531b-5a41-a1a3-bac10d5c6494'::uuid, 'ramsukhdas', 'hindi', '।।7.27।। हे भरतवंशमें उत्पन्न परंतप ! इच्छा (राग) और द्वेषसे उत्पन्न होनेवाले द्वन्द्व-मोहसे मोहित सम्पूर्ण प्राणी संसारमें मूढ़ताको अर्थात् जन्म-मरणको प्राप्त हो रहे हैं।'),
('b2ca1561-a8db-5992-babb-d7564728e0bf'::uuid, 'c6cae0e3-531b-5a41-a1a3-bac10d5c6494'::uuid, 'tejomayananda', 'hindi', '।।7.27।। हे परन्तप भारत ! इच्छा और द्वेष से उत्पन्न द्वन्द्वमोह से भूतमात्र उत्पत्ति काल में ही संमोह (अविवेक) को प्राप्त होते हैं।।
 '),
('467c311c-8e81-53bd-88c8-f35135c4590b'::uuid, 'e262c515-1c2d-52c5-b1f4-c51a91228025'::uuid, 'ramsukhdas', 'hindi', '।।7.28।। परन्तु जिन पुण्यकर्मा मनुष्योंके पाप नष्ट गये हैं, वे द्वन्द्वमोहसे रहित हुए मनुष्य दृढ़व्रती होकर मेरा भजन करते हैं।'),
('efd2b158-f1dc-5eff-9741-444862285dfe'::uuid, 'e262c515-1c2d-52c5-b1f4-c51a91228025'::uuid, 'tejomayananda', 'hindi', '।।7.28।। परन्तु जिन पुण्यकर्मी पुरुषों का पाप नष्ट हो गया है, वे द्वन्द्वमोह से निर्मुक्त और दृढ़वती पुरुष मुझे भजते हैं।।
 '),
('8b117ece-87cd-5020-bfa7-d23289a41c7c'::uuid, 'dd746d5b-2f47-50e2-b7f0-d021532a9d0e'::uuid, 'ramsukhdas', 'hindi', '।।7.29।।  जरा (वृद्धावस्था) और मरण (मृत्यु) से मोक्ष पानेके लिये जो  मेरा आश्रय लेकर प्रयत्न करते हैं, वे उस ब्रह्मको, सम्पूर्ण अध्यात्मको और सम्पूर्ण कर्मको भी जान जाते हैं।'),
('f7284af0-ac50-5f24-bfd4-62ed4d7d990d'::uuid, 'dd746d5b-2f47-50e2-b7f0-d021532a9d0e'::uuid, 'tejomayananda', 'hindi', '।।7.29।। जो मेरे शरणागत होकर जरा और मरण से मुक्ति पाने के लिए यत्न करते हैं, वे पुरुष उस ब्रह्म को, सम्पूर्ण अध्यात्म को और सम्पूर्ण कर्म को जानते हैं।।
 '),
('f50c7bde-8b13-5d66-a72e-8d3f24ab140c'::uuid, '2cdfd895-fc01-596c-9bed-527b98b45f81'::uuid, 'ramsukhdas', 'hindi', '।।7.30।। जो मनुष्य अधिभूत, अधिदैव और अधियज्ञके सहित मुझे जानते हैं, वे युक्तचेता मनुष्य अन्तकालमें भी मुझे ही जानते हैं अर्थात् प्राप्त होते हैं।'),
('791405ec-2087-5c13-a5b9-2ccc7552a0df'::uuid, '2cdfd895-fc01-596c-9bed-527b98b45f81'::uuid, 'tejomayananda', 'hindi', '।।7.30।। जो पुरुष अधिभूत और अधिदैव तथा अधियज्ञ के सहित मुझे जानते हैं, वे युक्तचित्त वाले पुरुष अन्तकाल में भी मुझे जानते हैं।।'),
('54d4759e-2d7a-5ef9-be88-2ecf2199409c'::uuid, '0a35738a-cd71-5d99-b5bd-2a6ea3e6b62b'::uuid, 'ramsukhdas', 'hindi', '।।8.1 -- 8.2।। अर्जुन बोले -- हे पुरुषोत्तम ! वह ब्रह्म क्या है? अध्यात्म क्या है? कर्म क्या है? अधिभूत किसको कहा गया है? और अधिदैव किसको कहा जाता है? यहाँ अधियज्ञ कौन है और वह इस देहमें कैसे है? हे मधूसूदन ! नियतात्मा (वशीभूत अंतःकरण वाले) मनुष्यके द्वारा अन्तकालमें आप कैसे जाननेमें आते हैं?'),
('debc2c71-e868-5dc9-a4f1-e9ada1a7b746'::uuid, '0a35738a-cd71-5d99-b5bd-2a6ea3e6b62b'::uuid, 'tejomayananda', 'hindi', '।।8.1।। अर्जुन ने कहा -हे पुरुषोत्तम ! वह ब्रह्म क्या है अध्यात्म क्या है? तथा कर्म क्या है? और अधिभूत नाम से क्या कहा गया है? तथा अधिदैव नाम से क्या कहा जाता है,'),
('03da8698-e4ec-55d6-a4b0-c06be6f5033a'::uuid, 'b5da4e49-943b-5f61-8746-7ebc22843877'::uuid, 'ramsukhdas', 'hindi', '।।8.1 -- 8.2।। अर्जुन बोले -- हे पुरुषोत्तम ! वह ब्रह्म क्या है? अध्यात्म क्या है? कर्म क्या है? अधिभूत किसको कहा गया है? और अधिदैव किसको कहा जाता है? यहाँ अधियज्ञ कौन है और वह इस देहमें कैसे है? हे मधूसूदन ! नियतात्मा (वशीभूत अन्तःकरणवाले) मनुष्यके द्वारा अन्तकालमें आप कैसे जाननेमें आते हैं?'),
('51ed8c8d-6643-52e9-8c40-6d19dc6128d7'::uuid, 'b5da4e49-943b-5f61-8746-7ebc22843877'::uuid, 'tejomayananda', 'hindi', '।।8.2।। और हे मधुसूदन ! यहाँ अधियज्ञ कौन है? और वह इस शरीर में कैसे है? और संयत चित्त वाले पुरुषों द्वारा अन्त समय में आप किस प्रकार जाने जाते हैं,'),
('501f52de-cc46-59e7-9ed2-eb91e992fd99'::uuid, 'df6b6259-6e52-5246-b81f-d9c574b51cf5'::uuid, 'ramsukhdas', 'hindi', '।।8.3।। श्रीभगवान् बोले -- परम अक्षर ब्रह्म है और जीवका अपना जो होनापन है, उसको अध्यात्म कहते हैं। प्राणियों का उद्भव (सत्ता को प्रकट) करनेवाला जो त्याग है उसको कर्म कहा जाता है।'),
('aa930a6b-884d-51c5-b183-1162f072fa1c'::uuid, 'df6b6259-6e52-5246-b81f-d9c574b51cf5'::uuid, 'tejomayananda', 'hindi', '।।8.3।। श्रीभगवान् ने कहा -- परम अक्षर (अविनाशी) तत्त्व ब्रह्म है; स्वभाव (अपना स्वरूप) अध्यात्म कहा जाता है; भूतों के भावों को उत्पन्न करने वाला विसर्ग (यज्ञ, प्रेरक बल) कर्म नाम से जाना जाता है।।
 '),
('be8fa334-947c-55de-8e72-4325135c4a0a'::uuid, 'bd07fb40-a7ad-5453-9035-2f99cd89feda'::uuid, 'ramsukhdas', 'hindi', '।।8.4।। हे देहधारियोंमें श्रेष्ठ अर्जुन ! क्षरभाव अर्थात् नाशवान् पदार्थको अधिभूत कहते हैं, पुरुष अर्थात् हिरण्यगर्भ ब्रह्माजी अधिदैव हैं और इस देहमें अन्तर्यामीरूपसे मैं ही अधियज्ञ हूँ।'),
('21b0500b-ac63-577d-96ad-77cd739a7bdd'::uuid, 'bd07fb40-a7ad-5453-9035-2f99cd89feda'::uuid, 'tejomayananda', 'hindi', '।।8.4।। हे देहधारियों में श्रेष्ठ अर्जुन ! नश्वर वस्तु (पंचमहाभूत) अधिभूत और पुरुष अधिदैव है; इस शरीर में मैं ही अधियज्ञ हूँ।।
 '),
('41556fe7-b26d-5f3f-9967-94b607eac17d'::uuid, 'f7475c48-ff10-5405-9ddf-6eb01a443475'::uuid, 'ramsukhdas', 'hindi', '।।8.5।। जो मनुष्य अन्तकालमें भी मेरा स्मरण करते हुए शरीर छोड़कर जाता है, वह मेरे स्वरुप को ही प्राप्त होता है, इसमें सन्देह नहीं है।'),
('266f3fa6-c3dd-5e10-add9-4fb9e91bd79e'::uuid, 'f7475c48-ff10-5405-9ddf-6eb01a443475'::uuid, 'tejomayananda', 'hindi', '।।8.5।। और जो कोई पुरुष अन्तकाल में मुझे ही स्मरण करता हुआ शरीर को त्याग कर जाता है, वह मेरे स्वरूप को प्राप्त होता है, इसमें कुछ भी संशय नहीं।।
 '),
('6c960c42-57bd-59ac-875b-45ab51f8f7b9'::uuid, 'b6d958e4-76fa-58c1-b6a4-8b37a2de338c'::uuid, 'ramsukhdas', 'hindi', '।।8.6।। हे कुन्तीपुत्र अर्जुन ! मनुष्य अन्तकाल में जिस-जिस भी भावका स्मरण करते हुए शरीर छोड़ता है वह उस (अन्तकालके) भावसे सदा भावित होता हुआ उस-उसको ही प्राप्त होता है अर्थात् उस-उस योनिमें ही चला जाता है।'),
('8b88800e-00c1-5548-8a57-6212317db3c0'::uuid, 'b6d958e4-76fa-58c1-b6a4-8b37a2de338c'::uuid, 'tejomayananda', 'hindi', '।।8.6।। हे कौन्तेय ! (यह जीव) अन्तकाल में जिस किसी भी भाव को स्मरण करता हुआ शरीर को त्यागता है, वह सदैव उस भाव के चिन्तन के फलस्वरूप उसी भाव को ही प्राप्त होता है।।
 '),
('c5dc3efb-b7f6-52f5-ae5c-341a0771064c'::uuid, '89535827-771c-528c-8058-86e79f79934a'::uuid, 'ramsukhdas', 'hindi', '।।8.7।। इसलिये तू सब समयमें मेरा स्मरण कर और युद्ध भी कर। मेरेमें मन और बुद्धि अर्पित करनेवाला तू निःसन्देह मेरेको ही प्राप्त होगा।'),
('e8111086-b7f2-5b18-8c07-c117adcbdbf3'::uuid, '89535827-771c-528c-8058-86e79f79934a'::uuid, 'tejomayananda', 'hindi', '।।8.7।। इसलिए, तुम सब काल में मेरा निरन्तर स्मरण करो; और युद्ध करो मुझमें अर्पण किये मन, बुद्धि से युक्त हुए निःसन्देह तुम मुझे ही प्राप्त होओगे।।
 '),
('f8a53a12-ee0a-5cd3-973a-7e6101abf610'::uuid, 'a3b577af-5887-52ca-a522-601bc06ee0c3'::uuid, 'ramsukhdas', 'hindi', '।।8.8।। हे पृथानन्दन ! अभ्यासयोगसे युक्त और अन्यका चिन्तन न करनेवाले चित्तसे परम दिव्य पुरुषका चिन्तन करता हुआ (शरीर छोड़नेवाला मनुष्य) उसीको प्राप्त हो जाता है।'),
('9e201013-a77f-5e3b-88c1-9cad16ca38ca'::uuid, 'a3b577af-5887-52ca-a522-601bc06ee0c3'::uuid, 'tejomayananda', 'hindi', '।।8.8।। हे पार्थ ! अभ्यासयोग से युक्त अन्यत्र न जाने वाले चित्त से निरन्तर चिन्तन करता हुआ (साधक) परम दिव्य पुरुष को प्राप्त होता है।।
 '),
('2c20ebed-6828-5aac-b1a7-2adb2b7bc5b7'::uuid, '024c5d09-14df-5802-8f77-980da8a78b4f'::uuid, 'ramsukhdas', 'hindi', '।।8.9।। जो सर्वज्ञ, पुराण, शासन करनेवाला, सूक्ष्म-से-सूक्ष्म, सबका धारण-पोषण करनेवाला, अज्ञानसे अत्यन्त परे, सूर्यकी तरह प्रकाशस्वरूप -- ऐसे अचिन्त्य स्वरूपका चिन्तन करता है।'),
('dfa87970-8f8d-5b50-867f-5c88680ee60c'::uuid, '024c5d09-14df-5802-8f77-980da8a78b4f'::uuid, 'tejomayananda', 'hindi', '।।8.9।। जो पुरुष सर्वज्ञ, प्राचीन (पुराण), सबके नियन्ता, सूक्ष्म से भी सूक्ष्मतर, सब के धाता, अचिन्त्यरूप, सूर्य के समान प्रकाश रूप और (अविद्या) अन्धकार से परे तत्त्व का अनुस्मरण करता है।।
 '),
('2398788c-abb4-5098-8977-3cf5da5eedef'::uuid, '7740a559-0254-5e03-b5b0-0e24bb5099e1'::uuid, 'ramsukhdas', 'hindi', '।।8.10।। वह भक्तियुक्त मनुष्य अन्तसमयमें अचल मनसे और योगबलके द्वारा भृकुटीके मध्यमें प्राणोंको अच्छी तरहसे प्रविष्ट करके (शरीर छोड़नेपर) उस परम दिव्य पुरुषको ही प्राप्त होता है।'),
('6854d061-297b-504b-94fd-059f244b9bec'::uuid, '7740a559-0254-5e03-b5b0-0e24bb5099e1'::uuid, 'tejomayananda', 'hindi', '।।8.10।। वह (साधक) अन्तकाल में योगबल से प्राण को भ्रकुटि के मध्य सम्यक् प्रकार स्थापन करके निश्चल मन से भक्ति युक्त होकर उस परम दिव्य पुरुष को प्राप्त होता है।।'),
('f9495417-e0b3-5a5b-a8e5-cda24a8a13e8'::uuid, '229f7af3-6bfa-5243-9fac-87d086cd898c'::uuid, 'ramsukhdas', 'hindi', '।।8.11।। वेदवेत्ता लोग जिसको अक्षर कहते हैं, वीतराग यति जिसको प्राप्त करते हैं और साधक जिसकी प्राप्तिकी इच्छा करते हुए ब्रह्मचर्यका पालन करते हैं, वह पद मैं तेरे लिये संक्षेपसे कहूँगा।'),
('eb234503-09ac-5f31-ad53-23830276789f'::uuid, '229f7af3-6bfa-5243-9fac-87d086cd898c'::uuid, 'tejomayananda', 'hindi', '।।8.11।। वेद के जानने वाले विद्वान जिसे अक्षर कहते हैं; रागरहित यत्नशील पुरुष जिसमें प्रवेश करते हैं; जिसकी इच्छा से (साधक गण) ब्रह्मचर्य का पालन करते हैं - उस पद (लक्ष्य) को मैं तुम्हें संक्षेप में कहूँगा।।
 '),
('1617f25f-58ef-58f8-921f-7992cb9fc6bb'::uuid, 'f2222c2c-776e-51cf-840f-47309970f4d2'::uuid, 'ramsukhdas', 'hindi', '।।8.12 -- 8.13।। (इन्द्रियोंके) सम्पूर्ण द्वारोंको रोककर मनका हृदयमें निरोध करके और अपने प्राणोंको मस्तकमें स्थापित करके योगधारणामें सम्यक् प्रकारसे स्थित हुआ जो ''ऊँ'' इस एक अक्षर ब्रह्मका  उच्चारण और मेरा स्मरण करता हुआ शरीरको छोड़कर जाता है, वह परमगतिको प्राप्त होता है।'),
('b768f364-b614-5b72-88b6-f744181d1dc1'::uuid, 'f2222c2c-776e-51cf-840f-47309970f4d2'::uuid, 'tejomayananda', 'hindi', '।।8.12।। सब (इन्द्रियों के) द्वारों को संयमित कर मन को हृदय में स्थिर करके और प्राण को मस्तक में स्थापित करके योगधारणा में स्थित हुआ।।'),
('9b024f6e-a3b6-51c3-969d-3bc2a4dd4e77'::uuid, '2c463b87-9b9e-517f-8805-2a457aebb10c'::uuid, 'ramsukhdas', 'hindi', '।।8.12 -- 8.13।। (इन्द्रियोंके) सम्पूर्ण द्वारोंको रोककर मनका हृदयमें निरोध करके और अपने प्राणोंको मस्तकमें स्थापित करके योगधारणामें सम्यक् प्रकारसे स्थित हुआ जो साधक  ''ऊँ'' इस एक अक्षर ब्रह्मका उच्चारण और मेरा स्मरण करता हुआ शरीरको छोड़कर जाता है, वह परमगतिको प्राप्त होता है।'),
('1c69baf4-d16c-54bf-a6c3-fcd6059c18fe'::uuid, '2c463b87-9b9e-517f-8805-2a457aebb10c'::uuid, 'tejomayananda', 'hindi', '।।8.13।। जो पुरुष ओऽम् इस एक अक्षर ब्रह्म का उच्चारण करता हुआ और मेरा स्मरण करता हुआ शरीर का त्याग करता है, वह परम गति को प्राप्त होता है।।
 '),
('d49d4d04-d24f-50ea-b0ec-12aaa74de141'::uuid, '36a57b78-8af1-5f62-ac68-67c2b3e81294'::uuid, 'ramsukhdas', 'hindi', '।।8.14।।हे पृथानन्दन ! अनन्यचित्तवाला जो मनुष्य मेरा नित्य-निरन्तर स्मरण करता है, उस नित्ययुक्त योगीके लिये मैं सुलभ हूँ अर्थात् उसको सुलभतासे प्राप्त हो जाता हूँ।'),
('b7478e61-b1ef-5fba-817a-39e5e8720394'::uuid, '36a57b78-8af1-5f62-ac68-67c2b3e81294'::uuid, 'tejomayananda', 'hindi', '।।8.14।। हे पार्थ ! जो अनन्यचित्त वाला पुरुष मेरा स्मरण करता है, उस नित्ययुक्त योगी के लिए मैं सुलभ हूँ अर्थात् सहज ही प्राप्त हो जाता हूँ।।
 '),
('3dca7bef-116b-5752-a576-1eefefac2294'::uuid, '079f240e-3b90-5584-a27a-4e75cfc546a2'::uuid, 'ramsukhdas', 'hindi', '।।8.15।। महात्मालोग मुझे प्राप्त करके दुःखालय और अशाश्वत पुनर्जन्मको प्राप्त नहीं होते; क्योंकि वे परमसिद्धिको प्राप्त हो गये हैं अर्थात् उनको परम प्रेमकी प्राप्ति हो गयी है।'),
('c9548709-62d0-5711-8506-be84c77277b9'::uuid, '079f240e-3b90-5584-a27a-4e75cfc546a2'::uuid, 'tejomayananda', 'hindi', '।।8.15।। परम सिद्धि को प्राप्त हुये महात्माजन मुझे प्राप्त कर अनित्य दुःख के आलयरूप (गृहरूप) पुनर्जन्म को नहीं प्राप्त होते हैं।।
 '),
('8391a4a0-2297-5e2d-bdbc-76bb37fb3153'::uuid, '2b8cb7cf-d821-519c-adaa-112bbecf09d2'::uuid, 'ramsukhdas', 'hindi', '।।8.16।। हे अर्जुन ! ब्रह्मलोकतक सभी लोक पुनरावर्ती है; परन्तु हे कौन्तेय ! मुझे प्राप्त होनेपर पुनर्जन्म नहीं होता।'),
('cc4c5b3c-d800-558b-a29e-a8612f140353'::uuid, '2b8cb7cf-d821-519c-adaa-112bbecf09d2'::uuid, 'tejomayananda', 'hindi', '।।8.16।। हे अर्जुन ! ब्रह्म लोक तक के सब लोग पुनरावर्ती स्वभाव वाले हैं। परन्तु, हे कौन्तेय ! मुझे प्राप्त होने पर पुनर्जन्म नहीं होता।।
 '),
('1014a365-98d0-5061-8782-6aeb754cae4d'::uuid, 'e59761d3-66f8-540d-89bb-4ecb7fd44773'::uuid, 'ramsukhdas', 'hindi', '।।8.17।। जो मनुष्य ब्रह्माके एक हज़ार चतुर्युगीवाले एक दिनको और सहस्त्र चतुर्युगीपर्यन्त एक रातको जानते हैं, वे मनुष्य ब्रह्माके दिन और रातको जाननेवाले हैं।'),
('f3138791-28b6-54ab-9546-230cec010fd1'::uuid, 'e59761d3-66f8-540d-89bb-4ecb7fd44773'::uuid, 'tejomayananda', 'hindi', '।।8.17।। जो लोग ब्रह्मा जी के एक दिन की अवधि जानते हैं जो कि सहस्र वर्ष की है तथा एक सहस्र वर्ष की अवधि की एक रात्रि को जानते हैं वे दिन और रात्रि को जानने वाले पुरुष हैं।।
 '),
('540657cd-5eb8-50b1-8d81-0c69824baf0e'::uuid, '8b2e2dff-85ef-5fb8-a057-118fd1e19f0c'::uuid, 'ramsukhdas', 'hindi', '।।8.18।। ब्रह्माजीके दिनके आरम्भकालमें अव्यक्त- (ब्रह्माजीके सूक्ष्म-शरीर-) से सम्पूर्ण प्राणी पैदा होते हैं और ब्रह्माजीकी रातके आरम्भकालमें उसी अव्यक्तमें सम्पूर्ण प्राणी लीन हो जाते हैं।'),
('786e8d95-774e-5134-84f2-cb8d9c168d1f'::uuid, '8b2e2dff-85ef-5fb8-a057-118fd1e19f0c'::uuid, 'tejomayananda', 'hindi', '।।8.18।। (ब्रह्माजी के) दिन का उदय होने पर अव्यक्त से (यह) व्यक्त (चराचर जगत्) उत्पन्न होता है; और (ब्रह्माजी की) रात्रि के आगमन पर उसी अव्यक्त में लीन हो जाता है।।
 '),
('0f52e9ec-898b-5bde-9380-99c2f3a96926'::uuid, 'd82bcfff-8d2c-53b9-8e56-cacfd5830a74'::uuid, 'ramsukhdas', 'hindi', '।।8.19।। हे पार्थ ! वही यह प्राणिसमुदाय उत्पन्न हो-होकर प्रकृतिके परवश हुआ ब्रह्माके दिनके समय उत्पन्न होता है और ब्रह्माकी रात्रिके समय लीन होता है।'),
('56228599-4a52-575f-9e2d-02e880a0d991'::uuid, 'd82bcfff-8d2c-53b9-8e56-cacfd5830a74'::uuid, 'tejomayananda', 'hindi', '।।8.19।। हे पार्थ ! वही यह भूतसमुदाय, है जो पुनः पुनः उत्पन्न होकर लीन होता है। अवश हुआ (यह भूतग्राम) रात्रि के आगमन पर लीन तथा दिन के उदय होने पर व्यक्त होता है।।
 '),
('2d4779dd-6b09-53c5-81ae-72c3cc497357'::uuid, 'a5f52f99-5d8e-540f-99e9-727da5167afc'::uuid, 'ramsukhdas', 'hindi', '।।8.20।। परन्तु उस अव्यक्त- (ब्रह्माजीके सूक्ष्म-शरीर-) से अन्य अनादि सर्वश्रेष्ठ भावरूप जो अव्यक्त है, उसका सम्पूर्ण प्राणियोंके नष्ट होनेपर भी नाश नहीं होता।'),
('959d6483-d13f-582e-9bbf-9e0f275784dc'::uuid, 'a5f52f99-5d8e-540f-99e9-727da5167afc'::uuid, 'tejomayananda', 'hindi', '।।8.20।। परन्तु उस अव्यक्त से परे अन्य जो सनातन अव्यक्त भाव है, वह समस्त भूतों के नष्ट होने पर भी नष्ट नहीं होता।।
 '),
('f9803f30-52af-5458-a8ea-a5ed26e58740'::uuid, '4dc2b0b4-46c9-5af9-a6e8-ed3a53020ce0'::uuid, 'ramsukhdas', 'hindi', '।।8.21।। उसीको अव्यक्त और अक्षर कहा गया है और उसीको परमगति कहा गया है तथा जिसको प्राप्त होनेपर जीव फिर लौटकर नहीं आते, वह मेरा परमधाम है।'),
('eaeebd24-e8ff-5880-99ad-ac9967dc35de'::uuid, '4dc2b0b4-46c9-5af9-a6e8-ed3a53020ce0'::uuid, 'tejomayananda', 'hindi', '।।8.21।। जो अव्यक्त अक्षर कहा गया है, वही परम गति (लक्ष्य) है। जिसे प्राप्त होकर (साधकगण) पुनः (संसार को) नहीं लौटते, वह मेरा परम धाम है।।
 '),
('3a447dbf-9793-5229-9803-6b4b60cb51b5'::uuid, '9b80e195-8bd7-5ba2-a1bd-888f218a3ae8'::uuid, 'ramsukhdas', 'hindi', '।।8.22।। हे पृथानन्दन अर्जुन ! सम्पूर्ण प्राणी जिसके अन्तर्गत हैं और जिससे यह सम्पूर्ण संसार व्याप्त है, वह परम पुरुष परमात्मा तो अनन्यभक्तिसे प्राप्त होनेयोग्य है।'),
('ddfd363b-6f7a-52ca-8424-98fc7994c2c0'::uuid, '9b80e195-8bd7-5ba2-a1bd-888f218a3ae8'::uuid, 'tejomayananda', 'hindi', '।।8.22।। हे पार्थ ! जिस (परमात्मा) के अन्तर्गत समस्त भूत हैं और जिससे यह सम्पूर्ण (जगत्) व्याप्त है, वह परम पुरुष अनन्य भक्ति से ही प्राप्त करने योग्य है।।
 '),
('27df2094-5300-5094-9e21-a3309b1180ad'::uuid, 'a15d2915-ab75-5147-b69e-83ffb90778de'::uuid, 'ramsukhdas', 'hindi', '।।8.23।। हे भरतवंशियोंमें श्रेष्ठ अर्जुन ! जिस काल अर्थात् मार्गमें शरीर छोड़कर गये हुए योगी अनावृत्तिको प्राप्त होते हैं अर्थात् पीछे लौटकर नहीं आते और (जिस मार्गमें गये हुए) आवृत्तिको प्राप्त होते हैं अर्थात् पीछे लौटकर आते हैं, उस कालको अर्थात् दोनों मार्गोंको मैं कहूँगा।'),
('3a7fd893-d732-5ec5-96a0-7432968cbb99'::uuid, 'a15d2915-ab75-5147-b69e-83ffb90778de'::uuid, 'tejomayananda', 'hindi', '।।8.23।। हे भरतश्रेष्ठ ! जिस काल में (मार्ग में) शरीर त्याग कर गये हुए योगीजन अपुनरावृत्ति को, और (या) पुनरावृत्ति को प्राप्त होते हैं, वह काल (मार्ग) मैं तुम्हें बताऊँगा।।
 '),
('30422755-a9eb-5a45-b394-88a8ca9e5c69'::uuid, '46e0ee3c-ed51-5493-9e72-24f889d6ad5e'::uuid, 'ramsukhdas', 'hindi', '।।8.24।। जिस मार्गमें प्रकाशस्वरूप अग्निका अधिपति देवता, दिनका अधिपति देवता, शुक्लपक्षका अधिपति देवता, और छः महीनोंवाले उत्तरायणका अधिपति देवता है, शरीर छोड़कर उस मार्गसे गये हुए ब्रह्मवेत्ता पुरुष (पहले ब्रह्मलोकको प्राप्त होकर पीछे ब्रह्माजीके साथ) ब्रह्मको प्राप्त हो जाते हैं।'),
('e27c2421-4367-5b51-9cd8-3170b92d3ceb'::uuid, '46e0ee3c-ed51-5493-9e72-24f889d6ad5e'::uuid, 'tejomayananda', 'hindi', '।।8.24।। जो ब्रह्मविद् साधकजन मरणोपरान्त अग्नि, ज्योति, दिन, शुक्लपक्ष और उत्तरायण के छः मास वाले मार्ग से जाते हैं, वे ब्रह्म को प्राप्त होते हैं।।
 '),
('99781ae3-bab9-58c5-b53e-c0f47c5f6eed'::uuid, 'c1a256da-a274-55bd-9628-73e55c1d39ca'::uuid, 'ramsukhdas', 'hindi', '।।8.25।। जिस मार्गमें धूमका अधिपति देवता, रात्रिका अधिपति देवता, कृष्णपक्षका अधिपति देवता और छः महीनोंवाले दक्षिणायनका अधिपति देवता है, शरीर छोड़कर उस मार्गसे गया हुआ योगी (सकाम मनुष्य) चन्द्रमाकी ज्योतिको प्राप्त होकर लौट आता है अर्थात् जन्म-मरणको प्राप्त होता है।'),
('b6e11cd8-246a-5bfd-aa93-cbf9ed5836a9'::uuid, 'c1a256da-a274-55bd-9628-73e55c1d39ca'::uuid, 'tejomayananda', 'hindi', '।।8.25।। धूम, रात्रि, कृष्णपक्ष और दक्षिणायन के छः मास वाले मार्ग से चन्द्रमा की ज्योति को प्राप्त कर, योगी (संसार को) लौटता है।।
 '),
('7a365b90-5fc7-5f71-8342-730d39c65a42'::uuid, '82d794a7-e2da-5c17-bc6b-87f6850ef802'::uuid, 'ramsukhdas', 'hindi', '।।8.26।। क्योंकि शुक्ल और कृष्ण -- ये दोनों गतियाँ अनादिकालसे जगत्-(प्राणिमात्र-) के साथ सम्बन्ध रखनेवाली मानी गई हैं। इनमेंसे एक गतिमें जानेवालेको लौटना नहीं पड़ता और दूसरी गतिमें जानेवालेको लौटना पड़ता है।'),
('5742248c-49cd-557a-9a85-4da69c31d002'::uuid, '82d794a7-e2da-5c17-bc6b-87f6850ef802'::uuid, 'tejomayananda', 'hindi', '।।8.26।। जगत् के ये दो प्रकार के शुक्ल और कृष्ण मार्ग सनातन माने गये हैं । इनमें एक (शुक्ल) के द्वारा (साधक) अपुनरावृत्ति को तथा अन्य (कृष्ण) के द्वारा पुनरावृत्ति को प्राप्त होता है।।
 '),
('aa9c889c-aed5-542f-866c-2a8ab8e0716c'::uuid, '64ecf1da-d332-5de6-9cc6-29542ebcdbd3'::uuid, 'ramsukhdas', 'hindi', '।।8.27।। हे पृथानन्दन  ! इन दोनों मार्गोंको जाननेवाला कोई भी योगी मोहित नहीं होता। अतः हे अर्जुन ! तू सब समयमें योगयुक्त हो जा।'),
('0fdd09c7-1c2f-5b16-b780-4c8097cc2354'::uuid, '64ecf1da-d332-5de6-9cc6-29542ebcdbd3'::uuid, 'tejomayananda', 'hindi', '।।8.27।। हे पार्थ इन दो मार्गों को (तत्त्व से) जानने वाला कोई भी योगी मोहित नहीं होता। इसलिए, हे अर्जुन ! तुम सब काल में योगयुक्त बनो।।
 '),
('a61ce310-f5c8-587b-aead-377f90f46031'::uuid, '6ed58d47-8424-5726-a484-f983fe7f90e4'::uuid, 'ramsukhdas', 'hindi', '।।8.28।। योगी इसको (शुक्ल और कृष्णमार्गके रहस्यको) जानकर वेदोंमें, यज्ञोंमें, तपोंमें तथा दानमें जो-जो पुण्यफल कहे गये हैं, उन सभी पुण्यफलोंका अतिक्रमण कर जाता है और आदिस्थान परमात्माको प्राप्त हो जाता है।'),
('ac6a186b-583e-531c-8b59-ef8195e02021'::uuid, '6ed58d47-8424-5726-a484-f983fe7f90e4'::uuid, 'tejomayananda', 'hindi', '।।8.28।। योगी पुरुष यह सब (दोनों मार्गों के तत्त्व को) जानकर वेदाध्ययन, यज्ञ, तप और दान करने में जो पुण्य फल कहा गया है, उस सबका उल्लंघन कर जाता है और आद्य (सनातन), परम स्थान को प्राप्त होता है।।'),
('60b56bdf-9744-5184-8010-19e7f0a803f5'::uuid, '5cb6ec4b-1ec9-534d-9dfd-ab24b0b469ec'::uuid, 'ramsukhdas', 'hindi', '।।9.1।। श्रीभगवान् बोले -- यह अत्यन्त गोपनीय विज्ञानसहित ज्ञान दोषदृष्टिरहित तेरे लिये तो मैं फिर अच्छी तरहसे कहूँगा, जिसको जानकर तू अशुभसे अर्थात् जन्म-मरणरूप संसारसे मुक्त हो जायगा।'),
('a00a2344-73f4-5a55-bab9-509e6accb811'::uuid, '5cb6ec4b-1ec9-534d-9dfd-ab24b0b469ec'::uuid, 'tejomayananda', 'hindi', '।।9.1।। श्रीभगवान् ने कहा -- तुम अनसूयु (दोष दृष्टि रहित) के लिए मैं इस गुह्यतम ज्ञान को विज्ञान के सहित कहूँगा, जिसको जानकर तुम अशुभ (संसार बंधन) से मुक्त हो जाओगे।।
 '),
('b54dc6e8-f57b-56f6-8cce-b5cf7ebd0a12'::uuid, '2a712fc2-43bf-57b0-9256-6951f09756f7'::uuid, 'ramsukhdas', 'hindi', '।।9.2।। यह सम्पूर्ण विद्याओंका और सम्पूर्ण गोपनीयोंका राजा है। यह अति पवित्र तथा अतिश्रेष्ठ है और इसका फल भी प्रत्यक्ष है। यह धर्ममय है, अविनाशी है और करनेमें बहुत सुगम है अर्थात् इसको प्राप्त करना बहुत सुगम है।'),
('9ffdd40d-b359-53de-8350-84ed7ecd26e2'::uuid, '2a712fc2-43bf-57b0-9256-6951f09756f7'::uuid, 'tejomayananda', 'hindi', '।।9.2।। यह ज्ञान राजविद्या (विद्याओं का राजा) और राजगुह्य (सब गुह्यों अर्थात् रहस्यों का राजा) एवं पवित्र, उत्तम, प्रत्यक्ष ज्ञानवाला और धर्मयुक्त है, तथा करने में सरल और अव्यय है।।
 '),
('a81e3314-2564-5830-a699-3115bb001bd7'::uuid, 'e37da1cd-b33e-5a8a-929b-6273dfa406de'::uuid, 'ramsukhdas', 'hindi', '।।9.3।। हे परंतप! इस धर्मकी महिमापर श्रद्धा न रखनेवाले मनुष्य मेरे प्राप्त न होकर मृत्युरूप संसारके मार्गमें लौटते रहते हैं अर्थात् बार-बार जन्मते-मरते रहते हैं।'),
('1c6b31b8-0ac3-557d-890d-ebe1d47c6b32'::uuid, 'e37da1cd-b33e-5a8a-929b-6273dfa406de'::uuid, 'tejomayananda', 'hindi', '।।9.3।। हे परन्तप ! इस धर्म में श्रद्धारहित पुरुष मुझे प्राप्त न होकर मृत्युरूपी संसार में रहते हैं (भ्रमण करते हैं)।।
 '),
('be75c0f9-6d37-5c80-976a-470fad602c22'::uuid, '09a9275c-8aed-53ec-8d58-3dfb46927cc6'::uuid, 'ramsukhdas', 'hindi', '।।9.4 -- 9.5।। यह सब संसार मेरे निराकार स्वरूपसे व्याप्त है। सम्पूर्ण प्राणी मेरेमें स्थित हैं; परन्तु मैं उनमें स्थित नहीं हूँ तथा वे प्राणी भी मुझ में स्थित नहीं हैं -- मेरे इस ईश्वर-सम्बन्धी योग-(सामर्थ्य-) को देख ! सम्पूर्ण प्राणियोंको उत्पन्न करनेवाला और उनका धारण, भरण-पोषण करनेवाला मेरा स्वरूप उन प्राणियोंमें स्थित नहीं है।'),
('a9d9e732-e0fe-5928-9602-fa2d5b651841'::uuid, '09a9275c-8aed-53ec-8d58-3dfb46927cc6'::uuid, 'tejomayananda', 'hindi', '।।9.4।। यह सम्पूर्ण जगत् मुझ (परमात्मा) के अव्यक्त स्वरूप से व्याप्त है; भूतमात्र मुझमें स्थित है, परन्तु मैं उनमें स्थित नहीं हूं।।
 '),
('b6bfbd84-3715-5cbd-8eb5-92dc320db91c'::uuid, '506a222e-9e68-55cb-aee2-53e4a265d737'::uuid, 'ramsukhdas', 'hindi', '।।9.4 -- 9.5।। यह सब संसार मेरे निराकार स्वरूपसे व्याप्त है। सम्पूर्ण प्राणी मुझ में स्थित हैं; परन्तु मैं उनमें स्थित नहीं हूँ तथा वे प्राणी भी मेरेमें स्थित नहीं हैं -- मेरे इस ईश्वर-सम्बन्धी योग-(सामर्थ्य-) को देख ! सम्पूर्ण प्राणियोंको उत्पन्न करनेवाला और उनका धारण, भरण-पोषण करनेवाला मेरा स्वरूप उन प्राणियोंमें स्थित नहीं है।'),
('f94d8437-ac1a-5ab9-8293-d9f0424132b2'::uuid, '506a222e-9e68-55cb-aee2-53e4a265d737'::uuid, 'tejomayananda', 'hindi', '।।9.5।। और (वस्तुत:) भूतमात्र मुझ में स्थित नहीं है; मेरे ईश्वरीय योग को देखो कि भूतों को धारण करने वाली और भूतों को उत्पन्न करने वाली मेरी आत्मा उन भूतों में स्थित नहीं है।।
 '),
('e9bad91d-4561-50c5-9482-79018ab104b8'::uuid, 'b4c94307-c261-526e-8e49-c014d748788a'::uuid, 'ramsukhdas', 'hindi', '।।9.6।। जैसे सब जगह विचरनेवाली महान् वायु नित्य ही आकाशमें स्थित रहती है, ऐसे ही सम्पूर्ण प्राणी मुझमें ही स्थित रहते हैं -- ऐसा तुम मान लो।'),
('50b47e79-bbb6-5706-80a6-881caede39d5'::uuid, 'b4c94307-c261-526e-8e49-c014d748788a'::uuid, 'tejomayananda', 'hindi', '।।9.6।। जैसे सर्वत्र विचरण करने वाली महान् वायु सदा आकाश में स्थित रहती हैं, वैसे ही सम्पूर्ण भूत मुझमें स्थित हैं, ऐसा तुम जानो।।
 '),
('eeb4dbb0-faad-59e2-a855-4b7d4ceabb06'::uuid, 'b1bfddf1-d293-5863-83b3-520157d7d7ba'::uuid, 'ramsukhdas', 'hindi', '।।9.7।। हे कुन्तीनन्दन ! कल्पोंका क्षय होनेपर सम्पूर्ण प्राणी मेरी प्रकृतिको प्राप्त होते हैं और कल्पोंके आदिमें मैं फिर उनकी रचना करता हूँ।'),
('94949d23-496f-53dd-869f-4f7f4dec0b97'::uuid, 'b1bfddf1-d293-5863-83b3-520157d7d7ba'::uuid, 'tejomayananda', 'hindi', '।।9.7।। हे कौन्तेय ! (एक) कल्प के अन्त में समस्त भूत मेरी प्रकृति को प्राप्त होते हैं; और (दूसरे) कल्प के प्रारम्भ में उनको मैं फिर रचता हूँ।।
 '),
('d40434fe-c3c0-570c-b834-31d827741db6'::uuid, '3dd3f0fa-a064-5bbe-93d4-c827b38c0501'::uuid, 'ramsukhdas', 'hindi', '।।9.8।। प्रकृतिके वशमें होनेसे परतन्त्र हुए इस सम्पूर्ण प्राणिसमुदायको मैं (कल्पोंके आदिमें) अपनी प्रकृतिको वशमें करके बार-बार रचता हूँ।'),
('5261fd96-ef75-5950-a193-8b60bf42769a'::uuid, '3dd3f0fa-a064-5bbe-93d4-c827b38c0501'::uuid, 'tejomayananda', 'hindi', '।।9.8।। प्रकृति को अपने वश में करके (अर्थात् उसे चेतनता प्रदान कर) स्वभाव के वश से परतन्त्र (अवश) हुए इस सम्पूर्ण भूत समुदाय को मैं पुन:-पुन: रचता हूँ।।
 '),
('19422660-4b88-5957-bf31-f0058bc39ca6'::uuid, '8da766e6-e15a-5b0d-a402-f53cbb73d6fd'::uuid, 'ramsukhdas', 'hindi', '।।9.9।। हे धनञ्जय ! उन (सृष्टि-रचना आदि) कर्मोंमें अनासक्त और उदासीनकी तरह रहते हुए मेरेको वे कर्म नहीं बाँधते।'),
('673c803f-1d58-5893-91b1-88a4c25af8b3'::uuid, '8da766e6-e15a-5b0d-a402-f53cbb73d6fd'::uuid, 'tejomayananda', 'hindi', '।।9.9।। हे धनंजय ! उन कर्मों में आसक्ति रहित और उदासीन के समान स्थित मुझ (परमात्मा) को वे कर्म नहीं बांधते हैं।।
 '),
('e93e53dd-43c8-56bf-84c4-c6217f4e2d9e'::uuid, '4b08a8c8-fd3f-5a51-908e-d8d7816f818c'::uuid, 'ramsukhdas', 'hindi', '।।9.10।। प्रकृति मेरी अध्यक्षतामें सम्पूर्ण चराचर जगत् को रचती है। हे कुन्तीनन्दन ! इसी हेतुसे जगत् का विविध प्रकारसे परिवर्तन होता है।'),
('c02b7455-8063-58e2-8b01-880a5ff0d3bc'::uuid, '4b08a8c8-fd3f-5a51-908e-d8d7816f818c'::uuid, 'tejomayananda', 'hindi', '।।9.10।। हे कौन्तेय ! मुझ अध्यक्ष के कारण ( अर्थात् मेरी अध्यक्षता में) प्रकृति चराचर जगत् को उत्पन्न करती है; इस कारण यह जगत् घूमता रहता है।।
 '),
('b0d45f20-a979-5e82-9982-d94ff4a7a1a7'::uuid, '05961472-12d9-5efc-b8ea-4e6fc1735f34'::uuid, 'ramsukhdas', 'hindi', '।।9.11।। मूर्खलोग मेरे सम्पूर्ण प्राणियोंके महान् ईश्वररूप परमभावको न जानते हुए मुझे मनुष्यशरीरके आश्रित मानकर अर्थात् साधारण मनुष्य मानकर मेरी अवज्ञा करते हैं।'),
('9c887865-b1fb-516c-a4e9-f1c8102d8353'::uuid, '05961472-12d9-5efc-b8ea-4e6fc1735f34'::uuid, 'tejomayananda', 'hindi', '।।9.11।। समस्त भूतों के महान् ईश्वर रूप मेरे परम भाव को नहीं जानते हुए मूढ़ लोग मनुष्य शरीरधारी मुझ परमात्मा का अनादर करते हैं।।'),
('d923c799-bc6f-50d4-9114-c454f4671dff'::uuid, 'de6eced8-c049-535b-bc8a-31a89afa832e'::uuid, 'ramsukhdas', 'hindi', '।।9.12।। जिनकी सब आशाएँ व्यर्थ होती हैं, सब शुभ-कर्म व्यर्थ होते हैं और सब ज्ञान व्यर्थ होते हैं अर्थात् जिनकी आशाएँ, कर्म और ज्ञान सत्-फल देनेवाले नहीं होते, ऐसे अविवेकी मनुष्य आसुरी, राक्षसी और मोहिनी फकृतिका आश्रय लेते हैं।'),
('3b390900-97f6-52ea-bafc-b6a0cfaabb73'::uuid, 'de6eced8-c049-535b-bc8a-31a89afa832e'::uuid, 'tejomayananda', 'hindi', '।।9.12।। वृथा आशा, वृथा कर्म और वृथा ज्ञान वाले अविचारीजन राक्षसों के और असुरों के मोहित करने वाले स्वभाव को धारण किये रहते हैं।।
 ')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('30e62e35-1d37-5460-9869-51bf297dd62a'::uuid, '47b344ec-b43e-5fde-85d8-7dee4b90fe88'::uuid, 'ramsukhdas', 'hindi', '।।9.13।। परन्तु हे पृथानन्दन ! दैवी प्रकृतिके आश्रित अनन्यमनवाले महात्मालोग मुझे सम्पूर्ण प्राणियोंका आदि और अविनाशी समझकर मेरा भजन करते हैं।'),
('9b7e55fc-02f7-516c-8607-e330d5271b6b'::uuid, '47b344ec-b43e-5fde-85d8-7dee4b90fe88'::uuid, 'tejomayananda', 'hindi', '।।9.13।। हे पार्थ ! परन्तु दैवी प्रकृति के आश्रित महात्मा पुरुष मुझे समस्त भूतों का आदिकारण और अव्ययस्वरूप जानकर अनन्यमन से युक्त होकर मुझे भजते हैं।।
 '),
('15effd8c-46e4-5f02-8fe7-4857bd204599'::uuid, 'db488ea7-8b3f-5c9a-ad38-9b161f25d24a'::uuid, 'ramsukhdas', 'hindi', '।।9.14।। नित्य- (मेरेमें) युक्त मनुष्य दृढ़व्रती होकर लगनपूर्वक साधनमें लगे हुए और भक्तिपूर्वक कीर्तन करते हुए तथा नमस्कार करते हुये निरन्तर मेरी उपासना करते हैं।'),
('b5e351ab-f92e-5242-b451-e7928d45058e'::uuid, 'db488ea7-8b3f-5c9a-ad38-9b161f25d24a'::uuid, 'tejomayananda', 'hindi', '।।9.14।। सतत मेरा कीर्तन करते हुए, प्रयत्नशील, दढ़व्रती पुरुष मुझे नमस्कार करते हुए, नित्ययुक्त होकर भक्तिपूर्वक मेरी उपासना करते हैं।।
 '),
('822948d7-ca43-5ae6-8549-09a7f6be91e2'::uuid, '2b102cad-2dba-5c60-ae6a-aab71303d17d'::uuid, 'ramsukhdas', 'hindi', '।।9.15।। दूसरे साधक ज्ञानयज्ञके द्वारा एकीभावसे (अभेद-भावसे) मेरा पूजन करते हुए मेरी उपासना करते हैं और दूसरे कई साधक अपनेको पृथक् मानकर चारों तरफ मुखवाले मेरे विराट्ररुपकी अर्थात् संसारको मेरा विराट्ररुप मानकर (सेव्य-सेवकभावसे) मेरी अनेक प्रकारसे उपासना करते हैं।'),
('b52c0399-4ec1-5f4e-88a7-7bb1e18ad140'::uuid, '2b102cad-2dba-5c60-ae6a-aab71303d17d'::uuid, 'tejomayananda', 'hindi', '।।9.15।। कोई मुझे ज्ञानयज्ञ के द्वारा पूजन करते हुए एकत्वभाव से उपासते हैं, कोई पृथक भाव से, कोई बहुत प्रकार से मुझ विराट स्वरूप (विश्वतो मुखम्) को उपासते हैं।।
 '),
('c75c0c9e-22b8-5555-8dca-5f8705944e54'::uuid, 'f8f0861e-e2ba-599d-84da-238dd603e697'::uuid, 'ramsukhdas', 'hindi', '।।9.16 -- 9.18।।  क्रतु मैं हूँ, यज्ञ मैं हूँ, स्वधा मैं हूँ, औषध मैं हूँ, मन्त्र मैं हूँ, घृत मैं हूँ, अग्नि मैं हूँ और हवनरूप क्रिया भी मैं हूँ। जाननेयोग्य पवित्र, ओंकार, ऋग्वेद, सामवेद और यजुर्वेद भी मैं ही हूँ। इस सम्पूर्ण जगत्का पिता, धाता, माता, पितामह, गति, भर्ता, प्रभु, साक्षी, निवास, आश्रय, सुहृद्, उत्पत्ति, प्रलय, स्थान, निधान तथा अविनाशी बीज भी मैं ही हूँ।'),
('b3589fd0-e324-5f15-b019-d747df4577a1'::uuid, 'f8f0861e-e2ba-599d-84da-238dd603e697'::uuid, 'tejomayananda', 'hindi', '।।9.16।। मैं ऋक्रतु हूँ; मैं यज्ञ हूँ; स्वधा और औषध मैं हूँ, मैं मन्त्र हूँ, घी हूँ, मैं अग्नि हूँ और हुतं अर्थात् हवन कर्म मैं हूँ।।
 '),
('7b4f69dc-aa6d-5d30-9f26-7d9a74c21660'::uuid, 'cdcebaf2-b698-5af0-b875-90b9e0b044f5'::uuid, 'ramsukhdas', 'hindi', '।।9.16 -- 9.18।। क्रतु मैं हूँ, यज्ञ मैं हूँ, स्वधा मैं हूँ, औषध मैं हूँ, मन्त्र मैं हूँ, घृत मैं हूँ, अग्नि मैं हूँ और हवनरूप क्रिया भी मैं हूँ। जाननेयोग्य पवित्र, ओंकार, ऋग्वेद, सामवेद और यजुर्वेद भी मैं ही हूँ। इस सम्पूर्ण जगत् का पिता, धाता, माता, पितामह, गति, भर्ता, प्रभु, साक्षी, निवास, आश्रय, सुहृद्, उत्पत्ति, प्रलय, स्थान, निधान तथा अविनाशी बीज भी मैं ही हूँ।'),
('bb1f713c-05cc-5b09-ae95-4cda69b01817'::uuid, 'cdcebaf2-b698-5af0-b875-90b9e0b044f5'::uuid, 'tejomayananda', 'hindi', '।।9.17।। मैं ही इस जगत् का पिता, माता, धाता (धारण करने वाला) और पितामह हूँमैं वेद्य (जानने योग्य) वस्तु हूँ, पवित्र, ओंकार, ऋग्वेद, सामवेद और यजुर्वेद भी मैं ही हूँ।।
 '),
('dafe0e95-8025-5668-9e2c-6e5b9ad4f53f'::uuid, '74f0ea7d-9ca6-5dba-8c1d-be323042c711'::uuid, 'ramsukhdas', 'hindi', '।।9.16 -- 9.18।।  क्रतु मैं हूँ, यज्ञ मैं हूँ, स्वधा मैं हूँ, औषध मैं हूँ, मन्त्र मैं हूँ, घृत मैं हूँ, अग्नि मैं हूँ और हवनरूप क्रिया भी मैं हूँ। जाननेयोग्य पवित्र, ओंकार, ऋग्वेद, सामवेद और यजुर्वेद भी मैं ही हूँ। इस सम्पूर्ण जगत्का पिता, धाता, माता, पितामह, गति, भर्ता, प्रभु, साक्षी, निवास, आश्रय, सुहृद्, उत्पत्ति, प्रलय, स्थान, निधान तथा अविनाशी बीज भी मैं ही हूँ।'),
('9497264a-0058-5d2b-aa2f-3962537736c3'::uuid, '74f0ea7d-9ca6-5dba-8c1d-be323042c711'::uuid, 'tejomayananda', 'hindi', '।।9.18।। गति (लक्ष्य), भरण-पोषण करने वाला, प्रभु (स्वामी), साक्षी, निवास, शरणस्थान तथा मित्र और उत्पत्ति, प्रलयरूप तथा स्थान (आधार), निधान और अव्यय कारण भी मैं हूँ।।
 '),
('45940f33-2656-5e59-9603-9de8a9fcdf60'::uuid, 'e1578302-c768-5fc4-91d1-1ec996faf21e'::uuid, 'ramsukhdas', 'hindi', '।।9.19।। हे अर्जुन ! (संसारके हितके लिये) मैं ही सूर्यरूपसे तपता हूँ, जलको ग्रहण करता हूँ और फिर उस जलको वर्षारूपसे बरसा देता हूँ। (और तो क्या कहूँ) अमृत और मृत्यु तथा सत् और असत् भी मैं ही हूँ।'),
('f9c28ce2-573f-5eaa-8fab-9f083a8b315f'::uuid, 'e1578302-c768-5fc4-91d1-1ec996faf21e'::uuid, 'tejomayananda', 'hindi', '।।9.19।। हे अर्जुन ! मैं ही (सूर्य रूप में) तपता हूँ; मैं वर्षा का निग्रह और उत्सर्जन करता हूँ। मैं ही अमृत और मृत्यु एवं सत् और असत् हूँ।।
 '),
('56eb09ca-e12f-5260-8165-7b2e05402fce'::uuid, '766677ca-b236-58ac-ac79-b5b6b503dafd'::uuid, 'ramsukhdas', 'hindi', '।।9.20।। वेदत्रयीमें कहे हुए सकाम अनुष्ठानको करनेवाले और सोमरसको पीनेवाले जो पापरहित मनुष्य यज्ञोंके द्वारा इन्द्ररूपसे मेरा पूजन करके स्वर्ग-प्राप्तिकी प्रार्थना करते हैं, वे पुण्यके फलस्वरूप इन्द्रलोकको प्राप्त करके वहाँ स्वर्गमें देवताओंके दिव्य भोगोंको भोगते हैं।'),
('a9c9f18f-0d8d-5324-bb66-745cbb9d3c39'::uuid, '766677ca-b236-58ac-ac79-b5b6b503dafd'::uuid, 'tejomayananda', 'hindi', '।।9.20।। तीनों वेदों के ज्ञाता (वेदोक्त सकाम कर्म करने वाले), सोमपान करने वाले एवं पापों से पवित्र हुए पुरुष मुझे यज्ञों के द्वारा पूजकर स्वर्ग प्राप्ति चाहते हैं; वे पुरुष अपने पुण्यों के फलरूप इन्द्रलोक को प्राप्त कर स्वर्ग में दिव्य देवताओं के भोग भोगते हैं।।
 '),
('0fb385b5-67b2-51a3-abdf-3dc96b5096b5'::uuid, '23080adf-dde2-5fb1-acee-43185708e0c7'::uuid, 'ramsukhdas', 'hindi', '।।9.21।। वे उस विशाल स्वर्गलोकके भोगोंको भोगकर पुण्य क्षीण होनेपर मृत्युलोकमें आ जाते हैं। इस प्रकार तीनों वेदोंमें कहे हुए सकाम धर्मका आश्रय लिये हुए भोगोंकी कामना करनेवाले मनुष्य आवागमनको प्राप्त होते हैं।'),
('bae03f96-4ea4-529e-ad61-cf7b9bea11e6'::uuid, '23080adf-dde2-5fb1-acee-43185708e0c7'::uuid, 'tejomayananda', 'hindi', '।।9.21।। वे उस विशाल स्वर्गलोक को भोगकर, पुण्यक्षीण होने पर, मृत्युलोक को प्राप्त होते हैं। इस प्रकार तीनों वेदों में कहे गये कर्म के शरण हुए और भोगों की कामना वाले पुरुष आवागमन (गतागत) को प्राप्त होते हैं।।
 '),
('627c2f11-68af-5b02-9d4c-4ac46a1c4d0b'::uuid, 'b40d8e98-4a3a-542f-8a71-28686d959b51'::uuid, 'ramsukhdas', 'hindi', '।।9.22।। जो अनन्य भक्त मेरा चिन्तन करते हुए मेरी उपासना करते हैं, मेरेमें निरन्तर लगे हुए उन भक्तोंका योगक्षेम (अप्राप्तकी प्राप्ति और प्राप्तकी रक्षा) मैं वहन करता हूँ।'),
('431580ac-00b3-5da8-9497-7b3d06771c8e'::uuid, 'b40d8e98-4a3a-542f-8a71-28686d959b51'::uuid, 'tejomayananda', 'hindi', '।।9.22।। अनन्य भाव से मेरा चिन्तन करते हुए जो भक्तजन मेरी ही उपासना करते हैं, उन नित्ययुक्त पुरुषों का योगक्षेम मैं वहन करता हूँ।।
 '),
('033e703b-62c9-59c3-90a8-3000ec12d0f4'::uuid, '5f5fc0f4-0c6e-53af-8067-1f7f7f4efb04'::uuid, 'ramsukhdas', 'hindi', '।।9.23।। हे कुन्तीनन्दन! जो भी भक्त (मनुष्य) श्रद्धापूर्वक अन्य देवताओंका पूजन करते हैं, वे भी करते हैं मेरा ही पूजन, पर करते है अविधिपूर्वक'),
('bba5194c-e385-52b4-9e3e-098fb9131504'::uuid, '5f5fc0f4-0c6e-53af-8067-1f7f7f4efb04'::uuid, 'tejomayananda', 'hindi', '।।9.23।। हे कौन्तेय ! श्रद्धा से युक्त जो भक्त अन्य देवताओं को पूजते हैं, वे भी मुझे ही अविधिपूर्वक पूजते हैं।।
 '),
('4796be59-a57c-5f38-9469-d069c89abf62'::uuid, '885a493f-d466-549b-9d95-13be09dc8f6a'::uuid, 'ramsukhdas', 'hindi', '।।9.24।। क्योंकि मैं ही सम्पूर्ण यज्ञोंका भोक्ता और स्वामी भी हूँ;  परन्तु वे मेरेको तत्त्वसे नहीं जानते, इसीसे उनका पतन होता है।'),
('cf9da246-8b28-5dd3-9dae-ee6a25c4f195'::uuid, '885a493f-d466-549b-9d95-13be09dc8f6a'::uuid, 'tejomayananda', 'hindi', '।।9.24।। क्योंकि सब यज्ञों का भोक्ता और स्वामी मैं ही हूँ, परन्तु वे मुझे तत्त्वत: नहीं जानते हैं, इसलिए वे गिरते हैं, अर्थात् संसार को प्राप्त होते हैं।।
 '),
('3e1213f5-44fa-514f-88de-b7ae809b60cf'::uuid, '6c482ef0-2212-57e6-a15c-73d2e50b963b'::uuid, 'ramsukhdas', 'hindi', '।।9.25।। (सकामभावसे) देवताओंका पूजन करनेवाले (शरीर छोड़नेपर) देवताओंको प्राप्त होते हैं। पितरोंका पूजन करनेवाले पितरोंको प्राप्त होते हैं। भूत-प्रेतोंका पूजन करनेवाले भूत-प्रेतोंको प्राप्त होते हैं। परन्तु मेरा पूजन करनेवाले मुझे ही प्राप्त होते हैं।'),
('71c10fbe-1a53-5820-8194-c32f470102c5'::uuid, '6c482ef0-2212-57e6-a15c-73d2e50b963b'::uuid, 'tejomayananda', 'hindi', '।।9.25।। देवताओं के पूजक देवताओं को प्राप्त होते हैं, पितरपूजक पितरों को जाते हैं, भूतों का यजन करने वाले भूतों को प्राप्त होते हैं और मुझे पूजने वाले भक्त मुझे ही प्राप्त होते हैं।।
 '),
('9089d4d1-2d02-5930-8816-1cc60b2d81b3'::uuid, '98246330-d83a-5901-85db-65a623a260f0'::uuid, 'ramsukhdas', 'hindi', '।।9.26।।जो भक्त पत्र, पुष्प, फल, जल आदि (यथासाध्य प्राप्त वस्तु) को भक्तिपूर्वक मेरे अर्पण करता है, उस मेरेमें तल्लीन हुए अन्तःकरणवाले भक्तके द्वारा भक्तिपूर्वक दिये हुए उपहार-(भेंट-) को मैं खा लेता हूँ।'),
('2ab0c7fd-6f4e-5c5b-89b8-5c7fa9f9c4a0'::uuid, '98246330-d83a-5901-85db-65a623a260f0'::uuid, 'tejomayananda', 'hindi', '।।9.26।। जो कोई भी भक्त मेरे लिए पत्र, पुष्प, फल, जल आदि भक्ति से अर्पण करता है, उस शुद्ध मन के भक्त का वह भक्तिपूर्वक अर्पण किया हुआ (पत्र पुष्पादि) मैं भोगता हूँ अर्थात् स्वीकार करता हूँ।।
 '),
('14bfdbec-f4c7-5bff-8a7b-317e52335d79'::uuid, '2c8bb0fc-cc1c-58b0-b2c9-13d158b269d5'::uuid, 'ramsukhdas', 'hindi', '।।9.27।। हे कुन्तीपुत्र ! तू जो कुछ करता है, जो कुछ खाता है, जो कुछ यज्ञ करता है, जो कुछ दान देता है और जो कुछ तप करता है, वह सब मेरे अर्पण कर दे।'),
('c43e0b29-9997-5c19-afbb-fe31505bd7ea'::uuid, '2c8bb0fc-cc1c-58b0-b2c9-13d158b269d5'::uuid, 'tejomayananda', 'hindi', '।।9.27।। हे कौन्तेय ! तुम जो कुछ कर्म करते हो, जो कुछ खाते हो, जो कुछ हवन करते हो, जो कुछ दान देते हो और जो कुछ तप करते हो, वह सब तुम मुझे अर्पण करो।।
 '),
('fe9f2cf5-9465-563b-9fa8-eec1a6894483'::uuid, '425c0695-0058-54d2-b717-00f501597a7c'::uuid, 'ramsukhdas', 'hindi', '।।9.28।। इस प्रकार मेरे अर्पण करनेसे जिनसे कर्मबन्धन होता है, ऐसे शुभ (विहित) और अशुभ (निषिद्ध) सम्पूर्ण कर्मोंके फलोंसे तू मुक्त हो जायगा। ऐसे अपनेसहित सब कुछ मेरे अर्पण करनेवाला और सबसे मुक्त हुआ तू मेरेको प्राप्त हो जायगा।'),
('9ec4e9e4-18bb-5e9b-a86f-3369821ba556'::uuid, '425c0695-0058-54d2-b717-00f501597a7c'::uuid, 'tejomayananda', 'hindi', '।।9.28।। इस प्रकार तुम शुभाशुभ फलस्वरूप कर्मबन्धनों से मुक्त हो जाओगे; और संन्यासयोग से युक्तचित्त हुए तुम विमुक्त होकर मुझे ही प्राप्त हो जाओगे।।
 '),
('3f9b1493-9271-511a-9776-b8c3970acfd3'::uuid, 'ebddad50-4e48-5c8b-94f7-5680a8fe296a'::uuid, 'ramsukhdas', 'hindi', '।।9.29।। मैं सम्पूर्ण प्राणियोंमें समान हूँ। उन प्राणियोंमें न तो कोई मेरा द्वेषी है और न कोई प्रिय है। परन्तु जो भक्तिपूर्वक मेरा भजन करते हैं, वे मेरेमें हैं और मैं  उनमें हूँ।'),
('d9d122c1-d43a-556d-8940-7d50d0444b56'::uuid, 'ebddad50-4e48-5c8b-94f7-5680a8fe296a'::uuid, 'tejomayananda', 'hindi', '।।9.29।। मैं समस्त भूतों में सम हूँ; न कोई मुझे अप्रिय है और न प्रिय; परन्तु जो मुझे भक्तिपूर्वक भजते हैं, वे मुझमें और मैं भी उनमें हूँ।।
 '),
('cd64b4eb-f1f4-54c6-8a54-181b506dd9be'::uuid, '1bc6778c-5496-57e7-ad98-579f9a69de9f'::uuid, 'ramsukhdas', 'hindi', '।।9.30।। अगर कोई दुराचारी-से-दुराचारी भी अनन्यभावसे मेरा भजन करता है, तो उसको साधु ही मानना चाहिये। कारण कि उसने निश्चय बहुत अच्छी तरह कर लिया है।'),
('cec37efa-da8c-5a48-a296-14dca94cb3cc'::uuid, '1bc6778c-5496-57e7-ad98-579f9a69de9f'::uuid, 'tejomayananda', 'hindi', '।।9.30।। यदि कोई अतिशय दुराचारी भी अनन्यभाव से मेरा भक्त होकर मुझे भजता है, वह साधु ही मानने योग्य है, क्योंकि वह यथार्थ निश्चय वाला है।।
 '),
('97473385-361b-5e2c-846e-e943196b76d9'::uuid, '3cd49e7d-5d58-512f-a200-84057d3a356e'::uuid, 'ramsukhdas', 'hindi', '।।9.31।। वह तत्काल (उसी क्षण) धर्मात्मा हो जाता है और निरन्तर रहनेवाली शान्तिको प्राप्त हो जाता है। हे कुन्तीनन्दन ! तुम प्रतिज्ञा करो कि मेरे भक्तका विनाश (पतन) नहीं होता।'),
('2b2c89e2-1de1-507d-96d7-b7091a389964'::uuid, '3cd49e7d-5d58-512f-a200-84057d3a356e'::uuid, 'tejomayananda', 'hindi', '।।9.31।। हे कौन्तेय, वह शीघ्र ही धर्मात्मा बन जाता है और शाश्वत शान्ति को प्राप्त होता है। तुम निश्चयपूर्वक सत्य जानो कि मेरा भक्त कभी नष्ट नहीं होता।।
 '),
('1fcbff4a-8d8e-5b8c-ab07-470a82d4084e'::uuid, '740bbc20-32f0-5666-a7f3-d3f03d5d9bde'::uuid, 'ramsukhdas', 'hindi', '।।9.32।। हे पृथानन्दन ! जो भी पापयोनिवाले हों तथा जो भी स्त्रियाँ, वैश्य और शूद्र हों, वे भी सर्वथा मेरे शरण होकर निःसन्देह परमगतिको प्राप्त हो जाते हैं।'),
('13beaeea-183d-52cf-9f80-c27b09787343'::uuid, '740bbc20-32f0-5666-a7f3-d3f03d5d9bde'::uuid, 'tejomayananda', 'hindi', '।।9.32।। हे पार्थ ! स्त्री, वैश्य और शूद्र ये जो कोई पापयोनि वाले हों, वे भी मुझ पर आश्रित (मेरे शरण) होकर परम गति को प्राप्त होते हैं।।
 '),
('c48935e1-321a-54be-8edd-d43085f7c030'::uuid, 'ee1f230f-d590-5c9a-b999-43eeb29b9230'::uuid, 'ramsukhdas', 'hindi', '।।9.33।। जो पवित्र आचरणवाले ब्राह्मण और ऋषिस्वरूप क्षत्रिय भगवान्  के भक्त हों, वे परमगतिको प्राप्त हो जायँ, इसमें तो कहना ही क्या है। इसलिये इस अनित्य और सुखरहित शरीरको प्राप्त करके तू मेरा भजन कर।'),
('69140008-3e08-5214-b499-f8563ae15d7d'::uuid, 'ee1f230f-d590-5c9a-b999-43eeb29b9230'::uuid, 'tejomayananda', 'hindi', '।।9.33।। फिर क्या कहना है कि पुण्यशील ब्राह्मण और राजर्षि भक्तजन (परम गति को प्राप्त होते हैं); (इसलिए) इस अनित्य और सुखरहित लोक को प्राप्त होकर (अब) तुम भक्तिपूर्वक मेरी ही पूजा करो।।
 '),
('1cd24f92-7135-5254-be98-974cc8f7c7e9'::uuid, 'ed0a1204-c94b-5828-800a-7abfd1772b21'::uuid, 'ramsukhdas', 'hindi', '।।9.34।। तू मेरा भक्त हो जा, मेरेमें मनवाला हो जा, मेरा पूजन करनेवाला हो जा और मेरेको नमस्कार कर। इस प्रकार मेरे साथ अपने-आपको लगाकर, मेरे परायण हुआ तू मेरेको ही प्राप्त होगा।

,'),
('c238930c-1d26-5936-b8de-2bd0cdd07c38'::uuid, 'ed0a1204-c94b-5828-800a-7abfd1772b21'::uuid, 'tejomayananda', 'hindi', '।।9.34।। (तुम) मुझमें स्थिर मन वाले बनो; मेरे भक्त और मेरे पूजन करने वाले बनो; मुझे नमस्कार करो; इस प्रकार मत्परायण (अर्थात् मैं ही जिसका परम लक्ष्य हूँ ऐसे) होकर आत्मा को मुझसे युक्त करके तुम मुझे ही प्राप्त होओगे।।'),
('1c3c0d81-5fc3-58a9-875f-a82093393758'::uuid, '10f6398d-c4dc-5da9-b592-8ba3dca1afdf'::uuid, 'ramsukhdas', 'hindi', '।।10.1।। श्रीभगवान् बोले -- हे महाबाहो अर्जुन ! मेरे परम वचनको तुम फिर भी सुनो, जिसे मैं तुम्हारे हितकी कामनासे कहूँगा; क्योंकि तुम मेरेमें अत्यन्त प्रेम रखते हो।'),
('50bc9b46-03a6-5e5f-9439-487c8432dbce'::uuid, '10f6398d-c4dc-5da9-b592-8ba3dca1afdf'::uuid, 'tejomayananda', 'hindi', '।।10.1।। श्रीभगवान् ने कहा -- हे महाबाहो ! पुन: तुम मेरे परम वचनों का श्रवण करो, जो मैं तुझ अतिशय प्रेम रखने वाले के लिये हित की इच्छा से कहूँगा।।
 '),
('23a4e8c1-dd65-5ecc-86c9-e601bd055974'::uuid, '034c4f59-c649-5d7a-bfc6-0c5e6523576e'::uuid, 'ramsukhdas', 'hindi', '।।10.2।। मेरे प्रकट होनेको न देवता जानते हैं और न महर्षि; क्योंकि मैं सब प्रकारसे देवताओं और महर्षियोंका आदि हूँ।'),
('97a85c02-66c3-51a1-b076-fd140990a6b3'::uuid, '034c4f59-c649-5d7a-bfc6-0c5e6523576e'::uuid, 'tejomayananda', 'hindi', '।।10.2।। मेरी उत्पत्ति (प्रभव) को न देवतागण जानते हैं और न महर्षिजन; क्योंकि मैं सब प्रकार से देवताओं और महर्षियों का भी आदिकारण हूँ।।
 '),
('36e92938-7dd8-5721-a7ef-11219d34e79d'::uuid, 'ad968164-2c65-5857-a67a-532cc4fa231c'::uuid, 'ramsukhdas', 'hindi', '।।10.3।। जो मनुष्य मुझे अजन्मा, अनादि और सम्पूर्ण लोकोंका महान् ईश्वर जानता है अर्थात् दृढ़तासे मानता है, वह मनुष्योंमें असम्मूढ़ (जानकार) है और वह सम्पूर्ण पापोंसे मुक्त हो जाता है।'),
('0c22bef1-8a7e-5c24-b355-4a79708d87fc'::uuid, 'ad968164-2c65-5857-a67a-532cc4fa231c'::uuid, 'tejomayananda', 'hindi', '।।10.3।। जो मुझे अजन्मा, अनादि और लोकों के महान् ईश्वर के रूप में जानता है, र्मत्य मनुष्यों में ऐसा संमोहरहित (ज्ञानी) पुरुष सब पापों से मुक्त हो जाता है।।
 '),
('7eabc282-d18f-578e-8e56-40bc048b57a3'::uuid, '5ed9ce8d-5da8-5a65-b6e1-5ae4baaa07ca'::uuid, 'ramsukhdas', 'hindi', '।।10.4 -- 10.5।। बुद्धि, ज्ञान, असम्मोह, क्षमा, सत्य, दम, शम, सुख, दुःख, भव, अभाव, भय, अभय, अहिंसा, समता, तुष्टि, तप, दान, यश और अपयश -- प्राणियोंके ये अनेक प्रकारके और अलग-अलग (बीस) भाव मेरेसे ही होते हैं।'),
('1045cfc9-6dfa-52ab-a8a5-715f65b390aa'::uuid, '5ed9ce8d-5da8-5a65-b6e1-5ae4baaa07ca'::uuid, 'tejomayananda', 'hindi', '।।10.4।। बुद्धि, ज्ञान, मोह का अभाव, क्षमा, सत्य, दम (इन्द्रिय संयम), शम (मन: संयम), सुख, दु:ख, जन्म और मृत्यु, भय और अभय।।
 '),
('058cc794-35af-5999-8a81-e2ab4cdb02ac'::uuid, '13ca1067-53c0-578b-a7fd-8c8d1eab20aa'::uuid, 'ramsukhdas', 'hindi', '।।10.4 -- 10.5।। बुद्धि, ज्ञान, असम्मोह, क्षमा, सत्य, दम, शम, सुख, दुःख, भव, अभाव, भय, अभय, अहिंसा, समता, तुष्टि, तप, दान, यश और अपयश -- प्राणियोंके ये अनेक प्रकारके और अलग-अलग (बीस) भाव मेरेसे ही होते हैं।'),
('9e4cdd9f-1ea4-5381-a0c6-89bb2e5ad76e'::uuid, '13ca1067-53c0-578b-a7fd-8c8d1eab20aa'::uuid, 'tejomayananda', 'hindi', '।।10.5।। अहिंसा, समता, सन्तोष, तप, दान. यश और अपयश ऐसे ये प्राणियों के नानाविध भाव मुझ से ही प्रकट होते हैं।।
 '),
('c6c5d5af-43b0-5ac6-b99c-3c3d6aaf29ce'::uuid, '08e901be-ad05-5cad-a38f-b24dd44d7d25'::uuid, 'ramsukhdas', 'hindi', '।।10.6।। सात महर्षि और उनसे भी पूर्वमें होनेवाले चार सनकादि तथा चौदह मनु -- ये सब-के-सब मेरे मनसे पैदा हुए हैं और मेरेमें भाव (श्रद्धाभक्ति) रखनेवाले हैं, जिनकी संसारमें यह सम्पूर्ण प्रजा है।'),
('c3b35a74-30d4-5b25-ab7b-da7382d13e4d'::uuid, '08e901be-ad05-5cad-a38f-b24dd44d7d25'::uuid, 'tejomayananda', 'hindi', '।।10.6।। सात महर्षिजन, पूर्वकाल के चार (सनकादि) तथा (चौदह) मनु ये मेरे प्रभाव वाले मेरे संकल्प से उत्पन्न हुए हैं, जिनकी संसार (लोक) में यह प्रजा है।।
 '),
('dfa95027-ec1b-55d3-8b45-2499d5da8122'::uuid, '64279be0-d27f-5ad6-9319-246653e6c66d'::uuid, 'ramsukhdas', 'hindi', '।।10.7।। जो मनुष्य मेरी इस विभूतिको और योगको तत्त्वसे जानता है अर्थात् दृढ़तापूर्वक मानता है, वह अविचल भक्तियोगसे युक्त हो जाता है; इसमें कुछ भी संशय नहीं है।'),
('0037974b-f525-5473-bb45-616e3710517e'::uuid, '64279be0-d27f-5ad6-9319-246653e6c66d'::uuid, 'tejomayananda', 'hindi', '।।10.7।। जो पुरुष इस मेरी विभूति और योग को तत्त्व से जानता है, वह पुरुष अविकम्प योग (अर्थात् निश्चल ध्यान योग) से युक्त हो जाता है, इसमें कुछ भी संशय नहीं है।।
 '),
('f0b1f58a-4ae5-5849-9759-0be795e9b31c'::uuid, '4869a956-b4ea-5734-bcf8-62320e674dc6'::uuid, 'ramsukhdas', 'hindi', '।।10.8।। मैं संसारमात्रका प्रभव (मूलकारण) हूँ, और मुझसे ही सारा संसार प्रवृत्त हो रहा है अर्थात् चेष्टा कर रहा है -- ऐसा मेरेको मानकर मेरेमें ही श्रद्धा-प्रेम रखते हुए बुद्धिमान् भक्त मेरा ही भजन करते हैं -- सब प्रकारसे मेरे ही शरण होते हैं।'),
('946e060d-cde4-50e2-a583-7f774e411d9f'::uuid, '4869a956-b4ea-5734-bcf8-62320e674dc6'::uuid, 'tejomayananda', 'hindi', '।।10.8।। मैं ही सबका प्रभव स्थान हूँ; मुझसे ही सब (जगत्) विकास को प्राप्त होता है, इस प्रकार जानकर बुधजन भक्ति भाव से युक्त होकर मुझे ही भजते हैं।।
 '),
('477192f8-1a4d-5fb5-81c9-45f52d92951e'::uuid, '0f2ba58c-f684-5bd5-9040-87d1f64c85b7'::uuid, 'ramsukhdas', 'hindi', '।।10.9।।। मेरेमें चित्तवाले, मेरेमें प्राणोंको अर्पण करनेवाले भक्तजन आपसमें मेरे गुण, प्रभाव आदिको जानते हुए और उनका कथन करते हुए ही नित्य-निरन्तर सन्तुष्ट रहते हैं और मेरेमें प्रेम करते हैं।'),
('1b4b57ec-8b9c-5797-ab39-ab52bcdd9c4e'::uuid, '0f2ba58c-f684-5bd5-9040-87d1f64c85b7'::uuid, 'tejomayananda', 'hindi', '।।10.9।। मुझमें ही चित्त को स्थिर करने वाले और मुझमें ही प्राणों (इन्द्रियों) को अर्पित करने वाले भक्तजन, सदैव परस्पर मेरा बोध कराते हुए, मेरे ही विषय में कथन करते हुए सन्तुष्ट होते हैं और रमते हैं।।
 '),
('96e11001-6e7a-5d14-9c7b-e004c3aa262a'::uuid, '7f6ea195-976c-5024-a29c-6245f8dba5fd'::uuid, 'ramsukhdas', 'hindi', '।।10.10।। उन नित्य-निरन्तर मेरेमें लगे हुए और प्रेमपूर्वक मेरा भजन करनेवाले भक्तोंको मैं वह बुद्धियोग देता हूँ, जिससे उनको मेरी प्राप्ति हो जाती है।'),
('5bc1b4a8-7e31-582f-9e18-4656d4370c1b'::uuid, '7f6ea195-976c-5024-a29c-6245f8dba5fd'::uuid, 'tejomayananda', 'hindi', '।।10.10।। उन (मुझ से) नित्य युक्त हुए और प्रेमपूर्वक मेरा भजन करने वाले भक्तों को, मैं वह ''बुद्धियोग'' देता हूँ जिससे वे मुझे प्राप्त होते हैं।।
 '),
('6b553d05-35b5-5f0d-9537-565288453d5d'::uuid, '0bec73d2-b93d-5aff-a187-b5bd459758ad'::uuid, 'ramsukhdas', 'hindi', '।।10.11।। उन भक्तोंपर कृपा करनेके लिये ही उनके स्वरूप (होनेपन) में रहनेवाला मैं उनके अज्ञानजन्य अन्धकारको देदीप्यमान ज्ञानरूप दीपकके द्वारा सर्वथा नष्ट कर देता हूँ।'),
('e88168d5-f65c-57b4-abab-5274a4bb9f18'::uuid, '0bec73d2-b93d-5aff-a187-b5bd459758ad'::uuid, 'tejomayananda', 'hindi', '।।10.11।। उनके ऊपर अनुग्रह करने के लिए मैं उनके अन्त:करण में स्थित होकर, अज्ञानजनित अन्धकार को प्रकाशमय ज्ञान के दीपक द्वारा नष्ट करता हूँ।।
 '),
('33a79d8b-99fb-54ed-a74d-aa463d098267'::uuid, '5cb8a5d5-415c-535a-b218-ff85e7ac02e1'::uuid, 'ramsukhdas', 'hindi', '।।10.12 -- 10.12।। अर्जुन बोले -- परम ब्रह्म, परम धाम और महान् पवित्र आप ही हैं। आप शाश्वत, दिव्य पुरुष, आदिदेव, अजन्मा और विभु (व्यापक) हैं -- ऐसा सब-के-सब ऋषि, देवर्षि नारद, असित, देवल तथा व्यास कहते हैं और स्वयं आप भी मेरे प्रति कहते हैं।'),
('e985af1d-84d6-55ef-9141-3808c8d7d9b8'::uuid, '5cb8a5d5-415c-535a-b218-ff85e7ac02e1'::uuid, 'tejomayananda', 'hindi', '।।10.12।। अर्जुन ने कहा आप -परम ब्रह्म, परम धाम और परम पवित्र हंै; सनातन दिव्य पुरुष, देवों के भी आदि देव, जन्म रहित और सर्वव्यापी हैं।।
 '),
('e436deb6-735f-5b17-b91b-9243b0d3e7ab'::uuid, '7d5e5da9-7ea0-5746-a68e-0b9b66127198'::uuid, 'ramsukhdas', 'hindi', '।।10.12 -- 10.13।। अर्जुन बोले -- परम ब्रह्म, परम धाम और महान् पवित्र आप ही हैं। आप शाश्वत, दिव्य पुरुष, आदिदेव, अजन्मा और विभु (व्यापक) हैं -- ऐसा सब-के-सब ऋषि, देवर्षि नारद, असित, देवल तथा व्यास कहते हैं और स्वयं आप भी मेरे प्रति कहते हैं।'),
('aef413ac-fb88-5381-8b7f-06c3ade9bca3'::uuid, '7d5e5da9-7ea0-5746-a68e-0b9b66127198'::uuid, 'tejomayananda', 'hindi', '।।10.13।। ऐसा आपको समस्त ऋषिजन कहते हैं;  वैसे ही देवर्षि नारद, असित, देवल ऋषि तथा व्यास और स्वयं आप भी मेरे प्रति कहते हैं।।
 '),
('1d5eff6a-88cd-5540-893d-63c0b4c09d0e'::uuid, 'fe918ed7-1928-5440-989d-d37ff9a912e4'::uuid, 'ramsukhdas', 'hindi', '।।10.14।। हे केशव ! मेरेसे आप जो कुछ कह रहे हैं, यह सब मैं सत्य मानता हूँ। हे भगवन् ! आपके प्रकट होनेको न तो देवता जानते हैं और न दानव ही जानते हैं।'),
('0f6a211c-6595-52c6-8da2-c91015c18ec3'::uuid, 'fe918ed7-1928-5440-989d-d37ff9a912e4'::uuid, 'tejomayananda', 'hindi', '।।10.14।। हे केशव ! जो कुछ भी आप मेरे प्रति कहते हैं, इस सबको मैं सत्य मानता हूँ। हे भगवन्, आपके (वास्तविक) स्वरूप को न देवता जानते हैं और न दानव।।
 '),
('331d6590-2720-553e-9456-d20992644ef1'::uuid, '94df8fad-9c4a-5eb1-a40a-0314766bdfa4'::uuid, 'ramsukhdas', 'hindi', '।।10.15।। हे भूतभावन ! हे भूतेश ! हे देवदेव ! हे जगत्पते ! हे पुरुषोत्तम ! आप स्वयं ही अपने-आपसे अपने-आपको जानते हैं।'),
('a1d69124-3b1f-50dc-a1fa-879a89bc5c8f'::uuid, '94df8fad-9c4a-5eb1-a40a-0314766bdfa4'::uuid, 'tejomayananda', 'hindi', '।।10.15।। हे पुरुषोत्तम ! हे भूतभावन ! हे भूतेश ! हे देवों के देव ! हे जगत् के स्वामी ! आप स्वयं ही अपने आप को जानते हैं।।
 '),
('8b151d5b-8bfa-50c1-841c-f957c0f9e407'::uuid, '3eff04d5-6ded-56cc-86bb-7627961bbb80'::uuid, 'ramsukhdas', 'hindi', '।।10.16।।  जिन विभूतियोंसे आप इन सम्पूर्ण लोकोंको व्याप्त करके स्थित हैं, उन सभी अपनी दिव्य विभूतियोंका सम्पूर्णतासे वर्णन करनेमें आप ही समर्थ हैं।'),
('03851a1e-9682-5c22-ad66-93b53592ba27'::uuid, '3eff04d5-6ded-56cc-86bb-7627961bbb80'::uuid, 'tejomayananda', 'hindi', '।।10.16।। आप ही उन अपनी दिव्य विभूतियों को अशेषत: कहने के लिए योग्य हैं, जिन विभूतियों के द्वारा इन समस्त लोकों को आप व्याप्त करके स्थित हैं।।
 '),
('2216c631-1dd1-5d5a-921c-cfc339d2ddfa'::uuid, 'd99a8d0d-9ee8-550d-905b-0c430d76d324'::uuid, 'ramsukhdas', 'hindi', '।।10.17।। हे योगिन् ! हरदम साङ्गोपाङ्ग चिन्तन करता हुआ मैं आपको कैसे जानूँ ? और हे भगवन् ! किन-किन भावोंमें आप मेरे द्वारा चिन्तन किये जा सकते हैं अर्थात् किन-किन भावोंमें मैं आपका चिन्तन करूँ ?'),
('410834af-1974-5861-86a7-7fb4e982f52e'::uuid, 'd99a8d0d-9ee8-550d-905b-0c430d76d324'::uuid, 'tejomayananda', 'hindi', '।।10.17।। हे योगेश्वर ! मैं किस प्रकार निरन्तर चिन्तन करता हुआ आपको जानूँ, और हे भगवन् ! आप किनकिन भावों में मेरे द्वारा चिन्तन करने योग्य हैं।।
 '),
('d066270e-b9bb-5df1-80b9-513aa52f2673'::uuid, 'c0e24b69-4f43-5b6b-97a8-f1958b29ff77'::uuid, 'ramsukhdas', 'hindi', '।।10.18।। हे जनार्दन ! आप अपने योग (सामर्थ्य) को और विभूतियोंको विस्तारसे फिर कहिये; क्योंकि आपके अमृतमय वचन सुनते-सुनते मेरी तृप्ति नहीं हो रही है।'),
('4ff25258-9e29-5f20-9242-d7937e1e7e18'::uuid, 'c0e24b69-4f43-5b6b-97a8-f1958b29ff77'::uuid, 'tejomayananda', 'hindi', '।।10.18।। हे जनार्दन ! अपनी योग शक्ति और विभूति को पुन: विस्तारपूर्वक कहिए, क्योंकि आपके अमृतमय वचनों को सुनते हुए मुझे तृप्ति नहीं होती।।
 '),
('a165d94e-17e3-56c5-a3ce-c24738ebe585'::uuid, 'ac86f39a-d934-52a4-9a78-01584eb356de'::uuid, 'ramsukhdas', 'hindi', '।।10.19।। श्रीभगवान् बोले -- हाँ, ठीक है। मैं अपनी दिव्य विभूतियोंको तेरे लिये प्रधानतासे (संक्षेपसे) कहूँगा; क्योंकि हे कुरुश्रेष्ठ ! मेरी विभूतियोंके विस्तारका अन्त नहीं है।'),
('c233d267-6039-5818-9b50-82f59681efda'::uuid, 'ac86f39a-d934-52a4-9a78-01584eb356de'::uuid, 'tejomayananda', 'hindi', '।।10.19।। श्रीभगवान् ने कहा -हन्त अब मैं तुम्हें अपनी दिव्य विभूतियों को प्रधानता से कहूँगा। हे कुरुश्रेष्ठ मेरे विस्तार का अन्त नहीं है।।
 '),
('69517ae1-602a-505b-8ae9-11272e2dbb69'::uuid, 'd48b04da-0136-5391-9f61-f1b7e57c64ad'::uuid, 'ramsukhdas', 'hindi', '।।10.20।। हे नींदको जीतनेवाले अर्जुन ! सम्पूर्ण प्राणियोंके आदि, मध्य तथा अन्तमें भी मैं ही हूँ और प्राणियोंके अन्तःकरणमें आत्मरूपसे भी मैं ही स्थित हूँ।'),
('74a17762-ff3e-549e-a8d7-184584fa3871'::uuid, 'd48b04da-0136-5391-9f61-f1b7e57c64ad'::uuid, 'tejomayananda', 'hindi', '।।10.20।। हे गुडाकेश (निद्राजित्) ! मैं समस्त भूतों के हृदय में स्थित सबकी आत्मा हूँ तथा सम्पूर्ण भूतों का आदि, मध्य और अन्त भी मैं ही हूँ।।
 '),
('61b738f3-feb8-5434-990f-bf9025bcc8d3'::uuid, 'c94ff7b3-0d58-5f35-b461-1ddf45ab658d'::uuid, 'ramsukhdas', 'hindi', '।।10.21।।  मैं अदितिके पुत्रोंमें विष्णु (वामन) और प्रकाशमान वस्तुओंमें किरणोंवाला सूर्य हूँ। मैं मरुतोंका तेज और नक्षत्रोंका अधिपति चन्द्रमा हूँ।'),
('9b43a6ba-40b6-5b68-a5be-8ac837d636c5'::uuid, 'c94ff7b3-0d58-5f35-b461-1ddf45ab658d'::uuid, 'tejomayananda', 'hindi', '।।10.21।। मैं (बारह) आदित्यों में विष्णु और ज्योतियों में अंशुमान् सूर्य हूँ; मैं (उनचास) मरुतों (वायु देवताओं) में मरीचि हूँ और नक्षत्रों में शशी (चन्द्रमा) हूँ।।
 '),
('0edb749c-baf9-5aa1-be5c-57043a213f84'::uuid, 'fd590e67-76bc-5168-8839-6e1cb6827149'::uuid, 'ramsukhdas', 'hindi', '।।10.22।। मैं वेदोंमें सामवेद हूँ, देवताओंमें इन्द्र हूँ, इन्द्रियोंमें मन हूँ और प्राणियोंकी चेतना हूँ।'),
('9e316b05-f6b7-592b-acf2-6bd2ad3fe1ab'::uuid, 'fd590e67-76bc-5168-8839-6e1cb6827149'::uuid, 'tejomayananda', 'hindi', '।।10.22।। मैं वेदों में सामवेद हूँ, देवों में वासव (इन्द्र) हूँ; मैं इन्द्रियों में मन और भूतप्राणियों में चेतना (ज्ञानशक्ति) हूँ।।
 '),
('66661fa1-0bc5-5811-8ac0-906d96e6e11b'::uuid, 'be2f4a9b-7770-5dcd-b3e7-a1bc3ea9a177'::uuid, 'ramsukhdas', 'hindi', '।।10.23।। रुद्रोंमें शंकर और यक्ष-राक्षसोंमें कुबेर मैं हूँ।वसुओंमें पावक (अग्नि) और शिखरवाले पर्वतोंमें सुमेरु मैं हूँ।'),
('f7abb3d1-b37a-59a3-a74e-7712198ac14c'::uuid, 'be2f4a9b-7770-5dcd-b3e7-a1bc3ea9a177'::uuid, 'tejomayananda', 'hindi', '।।10.23।। मैं (ग्यारह) रुद्रों में शंकर हूँ और यक्ष तथा राक्षसों में धनपति कुबेर (वित्तेश) हूँ; (आठ) वसुओं में अग्नि हूँ तथा शिखर वाले पर्वतों में मेरु हूँ।।
 '),
('6568f13a-574e-5a08-9537-75e55eb3eb73'::uuid, '4de15e78-5046-5443-be56-c9e3410befa9'::uuid, 'ramsukhdas', 'hindi', '।।10.24।। हे पार्थ ! पुरोहितोंमें मुख्य बृहस्पतिको मेरा स्वरूप समझो। सेनापतियोंमें स्कन्द और जलाशयोंमें समुद्र मैं हूँ।'),
('6f8cd3f9-4815-5ad8-a171-d68a5199a899'::uuid, '4de15e78-5046-5443-be56-c9e3410befa9'::uuid, 'tejomayananda', 'hindi', '।।10.24।। हे पार्थ ! पुरोहितों में मुझे बृहस्पति जानो; मैं सेनापतियों में स्कन्द और जलाशयों में समुद्र हूँ।।
 '),
('43794acf-4189-5784-a524-e36875201cf5'::uuid, 'ae14ee0d-3b7d-5baa-86f3-a27f464ddaa0'::uuid, 'ramsukhdas', 'hindi', '।।10.25।। महर्षियोंमें भृगु और वाणियों-(शब्दों-) में एक अक्षर अर्थात् प्रणव मैं हूँ। सम्पूर्ण यज्ञोंमें जपयज्ञ और स्थिर रहनेवालोंमें हिमालय मैं हूँ।'),
('2d27c51b-3b13-5b96-b743-e7517c849d90'::uuid, 'ae14ee0d-3b7d-5baa-86f3-a27f464ddaa0'::uuid, 'tejomayananda', 'hindi', '।।10.25।। मैं महर्षियों में भृगु और वाणी (शब्दों) में एकाक्षर ओंकार हूँ। मैं यज्ञों में जपयज्ञ और स्थावरों (अचलों) में हिमालय हूँ।।'),
('515af38c-a379-5b86-aefd-9d9c23a5616c'::uuid, 'df67bdd9-00b7-5846-b2f0-3f1ad923d4b8'::uuid, 'ramsukhdas', 'hindi', '।।10.26।। सम्पूर्ण वृक्षोंमें पीपल, देवर्षियोंमें नारद, गन्धर्वोंमें चित्ररथ और सिद्धोंमें कपिल मुनि मैं हूँ।'),
('2fe9ed4b-961c-5dc5-8b0c-959674a2271b'::uuid, 'df67bdd9-00b7-5846-b2f0-3f1ad923d4b8'::uuid, 'tejomayananda', 'hindi', '।।10.26।। मैं समस्त वृक्षों में अश्वत्थ (पीपल) हूँ और देवर्षियों में नारद हूँ; मैं गन्धर्वों में चित्ररथ और सिद्ध पुरुषों में कपिल मुनि हूँ।।
 '),
('e2aeaeae-89fe-5449-880f-be5b7d939133'::uuid, '58c335af-6a9f-52bb-8a45-2ac5c1f1635a'::uuid, 'ramsukhdas', 'hindi', '।।10.27।। घोड़ोंमें अमृतके साथ समुद्रसे प्रकट होनेवाले उच्चैःश्रवा नामक घोड़ेको, श्रेष्ठ हाथियोंमें ऐरावत नामक हाथीको और मनुष्योंमें राजाको मेरी विभूति मानो।'),
('f212bcce-3b87-541b-921d-23856583451d'::uuid, '58c335af-6a9f-52bb-8a45-2ac5c1f1635a'::uuid, 'tejomayananda', 'hindi', '।।10.27।। अश्वों में अमृत से उत्पन्न हुए उच्चैश्रवा नामक अश्व, हाथियों में ऐरावत और मनुष्यों में राजा मुझे ही जानो।।
 '),
('241c685a-3810-5bf4-a701-7bbd583e439d'::uuid, '23b7055f-24f3-509d-b448-330bdd266df7'::uuid, 'ramsukhdas', 'hindi', '।।10.28।। आयुधोंमें वज्र और धेनुओंमें कामधेनु मैं हूँ। सन्तान-उत्पत्तिका हेतु कामदेव मैं हूँ और सर्पोंमें वासुकि मैं हूँ।'),
('c71f9d69-c562-5432-8b4c-3397b9367a1c'::uuid, '23b7055f-24f3-509d-b448-330bdd266df7'::uuid, 'tejomayananda', 'hindi', '।।10.28।। मैं शस्त्रों में वज्र और धेनुओं (गायों) में कामधेनु हूँ, प्रजा उत्पत्ति का हेतु कन्दर्प (कामदेव) मैं हूँ और सर्पों में वासुकि हूँ।।
 ')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('5db3ebf6-4fcd-52b7-80c9-14cde43d19b9'::uuid, '6bdfac75-31de-5c07-90b5-8c3ce0b1fd02'::uuid, 'ramsukhdas', 'hindi', '।।10.29।। नागोंमें अनन्त (शेषनाग) और जल-जन्तुओंका अधिपति वरुण मैं हूँ। पितरोंमें अर्यमा और शासन करनेवालोंमें यमराज मैं हूँ।'),
('ed162546-ef95-520c-999d-6e2c274a287b'::uuid, '6bdfac75-31de-5c07-90b5-8c3ce0b1fd02'::uuid, 'tejomayananda', 'hindi', '।।10.29।। मैं नागों में अनन्त (शेषनाग) हूँ और जल देवताओं में वरुण हूँ; मैं पितरों में अर्यमा हँ और नियमन करने वालों में यम हूँ।।
 '),
('45e3d127-5eb5-5d4d-a9a1-ac669ce2e0a5'::uuid, '8bd37472-41bd-5c14-933a-cbebce43a454'::uuid, 'ramsukhdas', 'hindi', '।।10.30।। दैत्योंमें प्रह्लाद और गणना करनेवालोंमें काल मैं हूँ । पशुओंमें सिंह और पक्षियोंमें गरुड मैं हूँ।'),
('6d411147-ea80-5594-ad00-58b141096252'::uuid, '8bd37472-41bd-5c14-933a-cbebce43a454'::uuid, 'tejomayananda', 'hindi', '।।10.30।। मैं दैत्यों में प्रह्लाद और गणना करने वालों में काल हूँ, मैं ''पशुओं'' में सिंह (मृगेन्द्र) और पक्षियों में गरुड़ हूँ।।
 '),
('0c5492db-317c-55f4-bf0f-f5aa435906a7'::uuid, 'f40375a9-c9f5-5c6a-9a66-010ba15cc86e'::uuid, 'ramsukhdas', 'hindi', '।।10.31।। पवित्र करनेवालोंमें वायु और शास्त्रधारियोंमें राम मैं हूँ। जल-जन्तुओंमें मगर मैं हूँ। बहनेवाले स्त्रोतोंमें गङ्गाजी मैं हूँ।'),
('5b2da4fc-1c1e-50a1-aebe-1d31a2414651'::uuid, 'f40375a9-c9f5-5c6a-9a66-010ba15cc86e'::uuid, 'tejomayananda', 'hindi', '।।10.31।। मैं पवित्र करने वालों में वायु हूँ और शस्त्रधारियों में राम हूँ; तथा मत्स्यों (जलचरों) में मैं मगरमच्छ और नदियों में मैं गंगा हूँ।।
 '),
('cb33b459-0ac6-5503-9345-e4e5c9a4532b'::uuid, '12953804-97f5-598a-88cc-cd9b22fd31f6'::uuid, 'ramsukhdas', 'hindi', '।।10.32।। हे अर्जुन ! सम्पूर्ण सर्गोंके आदि, मध्य तथा अन्तमें मैं ही हूँ। विद्याओंमें अध्यात्मविद्या और परस्पर शास्त्रार्थ करनेवालोंका(तत्त्व-निर्णयके लिये किया जानेवाला) वाद मैं हूँ।'),
('9d701521-7a50-5f63-a658-78e3421274d4'::uuid, '12953804-97f5-598a-88cc-cd9b22fd31f6'::uuid, 'tejomayananda', 'hindi', '।।10.32।। हे अर्जुन ! सृष्टियों का आदि, अन्त और मध्य भी मैं ही हूँ, मैं विद्याओं में अध्यात्मविद्या और विवाद करने वालों में (अर्थात् विवाद के प्रकारों में) मैं वाद हूँ।।
 '),
('ddc06dc7-e083-5b62-a3a5-2ceb4aef2fdf'::uuid, '5c3d7487-717a-56fb-8db4-f9ecc1d7b01c'::uuid, 'ramsukhdas', 'hindi', '।।10.33।। अक्षरोंमें अकार और समासोंमें द्वन्द्व समास मैं हूँ। अक्षयकाल अर्थात् कालका भी महाकाल तथा सब ओर मुखवाला धाता भी मैं हूँ।'),
('be4176a7-6a30-50df-84b2-b273f136d648'::uuid, '5c3d7487-717a-56fb-8db4-f9ecc1d7b01c'::uuid, 'tejomayananda', 'hindi', '।।10.33।। मैं अक्षरों (वर्णमाला) में अकार और समासों में द्वन्द्व (नामक समास) हूँ; मैं अक्षय काल और विश्वतोमुख (विराट् स्वरूप) धाता हूँ।।
 '),
('a0c5265f-4342-5c4b-b951-6290a0408ed5'::uuid, 'b57a7f41-b0d5-5605-91ae-956e0f0666d9'::uuid, 'ramsukhdas', 'hindi', '।।10.34।। सबका हरण करनेवाली मृत्यु और उत्पन्न होनेवालोंका उभ्दव मैं हूँ तथा स्त्री-जातिमें कीर्ति, श्री, वाक्, स्मृति, मेधा, धृति और क्षमा मैं हूँ।'),
('1242eebe-cfcc-5709-92f9-6fc48c1e583a'::uuid, 'b57a7f41-b0d5-5605-91ae-956e0f0666d9'::uuid, 'tejomayananda', 'hindi', '।।10.34।। मैं सर्वभक्षक मृत्यु और भविष्य में होने वालों की उत्पत्ति का कारण हूँ; स्त्रियों में कीर्ति, श्री, वाक (वाणी), स्मृति, मेधा, धृति और क्षमा हूँ।।
 '),
('47c3c03e-5b57-5047-93dd-dcff32c3060f'::uuid, '6e3af952-af6a-5e4d-9a10-bc856eca2039'::uuid, 'ramsukhdas', 'hindi', '।।10.35।। गायी जानेवाली श्रुतियोंमें बृहत्साम और वैदिक छन्दोंमें गायत्री छन्द मैं हूँ। बारह महीनोंमें मार्गशीर्ष और छः ऋतुओंमें वसन्त मैं हूँ।'),
('6a49da14-a9a9-579b-aa71-775846715082'::uuid, '6e3af952-af6a-5e4d-9a10-bc856eca2039'::uuid, 'tejomayananda', 'hindi', '।।10.35।। सामों (गेय मन्त्रों) में मैं बृहत्साम और छन्दों में गायत्री छन्द हूँ; मैं मासों में मार्गशीर्ष (दिसम्बरजनवरी के भाग) और ऋतुओं में वसन्त हूँ।।
 '),
('6d531a03-d0e3-525a-8738-5843648b071b'::uuid, 'fe70e8c1-a538-568d-af01-b03669e4ea9a'::uuid, 'ramsukhdas', 'hindi', '।।10.36।। छल करनेवालोंमें जूआ और तेजस्वियोंमें तेज मैं हूँ। जीतनेवालोंकी विजय, निश्चय करनेवालोंका निश्चय और सात्त्विक मनुष्योंका सात्त्विक भाव मैं हूँ।'),
('990386b2-03d4-5a24-93ff-276e6d4051dc'::uuid, 'fe70e8c1-a538-568d-af01-b03669e4ea9a'::uuid, 'tejomayananda', 'hindi', '।।10.36।। मैं छल करने वालों में द्यूत हूँ और तेजस्वियों में तेज हूँ, मैं विजय हूँ; मैं व्यवसाय (उद्यमशीलता) हूँ और सात्विक पुरुषों का सात्विक भाव हूँ।।
 '),
('fbb51baa-be90-5505-8ee7-1aba906cb720'::uuid, '9c5da1f5-2d56-50dc-95e1-529f6974ec17'::uuid, 'ramsukhdas', 'hindi', '।।10.37।। वृष्णिवंशियोंमें वासुदेव और पाण्डवोंमें धनञ्जय मैं हूँ। मुनियोंमें वेदव्यास और कवियोंमें कवि शुक्राचार्य भी मैं हूँ।'),
('bffc74ea-6706-582b-bfcf-b390d57a0ba8'::uuid, '9c5da1f5-2d56-50dc-95e1-529f6974ec17'::uuid, 'tejomayananda', 'hindi', '।।10.37।। मैं वृष्णियों में वासुदेव हूँ और पाण्डवों में धनंजय, मैं मुनियों में व्यास और कवियों में उशना कवि हूँ।।
 '),
('b6d23ec3-2f68-5383-9718-c77e9e64c6da'::uuid, '76abbd73-3126-5417-8148-67094f760fe8'::uuid, 'ramsukhdas', 'hindi', '।।10.38।। दमन करनेवालोंमें दण्डनीति और विजय चाहनेवालोंमें नीति मैं हूँ। गोपनीय भावोंमें मौन और ज्ञानवानोंमें ज्ञान मैं हूँ।'),
('82523e28-2ae3-5a9f-9942-95e788b4dbc1'::uuid, '76abbd73-3126-5417-8148-67094f760fe8'::uuid, 'tejomayananda', 'hindi', '।।10.38।। मैं दमन करने वालों का दण्ड हूँ और विजयेच्छुओं की नीति हूँ; मैं गुह्यों में मौन हूँ और ज्ञानवानों का ज्ञान हूँ।।
 '),
('9447adf2-f914-5992-9a8d-051199dfa430'::uuid, '22f05195-d61f-5fae-a530-c6fbeef36198'::uuid, 'ramsukhdas', 'hindi', '।।10.39।। हे अर्जुन! सम्पूर्ण प्राणियोंका जो बीज है, वह बीज मैं ही हूँ; क्योंकि मेरे बिना कोई भी चर-अचर प्राणी नहीं है अर्थात् चर-अचर सब कुछ मैं ही हूँ।'),
('3216d4c7-b600-5107-b63f-af6c30a78b1a'::uuid, '22f05195-d61f-5fae-a530-c6fbeef36198'::uuid, 'tejomayananda', 'hindi', '।।10.39।। हे अर्जुन ! जो समस्त भूतों की उत्पत्ति का बीज (कारण) है, वह भी में ही हूँ, क्योंकि ऐसा कोई चर और अचर भूत नहीं है, जो मुझसे रहित है।।
 '),
('cb43bc53-ad3f-51d3-b885-5608b5309874'::uuid, 'e4da816e-b9e0-5b44-ab42-4ed2171ac57a'::uuid, 'ramsukhdas', 'hindi', '।।10.40।। हे परंतप अर्जुन ! मेरी दिव्य विभूतियोंका अन्त नहीं है। मैंने तुम्हारे सामने अपनी विभूतियोंका जो विस्तार कहा है, यह तो केवल संक्षेपसे कहा है।'),
('996081d3-9eed-55f9-a6de-d62457a9d103'::uuid, 'e4da816e-b9e0-5b44-ab42-4ed2171ac57a'::uuid, 'tejomayananda', 'hindi', '।।10.40।। हे परन्तप ! मेरी दिव्य विभूतियों का अन्त नहीं है; अपनी विभूतियों का यह विस्तार मैंने एक देश से अर्थात् संक्षेप में कहा है।।
 '),
('b54cd739-352f-5915-b9e6-956b256afbab'::uuid, '5eac06b9-a790-5427-9d94-84be18f94cb8'::uuid, 'ramsukhdas', 'hindi', '।।10.41।। जो-जो ऐश्वर्ययुक्त, शोभायुक्त और बलयुक्त प्राणी तथा वस्तु है, उस-उसको तुम मेरे ही तेज-(योग-) के अंशसे उत्पन्न हुई समझो।'),
('a5a7b753-be4e-52c0-84b7-5578ddd18c20'::uuid, '5eac06b9-a790-5427-9d94-84be18f94cb8'::uuid, 'tejomayananda', 'hindi', '।।10.41।। जो कोई भी विभूतियुक्त, कान्तियुक्त अथवा शक्तियुक्त वस्तु (या प्राणी) है, उसको तुम मेरे तेज के अंश से ही उत्पन्न हुई जानो।।
 '),
('5104821b-a2b6-5ecd-a792-18b5b2ff673a'::uuid, 'f41b38d6-776c-5e3e-978d-48b6244fc84d'::uuid, 'ramsukhdas', 'hindi', '।।10.42।। अथवा हे अर्जुन ! तुम्हें इस प्रकार बहुत-सी बातें जाननेकी क्या आवश्यकता है?  मैं अपने किसी एक अंशसे  सम्पूर्ण जगत् को व्याप्त करके स्थित हूँ।'),
('891efd76-ec88-5424-ac3d-e5e8eaf4a8b0'::uuid, 'f41b38d6-776c-5e3e-978d-48b6244fc84d'::uuid, 'tejomayananda', 'hindi', '।।10.42।। अथवा हे अर्जुन ! बहुत जानने से तुम्हारा क्या प्रयोजन है? मैं इस सम्पूर्ण जगत् को अपने एक अंश मात्र से धारण करके स्थित हूँ।।'),
('22f8d625-13ff-5d88-bda6-cb4e1d4858ed'::uuid, 'cf203c24-9c69-5343-9489-c4ac32571b7f'::uuid, 'ramsukhdas', 'hindi', '।।11.1।। अर्जुन बोले -- केवल मेरेपर कृपा करनेके लिये ही आपने जो परम गोपनीय अध्यात्मतत्तव जाननेका वचन कहा, उससे मेरा यह मोह नष्ट हो गया है।'),
('1e871221-c1f2-5572-940e-79a1e2ca296a'::uuid, 'cf203c24-9c69-5343-9489-c4ac32571b7f'::uuid, 'tejomayananda', 'hindi', '।।11.1।। अर्जुन ने कहा -- मुझ पर अनुग्रह करने के लिए जो परम गोपनीय, अध्यात्मविषयक वचन (उपदेश) आपके द्वारा कहा गया, उससे मेरा मोह दूर हो गया है।।
 '),
('54497f78-23ef-590a-bc15-208ad2359e27'::uuid, 'c1ed36ef-229d-5b48-abab-e6735afccec2'::uuid, 'ramsukhdas', 'hindi', '।।11.2।।  हे कमलनयन ! सम्पूर्ण प्राणियोंकी उत्पत्ति और प्रलय मैंने विस्तारपूर्वक आपसे ही सुना है और आपका अविनाशी माहात्म्य भी सुना है।'),
('d1097792-5460-51e6-942d-8da3bbbd4734'::uuid, 'c1ed36ef-229d-5b48-abab-e6735afccec2'::uuid, 'tejomayananda', 'hindi', '।।11.2।। हे कमलनयन ! मैंने भूतों की उत्पत्ति और प्रलय आपसे विस्तारपूर्वक सुने हैं तथा आपका अव्यय माहात्म्य (प्रभाव) भी सुना है।।
 '),
('f8b5d339-4417-5d05-987c-639f3ed02185'::uuid, 'acab8c6a-5263-5235-af04-51f695a380f3'::uuid, 'ramsukhdas', 'hindi', '।।11.3।। हे पुरुषोत्तम ! आप अपने-आपको जैसा कहते हैं, यह वास्तवमें ऐसा ही है। हे परमेश्वर ! आपके ईश्वर-सम्बन्धी रूपको मैं देखना चाहता हूँ।'),
('0392b594-efdd-5a5a-9efc-502a06d6924c'::uuid, 'acab8c6a-5263-5235-af04-51f695a380f3'::uuid, 'tejomayananda', 'hindi', '।।11.3।। हे परमेश्वर ! आप अपने को जैसा कहते हो, यह ठीक ऐसा ही है। (परन्तु) हे पुरुषोत्तम ! मैं आपके ईश्वरीय रूप को प्रत्यक्ष देखना चाहता हूँ।।
 '),
('5324bf33-c3c3-594d-9696-7c1f3a3cb6e8'::uuid, 'bd2015b9-2baa-5c92-ad72-9c58419acc14'::uuid, 'ramsukhdas', 'hindi', '।।11.4।। हे प्रभो ! मेरे द्वारा आपका वह परम ऐश्वर रूप देखा जा सकता है -- ऐसा अगर आप मानते हैं, तो हे योगेश्वर ! आप अपने उस अविनाशी स्वरूपको मुझे दिखा दीजिये।'),
('f5afb7b2-db93-589b-b624-4abb6cba47be'::uuid, 'bd2015b9-2baa-5c92-ad72-9c58419acc14'::uuid, 'tejomayananda', 'hindi', '।।11.4।। हे प्रभो ! यदि आप मानते हैं कि मेरे द्वारा वह आपका रूप देखा जाना संभव है, तो हे योगेश्वर ! आप अपने अव्यय रूप का दर्शन कराइये।।
 '),
('8d0ce1b4-a73b-5b7c-8f55-03539b31f463'::uuid, '2904542e-48ff-5375-883c-808e320c0a18'::uuid, 'ramsukhdas', 'hindi', '।।11.5।। श्रीभगवान् बोले -- हे पृथानन्दन ! अब मेरे अनेक तरहके, अनेक अनेक वर्णों और आकृतियोंवाले सैकड़ों-हजारों दिव्यरूपोंको तू देख।'),
('6d858004-737a-5ccd-aba9-654ca724ad83'::uuid, '2904542e-48ff-5375-883c-808e320c0a18'::uuid, 'tejomayananda', 'hindi', '।।11.5।। श्रीभगवान् ने कहा -- हे पार्थ ! मेरे सैकड़ों तथा सहस्रों नाना प्रकार के और नाना वर्ण तथा आकृति वाले दिव्य रूपों को देखो।।
 '),
('190a9cb8-039f-5cb2-8142-931034e69e9e'::uuid, '3bffd301-09a9-5ada-9b40-6ad89a9a09da'::uuid, 'ramsukhdas', 'hindi', '।।11.6।। हे भरतवंशोद्भव अर्जुन! तू बारह आदित्योंको, आठ वसुओंको, ग्यारह रुद्रोंको और दो अश्विनीकुमारोंको तथा उनचास मरुद्गणोंको देख। जिनको तूने पहले कभी देखा नहीं, ऐसे बहुत-से आश्चर्यजनक रूपोंको भी तू देख।'),
('0106967c-abda-5cd8-a4cb-f7de34d2d23f'::uuid, '3bffd301-09a9-5ada-9b40-6ad89a9a09da'::uuid, 'tejomayananda', 'hindi', '।।11.6।। हे भारत ! (मुझमें) आदित्यों, वसुओं, रुद्रों तथा अश्विनीकुमारों और मरुद्गणों को देखो, तथा और भी अनेक इसके पूर्व कभी न देखे हुए आश्चर्यों को देखो।।
 '),
('07f41b23-12d7-55ae-904f-8a462b6975de'::uuid, '7dcaec60-206b-5a52-a562-a2d3b8a11392'::uuid, 'ramsukhdas', 'hindi', '।।11.7।। हे नींदको जीतनेवाले अर्जुन! मेरे इस शरीरके एक देशमें चराचरसहित सम्पूर्ण जगत् को अभी देख ले। इसके सिवाय तू और भी जो कुछ देखना चाहता है, वह भी देख ले।'),
('b07e650b-22c0-51d4-a022-c3762766a98e'::uuid, '7dcaec60-206b-5a52-a562-a2d3b8a11392'::uuid, 'tejomayananda', 'hindi', '।।11.7।। हे गुडाकेश ! आज (अब) इस मेरे शरीर में एक स्थान पर स्थित हुए चराचर सहित सम्पूर्ण जगत् को देखो तथा और भी जो कुछ तुम देखना चाहते हो, उसे भी देखो।।
 '),
('9c67a92f-414d-59ef-8126-766386e7cbb5'::uuid, 'dd14f713-8c54-5162-b144-06f6ac0cb41a'::uuid, 'ramsukhdas', 'hindi', '।।11.8।। परन्तु तू अपनी इस आँखसे अर्थात् चर्मचक्षुसे मेरेको देख ही नहीं सकता, इसलिये मैं तुझे दिव्य चक्षु देता हूँ, जिससे तू मेरी ईश्वर-सम्बन्धी सामर्थ्यको देख।'),
('206215c3-9bf3-5b14-9ec8-cc1942e29b4f'::uuid, 'dd14f713-8c54-5162-b144-06f6ac0cb41a'::uuid, 'tejomayananda', 'hindi', '।।11.8।। परन्तु तुम अपने इन्हीं (प्राकृत) नेत्रों के द्वारा मुझे देखने में समर्थ नहीं हो; (इसलिए) मैं तुम्हें दिव्यचक्षु देता हूँ, जिससे तुम मेरे ईश्वरीय ''योग'' को देखो।।'),
('8f0e9b81-45bf-570c-827e-7c229a6cdfa5'::uuid, '2876e97a-c26f-5e5d-9ab2-9a06c893416d'::uuid, 'ramsukhdas', 'hindi', '।।11.9।। सञ्जय बोले -- हे राजन् ! ऐसा कहकर फिर महायोगेश्वर भगवान् श्रीकृष्णने अर्जुनको परम ऐश्वर-रूप दिखाया।'),
('b8786b6d-fa8a-5570-a251-ce4a201bcae1'::uuid, '2876e97a-c26f-5e5d-9ab2-9a06c893416d'::uuid, 'tejomayananda', 'hindi', '।।11.9।। संजय ने कहा -- हे राजन् ! महायोगेश्वर हरि ने इस प्रकार कहकर फिर अर्जुन के लिए परम ऐश्वर्ययुक्त रूप को दर्शाया।।
 '),
('ed12a537-bcaf-5bc0-9677-f569f2968d64'::uuid, '835f9e7c-3884-555e-8f6a-f5d90f30d6e8'::uuid, 'ramsukhdas', 'hindi', '।।11.10 -- 11.11।। जिसके अनेक मुख और नेत्र हैं, अनेक तहरके अद्भुत दर्शन हैं, अनेक दिव्य आभूषण हैं, हाथोंमें उठाये हुए अनेक दिव्य आयुध हैं तथा जिनके गलेमें दिव्य मालाएँ हैं, जो दिव्य वस्त्र पहने हुए हैं, जिनके ललाट तथा शरीरपर दिव्य चन्दन, कुंकुम आदि लगा हुआ है, ऐसे सम्पूर्ण आश्चर्यमय, अनन्तरूपवाले तथा चारों तरफ मुखवाले देव-(अपने दिव्य स्वरूप-) को भगवान् ने दिखाया।'),
('e376c374-5a4d-5ab4-aec4-3299a7d78764'::uuid, '835f9e7c-3884-555e-8f6a-f5d90f30d6e8'::uuid, 'tejomayananda', 'hindi', '।।11.10।। उस अनेक मुख और नेत्रों से युक्त तथा अनेक अद्भुत दर्शनों वाले एवं बहुत से दिव्य भूषणों से युक्त और बहुत से दिव्य शस्त्रों को हाथों में उठाये हुये।।'),
('abed4a81-5915-5a08-b680-7c1ea6e3b390'::uuid, 'b3fc7603-7a71-5357-9c8a-480993340bb8'::uuid, 'ramsukhdas', 'hindi', '।।11.10 -- 11.11।। जिसके अनेक मुख और नेत्र हैं, अनेक तहरके अद्भुत दर्शन हैं, अनेक दिव्य आभूषण हैं, हाथोंमें उठाये हुए अनेक दिव्य आयुध हैं तथा जिनके गलेमें दिव्य मालाएँ हैं, जो दिव्य वस्त्र पहने हुए हैं, जिनके ललाट तथा शरीरपर दिव्य चन्दन, कुंकुम आदि लगा हुआ है, ऐसे सम्पूर्ण आश्चर्यमय, अनन्त रूपोंवाले तथा चारों तरफ मुखवाले देव-(अपने दिव्य स्वरूप-) को भगवान् ने दिखाया।'),
('dc6bfcaa-8046-5e1c-82ca-d134a672c8a4'::uuid, 'b3fc7603-7a71-5357-9c8a-480993340bb8'::uuid, 'tejomayananda', 'hindi', '।।11.11।। दिव्य माला और वस्त्रों को धारण किये हुये और दिव्य गन्ध का लेपन किये हुये एवं समस्त प्रकार के आश्चर्यों से युक्त अनन्त, विश्वतोमुख (विराट् स्वरूप) परम देव (को अर्जुन ने देखा)।।
 '),
('1bbdd2a5-d5c6-58cd-b8fa-4cb9af1f88a5'::uuid, '5a4c12fa-9b87-5270-8480-4b171e2aa560'::uuid, 'ramsukhdas', 'hindi', '।।11.12।। अगर आकाशमें एक साथ हजारों सूर्य उदित हो जायँ, तो भी उन सबका प्रकाश मिलकर उस महात्मा-(विराट् रूप परमात्मा-) के प्रकाशके समान शायद ही हो।'),
('ebb6067f-99f2-5f54-857e-32cc24f27620'::uuid, '5a4c12fa-9b87-5270-8480-4b171e2aa560'::uuid, 'tejomayananda', 'hindi', '।।11.12।। आकाश में सहस्र सूर्यों के एक साथ उदय होने से उत्पन्न जो प्रकाश होगा, वह उस (विश्वरूप) परमात्मा के प्रकाश के सदृश होगा।।
 '),
('c588f69a-c1df-568f-94b2-0de0b73e9acd'::uuid, '6447375e-f3ed-5c01-9d7e-a672fe5eea72'::uuid, 'ramsukhdas', 'hindi', '।।11.13।। उस समय अर्जुनने देवोंके देव भगवान् के उस शरीरमें एक जगह स्थित अनेक प्रकारके विभागोंमें विभक्त सम्पूर्ण जगत् को देखा।'),
('e072d40e-1875-5993-b616-6a7c0de2ab0a'::uuid, '6447375e-f3ed-5c01-9d7e-a672fe5eea72'::uuid, 'tejomayananda', 'hindi', '।।11.13।। पाण्डुपुत्र अर्जुन ने उस समय अनेक प्रकार से विभक्त हुए सम्पूर्ण जगत् को देवों के देव श्रीकृष्ण के शरीर में एक स्थान पर स्थित देखा।।'),
('00db6d8c-e885-5f5b-8321-7225435c24e6'::uuid, '26c79fd3-5b59-5a01-8706-7854cfc2a811'::uuid, 'ramsukhdas', 'hindi', '।।11.14।। भगवान् के विश्वरूपको देखकर अर्जुन बहुत चकित हुए और आश्चर्यके कारण उनका शरीर रोमाञ्चित हो गया। वे हाथ जोड़कर विश्वरूप देवको मस्तकसे प्रणाम करके बोले।'),
('79708c93-f811-5616-b83b-3dd379c90637'::uuid, '26c79fd3-5b59-5a01-8706-7854cfc2a811'::uuid, 'tejomayananda', 'hindi', '।।11.14।। उसके उपरान्त वह आश्चर्यचकित हुआ हर्षित रोमों वाला (जिसे रोमांच का अनुभव हो रहा हो) धनंजय अर्जुन विश्वरूप देव को (श्रद्धा भक्ति सहित) शिर से प्रणाम करके हाथ जोड़कर बोला।।'),
('3e824395-6d13-5bf7-907f-6236275bc579'::uuid, 'cb32a00d-21bd-5882-baab-c0e88089b2b8'::uuid, 'ramsukhdas', 'hindi', '।।11.15।। अर्जुन बोले -- हे देव ! मैं आपके शरीरमें सम्पूर्ण देवताओंको, प्राणियोंके विशेष-विशेष समुदायोंको कमलासनपर बैठे हुए ब्रह्माजीको, शङ्करजीको, सम्पूर्ण ऋषियोंको और सम्पूर्ण दिव्य सर्पोंको देख रहा हूँ।'),
('dd26851e-cf7c-52eb-9e5b-89408d7089ff'::uuid, 'cb32a00d-21bd-5882-baab-c0e88089b2b8'::uuid, 'tejomayananda', 'hindi', '।।11.15।। अर्जुन ने कहा -- हे देव! मैं आपके शरीर में समस्त देवों को तथा अनेक भूतविशेषों के समुदायों को और कमलासन पर स्थित सृष्टि के स्वामी ब्रह्माजी को, ऋषियों को और दिव्य सर्पों को देख रहा हूँ।।
 '),
('d6b698bf-da86-53ad-ad1a-d8b2eed5c26f'::uuid, '192a9daa-4cc3-5093-9c30-4e93c9bdd135'::uuid, 'ramsukhdas', 'hindi', '।।11.16।। हे विश्वरूप ! हे विश्वेश्वरव ! आपको मैं अनेक हाथों, पेटों, मुखों और नेत्रोंवाला तथा सब ओरसे अनन्त रूपोंवाला देख रहा हूँ। मैं आपके न आदिको, न मध्यको और न अन्तको ही देख रहा हूँ।'),
('f6a8fbdf-8cf1-56c6-b42c-86059059b402'::uuid, '192a9daa-4cc3-5093-9c30-4e93c9bdd135'::uuid, 'tejomayananda', 'hindi', '।।11.16।। हे विश्वेश्वर! मैं आपकी अनेक बाहु, उदर, मुख और नेत्रों से युक्त तथा सब ओर से अनन्त रूपों वाला देखता हूँ। हे विश्वरूप! मैं आपके न अन्त को देखता हूँ और न मध्य को और न आदि को।।
 '),
('5afef24e-9a36-5bc4-a1d4-31ee55a69a84'::uuid, '42caf673-7f83-5e1a-8837-00f15d2dc7b3'::uuid, 'ramsukhdas', 'hindi', '।।11.17।। मैं आपको किरीट, गदा, चक्र (तथा शङ्ख और पद्म) धारण किये हुए देख रहा हूँ। आपको तेजकी राशि, सब ओर प्रकाश करनेवाले, देदीप्यमान अग्नि तथा सूर्यके समान कान्तिवाले, नेत्रोंके द्वारा कठिनतासे देखे जानेयोग्य और सब तरफसे अप्रमेयस्वरूप देख रहा हूँ।'),
('780a21d9-9fa9-5133-98f5-d8d9829030e2'::uuid, '42caf673-7f83-5e1a-8837-00f15d2dc7b3'::uuid, 'tejomayananda', 'hindi', '।।11.17।। मैं आपका मुकुटयुक्त, गदायुक्त और चक्रधारण किये हुये तथा सब ओर से प्रकाशमान् तेज का पुंज, दीप्त अग्नि और सूर्य के समान ज्योतिर्मय, देखने में अति कठिन और अप्रमेयस्वरूप सब ओर से देखता हूँ।।
 '),
('1d889914-4011-5894-ae65-58a41bf3f86c'::uuid, '070e78e0-b554-562b-bbbe-e46dcb51accb'::uuid, 'ramsukhdas', 'hindi', '।।11.18।। आप ही जाननेयोग्य परम अक्षर (अक्षरब्रह्म) हैं, आप ही इस सम्पूर्ण विश्वके परम आश्रय हैं, आप ही सनातनधर्मके रक्षक हैं और आप ही अविनाशी सनातन पुरुष हैं -- ऐसा मैं मानता हूँ।'),
('83e422e8-7ae5-5007-b72c-033864ae790b'::uuid, '070e78e0-b554-562b-bbbe-e46dcb51accb'::uuid, 'tejomayananda', 'hindi', '।।11.18।। आप ही जानने योग्य (वेदितव्यम्) परम अक्षर हैं; आप ही इस विश्व के परम आश्रय (निधान) हैं ! आप ही शाश्वत धर्म के रक्षक हैं और आप ही सनातन पुरुष हैं,ऐसा मेरा मत है।।
 '),
('ba2775cc-20e0-5301-8edf-4db7d2a2d087'::uuid, '55b5f6b4-10c3-5df6-9721-6e2c9e2280c7'::uuid, 'ramsukhdas', 'hindi', '।।11.19।। आपको मैं आदि, मध्य और अन्तसे रहित, अनन्त प्रभावशाली, अनन्त भुजाओंवाले, चन्द्र और सूर्यरूप नेत्रोवाले, प्रज्वलित अग्निके समान मुखोंवाले और अपने तेजसे संसारको संतप्त करते हुए देख रहा हूँ।'),
('6947e9f2-575f-5a7f-a4b6-6788f0a6cc0b'::uuid, '55b5f6b4-10c3-5df6-9721-6e2c9e2280c7'::uuid, 'tejomayananda', 'hindi', '।।11.19।। मैं आपको आदि, अन्त और मध्य से रहित तथा अनंत सार्मथ्य से युक्त और अनंत बाहुओं वाला तथा चन्द्रसूर्यरूपी नेत्रों वाला और दीप्त अग्निरूपी मुख वाला तथा अपने तेज से इस विश्व को तपाते हुए देखता हूँ।।
 '),
('0cb7e0e2-aa86-59cd-8d51-775d00c814f8'::uuid, 'd8d870a5-a336-5f00-acd7-5642effcd875'::uuid, 'ramsukhdas', 'hindi', '।।11.20।। हे महात्मन् ! यह स्वर्ग और पृथ्वीके बीचका अन्तराल और सम्पूर्ण दिशाएँ एक आपसे ही परिपूर्ण हैं। आपके इस अद्भुत और उग्ररूपको देखकर तीनों लोक व्यथित (व्याकुल) हो रहे हैं।'),
('b18af21b-3091-551c-bdc3-138857d5ae67'::uuid, 'd8d870a5-a336-5f00-acd7-5642effcd875'::uuid, 'tejomayananda', 'hindi', '।।11.20।। हे महात्मन् ! स्वर्ग और पृथ्वी के मध्य का यह आकाश तथा समस्त दिशाएं अकेले आप से ही व्याप्त हैं; आपके इस अद्भुत और उग्र रूप को देखकर तीनों लोक अतिव्यथा (भय) को प्राप्त हो रहे हैं।।
 '),
('7afa0dfb-a64d-5254-a86c-1766ddd393c4'::uuid, '32157bf6-f2a9-5a7f-9f6c-957f98976d68'::uuid, 'ramsukhdas', 'hindi', '।।11.21।। वे ही देवताओंके समुदाय आपमें प्रविष्ट हो रहे हैं। उनमेंसे कई तो भयभीत होकर हाथ जोड़े हुए आपके नामों और गुणोंका कीर्तन कर रहे हैं। महर्षियों और सिद्धोंके समुदाय ''कल्याण हो ! मङ्गल हो !'' ऐसा कहकर उत्तम-उत्तम स्तोत्रोंके द्वारा आपकी स्तुति कर रहे हैं।'),
('4409770d-e825-5217-a8c0-69809c0b4a82'::uuid, '32157bf6-f2a9-5a7f-9f6c-957f98976d68'::uuid, 'tejomayananda', 'hindi', '।।11.21।। ये समस्त देवताओं के समूह आप में ही प्रवेश कर रहे हैं और कई एक भयभीत होकर हाथ जोड़े हुए आप की स्तुति करते हैं; महर्षि और सिद्धों के समुदाय ''कल्याण होवे'' (स्वस्तिवाचन करते हुए) ऐसा कहकर, उत्तम (या सम्पूर्ण) स्रोतों द्वारा आपकी स्तुति करते हैं।।
 '),
('9c5fd225-c761-5b5f-89dc-f554a987434c'::uuid, '5ee66cf5-a09d-574a-9827-f74b97fc56a1'::uuid, 'ramsukhdas', 'hindi', '।।11.22।। जो ग्यारह रुद्र, बारह आदित्य, आठ वसु, बारह साध्यगण, दस विश्वेदेव और दो अश्विनीकुमार, उनचास मरुद्गण, सात पितृगण तथा गन्धर्व, यक्ष, असुर और सिद्धोंके समुदाय हैं, वे सभी चकित होकर आपको देख रहे हैं।'),
('7f6a5d73-4b19-5d6b-a49c-1ef2f75dc531'::uuid, '5ee66cf5-a09d-574a-9827-f74b97fc56a1'::uuid, 'tejomayananda', 'hindi', '।।11.22।। रुद्रगण, आदित्य, वसु और साध्यगण, विश्वेदेव तथा दो अश्विनीकुमार, मरुद्गण और उष्मपा, गन्धर्व, यक्ष, असुर और सिद्धगणों के समुदाय- ये सब ही विस्मित होते हुए आपको देखते हैं।।
 '),
('ba5f1eb6-8ed8-55bc-adc0-49b9a27a87e0'::uuid, '8346db69-7987-5a30-9c6b-2a23cdf3373d'::uuid, 'ramsukhdas', 'hindi', '।।11.23।। हे महाबाहो! आपके बहुत मुखों और नेत्रोंवाले, बहुत भुजाओं, जंघाओं और चरणोंवाले, बहुत उदरोंवाले, बहुत विकराल दाढ़ोंवाले महान् रूपको देखकर सब प्राणी व्यथित हो रहे हैं तथा मैं भी व्यथित हो रहा हूँ।'),
('8c81091f-043d-5e15-a326-afd6d714d061'::uuid, '8346db69-7987-5a30-9c6b-2a23cdf3373d'::uuid, 'tejomayananda', 'hindi', '।।11.23।। हे महाबाहो! आपके बहुत मुख तथा नेत्र वाले, बहुत बाहु, उरु (जंघा) तथा पैरों वाले, बहुत-ंंसी उदरों वाले तथा बहुतसी विकराल दाढ़ों वाले महान् रूप को देखकर सब लोग व्यथित हो रहे हैं और उसी प्रकार मैं भी (व्याकुल हो रहा हूँ)।।
 '),
('e06f479e-4f45-5209-978d-6d35a1051b93'::uuid, '6b7a3dda-850f-54d4-b6da-6e45ed45c8d5'::uuid, 'ramsukhdas', 'hindi', '।।11.24।। हे विष्णो ! आपके अनेक देदीप्यमान वर्ण हैं, आप आकाशको स्पर्श कर रहे हैं, आपका मुख फैला हुआ है आपके नेत्र प्रदीप्त और विशाल हैं। ऐसे आपको देखकर भयभीत अन्तःकरणवाला मैं धैर्य और शान्तिको प्राप्त नहीं हो रहा हूँ।'),
('5d555de2-8836-5c68-b0f5-3c479069c122'::uuid, '6b7a3dda-850f-54d4-b6da-6e45ed45c8d5'::uuid, 'tejomayananda', 'hindi', '।।11.24।। हे विष्णो! आकाश के साथ स्पर्श किये हुए देदीप्यमान अनेक रूपों से युक्त तथा विस्तरित मुख और प्रकाशमान विशाल नेत्रों से युक्त आपको देखकर भयभीत हुआ मैं धैर्य और शान्ति को नहीं प्राप्त हो रहा हूँ।।
 '),
('903e8a78-d252-5fc7-ae4b-92e33dcb35a0'::uuid, '70b1db7f-c918-5dc0-8e6c-d8efc52501f0'::uuid, 'ramsukhdas', 'hindi', '।।11.25।। आपके प्रलयकालकी अग्निके समान प्रज्वलित और दाढ़ोंके कारण विकराल (भयानक) मुखोंको देखकर मुझे न तो दिशाओंका ज्ञान हो रहा है और न शान्ति ही मिल रही है। इसलिये हे देवेश ! हे जगन्निवास ! आप प्रसन्न होइये।'),
('3b087ad7-3641-5f93-adef-6cee00050b60'::uuid, '70b1db7f-c918-5dc0-8e6c-d8efc52501f0'::uuid, 'tejomayananda', 'hindi', '।।11.25।। आपके विकराल दाढ़ों वाले और प्रलयाग्नि के समान प्रज्वलित मुखों को देखकर, मैं न दिशाओं को जान पा रहा हूँ और न शान्ति को प्राप्त हो रहा हूँ; इसलिए हे देवेश!  हे जगन्निवास! आप प्रसन्न हो जाइए।।
 '),
('b6b932d3-bfe4-57fb-9540-390f174095ed'::uuid, '3360d1ad-4fd3-5795-b636-d4fb72e05a49'::uuid, 'ramsukhdas', 'hindi', '।।11.26 -- 11.27।। हमारे मुख्य योद्धाओंके सहित भीष्म, द्रोण और वह कर्ण भी आपमें प्रविष्ट हो रहे हैं। राजाओंके समुदायोंके सहित धृतराष्ट्रके वे ही सब-के-सब पुत्र आपके विकराल दाढ़ोंके कारण भयंकर मुखोंमें बड़ी तेजीसे प्रविष्ट हो रहे हैं। उनमेंसे कई-एक तो चूर्ण हुए सिरोंसहित आपके दाँतोंके बीचमें फँसे हुए दीख रहे हैं।'),
('6452c27d-8219-5fd9-b548-8c8655798ddc'::uuid, '3360d1ad-4fd3-5795-b636-d4fb72e05a49'::uuid, 'tejomayananda', 'hindi', '।।11.26।। और ये समस्त धृतराष्ट्र के पुत्र राजाओं के समुदाय सहित आप में प्रवेश करते हैं। भीष्म, द्रोण तथा कर्ण और हमारे पक्ष के भी प्रधान योद्धाओं के सहित.।।
 '),
('de7e8b21-f0f6-5f52-b5ff-b02c472b2816'::uuid, '662847cf-2d99-5e79-9022-b3a15c40d737'::uuid, 'ramsukhdas', 'hindi', '।।11.26 -- 11.27।। हमारे मुख्य  योद्धाओंके सहित भीष्म, द्रोण और वह कर्ण भी आपमें प्रविष्ट हो रहे हैं। राजाओंके समुदायोंके सहित धृतराष्ट्रके वे ही सब-के-सब पुत्र आपके विकराल दाढ़ोंके कारण भयंकर मुखोंमें बड़ी तेजीसे प्रविष्ट हो रहे हैं। उनमेंसे कईएक तो चूर्ण हुए सिरोंसहित आपके दाँतोंके बीचमें फँसे हुए दीख रहे हैं।'),
('4e924cc2-c24d-5466-957f-5ad14ab5a684'::uuid, '662847cf-2d99-5e79-9022-b3a15c40d737'::uuid, 'tejomayananda', 'hindi', '।।11.27।। तीव्र वेग से आपके विकराल दाढ़ों वाले भयानक मुखों में प्रवेश करते हैं और कई एक चूर्णित शिरों सहित आपके दांतों के बीच में फँसे हुए दिख रहे हैं।।'),
('e0887af9-0716-53ad-a8bc-3d3f2e54829d'::uuid, '8db8138e-ae14-5c0d-a9af-0a1e2250ab0b'::uuid, 'ramsukhdas', 'hindi', '।।11.28।। जैसे नदियोंके बहुत-से जलके प्रवाह स्वाभाविक ही समुद्रके सम्मुख दौड़ते हैं, ऐसे ही वे संसारके महान् शूरवीर आपके प्रज्वलित मुखोंमें प्रवेश कर रहे हैं।'),
('186e06bd-e9f3-5866-91a5-0a0e6cd476bc'::uuid, '8db8138e-ae14-5c0d-a9af-0a1e2250ab0b'::uuid, 'tejomayananda', 'hindi', '।।11.28।। जैसे नदियों के बहुत से जलप्रवाह समुद्र की ओर वेग से बहते हैं, वैसे ही मनुष्यलोक के ये वीर योद्धागण आपके प्रज्वलित मुखों में प्रवेश करते हैं।।
 '),
('4d37a1bd-43de-53dc-85c5-29999b786da8'::uuid, 'ba65e7f4-4e6d-585e-94c4-af0daeb1ce9b'::uuid, 'ramsukhdas', 'hindi', '।।11.29।। जैसे पतंगे मोहवश अपना नाश करनेके लिये बड़े वेगसे दौड़ते हुए प्रज्वलित अग्निमें प्रविष्ट होते हैं, ऐसे ही ये सब लोग भी मोहवश अपना नाश करनेके लिये बड़े वेगसे दौड़ते हुए आपके मुखोंमें प्रविष्ट हो रहे हैं।'),
('f6d2dff2-627a-5ff2-a505-71bc2fa32699'::uuid, 'ba65e7f4-4e6d-585e-94c4-af0daeb1ce9b'::uuid, 'tejomayananda', 'hindi', '।।11.29।। जैसे पतंगे अपने नाश के लिए प्रज्वलित अग्नि में अतिवेग से प्रवेश करते हैं, वैसे ही ये लोग भी अपने नाश के लिए आपके मुखों में अतिवेग से प्रवेश करते हैं।।
 '),
('43b2ce8e-5921-5d80-a24d-ff2ffab2d97a'::uuid, 'ed305a07-251d-5880-b621-348554f03d19'::uuid, 'ramsukhdas', 'hindi', '।।11.30।। आप अपने प्रज्वलित मुखोंद्वारा सम्पूर्ण लोकोंका ग्रसन करते हुए उन्हें चारों ओरसे बार-बार चाट रहे हैं और हे विष्णो ! आपका उग्र प्रकाश अपने तेजसे सम्पूर्ण जगत् को परिपूर्ण करके सबको तपा रहा है।'),
('1c4154a3-5aea-5595-85fd-3449f190f61d'::uuid, 'ed305a07-251d-5880-b621-348554f03d19'::uuid, 'tejomayananda', 'hindi', '।।11.30।। हे विष्णो! आप प्रज्वलित मुखों के द्वारा इन समस्त लोकों का ग्रसन करते हुए आस्वाद ले रहे हैं, आपका उग्र प्रकाश सम्पूर्ण जगत् को तेज के द्वारा परिपूर्ण करके तपा रहा है।।
 '),
('cd3c58c5-34a5-504a-bb02-35f12a075768'::uuid, 'bd507b77-94f3-5d16-9fef-e72b2813779c'::uuid, 'ramsukhdas', 'hindi', '।।11.31।। मुझे यह बताइये कि उग्ररूपवाले आप कौन हैं? हे देवताओंमें श्रेष्ठ ! आपको नमस्कार हो। आप प्रसन्न होइये। आदिरूप आपको मैं तत्त्वसे जानना चाहता हूँ; क्योंकि मैं आपकी प्रवृत्तिको नहीं जानता।'),
('5b7f0a71-d246-5bc2-b2ae-60ac4d786e80'::uuid, 'bd507b77-94f3-5d16-9fef-e72b2813779c'::uuid, 'tejomayananda', 'hindi', '।।11.31।। (कृपया) मेरे प्रति कहिये, कि उग्ररूप वाले आप कौन हैं? हे देवों में श्रेष्ठ! आपको नमस्कार है, आप प्रसन्न होइये। आदि स्वरूप आपको मैं (तत्त्व से) जानना चाहता हूँ, क्योंकि आपकी प्रवृत्ति (अर्थात् प्रयोजन को) को मैं नहीं समझ पा रहा हूँ।।
 '),
('d3bc46b2-9153-5c28-ac60-fc0ce6b21e12'::uuid, 'd8c52c70-7894-5309-a0f0-2faff73ab55c'::uuid, 'ramsukhdas', 'hindi', '।।11.32।। श्रीभगवान् बोले -- मैं सम्पूर्ण लोकोंका क्षय करनेवाला बढ़ा हुआ काल हूँ और इस समय मैं इन सब लोगोंका संहार करनेके लिये यहाँ आया हूँ। तुम्हारे प्रतिपक्षमें जो योद्धालोग खड़े हैं, वे सब तुम्हारे युद्ध किये बिना भी नहीं रहेंगे।'),
('60bfc342-8394-527d-9baa-f490f56f1441'::uuid, 'd8c52c70-7894-5309-a0f0-2faff73ab55c'::uuid, 'tejomayananda', 'hindi', '।।11.32।। श्रीभगवान् ने कहा -- मैं लोकों का नाश करने वाला प्रवृद्ध काल हूँ। इस समय, मैं इन लोकों का संहार करने में प्रवृत्त हूँ। जो प्रतिपक्षियों की सेना में स्थित योद्धा हैं, वे सब तुम्हारे बिना भी नहीं रहेंगे।।
 '),
('0de82ba0-b6a9-5b59-9937-f3a73617bddc'::uuid, 'e10174ad-ae31-5050-9a65-15009b027d89'::uuid, 'ramsukhdas', 'hindi', '।।11.33।। इसलिये तुम युद्धके लिये खड़े हो जाओ और यशको प्राप्त करो तथा शत्रुओंको जीतकर धन-धान्यसे सम्पन्न राज्यको भोगो। ये सभी मेरे द्वारा पहलेसे ही मारे हुए हैं। हे सव्यसाचिन् !  तुम निमित्तमात्र बन जाओ।'),
('10232bb4-c5ca-5271-b190-c2c0ddd2ba77'::uuid, 'e10174ad-ae31-5050-9a65-15009b027d89'::uuid, 'tejomayananda', 'hindi', '।।11.33।। इसलिए तुम उठ खड़े हो जाओ और यश को प्राप्त करो; शत्रुओं को जीतकर समृद्ध राज्य को भोगो। ये सब पहले से ही मेरे द्वारा मारे जा चुके हैं। हे सव्यसाचिन्! तुम केवल निमित्त ही बनो।।
 '),
('6e1efbc1-58e0-569e-9978-d56b8ae8ce7e'::uuid, '2c556b1c-9a2f-5d48-8447-5d30303b5a45'::uuid, 'ramsukhdas', 'hindi', '।।11.34।। द्रोण, भीष्म, जयद्रथ और कर्ण तथा अन्य सभी मेरे द्वारा मारे हुए शूरवीरोंको तुम मारो। तुम व्यथा मत करो और युद्ध करो। युद्धमें तुम निःसन्देह वैरियोंको जीतोगे।'),
('eb070f3f-a070-55c0-a4ae-13484c8abc9d'::uuid, '2c556b1c-9a2f-5d48-8447-5d30303b5a45'::uuid, 'tejomayananda', 'hindi', '।।11.34।। द्रोण, भीष्म, जयद्रथ, कर्ण तथा और भी बहुत से मेरे द्वारा मारे गये वीर योद्धाओं को तुम मारो; भय मत करो; युद्ध करो; तुम युद्ध में शत्रुओं को जीतोगे।।
 '),
('4102ab37-ae25-5017-8cd8-acc7292e151f'::uuid, 'c17ed87f-a313-5e74-a6c9-4c3cd47c17a2'::uuid, 'ramsukhdas', 'hindi', '।।11.35।। सञ्जय बोले -- भगवान् केशवका यह वचन सुनकर भयसे कम्पित हुए किरीटी अर्जुन हाथ जोड़कर नमस्कार करके और अत्यन्त भयभीत होकर फिर प्रणाम करके गद्गदं वाणीसे भगवान् कृष्णसे बोले।'),
('81986955-5697-515c-a761-03ec735ab235'::uuid, 'c17ed87f-a313-5e74-a6c9-4c3cd47c17a2'::uuid, 'tejomayananda', 'hindi', '।।11.35।। संजय ने कहा -- केशव भगवान् के इस वचन को सुनकर मुकुटधारी अर्जुन हाथ जोड़े हुए, कांपता हुआ नमस्कार करके पुन: भयभीत हुआ श्रीकृष्ण के प्रति गद्गद् वाणी से बोला।।
 '),
('34ee9daa-d916-53b4-ac25-2f422ad2bbf9'::uuid, '9fbce802-01b7-5c77-8058-daa347063130'::uuid, 'ramsukhdas', 'hindi', '।।11.36।। अर्जुन बोले -- हे अन्तर्यामी भगवन् ! आपके नाम, गुण, लीलाका कीर्तन करनेसे यह सम्पूर्ण जगत् हर्षित हो रहा है और अनुराग(-प्रेम-) को प्राप्त हो रहा है। आपके नाम, गुण आदिके कीर्तनसे भयभीत होकर राक्षसलोग दसों दिशाओंमें भागते हुए जा रहे हैं और सम्पूर्ण सिद्धगण आपको नमस्कार कर रहे हैं। यह सब होना उचित ही है।'),
('068d2fe8-7154-54c1-9f11-04698913fda1'::uuid, '9fbce802-01b7-5c77-8058-daa347063130'::uuid, 'tejomayananda', 'hindi', '।।11.36।। अर्जुन ने कहा -- यह योग्य ही है कि आपके कीर्तन से जगत् अति हर्षित होता है और अनुराग को भी प्राप्त होता है। भयभीत राक्षस लोग समस्त दिशाओं में भागते हैं और समस्त सिद्धगणों के समुदाय आपको नमस्कार करते हैं।।')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('1470c838-1438-518a-a1dd-26cdbb66b461'::uuid, '36fb947c-3533-5367-82f2-df0bc24358c1'::uuid, 'ramsukhdas', 'hindi', '।।11.37।। हे महात्मन् ! गुरुओंके भी गुरु और ब्रह्माके भी आदिकर्ता आपके लिये (वे सिद्धगण) नमस्कार क्यों नहीं करें? क्योंकि हे अनन्त ! हे देवेश ! हे जगन्निवास ! आप अक्षरस्वरूप हैं; आप सत् भी हैं, असत् भी हैं, और सत्-असत् से पर भी जो कुछ है, वह भी आप ही हैं।'),
('712d6f1c-97ec-53b0-bccd-7e7ded275e17'::uuid, '36fb947c-3533-5367-82f2-df0bc24358c1'::uuid, 'tejomayananda', 'hindi', '।।11.37।। हे महात्मन् ! ब्रह्मा के भी आदि कर्ता और सबसे श्रेष्ठ आपके लिए वे कैसे नमस्कार नहीं करें? (क्योंकि) हे अनन्त! हे देवेश! हे जगन्निवास! जो सत् असत् और इन दोनों से परे अक्षरतत्त्व है, वह आप ही हैं।।
 '),
('eba15749-a2ef-51ac-afb3-a1f5bcf31f61'::uuid, '3c57efa3-e4b2-5a85-a51c-fab9ebaa3a16'::uuid, 'ramsukhdas', 'hindi', '।।11.38।। आप ही आदिदेव और पुराणपुरुष हैं तथा आप ही इस संसारके परम आश्रय हैं। आप ही सबको जाननेवाले, जाननेयोग्य और परमधाम हैं। हे अनन्तरूप ! आपसे ही सम्पूर्ण संसार व्याप्त है।'),
('5979e0fe-9a55-5c05-9276-05d6b92e0c6e'::uuid, '3c57efa3-e4b2-5a85-a51c-fab9ebaa3a16'::uuid, 'tejomayananda', 'hindi', '।।11.38।। आप आदिदेव और पुराण (सनातन) पुरुष हैं। आप इस जगत् के परम आश्रय, ज्ञाता, ज्ञेय, (जानने योग्य) और परम धाम हैं। हे अनन्तरूप आपसे ही यह विश्व व्याप्त है।।
 '),
('cd7a6709-ff7f-553e-a3b3-c2b779233f8e'::uuid, '72ece883-3e44-5692-95b5-c801e9590684'::uuid, 'ramsukhdas', 'hindi', '।।11.39।। आप ही वायु, यमराज, अग्नि, वरुण, चन्द्रमा, दक्ष आदि प्रजापति और प्रपितामह (ब्रह्माजीके भी पिता) हैं। आपको हजारों बार नमस्कार हो! नमस्कार हो ! ! और फिर भी आपको बार-बार नमस्कार हो ! नमस्कार हो !'),
('2489e63e-e195-5bed-8ecf-cabcfb265708'::uuid, '72ece883-3e44-5692-95b5-c801e9590684'::uuid, 'tejomayananda', 'hindi', '।।11.39।। आप वायु, यम, अग्नि, वरुण, चन्द्रमा, प्रजापति (ब्रह्मा) और प्रपितामह (ब्रह्मा के भी कारण) हैं; आपके लिए सहस्र बार नमस्कार, नमस्कार है, पुन: आपको बारम्बार नमस्कार, नमस्कार है।।
 '),
('20d446a8-0f5f-58ec-8b2c-4a1d6279ea90'::uuid, '5183d7fc-6a36-584c-840f-dec8ab821965'::uuid, 'ramsukhdas', 'hindi', '।।11.40।। हे सर्व ! आपको आगेसे भी नमस्कार हो !  पीछेसे भी नमस्कार हो ! सब ओरसे ही नमस्कार हो ! हे अनन्तवीर्य ! अमित विक्रमवाले आपने सबको समावृत कर रखा है; अतः सब कुछ आप ही हैं।'),
('a4de470c-cb4d-595e-96f7-be201011e0b3'::uuid, '5183d7fc-6a36-584c-840f-dec8ab821965'::uuid, 'tejomayananda', 'hindi', '।।11.40।। हे अनन्तसार्मथ्य वाले भगवन्! आपके लिए अग्रत: और पृष्ठत: नमस्कार है, हे सर्वात्मन्! आपको सब ओर से नमस्कार है। आप अमित विक्रमशाली हैं और आप सबको व्याप्त किये हुए हैं, इससे आप सर्वरूप हैं।।
 '),
('9d37cd84-2ec1-5d2c-a3be-53852c6569ee'::uuid, '507b156b-d4b6-5d84-9ab9-7b50ae3bbdbf'::uuid, 'ramsukhdas', 'hindi', '।।11.41 -- 11.42।। आपकी महिमा और स्वरूपको न जानते हुए ''मेरे सखा हैं'' ऐसा मानकर मैंने प्रमादसे अथवा प्रेमसे हठपूर्वक (बिना सोचे-समझे) ''हे कृष्ण ! हे यादव ! हे सखे !'' इस प्रकार जो कुछ कहा है; और हे अच्युत ! हँसी-दिल्लगीमें, चलते-फिरते, सोते-जागते, उठते-बैठते, खाते-पीते समयमें अकेले अथवा उन सखाओं, कुटुम्बियों आदिके सामने मेरे द्वारा आपका जो कुछ तिरस्कार किया गया है;  वह सब अप्रमेयस्वरुप आपसे मैं क्षमा माँगता हूँ।'),
('8ce924ec-3043-5f60-88c0-da9b685eb3cb'::uuid, '507b156b-d4b6-5d84-9ab9-7b50ae3bbdbf'::uuid, 'tejomayananda', 'hindi', '।।11.41।। हे भगवन्! आपको सखा मानकर आपकी इस महिमा को न जानते हुए मेरे द्वारा प्रमाद से अथवा प्रेम से भी "हे कृष्ण हे! यादव हे सखे!" इस प्रकार जो कुछ बलात् कहा गया है।।
 '),
('cd741fea-b4fe-5833-b7ce-0fd5c71a4cb5'::uuid, 'a9beb7a3-faee-52fd-b68c-f425a866141a'::uuid, 'ramsukhdas', 'hindi', '।।11.41 -- 11.42।। आपकी  महिमा और स्वरूपको न जानते हुए ''मेरे सखा हैं'' ऐसा मानकर मैंने प्रमादसे अथवा प्रेमसे भी हठपूर्वक (बिना सोचे-समझे) ''हे कृष्ण ! हे यादव ! हे सखे !'' इस प्रकार जो कुछ कहा है; और हे अच्युत ! हँसी-दिल्लगीमें, चलते-फिरते, सोते-जागते, उठते-बैठते, खाते-पीते समयमें अकेले अथवा उन सखाओं, कुटुम्बियों आदिके सामने मेरे द्वारा आपका जो कुछ तिरस्कार किया गया है, वह सब अप्रमेस्वरूप आपसे मैं क्षमा करवाता हूँ ।'),
('bba4d144-14a1-5ef0-b2ff-31b1ec70ac08'::uuid, 'a9beb7a3-faee-52fd-b68c-f425a866141a'::uuid, 'tejomayananda', 'hindi', '।।11.42।। और, हे अच्युत! जो आप मेरे द्वारा हँसी के लिये बिहार, शय्या, आसन और भोजन के समय अकेले में अथवा अन्यों के समक्ष भी अपमानित किये गये हैं, उन सब के लिए अप्रमेय स्वरूप आप से मैं क्षमायाचना करता हूँ।।
 '),
('b2259cf2-94bb-5798-addb-c472d34aa24f'::uuid, '70f5118b-e116-5215-95a3-9d8cfeace4c9'::uuid, 'ramsukhdas', 'hindi', '।।11.43।। आप ही इस चराचर संसारके पिता हैं, आप ही पूजनीय हैं और आप ही गुरुओंके महान् गुरु हैं। हे अनन्त प्रभावशाली भगवन् ! इस त्रिलोकीमें आपके समान भी दूसरा कोई नहीं है, फिर अधिक तो हो ही कैसे सकता है !'),
('c701a418-8605-5810-9f81-1acb81d6caed'::uuid, '70f5118b-e116-5215-95a3-9d8cfeace4c9'::uuid, 'tejomayananda', 'hindi', '।।11.43।। आप इस चराचर जगत् के पिता, पूजनीय और सर्वश्रेष्ठ गुरु हैं। हे अप्रितम प्रभाव वाले भगवन्! तीनों लोकों में आपके समान भी कोई नहीं हैं, तो फिर आपसे अधिक श्रेष्ठ कैसे होगा?।।
 '),
('61e531dd-03cd-5f43-a90a-05f8a2d8c5d2'::uuid, '419ca3cb-346d-5899-8862-253260a9d64d'::uuid, 'ramsukhdas', 'hindi', '।।11.44।। इसलिये शरीरसे लम्बा पड़कर स्तुति करनेयोग्य आप ईश्वरको मैं प्रणाम करके प्रसन्न करना चाहता हूँ। जैसे पिता पुत्रके, मित्र मित्रके और पति पत्नीके अपमानको सह लेता है, ऐसे ही हे देव ! आप मेरे द्वारा किया गया अपमान सहनेमें समर्थ हैं।'),
('7e49f3b0-cdc4-544f-beb2-9986ec179fa1'::uuid, '419ca3cb-346d-5899-8862-253260a9d64d'::uuid, 'tejomayananda', 'hindi', '।।11.44।। इसलिये हे भगवन्! मैं शरीर के द्वारा साष्टांग प्रणिपात करके स्तुति के योग्य आप ईश्वर को प्रसन्न होने के लिये प्रार्थना करता हूँ। हे देव! जैसे पिता पुत्र के, मित्र अपने मित्र के और प्रिय अपनी प्रिया के(अपराध को क्षमा करता है), वैसे ही आप भी मेरे अपराधों को क्षमा कीजिये।।
 '),
('c207f315-32d5-5764-af09-4ead46e1e72e'::uuid, '0b1622f1-1deb-5c1f-a72d-cd6f7baa924e'::uuid, 'ramsukhdas', 'hindi', '।।11.45।। मैंने ऐसा रुप पहले कभी नहीं देखा। इस रूपको देखकर मैं हर्षित हो रहा हूँ और (साथ-ही-साथ) भयसे मेरा मन अत्यन्त व्यथित हो रहा है। अतः आप मुझे अपने उसी देवरूपको (सौम्य विष्णुरूपको)  दिखाइये। हे देवेश ! हे जगन्निवास ! आप प्रसन्न होइये।'),
('1504aec9-b9f6-51a1-b5d1-f7d417e9605a'::uuid, '0b1622f1-1deb-5c1f-a72d-cd6f7baa924e'::uuid, 'tejomayananda', 'hindi', '।।11.45।। मैं आपके इस अदृष्टपूर्व रूप को देखकर हर्षित हो रहा हूँ और मेरा मन भय से अतिव्याकुल भी हो रहा हैं। इसलिए हे देव! आप उस पूर्वकाल को ही मुझे दिखाइये। हे देवेश! हे जगन्निवास! आप प्रसन्न होइये।।
 '),
('1b4d71b3-ba2a-548b-bf5a-fb798fbe4610'::uuid, 'b9169044-c90a-53d0-ad81-c69e3826f833'::uuid, 'ramsukhdas', 'hindi', '।।11.46।।  मैं आपको वैसे ही किरीटधारी, गदाधारी और हाथमें चक्र लिये हुए देखना चाहता हूँ। इसलिये हे सहस्रबाहो ! हे विश्वमूर्ते ! आप उसी चतुर्भुजरूपसे हो जाइये।'),
('46221804-3a96-5bcb-ac36-314e7e6cf2a6'::uuid, 'b9169044-c90a-53d0-ad81-c69e3826f833'::uuid, 'tejomayananda', 'hindi', '।।11.46।। मैं आपको उसी प्रकार मुकुटधारी, गदा और चक्र हाथ में लिए हुए देखना चाहता हूँ। हे विश्वमूर्ते! हे सहस्रबाहो! आप उस चतुर्भुजरूप के ही बन जाइए।।
 '),
('adc03dd0-1ef5-5374-bd58-c0e8f75af0c5'::uuid, '6ed28195-eb9d-5603-a951-8dfb26a5614d'::uuid, 'ramsukhdas', 'hindi', '।।11.47।। श्रीभगवान् बोले -- हे अर्जुन ! मैंने प्रसन्न होकर अपनी सामर्थ्यसे यह अत्यन्त श्रेष्ठ, तेजोमय, सबका आदि और अनन्त विश्वरूप तुझे दिखाया है, जिसको तुम्हारे सिवाय पहले किसीने नहीं देखा है।'),
('c89272fd-3f5c-5b75-84e6-91c733ebe1c4'::uuid, '6ed28195-eb9d-5603-a951-8dfb26a5614d'::uuid, 'tejomayananda', 'hindi', '।।11.47।। हे अर्जुन! तुम पर प्रसन्न होकर मैंने अपनी योगशक्ति (आत्मयोगात्) के प्रभाव से यह अपना परम तेजोमय, सबका आदि और अनन्त विश्वरूप तुझे दर्शाया है, जिसे तुम्हारे पूर्व किसी ने नहीं देखा है।।
 '),
('a20e019b-14e1-5234-8f67-9cae842f33a0'::uuid, 'f7f2490b-e367-5eb8-8ca1-9cc7433265a5'::uuid, 'ramsukhdas', 'hindi', '।।11.48।। हे कुरुप्रवीर! मनुष्यलोकमें इस प्रकारके विश्वरूपवाला मैं न वेदोंके पढ़नेसे, न यज्ञोंके अनुष्ठानसे, न दानसे, न उग्र तपोंसे और न मात्र क्रियाओंसे तेरे (कृपापात्रके) सिवाय और किसीके द्वारा देखा जाना शक्य हूँ।'),
('1e44ae0a-20a9-5c87-aa86-889ffe1f929b'::uuid, 'f7f2490b-e367-5eb8-8ca1-9cc7433265a5'::uuid, 'tejomayananda', 'hindi', '।।11.48।। हे कुरुप्रवीर! तुम्हारे अतिरिक्त इस मनुष्य लोक में किसी अन्य के द्वारा मैं इस रूप में, न वेदाध्ययन और न यज्ञ, न दान और न (धार्मिक) क्रियायों के द्वारा और न उग्र तपों के द्वारा ही देखा जा सकता हूँ।।
 '),
('854c50f5-ab81-50bb-8f57-d349a76eed10'::uuid, 'b4c8a0ce-7c71-5d0b-a6dd-75af2230647b'::uuid, 'ramsukhdas', 'hindi', '।।11.49।। यह इस प्रकारका मेरा घोररूप देखकर तेरेको व्यथा नहीं होनी चाहिये और मूढ़भाव भी नहीं होना चाहिये। अब निर्भय और प्रसन्न मनवाला होकर तू फिर उसी मेरे इस (चतुर्भुज) रूपको अच्छी तरह देख ले।'),
('48a7f44c-610f-5db1-a1af-034f61233431'::uuid, 'b4c8a0ce-7c71-5d0b-a6dd-75af2230647b'::uuid, 'tejomayananda', 'hindi', '।।11.49।। इस प्रकार मेरे इस घोर रूप को देखकर तुम व्यथा और मूढ़भाव को मत प्राप्त हो। निर्भय और प्रसन्नचित्त होकर तुम पुन: मेरे उसी (पूर्व के) रूप को देखो।।
 '),
('008772b9-086f-5e65-9dc6-da312eec6e59'::uuid, '95c8c7b8-4512-54b0-9268-961973d087b0'::uuid, 'ramsukhdas', 'hindi', '।।11.50।। सञ्जय बोले -- वासुदेवभगवान् ने अर्जुनसे ऐसा कहकर फिर उसी प्रकारसे अपना रूप (देवरूप) दिखाया और महात्मा श्रीकृष्णने पुनः सौम्यवपु (द्विभुजरूप) होकर इस भयभीत अर्जुनको आश्वासन दिया।'),
('f8fbee6b-4b95-5068-a009-f8c93d48034b'::uuid, '95c8c7b8-4512-54b0-9268-961973d087b0'::uuid, 'tejomayananda', 'hindi', '।।11.50।। संजय ने कहा -- भगवान् वासुदेव ने अर्जुन से इस प्रकार कहकर, पुन: अपने (पूर्व) रूप को दर्शाया, और फिर, सौम्यरूप महात्मा श्रीकृष्ण ने इस भयभीत अर्जुन को आश्वस्त किया।।
 '),
('d8cce625-cba5-53ec-a2da-ada7ed82cd02'::uuid, 'd14e4c70-7b12-54d7-a3e4-727e0ef42eb0'::uuid, 'ramsukhdas', 'hindi', '।।11.51।। अर्जुन बोले -- हे जनार्दन ! आपके इस सौम्य मनुष्यरूपको देखकर मैं इस समय स्थिरचित्त हो गया हूँ और अपनी स्वाभाविक स्थितिको प्राप्त हो गया हूँ।'),
('8dba8fa5-bbc6-548f-b912-9ba479eae17b'::uuid, 'd14e4c70-7b12-54d7-a3e4-727e0ef42eb0'::uuid, 'tejomayananda', 'hindi', '।।11.51।। अर्जुन ने कहा -- हे जनार्दन! आपके इस सौम्य मनुष्य रूप को देखकर अब मैं शांतचित्त हुआ अपने स्वभाव को प्राप्त हो गया हूँ।।
 '),
('aaf16268-cf7c-5d40-8d13-fde35e01faa6'::uuid, '99d77227-ae68-5f59-87c1-7ef93bf4248f'::uuid, 'ramsukhdas', 'hindi', '।।11.52।। श्रीभगवान् बोले -- मेरा यह जो रूप तुमने देखा है, इसके दर्शन अत्यन्त ही दुर्लभ हैं। इस रूपको देखनेके लिये देवता भी नित्य लालायित रहते हैं।'),
('b2ac1f32-957b-54a5-93ae-60750bd09a15'::uuid, '99d77227-ae68-5f59-87c1-7ef93bf4248f'::uuid, 'tejomayananda', 'hindi', '।।11.52।। श्रीभगवान् ने कहा -- मेरा यह रूप देखने को मिलना अति दुर्लभ है, जिसको कि तुमने देखा है। देवतागण भी सदा इस रूप के दर्शन के इच्छुक रहते हैं।।
 '),
('7caa79cc-19e0-5a7a-8574-489c13adf711'::uuid, '0ead38a2-056d-5f6c-b74a-f868d9da38b2'::uuid, 'ramsukhdas', 'hindi', '।।11.53।। जिस प्रकार तुमने मुझे देखा है, इस प्रकारका (चतुर्भुजरूपवाला) मैं न तो वेदोंसे, न तपसे, न दानसे और न यज्ञसे ही देखा जा सकता हूँ।'),
('de3fe483-91a9-55c3-9ccc-1dfef347d682'::uuid, '0ead38a2-056d-5f6c-b74a-f868d9da38b2'::uuid, 'tejomayananda', 'hindi', '।।11.53।। न वेदों से, न तप से, न दान से और न यज्ञ से ही मैं इस प्रकार देखा जा सकता हूँ, जैसा कि तुमने मुझे देखा है।।
 '),
('f2f8b0b5-da01-5b5e-8309-2bae36528ad7'::uuid, '50560950-f300-5572-8bee-8f9b55023a5b'::uuid, 'ramsukhdas', 'hindi', '।।11.54।। परन्तु हे शत्रुतापन अर्जुन ! इस प्रकार (चतुर्भुजरूपवाला) मैं अनन्यभक्तिसे ही तत्त्वसे जाननेमें, सगुणरूपसे देखनेमें और प्राप्त करनेमें शक्य हूँ।'),
('468c7c64-bf30-53f4-9d4f-3ad01a3e512d'::uuid, '50560950-f300-5572-8bee-8f9b55023a5b'::uuid, 'tejomayananda', 'hindi', '।।11.54।। परन्तु हे परन्तप अर्जुन! अनन्य भक्ति के द्वारा मैं तत्त्वत: ''जानने'', ''देखने'' और ''प्रवेश'' करने के लिए (एकी भाव से प्राप्त होने के लिए) भी, शक्य हूँ!।।
 '),
('4c155975-d155-52a7-b626-f3eda8fa481d'::uuid, '1a17483b-4df1-5687-9a7b-f16b81db02d6'::uuid, 'ramsukhdas', 'hindi', '।।11.55।। हे पाण्डवन ! जो मेरे लिये ही कर्म करनेवाला, मेरे ही परायण और मेरा ही भक्त है तथा सर्वथा आसक्तिरहित और प्राणिमात्रके साथ निर्वैर है, वह भक्त मेरेको प्राप्त होता है।'),
('f0161a8e-13b8-5c42-8955-482d7b058dd1'::uuid, '1a17483b-4df1-5687-9a7b-f16b81db02d6'::uuid, 'tejomayananda', 'hindi', '।।11.55।। हे पाण्डव! जो पुरुष मेरे लिए ही कर्म करने वाला है, और मुझे ही परम लक्ष्य मानता है, जो मेरा भक्त है तथा संगरहित है, जो भूतमात्र के प्रति निर्वैर है, वह मुझे प्राप्त होता है।।'),
('a290b477-efc8-5ae0-9eef-21c6e80374e7'::uuid, '5cb373d4-b326-597d-9896-4f3368ed11bc'::uuid, 'ramsukhdas', 'hindi', '।।12.1।।जो भक्त इस प्रकार निरन्तर आपमें लगे रहकर आप-(सगुण भगवान्-) की उपासना करते हैं और जो अविनाशी निराकारकी ही उपासना करते हैं, उनमेंसे उत्तम योगवेत्ता कौन हैं?'),
('68983bc1-5910-580a-9a4d-6cc53ff6d520'::uuid, '5cb373d4-b326-597d-9896-4f3368ed11bc'::uuid, 'tejomayananda', 'hindi', '।।12.1।। अर्जुन ने कहा -- जो भक्त, सतत युक्त होकर इस (पूर्वोक्त) प्रकार से आपकी उपासना करते हैं और जो भक्त अक्षर, और अव्यक्त की उपासना करते हैं, उन दोनों में कौन उत्तम योगवित् है।।
 '),
('1346f43a-8791-5d10-a6dc-2e326a63b6f8'::uuid, '8209192a-dbcf-591b-b9e0-2877f6c6ed92'::uuid, 'ramsukhdas', 'hindi', '।।12.2।।मेरेमें मनको लगाकर नित्य-निरन्तर मेरेमें लगे हुए जो भक्त परम श्रद्धासे युक्त होकर मेरी उपासना करते हैं, वे मेरे मतमें सर्वश्रेष्ठ योगी हैं।'),
('cd03f450-66c6-511b-a587-0e56c345e5f4'::uuid, '8209192a-dbcf-591b-b9e0-2877f6c6ed92'::uuid, 'tejomayananda', 'hindi', '।।12.2।। श्रीभगवान् ने कहा -- मुझमें मन को एकाग्र करके नित्ययुक्त हुए जो भक्तजन परम श्रद्धा से युक्त होकर मेरी उपासना करते हैं, वे, मेरे मत से, युक्ततम हैं अर्थात् श्रेष्ठ हैं।।
 '),
('df93b02e-0638-5b28-92f2-4b092279990c'::uuid, '686c7422-99fa-5a8c-920d-d775fda753d3'::uuid, 'ramsukhdas', 'hindi', '।।12.3।।जो अपनी इन्द्रियोंको वशमें करके अचिन्त्य, सब जगह परिपूर्ण, अनिर्देश्य, कूटस्थ, अचल, ध्रुव, अक्षर और अव्यक्तकी उपासना करते हैं, वे प्राणिमात्रके हितमें रत और सब जगह समबुद्धिवाले मनुष्य मुझे ही प्राप्त होते हैं।'),
('9778e0b9-8874-5387-ac79-38f819c3b13f'::uuid, '686c7422-99fa-5a8c-920d-d775fda753d3'::uuid, 'tejomayananda', 'hindi', '।।12.3।। परन्तु जो भक्त अक्षर ,अनिर्देश्य, अव्यक्त, सर्वगत, अचिन्त्य, कूटस्थ, अचल और ध्रुव की उपासना करते हैं।।
 '),
('e9be2c11-de5c-5d3b-8cb2-81ff5f395f63'::uuid, 'd6a36d9f-78dc-5610-97be-4c0756c3c0b2'::uuid, 'ramsukhdas', 'hindi', '।।12.4।।जो अपनी इन्द्रियोंको वशमें करके अचिन्त्य, सब जगह परिपूर्ण, अनिर्देश्य, कूटस्थ, अचल, ध्रुव, अक्षर और अव्यक्तकी उपासना करते हैं, वे प्राणिमात्रके हितमें रत और सब जगह समबुद्धिवाले मनुष्य मुझे ही प्राप्त होते हैं।'),
('647afc59-5366-5afb-91bd-74b7d1fa46d5'::uuid, 'd6a36d9f-78dc-5610-97be-4c0756c3c0b2'::uuid, 'tejomayananda', 'hindi', '।।12.4।। इन्द्रिय समुदाय को सम्यक् प्रकार से नियमित करके, सर्वत्र समभाव वाले, भूतमात्र के हित में रत वे भक्त मुझे ही प्राप्त होते हैं।।
 '),
('6a701af7-65b4-52c2-b716-e77b7abed479'::uuid, '579f4b38-2ad4-5f54-b09d-78a3ab3550d2'::uuid, 'ramsukhdas', 'hindi', '।।12.5।।अव्यक्तमें आसक्त चित्तवाले उन साधकोंको (अपने साधनमें) कष्ट अधिक होता है; क्योंकि देहाभिमानियोंके द्वारा अव्यक्त-विषयक गति कठिनतासे प्राप्त की जाती है।'),
('7c1e7539-e4ae-580f-bd98-39519d7542c7'::uuid, '579f4b38-2ad4-5f54-b09d-78a3ab3550d2'::uuid, 'tejomayananda', 'hindi', '।।12.5।। परन्तु उन अव्यक्त में आसक्त हुए चित्त वाले पुरुषों को क्लेश अधिक होता है, क्योंकि देहधारियों से अव्यक्त की गति कठिनाईपूर्वक प्राप्त की जाती है।।
 '),
('8aebcdfc-a204-59a5-ba6e-3c0af510f272'::uuid, '0a2b22d9-aecb-5774-9032-a79648cafb3b'::uuid, 'ramsukhdas', 'hindi', '।।12.6।।परन्तु जो कर्मोंको मेरे अर्पण करके और मेरे परायण होकर अनन्ययोगसे मेरा ही ध्यान करते हुए मेरी उपासना करते हैं।'),
('764d6bb1-594a-578b-ad51-3aba957e6474'::uuid, '0a2b22d9-aecb-5774-9032-a79648cafb3b'::uuid, 'tejomayananda', 'hindi', '।।12.6।। परन्तु जो भक्तजन मुझे ही परम लक्ष्य समझते हुए सब कर्मों को मुझे अर्पण करके अनन्ययोग के द्वारा मेरा (सगुण का) ही ध्यान करते हैं।।'),
('396a9455-63ff-5139-9673-0141d7940ad4'::uuid, '67e5f4ad-737f-5979-8ef3-64014b903963'::uuid, 'ramsukhdas', 'hindi', '।।12.7।।हे पार्थ ! मेरेमें आविष्ट चित्तवाले उन भक्तोंका मैं मृत्युरूप संसार-समुद्रसे शीघ्र ही उद्धार करनेवाला बन जाता हूँ।'),
('a399d4da-c204-5056-9d98-8dcf216b765c'::uuid, '67e5f4ad-737f-5979-8ef3-64014b903963'::uuid, 'tejomayananda', 'hindi', '।।12.7।। हे पार्थ ! जिनका चित्त मुझमें ही स्थिर हुआ है ऐसे भक्तों का मैं शीघ्र ही मृत्युरूप संसार सागर से उद्धार करने वाला होता हूँ।।
 '),
('0961928c-c15f-5691-86f4-6599ebef0d77'::uuid, '18a70a01-bf31-5b20-974d-9eb9a2551d2d'::uuid, 'ramsukhdas', 'hindi', '।।12.8।।तू मेरेमें मनको लगा और मेरेमें ही बुद्धिको लगा; इसके बाद तू मेरेमें ही निवास करेगा -- इसमें संशय नहीं है।'),
('850bc1a3-11a8-500c-9122-e02e30d261d5'::uuid, '18a70a01-bf31-5b20-974d-9eb9a2551d2d'::uuid, 'tejomayananda', 'hindi', '।।12.8।। तुम अपने मन और बुद्धि को मुझमें ही स्थिर करो, तदुपरान्त तुम मुझमें ही निवास करोगे, इसमें कोई संशय नहीं है।।
 '),
('d0ae6188-1c88-57d5-b131-ce3b821a83b9'::uuid, '6ef0f631-b1c8-5809-96f3-33ee56f47a55'::uuid, 'ramsukhdas', 'hindi', '।।12.9।।अगर तू मनको मेरेमें अचलभावसे स्थिर (अर्पण) करनेमें समर्थ नहीं है, तो हे धनञ्जय ! अभ्यासयोगके द्वारा तू मेरी प्राप्तिकी इच्छा कर।'),
('1e327842-4657-5670-bbc9-5be70a8dafb3'::uuid, '6ef0f631-b1c8-5809-96f3-33ee56f47a55'::uuid, 'tejomayananda', 'hindi', '।।12.9।। हे धनंजय ! यदि तुम अपने मन को मुझमें स्थिर करने में समर्थ नहीं हो, तो अभ्यासयोग के द्वारा तुम मुझे प्राप्त करने की इच्छा (अर्थात् प्रयत्न) करो।।
 '),
('71db812b-3451-5e97-9cdb-c4d6868468ab'::uuid, '5deb16c4-4ee5-5bf4-a8b0-ba44108c0633'::uuid, 'ramsukhdas', 'hindi', '।।12.10।।अगर तू अभ्यास-(योग-) में भी असमर्थ है, तो मेरे लिये कर्म करनेके परायण हो जा। मेरे लिये कर्मोंको करता हुआ भी तू सिद्धिको प्राप्त हो जायगा।'),
('217a55df-658d-5ece-adfc-98ed834835a7'::uuid, '5deb16c4-4ee5-5bf4-a8b0-ba44108c0633'::uuid, 'tejomayananda', 'hindi', '।।12.10।। यदि तुम अभ्यास में भी असमर्थ हो तो मत्कर्म परायण बनो; इस प्रकार मेरे लिए कर्मों को करते हुए भी तुम सिद्धि को प्राप्त करोगे।।
 '),
('39c2e719-875a-51a0-a126-5996aa1b923a'::uuid, 'da0bd3d1-5dbb-553e-a45e-8d1fd05111c3'::uuid, 'ramsukhdas', 'hindi', '।।12.11।।अगर मेरे योग-(समता-) के आश्रित हुआ तू इस(पूर्वश्लोकमें कहे गये साधन-) को भी करनेमें असमर्थ है, तो मन-इन्द्रियोंको वशमें करके सम्पूर्ण कर्मोंके फलका त्याग कर।'),
('a8e2b8e4-a5d2-54c2-a6cb-bd20eb2bc1b0'::uuid, 'da0bd3d1-5dbb-553e-a45e-8d1fd05111c3'::uuid, 'tejomayananda', 'hindi', '।।12.11।। और यदि इसको भी करने के लिए तुम असमर्थ हो, तो आत्मसंयम से युक्त होकर मेरी प्राप्ति रूप योग का आश्रय लेकर, तुम समस्त कर्मों के फल का त्याग करो।।
 '),
('f8ff0e07-2560-5aaf-9b0c-b344da0da66e'::uuid, 'bf12ad55-b500-5f2c-932d-ade38a585961'::uuid, 'ramsukhdas', 'hindi', '।।12.12।।अभ्याससे शास्त्रज्ञान श्रेष्ठ है, शास्त्रज्ञानसे ध्यान श्रेष्ठ है और ध्यानसे भी सब कर्मोंके फलका त्याग श्रेष्ठ है। कर्मफलत्यागसे तत्काल ही परमशान्ति प्राप्त हो जाती है।'),
('92fb0626-1e06-59c6-b50c-ee94074eba3f'::uuid, 'bf12ad55-b500-5f2c-932d-ade38a585961'::uuid, 'tejomayananda', 'hindi', '।।12.12।। अभ्यास से ज्ञान श्रेष्ठ है; ज्ञान से श्रेष्ठ ध्यान है और ध्यान से भी श्रेष्ठ कर्मफल त्याग है त्याग; से तत्काल ही शान्ति मिलती है।।
 '),
('3e919373-a9d5-5c57-a7f5-12033082bc2f'::uuid, 'f436e2e9-c483-579a-aa80-ca9bf18c84e0'::uuid, 'ramsukhdas', 'hindi', '।।12.13।।सब प्राणियोंमें द्वेषभावसे रहित, सबका मित्र (प्रेमी) और दयालु, ममतारहित, अहंकाररहित, सुखदुःखकी प्राप्तिमें सम, क्षमाशील, निरन्तर सन्तुष्ट, योगी, शरीरको वशमें किये हुए, दृढ़ निश्चयवाला? मेरेमें अर्पित मनबुद्धिवाला जो मेरा भक्त है, वह मेरेको प्रिय है।'),
('8f96c549-2612-5bf1-be00-a373e9756100'::uuid, 'f436e2e9-c483-579a-aa80-ca9bf18c84e0'::uuid, 'tejomayananda', 'hindi', '।।12.13।। भूतमात्र के प्रति जो द्वेषरहित है तथा सबका मित्र तथा करुणावान् है; जो ममता और अहंकार से रहित, सुख और दु:ख में सम और क्षमावान् है।।
 '),
('0b0aaeec-f826-53d3-a2c8-94b017b0a0a7'::uuid, '8348abef-4e59-5cf9-893d-de6e33e3aef7'::uuid, 'ramsukhdas', 'hindi', '।।12.14।।सब प्राणियोंमें द्वेषभावसे रहित, सबका मित्र (प्रेमी) और दयालु, ममतारहित, अहंकाररहित, सुखदुःखकी प्राप्तिमें सम, क्षमाशील, निरन्तर सन्तुष्ट,योगी, शरीरको वशमें किये हुए, दृढ़ निश्चयवाला, मेरेमें अर्पित मन-बुद्धिवाला जो मेरा भक्त है, वह मेरेको प्रिय है।'),
('6558a980-dfa4-5956-b8a9-72c995416b5b'::uuid, '8348abef-4e59-5cf9-893d-de6e33e3aef7'::uuid, 'tejomayananda', 'hindi', '।।12.14।। जो संयतात्मा, दृढ़निश्चयी योगी सदा सन्तुष्ट है, जो अपने मन और बुद्धि को मुझमें अर्पण किये हुए है, जो ऐसा मेरा भक्त है, वह मुझे प्रिय है।।
 '),
('b1f6fbb2-f898-5053-9121-9d83710e37c4'::uuid, '89c6ed3c-4eb2-53a3-b770-cf9debcfc3b2'::uuid, 'ramsukhdas', 'hindi', '।।12.15।।जिससे किसी प्राणीको उद्वेग नहीं होता और जिसको खुद भी किसी प्राणीसे उद्वेग नहीं होता तथा जो हर्ष, अमर्ष (ईर्ष्या), भय और उद्वेगसे रहित है, वह मुझे प्रिय है।'),
('9e15f088-89c7-56c0-8afe-13ca51d2805a'::uuid, '89c6ed3c-4eb2-53a3-b770-cf9debcfc3b2'::uuid, 'tejomayananda', 'hindi', '।।12.15।। जिससे कोई लोक (अर्थात् जीव, व्यक्ति) उद्वेग को प्राप्त नहीं होता और जो स्वयं भी किसी व्यक्ति से उद्वेग अनुभव नहीं करता तथा जो हर्ष, अमर्ष (असहिष्णुता) भय और उद्वेगों से मुक्त है,वह भक्त मुझे प्रिय है।।
 '),
('6b66c016-d809-572f-b0bf-7e91f296cf17'::uuid, '0290ea0a-4d78-5d22-9394-d5a449123cdc'::uuid, 'ramsukhdas', 'hindi', '।।12.16।।जो आकाङ्क्षासे रहित, बाहर-भीतरसे पवित्र, दक्ष, उदासीन, व्यथासे रहित और सभी आरम्भोंका अर्थात् नये-नये कर्मोंके आरम्भका सर्वथा त्यागी है, वह मेरा भक्त मुझे प्रिय है।'),
('46ed857d-019e-5422-a937-1c9209166a3f'::uuid, '0290ea0a-4d78-5d22-9394-d5a449123cdc'::uuid, 'tejomayananda', 'hindi', '।।12.16।। जो अपेक्षारहित, शुद्ध, दक्ष, उदासीन, व्यथारहित और सर्वकर्मों का संन्यास करने वाला मेरा भक्त है, वह मुझे प्रिय है।।
 '),
('5b129d70-b9bc-5ffb-8b82-7c82fc3e50e9'::uuid, '7d5546bd-b4f0-53e6-be61-9de2239d80a6'::uuid, 'ramsukhdas', 'hindi', '।।12.17।।जो न कभी हर्षित होता है, न द्वेष करता है, न शोक करता है, न कामना करता है और जो शुभ-अशुभ कर्मोंमें राग-द्वेषका त्यागी है, वह भक्तिमान् मनुष्य मुझे प्रिय है।'),
('5d538645-c20d-5ff7-8976-9ffa17515557'::uuid, '7d5546bd-b4f0-53e6-be61-9de2239d80a6'::uuid, 'tejomayananda', 'hindi', '।।12.17।। जो न हर्षित होता है और न द्वेष करता है; न शोक करता है और न आकांक्षा; तथा जो शुभ और अशुभ को त्याग देता है, वह भक्तिमान् पुरुष मुझे प्रिय है।।
 '),
('753ff461-5081-58d9-a7cb-ab5fcf9ee25b'::uuid, 'c8be94c2-6220-5c29-9ebf-3adf9ddd4e58'::uuid, 'ramsukhdas', 'hindi', '।।12.18।।जो शत्रु और मित्रमें तथा मान-अपमानमें सम है और शीत-उष्ण (अनुकूलता-प्रतिकूलता) तथा सुख-दुःखमें सम है एवं आसक्तिसे रहित है, और जो निन्दास्तुतिको समान समझनेवाला, मननशील, जिस-किसी प्रकारसे भी (शरीरका निर्वाह होनेमें) संतुष्ट, रहनेके स्थान तथा शरीरमें ममता-आसक्तिसे रहित और स्थिर बुद्धिवाला है, वह भक्तिमान् मनुष्य मुझे प्रिय है।'),
('e1a74989-7367-5012-8f14-9888d3bdad3e'::uuid, 'c8be94c2-6220-5c29-9ebf-3adf9ddd4e58'::uuid, 'tejomayananda', 'hindi', '।।12.18।। जो पुरुष शत्रु और मित्र में तथा मान और अपमान में सम है; जो शीत-उष्ण व सुखदु:खादिक द्वन्द्वों में सम है और आसक्ति रहित है।।
 '),
('12221b43-7afe-5017-8cff-392214f86872'::uuid, 'ef8ab183-dc1a-5bbb-8a67-8718aa926bb8'::uuid, 'ramsukhdas', 'hindi', '।।12.19।।जो शत्रु और मित्रमें तथा मान-अपमानमें सम है और शीतउष्ण (अनुकूलता-प्रतिकूलता) तथा सुख-दुःखमें सम है एवं आसक्तिसे रहित है, और जो निन्दा-स्तुतिको समान समझनेवाला, मननशील, जिस-किसी प्रकारसे भी (शरीरका निर्वाह होनेमें) संतुष्ट, रहनेके स्थान तथा शरीरमें ममता-आसक्तिसे रहित और स्थिर बुद्धिवाला है, वह भक्तिमान् मनुष्य मुझे प्रिय है।'),
('6591b03d-b457-5433-884e-3c4ab796bb86'::uuid, 'ef8ab183-dc1a-5bbb-8a67-8718aa926bb8'::uuid, 'tejomayananda', 'hindi', '।।12.19।। जिसको निन्दा और स्तुति दोनों ही तुल्य है, जो मौनी है, जो किसी अल्प वस्तु से भी सन्तुष्ट है, जो अनिकेत है, वह स्थिर बुद्धि का भक्तिमान् पुरुष मुझे प्रिय है।।
 '),
('60d94206-da00-5452-a956-5577e3077d1c'::uuid, 'd71b5192-1e47-5691-88ae-e3302bcb212b'::uuid, 'ramsukhdas', 'hindi', '।।12.20।।जो मेरेमें श्रद्धा रखनेवाले और मेरे परायण हुए भक्त पहले कहे हुए इस धर्ममय अमृतका अच्छी तरहसे सेवन करते हैं, वे मुझे अत्यन्त प्रिय हैं।'),
('f540218c-fba2-58ed-b13f-58026b46d698'::uuid, 'd71b5192-1e47-5691-88ae-e3302bcb212b'::uuid, 'tejomayananda', 'hindi', '।।12.20।। जो भक्त श्रद्धावान् तथा मुझे ही परम लक्ष्य समझने वाले हैं और इस यथोक्त धर्ममय अमृत का अर्थात् धर्ममय जीवन का पालन करते हैं, वे मुझे अतिशय प्रिय हैं।।'),
('1df9a73f-cf17-5e2d-be32-9e6c0c2adcd3'::uuid, '28eb3377-5a81-5458-9ec1-ba0c094e42e5'::uuid, 'ramsukhdas', 'hindi', '।।13.1।। No Translation'),
('5a7129e9-bf15-5b06-a465-4125c0abf447'::uuid, '28eb3377-5a81-5458-9ec1-ba0c094e42e5'::uuid, 'tejomayananda', 'hindi', '।।13.1।। अर्जुन ने कहा -- हे केशव ! मैं, प्रकृति और पुरुष, क्षेत्र और क्षेत्रज्ञ तथा ज्ञान और ज्ञेय को जानना चाहता हूँ।।
 '),
('55d305c8-9049-55e7-b72b-e019faaf2b11'::uuid, 'ab165159-e56e-56f5-b5d7-eb0ac14c988d'::uuid, 'ramsukhdas', 'hindi', '।।13.2।।श्रीभगवान् बोले -- हे कुन्तीपुत्र अर्जुन ! ''यह'' -- रूपसे कहे जानेवाले शरीरको ''क्षेत्र'' कहते हैं और इस क्षेत्रको जो जानता है, उसको ज्ञानीलोग ''क्षेत्रज्ञ'' नामसे कहते हैं।'),
('33188d5a-5074-5677-9d4c-4aaa35673103'::uuid, 'ab165159-e56e-56f5-b5d7-eb0ac14c988d'::uuid, 'tejomayananda', 'hindi', '।।13.2।। श्रीभगवान् ने कहा -- हे कौन्तेय ! यह शरीर क्षेत्र कहा जाता है और इसको जो जानता है, उसे तत्त्वज्ञ जन, क्षेत्रज्ञ कहते हैं।।
 '),
('4e699e3a-1ab5-5b63-987e-6f63f3b3782b'::uuid, '75849c61-1df7-5e2f-8b9e-5da603950fcb'::uuid, 'ramsukhdas', 'hindi', '।।13.3।।हे भरतवंशोद्भव अर्जुन ! तू सम्पूर्ण क्षेत्रोंमें क्षेत्रज्ञ मेरेको ही समझ; और क्षेत्र-क्षेत्रज्ञका जो ज्ञान है, वही मेरे मतमें ज्ञान है।'),
('e9dfa478-d896-577f-a4e3-dcc728d7dc87'::uuid, '75849c61-1df7-5e2f-8b9e-5da603950fcb'::uuid, 'tejomayananda', 'hindi', '।।13.3।। हे भारत ! तुम समस्त क्षेत्रों में क्षेत्रज्ञ मुझे ही जानो। क्षेत्र और क्षेत्रज्ञ का जो ज्ञान है, वही (वास्तव में) ज्ञान है , ऐसा मेरा मत है।।
 '),
('15f9c542-0a03-55cb-a8e7-f472e891d383'::uuid, '67663178-cb87-5b18-aac6-1316d1fa8d35'::uuid, 'ramsukhdas', 'hindi', '।।13.4।।वह क्षेत्र जो है, जैसा है, जिन विकारोंवाला है और जिससे जो पैदा हुआ है; तथा वह क्षेत्रज्ञ भी जो है और जिस प्रभाववाला है, वह सब संक्षेपमें मेरेसे सुन।'),
('5465b2d6-eb4c-52db-8022-46ff2aed3d9c'::uuid, '67663178-cb87-5b18-aac6-1316d1fa8d35'::uuid, 'tejomayananda', 'hindi', '।।13.4।। इसलिये, वह क्षेत्र जो है और जैसा है तथा जिन विकारों वाला है, और जिस (कारण) से जो (कार्य) हुआ है तथा वह (क्षेत्रज्ञ) भी जो है और जिस प्रभाव वाला है, वह संक्षेप में मुझसे सुनो।।
 '),
('3f7978d1-a1f1-544d-b7b9-7d1a8d6202b8'::uuid, 'eab8c5c8-95d1-5393-89be-4a92466c8c38'::uuid, 'ramsukhdas', 'hindi', '।।13.5।।(यह क्षेत्रक्षेत्रज्ञका तत्त्व) ऋषियोंके द्वारा बहुत विस्तारसे कहा गया है तथा वेदोंकी ऋचाओं-द्वारा बहुत प्रकारसे कहा गया है और युक्तियुक्त एवं निश्चित किये हुए ब्रह्मसूत्रके पदोंद्वारा भी कहा गया है।'),
('e652c9de-1a15-58fd-b651-6c64e8992a78'::uuid, 'eab8c5c8-95d1-5393-89be-4a92466c8c38'::uuid, 'tejomayananda', 'hindi', '।।13.5।। (क्षेत्र-क्षेत्रज्ञ के विषय में) ऋषियों द्वारा विभिन्न और विविध छन्दों में बहुत प्रकार से गाया गया है, तथा सम्यक् प्रकार से निश्चित किये हुये युक्तियुक्त ब्रह्मसूत्र के पदों द्वारा (अर्थात् ब्रह्म के सूचक शब्दों द्वारा) भी (वैसे ही कहा गया है)।।
 '),
('b47144a9-de3d-59ba-b7dc-3fbbb41ab285'::uuid, 'd221307c-21bb-53a0-8bb8-a778d9c65ea1'::uuid, 'ramsukhdas', 'hindi', '।।13.6।।मूल प्रकृति, समष्टि बुद्धि (महत्तत्त्व), समष्टि अहंकार, पाँच महाभूत और दस इन्द्रियाँ, एक मन तथा पाँचों इन्द्रियोंके पाँच विषय ( -- यह चौबीस तत्त्वोंवाला क्षेत्र है)।'),
('50c68e4c-f672-5cc2-912c-fffdabc6108a'::uuid, 'd221307c-21bb-53a0-8bb8-a778d9c65ea1'::uuid, 'tejomayananda', 'hindi', '।।13.6।। पंच महाभूत, अहंकार, बुद्धि, अव्यक्त (प्रकृति), दस इन्द्रियाँ, एक मन, इन्द्रियों के पाँच विषय।।
 '),
('46975284-b2d7-596e-aca9-15f9364a6b47'::uuid, '4fecdcdf-f181-564d-862e-094778c09383'::uuid, 'ramsukhdas', 'hindi', '।।13.7।।इच्छा, द्वेष, सुख, दुःख, संघात, चेतना (प्राणशक्ति) और धृति -- इन विकारोंसहित यह क्षेत्र संक्षेपसे कहा गया है।'),
('b7d68368-2429-5a90-98af-a8edee6015ea'::uuid, '4fecdcdf-f181-564d-862e-094778c09383'::uuid, 'tejomayananda', 'hindi', '।।13.7।। इच्छा, द्वेष, सुख, दुख, संघात (स्थूलदेह), चेतना (अन्त:करण की चेतन वृत्ति) तथा धृति -  इस प्रकार यह क्षेत्र विकारों के सहित संक्षेप में कहा गया है।।
 '),
('b36fd51f-68d5-5254-ba99-47c8e7141746'::uuid, '0a6aaad4-176e-5534-b4ad-a5bc7fce3ae1'::uuid, 'ramsukhdas', 'hindi', '।।13.8।।मानित्व-(अपनेमें श्रेष्ठताके भाव-) का न होना, दम्भित्व-(दिखावटीपन-) का न होना, अहिंसा, क्षमा, सरलता, गुरुकी सेवा, बाहर-भीतरकी शुद्धि, स्थिरता और मनका वशमें होना।'),
('5874163a-ae1f-5721-b69f-09f84e221816'::uuid, '0a6aaad4-176e-5534-b4ad-a5bc7fce3ae1'::uuid, 'tejomayananda', 'hindi', '।।13.8।। अमानित्व, अदम्भित्व, अहिंसा, क्षमा, आर्जव, आचार्य की सेवा, शुद्धि, स्थिरता और आत्मसंयम।।
 '),
('b3ea62e1-ca11-55b8-b75e-237819e40407'::uuid, '8651ec69-3512-5cdb-9f4e-4be93fa3a48a'::uuid, 'ramsukhdas', 'hindi', '।।13.9।।इन्द्रियोंके विषयोंमें वैराग्यका होना, अहंकारका भी न होना और जन्म, मृत्यु, वृद्धावस्था तथा व्याधियोंमें दुःखरूप दोषोंको बार-बार देखना।'),
('9bd9f516-d3fe-551a-b260-d554b5eb839d'::uuid, '8651ec69-3512-5cdb-9f4e-4be93fa3a48a'::uuid, 'tejomayananda', 'hindi', '।।13.9।। इन्द्रियों के विषय के प्रति वैराग्य, अहंकार का अभाव, जन्म, मृत्यु, वृद्धवस्था, व्याधि और दुख में दोष दर्शन...৷৷.।।
 '),
('b47dd0d1-5596-50e2-81e4-080ed623662f'::uuid, '8867c1ab-4570-5743-8323-4249d8e4a7ae'::uuid, 'ramsukhdas', 'hindi', '।।13.10।।आसक्तिरहित होना;  पुत्र,  स्त्री, घर आदिमें एकात्मता (घनिष्ठ सम्बन्ध) न होना और अनुकूलता-प्रतिकूलताकी प्राप्तिमें चित्तका नित्य सम रहना।'),
('da8caa89-037a-5aa5-826d-1e8d43294739'::uuid, '8867c1ab-4570-5743-8323-4249d8e4a7ae'::uuid, 'tejomayananda', 'hindi', '।।13.10।। आसक्ति तथा पुत्र, पत्नी, गृह आदि में अनभिष्वङ्ग (तादात्म्य का अभाव); और इष्ट और अनिष्ट की प्राप्ति में समचित्तता।।
 '),
('32856e59-1175-5896-9c68-9e5f28a04d5c'::uuid, '7d239131-6022-5a71-8e31-90a0b90e6157'::uuid, 'ramsukhdas', 'hindi', '।।13.11।।मेरेमें अनन्ययोगके द्वारा अव्यभिचारिणी भक्तिका होना, एकान्त स्थानमें रहनेका स्वभाव होना और जन-समुदायमें प्रीतिका न होना।'),
('47a63eba-aeab-5520-ac9d-791296bce969'::uuid, '7d239131-6022-5a71-8e31-90a0b90e6157'::uuid, 'tejomayananda', 'hindi', '।।13.11।। अनन्ययोग के द्वारा मुझमें अव्यभिचारिणी भक्ति; एकान्त स्थान में रहने का स्वभाव और (असंस्कृत) जनों के समुदाय में अरुचि।।
 ')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('479724a9-aea6-5ec0-ac63-cefe279f69a9'::uuid, '412cce2c-fc8f-57e9-b337-558b69c0de45'::uuid, 'ramsukhdas', 'hindi', '।।13.12।।अध्यात्मज्ञानमें नित्य-निरन्तर रहना, तत्त्वज्ञानके अर्थरूप परमात्माको सब जगह देखना -- यह (पूर्वोक्त साधन-समुदाय) तो ज्ञान है; और जो इसके विपरीत है वह अज्ञान है -- ऐसा कहा गया है।'),
('2102690e-ae1e-542f-9c23-b57d9c0eaf9a'::uuid, '412cce2c-fc8f-57e9-b337-558b69c0de45'::uuid, 'tejomayananda', 'hindi', '।।13.12।। अध्यात्मज्ञान में नित्यत्व अर्थात् स्थिरता तथा तत्त्वज्ञान के अर्थ रूप परमात्मा का दर्शन, यह सब तो ज्ञान कहा गया है, और जो इससे विपरीत है, वह अज्ञान है।।
 '),
('731a0a31-31c6-52f6-aa8d-10a428c9656f'::uuid, '7a07da7b-b4bc-5365-b580-4bd91064e91f'::uuid, 'ramsukhdas', 'hindi', '।।13.13।। जो ज्ञेय है, उस-(परमात्मतत्त्व-) को मैं अच्छी तरहसे कहूँगा, जिसको जानकर मनुष्य अमरताका अनुभव कर लेता है। वह (ज्ञेय-तत्त्व) अनादि और परम ब्रह्म है। उसको न सत् कहा जा सकता है और न असत् ही कहा जा सकता है।'),
('f035bfec-2ca3-5317-a185-29ee8b093911'::uuid, '7a07da7b-b4bc-5365-b580-4bd91064e91f'::uuid, 'tejomayananda', 'hindi', '।।13.13।। मैं उस ज्ञेय वस्तु को स्पष्ट कहूंगा जिसे जानकर मनुष्य अमृतत्व को प्राप्त करता है। वह ज्ञेय है - अनादि, परम ब्रह्म, जो न सत् और न असत् ही कहा जा सकता है।।
 '),
('b96d9d60-b1c5-5209-835d-5bbd7fd71d7f'::uuid, 'eb20a4db-bd61-5525-b49c-cf2581122a7a'::uuid, 'ramsukhdas', 'hindi', '।।13.14।।वे (परमात्मा) सब जगह हाथों और पैरोंवाले, सब जगह नेत्रों, सिरों और मुखोंवाले तथा सब जगह कानोंवाले हैं। वे संसारमें सबको व्याप्त करके स्थित हैं।'),
('318d3b5d-9f8b-55c9-a36e-ce580d995dbc'::uuid, 'eb20a4db-bd61-5525-b49c-cf2581122a7a'::uuid, 'tejomayananda', 'hindi', '।।13.14।। वह सब ओर हाथ-पैर वाला है और सब ओर से नेत्र, शिर और मुखवाला तथा सब ओर से श्रोत्रवाला है; वह जगत् में सबको व्याप्त करके स्थित है।।
 '),
('d1b484b3-8408-5468-afa9-6aef2f562e09'::uuid, '93799091-8a25-5dd0-9999-5d123c5d3225'::uuid, 'ramsukhdas', 'hindi', '।।13.15।।वे (परमात्मा) सम्पूर्ण इन्द्रियोंसे रहित हैं और सम्पूर्ण इन्द्रियोंके विषयोंको प्रकाशित करनेवाले हैं; आसक्तिरहित हैं और सम्पूर्ण संसारका भरण-पोषण करनेवाले हैं; तथा गुणोंसे रहित हैं और सम्पूर्ण गुणोंके भोक्ता हैं।'),
('0467feed-fde1-5782-b424-0844dc7c0a57'::uuid, '93799091-8a25-5dd0-9999-5d123c5d3225'::uuid, 'tejomayananda', 'hindi', '।।13.15।। वह समस्त इन्द्रियों के गुणो (कार्यों) के द्वारा प्रकाशित होने वाला, परन्तु (वस्तुत:) समस्त इन्द्रियों से रहित है; आसक्ति रहित तथा गुण रहित होते हुए भी सबको धारणपोषण करने वाला और गुणों का भोक्ता है।।
 '),
('f46c4715-ab8e-56e3-a606-65c68769d5ae'::uuid, '75629797-0700-5fa5-af78-1c500f574f36'::uuid, 'ramsukhdas', 'hindi', '।।13.16।।वे परमात्मा सम्पूर्ण प्राणियोंके बाहर-भीतर परिपूर्ण हैं और चर-अचर प्राणियोंके रूपमें भी वे ही हैं एवं दूर-से-दूर तथा नजदीक-से-नजदीक भी वे ही हैं। वे अत्यन्त सूक्ष्म होनेसे जाननेका विषय नहीं हैं।'),
('27d03105-e73b-545e-9f98-851286a086b4'::uuid, '75629797-0700-5fa5-af78-1c500f574f36'::uuid, 'tejomayananda', 'hindi', '।।13.16।। (वह ब्रह्म) भूत मात्र के अन्तर्बाह्य स्थित है; वह चर है और अचर भी। सूक्ष्म होने से वह अविज्ञेय है; वह सुदूर और अत्यन्त समीपस्थ भी है।।
 '),
('be4eff49-a6e2-55b1-9538-3e51b762015c'::uuid, '99134278-0eff-5b1e-9164-17abb1ab74b2'::uuid, 'ramsukhdas', 'hindi', '।।13.17।।वे परमात्मा स्वयं विभागरहित होते हुए भी सम्पूर्ण प्राणियोंमें विभक्तकी तरह स्थित हैं। वे जाननेयोग्य परमात्मा ही सम्पूर्ण प्राणियोंको उत्पन्न करनेवाले, उनका भरण-पोषण करनेवाले और संहार करनेवाले हैं।'),
('50250d7f-b693-529e-82ab-7bdd64504136'::uuid, '99134278-0eff-5b1e-9164-17abb1ab74b2'::uuid, 'tejomayananda', 'hindi', '।।13.17।। और वह अविभक्त है, तथापि वह भूतों में विभक्त के समान स्थित है। वह ज्ञेय ब्रह्म भूतमात्र का भर्ता, संहारकर्ता और उत्पत्ति कर्ता है।।
 '),
('46fe0449-2f7e-5efe-8a1a-4dfb58f78519'::uuid, 'd2804118-d15b-5286-8f42-34f32a338726'::uuid, 'ramsukhdas', 'hindi', '।।13.18।।वह परमात्मा सम्पूर्ण ज्योतियोंका भी ज्योति और अज्ञानसे अत्यन्त परे कहा गया है। वह ज्ञानस्वरूप, जाननेयोग्य, ज्ञान(साधन-समुदाय) से प्राप्त करनेयोग्य और सबके हृदयमें विराजमान है।'),
('d049c7f2-e39b-5ac1-b605-3477bae09b3a'::uuid, 'd2804118-d15b-5286-8f42-34f32a338726'::uuid, 'tejomayananda', 'hindi', '।।13.18।। (वह ब्रह्म) ज्योतियों की भी ज्योति और (अज्ञान) अन्धकार से परे कहा जाता है। वह ज्ञान (चैतन्यस्वरूप) ज्ञेय और ज्ञान के द्वारा जानने योग्य (ज्ञानगम्य) है। वह सभी के हृदय में स्थित है।।'),
('0cdd2823-794f-51bd-9955-e6b68ec99aeb'::uuid, '2dc1b5da-fa89-54d4-a7c0-a67ef381e075'::uuid, 'ramsukhdas', 'hindi', '।।13.19।।इस प्रकार क्षेत्र, ज्ञान और ज्ञेयको संक्षेपसे कहा गया। मेरा भक्त इसको तत्त्वसे जानकर मेरे भावको प्राप्त हो जाता है।'),
('a89004f7-ff8d-53f1-ac4e-3b456754bbc8'::uuid, '2dc1b5da-fa89-54d4-a7c0-a67ef381e075'::uuid, 'tejomayananda', 'hindi', '।।13.19।। इस प्रकार, (मेरे द्वारा) क्षेत्र, ज्ञान और ज्ञेय को संक्षेपत: कहा गया। इसे तत्त्व से जानकर (विज्ञाय) मेरा भक्त मेरे स्वरूप को प्राप्त होता है।।
 '),
('c923c0fb-8323-51c1-81ca-c63d903c5c2b'::uuid, '7e8bf466-cc54-5a57-826a-fe9d24787dc6'::uuid, 'ramsukhdas', 'hindi', '।।13.20।।प्रकृति और पुरुष -- दोनोंको ही तुम अनादि समझो और विकारों तथा गुणोंको भी प्रकृतिसे ही उत्पन्न समझो। कार्य और करणके द्वारा होनेवाली क्रियाओंको उत्पन्न करनेमें प्रकृति हेतु कही जाती है और सुख-दुःखोंके भोक्तापनमें पुरुष हेतु कहा जाता है।'),
('fc0a578c-0ef7-5270-801c-9e0f4886d7ca'::uuid, '7e8bf466-cc54-5a57-826a-fe9d24787dc6'::uuid, 'tejomayananda', 'hindi', '।।13.20।। प्रकृति और पुरुष इन दोनों को ही तुम अनादि जानो। और तुम यह भी जानो कि सभी विकार और गुण प्रकृति से ही उत्पन्न हुए हैं।।'),
('f52542aa-12ef-53bd-a861-ce6d67d61064'::uuid, 'bd572132-785c-58ce-930e-491ac888b364'::uuid, 'ramsukhdas', 'hindi', '।।13.21।।प्रकृति और पुरुष -- दोनोंको ही तुम अनादि समझो और विकारों तथा गुणोंको भी प्रकृतिसे ही उत्पन्न समझो। कार्य और करणके द्वारा होनेवाली क्रियाओंको उत्पन्न करनेमें प्रकृति हेतु कही जाती है और सुखदुःखोंके भोक्तापनमें पुरुष हेतु कहा जाता है।'),
('e7cf00b4-f317-544a-a2dc-365b9eaf17fb'::uuid, 'bd572132-785c-58ce-930e-491ac888b364'::uuid, 'tejomayananda', 'hindi', '।।13.21।। कार्य और कारण के उत्पन्न करने में हेतु प्रकृति कही जाती है और पुरुष सुख-दु:ख के भोक्तृत्व में हेतु कहा जाता है।।
 '),
('5bc62e1c-005d-510c-a873-6b8a9d01f94d'::uuid, '1ffbd5ac-37a8-5a4e-8d62-e031d04ab246'::uuid, 'ramsukhdas', 'hindi', '।।13.22।।प्रकृतिमें स्थित पुरुष ही प्रकृतिजन्य गुणोंका भोक्ता बनता है और गुणोंका सङ्ग ही उसके ऊँच-नीच योनियोंमें जन्म लेनेका कारण बनता है।'),
('5beed77f-2404-576f-aed8-aefb4cd262a5'::uuid, '1ffbd5ac-37a8-5a4e-8d62-e031d04ab246'::uuid, 'tejomayananda', 'hindi', '।।13.22।। प्रकृति में स्थित पुरुष प्रकृति से उत्पन्न गुणों को भोगता है। इन गुणों का संग ही इस पुरुष (जीव) के शुभ और अशुभ योनियों में जन्म लेने का कारण है।।'),
('33e991c4-e21a-5b0c-9988-bb5c3e1e0f7b'::uuid, '1d11b633-697d-5909-a138-628b16c65a1b'::uuid, 'ramsukhdas', 'hindi', '।।13.23।।यह पुरुष प्रकृति-(शरीर-) के साथ सम्बन्ध रखनेसे ''उपद्रष्टा'', उसके साथ मिलकर सम्मति, अनुमति देनेसे ''अनुमन्ता'', अपनेको उसका भरणपोषण करनेवाला माननेसे ''भर्ता'', उसके सङ्गसे सुखदुःख भोगनेसे ''भोक्ता'', और अपनेको उसका स्वामी माननेसे ''महेश्वर'' बन जाता है। परन्तु स्वरूपसे यह पुरुष ''परमात्मा'' कहा जाता है। यह देहमें रहता हुआ भी देहसे पर (सम्बन्ध-रहित) ही है।'),
('2a848674-2862-5843-b336-5fad9777f39e'::uuid, '1d11b633-697d-5909-a138-628b16c65a1b'::uuid, 'tejomayananda', 'hindi', '।।13.23।। परम पुरुष ही इस देह में उपद्रष्टा, अनुमन्ता ,भर्ता, भोक्ता, महेश्वर और परमात्मा कहा जाता है।।
 '),
('6435c692-ad54-5e4c-ab9c-0ffc65db8eb3'::uuid, 'bef08c94-dfab-5a45-bc24-1d290efc6994'::uuid, 'ramsukhdas', 'hindi', '।।13.24।।इस प्रकार पुरुषको और गुणोंके सहित प्रकृतिको जो मनुष्य अलग-अलग जानता है, वह सब तरहका बर्ताव करता हुआ भी फिर जन्म नहीं लेता।'),
('a311f442-4830-5b0d-92ce-0c294ef1825d'::uuid, 'bef08c94-dfab-5a45-bc24-1d290efc6994'::uuid, 'tejomayananda', 'hindi', '।।13.24।। इस प्रकार पुरुष और गुणों के सहित प्रकृति को जो मनुष्य जानता है, वह सब प्रकार से रहता हुआ (व्यवहार करता हुआ) भी पुन: नहीं जन्मता है।।
 '),
('56bdc955-b476-54c6-b4dd-2d0331d5f2bb'::uuid, '8ffe367b-2ca1-5f59-a5d5-475c965e3fad'::uuid, 'ramsukhdas', 'hindi', '।।13.25।।कई मनुष्य ध्यानयोगके द्वारा, कई सांख्ययोगके द्वारा और कई कर्मयोगके द्वारा अपने-आपसे अपने-आपमें परमात्मतत्त्वका अनुभव करते हैं।'),
('cdfd8bac-3c59-5b6e-8cec-159a370e04e2'::uuid, '8ffe367b-2ca1-5f59-a5d5-475c965e3fad'::uuid, 'tejomayananda', 'hindi', '।।13.25।। कोई पुरुष ध्यान के अभ्यास से आत्मा को आत्मा (हृदय) में आत्मा (शुद्ध बुद्धि) के द्वारा देखते हैं; अन्य लोग सांख्य योग के द्वारा तथा कोई साधक कर्मयोग से (आत्मा को देखते हैं )।।
 '),
('87068b08-33db-576e-bfbb-d673e38b1895'::uuid, 'a705be51-2e65-5c78-b7bf-8e8882eaec04'::uuid, 'ramsukhdas', 'hindi', '।।13.26।।दूसरे मनुष्य इस प्रकार (ध्यानयोग, सांख्ययोग, कर्मयोग, आदि साधनोंको) नहीं जानते, केवल (जीवन्मुक्त महापुरुषोंसे) सुनकर उपासना करते हैं, ऐसे वे सुननेके परायण मनुष्य भी मृत्युको तर जाते हैं।'),
('b24a3a32-8ee2-52fd-b99e-4ff6ea4df879'::uuid, 'a705be51-2e65-5c78-b7bf-8e8882eaec04'::uuid, 'tejomayananda', 'hindi', '।।13.26।। परन्तु, अन्य लोग जो स्वयं इस प्रकार न जानते हुए, दूसरों से (आचार्यों से) सुनकर ही उपासना करते हैं, वे श्रुतिपरायण (अर्थात् श्रवण ही जिनके लिए परम साधन है) लोग भी मृत्यु को नि:सन्देह तर जाते हैं।।
 '),
('34cf9c80-0956-5cc0-8664-7cc5435315fe'::uuid, 'ced1d908-d1ba-5d43-abea-848734015dfb'::uuid, 'ramsukhdas', 'hindi', '।।13.27।।हे भरतवंशियोंमें श्रेष्ठ अर्जुन ! स्थावर और जंगम जितने भी प्राणी पैदा होते हैं, उनको तुम क्षेत्र और क्षेत्रज्ञके संयोगसे उत्पन्न हुए समझो।'),
('46ed38fe-4504-580f-bfa3-3fb41baa3cbb'::uuid, 'ced1d908-d1ba-5d43-abea-848734015dfb'::uuid, 'tejomayananda', 'hindi', '।।13.27।। हे भरत श्रेष्ठ ! यावन्मात्र जो कुछ भी स्थावर जंगम (चराचर) वस्तु उत्पन्न होती है, उस सबको तुम क्षेत्र और क्षेत्रज्ञ के संयोग से उत्पन्न हुई जानो।।
 '),
('e96f9d27-6b07-5aad-a694-d123e566d075'::uuid, '28c174d8-82db-5d82-a562-b7b32e4e905a'::uuid, 'ramsukhdas', 'hindi', '।।13.28।।जो नष्ट होते हुए सम्पूर्ण प्राणियोंमें परमात्माको नाशरहित और समरूपसे स्थित देखता है, वही वास्तवमें सही देखता है।'),
('0ad9b733-fa25-5381-9033-c9369290db4a'::uuid, '28c174d8-82db-5d82-a562-b7b32e4e905a'::uuid, 'tejomayananda', 'hindi', '।।13.28।। जो पुरुष समस्त नश्वर भूतों में अनश्वर परमेश्वर को समभाव से स्थित देखता है, वही (वास्तव में) देखता है।।
 '),
('974e21ef-a46c-580c-9d0b-6aee7e067dd6'::uuid, 'abd8d324-d849-5a46-8676-c8e9c7ef53f2'::uuid, 'ramsukhdas', 'hindi', '।।13.29।।क्योंकि सब जगह समरूपसे स्थित ईश्वरको समरूपसे देखनेवाला मनुष्य अपने-आपसे अपनी हिंसा नहीं करता, इसलिये वह परमगतिको प्राप्त हो जाता है।'),
('af0ee02d-8edc-5adf-b943-937de441a3f4'::uuid, 'abd8d324-d849-5a46-8676-c8e9c7ef53f2'::uuid, 'tejomayananda', 'hindi', '।।13.29।। निश्चय ही, वह पुरुष सर्वत्र सम भाव से स्थित परमेश्वर को समान हुआ आत्मा (स्वयं) के द्वारा आत्मा (स्वयं) का नाश नहीं करता है, इससे वह परम गति को प्राप्त होता है।।
 '),
('daf7ecab-a5df-5d50-a2f2-13e5eac5fcd6'::uuid, '3bcb6772-fe6f-5355-acaf-232cc201ca42'::uuid, 'ramsukhdas', 'hindi', '।।13.30।।जो सम्पूर्ण क्रियाओंको सब प्रकारसे प्रकृतिके द्वारा ही की जाती हुई देखता है और अपने-आपको अकर्ता देखता (अनुभव करता) है, वही यथार्थ देखता है।'),
('ac520872-840f-5f0d-a8c4-778fa6cdc6bd'::uuid, '3bcb6772-fe6f-5355-acaf-232cc201ca42'::uuid, 'tejomayananda', 'hindi', '।।13.30।। जो पुरुष समस्त कर्मों को सर्वश: प्रकृति द्वारा ही किये गये देखता है तथा आत्मा को अकर्ता देखता है, वही (वास्तव में) देखता है।।
 '),
('07bdeef8-fe12-59fa-986d-3996d2bfa237'::uuid, 'b36737b3-0163-5e9a-8040-f5b562cc4238'::uuid, 'ramsukhdas', 'hindi', '।।13.31।।जिस कालमें साधक प्राणियोंके अलग-अलग भावोंको एक प्रकृतिमें ही स्थित देखता है और उस प्रकृतिसे ही उन सबका विस्तार देखता है, उस कालमें वह ब्रह्मको प्राप्त हो जाता है।'),
('18bf3418-2156-5e2d-bab6-b7407484100d'::uuid, 'b36737b3-0163-5e9a-8040-f5b562cc4238'::uuid, 'tejomayananda', 'hindi', '।।13.31।। यह पुरुष जब भूतों के पृथक् भावों को एक (परमात्मा) में स्थित देखता है तथा उस (परमात्मा) से ही यह विस्तार हुआ जानता है, तब वह ब्रह्म को प्राप्त होता है।।
 '),
('42328de0-9ebe-5b70-817b-b854fa35e601'::uuid, 'b2441b8d-92e6-5b6d-ac07-d8382329474f'::uuid, 'ramsukhdas', 'hindi', '।।13.32।।हे कुन्तीनन्दन ! यह पुरुष स्वयं अनादि और गुणोंसे रहित होनेसे अविनाशी परमात्मस्वरूप ही है। यह शरीरमें रहता हुआ भी न करता है और न लिप्त होता है।'),
('1509fe75-120c-56db-8e6c-2ed8deb2cfc3'::uuid, 'b2441b8d-92e6-5b6d-ac07-d8382329474f'::uuid, 'tejomayananda', 'hindi', '।।13.32।। हे कौन्तेय ! अनादि और निर्गुण होने से यह परमात्मा अव्यय है। शरीर में स्थित हुआ भी, वस्तुत:, वह न (कर्म) करता है और न (फलों से) लिप्त होता है।।
 '),
('483d8def-9376-5e74-99ea-bf7cd1648995'::uuid, '4c6e64a9-14d5-5690-b9f3-68f6c6ba3028'::uuid, 'ramsukhdas', 'hindi', '।।13.33।।जैसे सब जगह व्याप्त आकाश अत्यन्त सूक्ष्म होनेसे कहीं भी लिप्त नहीं होता, ऐसे ही सब जगह परिपूर्ण आत्मा किसी भी देहमें लिप्त नहीं होता।'),
('d09412ea-3634-542e-b71d-20dda25cbf18'::uuid, '4c6e64a9-14d5-5690-b9f3-68f6c6ba3028'::uuid, 'tejomayananda', 'hindi', '।।13.33।। जिस प्रकार सर्वगत आकाश सूक्ष्म होने के कारण लिप्त नहीं होता, उसी प्रकार सर्वत्र देह में स्थित आत्मा लिप्त नहीं होता।।
 '),
('e1c63cc3-bef1-5115-aed0-b549833cad64'::uuid, '83904f5e-00c8-5f1e-b461-91f6e7852940'::uuid, 'ramsukhdas', 'hindi', '।।13.34।।हे भरतवंशोद्भव अर्जुन ! जैसे एक ही सूर्य सम्पूर्ण संसारको प्रकाशित करता है, ऐसे ही क्षेत्री (क्षेत्रज्ञ, आत्मा) सम्पूर्ण क्षेत्रको प्रकाशित करता है।'),
('479efd63-6860-50dc-81bb-c1f880ed04a5'::uuid, '83904f5e-00c8-5f1e-b461-91f6e7852940'::uuid, 'tejomayananda', 'hindi', '।।13.34।। हे भारत ! जिस प्रकार एक ही सूर्य इस सम्पूर्ण लोक को प्रकाशित करता है, उसी प्रकार एक ही क्षेत्री (क्षेत्रज्ञ) सम्पूर्ण क्षेत्र को प्रकाशित करता है।।
 '),
('79df3ff0-852f-573c-aa08-6b49f332da85'::uuid, '2ca4e792-b204-5c58-a965-56e2e57eeeff'::uuid, 'ramsukhdas', 'hindi', '।।13.35।।इस प्रकार जो ज्ञानरूपी नेत्रसे क्षेत्र और क्षेत्रज्ञके अन्तर-(विभाग-) को तथा कार्य-कारणसहित प्रकृतिसे स्वयंको अलग जानते हैं, वे परमात्माको प्राप्त हो जाते हैं।'),
('3d1a5e3a-3ffa-5bf3-aa05-27594fb9fd45'::uuid, '2ca4e792-b204-5c58-a965-56e2e57eeeff'::uuid, 'tejomayananda', 'hindi', '।।13.35।। इस प्रकार, जो पुरुष ज्ञानचक्षु के द्वारा क्षेत्र और क्षेत्रज्ञ के भेद को तथा प्रकृति के विकारों से मोक्ष को जानते हैं, वे परम ब्रह्म को प्राप्त होते हैं।।'),
('8bb636bb-ee14-5bbf-a896-a1363cd5f9f4'::uuid, '86f46b0a-84f8-5a26-8818-5b6824479173'::uuid, 'ramsukhdas', 'hindi', '।।14.1।।श्रीभगवान् बोले -- सम्पूर्ण ज्ञानोंमें उत्तम और पर ज्ञानको मैं फिर कहूँगा, जिसको जानकर सब-के-सब मुनिलोग इस संसारसे मुक्त होकर परमसिद्धिको प्राप्त हो गये हैं।'),
('7323087b-1fe3-55c0-aa80-3dccf9f624ab'::uuid, '86f46b0a-84f8-5a26-8818-5b6824479173'::uuid, 'tejomayananda', 'hindi', '।।14.1।। श्री भगवान् ने कहा -- समस्त ज्ञानों में उत्तम परम ज्ञान को मैं पुन: कहूंगा, जिसको जानकर सभी मुनिजन इस (लोक) से जाकर (इस जीवनोपरान्त) परम सिद्धि को प्राप्त हुए हैं।।
 '),
('5c7b2a11-7ffb-5c2a-b29b-05f35e28831f'::uuid, '830be355-3c87-5597-9686-3ed01f7a69fb'::uuid, 'ramsukhdas', 'hindi', '।।14.2।।इस ज्ञानका आश्रय लेकर जो मनुष्य मेरी सधर्मताको प्राप्त हो गये हैं, वे महासर्गमें भी पैदा नहीं होते और महाप्रलयमें भी व्यथित नहीं होते।'),
('7a14681b-496a-5445-b18d-ad42dc5a88f5'::uuid, '830be355-3c87-5597-9686-3ed01f7a69fb'::uuid, 'tejomayananda', 'hindi', '।।14.2।। इस ज्ञान का आश्रय लेकर मेरे स्वरूप (सार्धम्यम्) को प्राप्त पुरुष सृष्टि के आदि में जन्म नहीं लेते और प्रलयकाल में व्याकुल भी नहीं होते हैं।।'),
('5e341cb5-bc35-5261-9d0d-40dda32f9c98'::uuid, 'd92d986f-4c0a-5b0e-a430-bd6259c567a8'::uuid, 'ramsukhdas', 'hindi', '।।14.3।।हे भरतवंशोद्भव अर्जुन ! मेरी मूल प्रकृति तो उत्पत्ति-स्थान है और मैं उसमें जीवरूप गर्भका स्थापन करता हूँ। उससे सम्पूर्ण प्राणियोंकी उत्पत्ति होती है।'),
('a2c298f1-858e-5647-98b3-5f02b053dd7d'::uuid, 'd92d986f-4c0a-5b0e-a430-bd6259c567a8'::uuid, 'tejomayananda', 'hindi', '।।14.3।। हे भारत ! मेरी महद् ब्रह्मरूप प्रकृति, (भूतों की) योनि है, जिसमें मैं गर्भाधान करता हूँ; इससे समस्त भूतों की उत्पत्ति होती है।।
 '),
('2843af6e-fb96-546c-aa94-d3e8691689ee'::uuid, '06c1ae51-a800-5185-88f4-c4423ebafa69'::uuid, 'ramsukhdas', 'hindi', '।।14.4।।हे कुन्तीनन्दन ! सम्पूर्ण योनियोंमें प्राणियोंके जितने शरीर पैदा होते हैं, उन सबकी मूल प्रकृति तो माता है और मैं बीज-स्थापन करनेवाला पिता हूँ।'),
('8bccc942-0f33-5ebc-aaa7-e87c65b69e98'::uuid, '06c1ae51-a800-5185-88f4-c4423ebafa69'::uuid, 'tejomayananda', 'hindi', '।।14.4।। हे कौन्तेय ! समस्त योनियों में जितनी मूर्तियाँ (शरीर) उत्पन्न होती हैं, उन सबकी योनि अर्थात् गर्भ है महद्ब्रह्म और मैं बीज की स्थापना करने वाला पिता हूँ।।
 '),
('9b5ba7d2-b31f-5a83-8e51-72066913bfc7'::uuid, '06858a54-f524-5fb7-90f3-04ae7950bba1'::uuid, 'ramsukhdas', 'hindi', '।।14.5।।हे महाबाहो ! प्रकृतिसे उत्पन्न होनेवाले सत्त्व, रज और तम -- ये तीनों गुण अविनाशी देहीको देहमें बाँध देते हैं।'),
('d642639e-c526-54b2-923b-6ac71013c0a1'::uuid, '06858a54-f524-5fb7-90f3-04ae7950bba1'::uuid, 'tejomayananda', 'hindi', '।।14.5।। हे महाबाहो ! सत्त्व, रज और तम ये प्रकृति से उत्पन्न तीनों गुण देही आत्मा को देह के साथ बांध देते हैं।।
 '),
('da18d73b-be0d-58a8-9950-2e52807991c4'::uuid, '595f34ef-b382-54d9-a630-1deb1b6cf316'::uuid, 'ramsukhdas', 'hindi', '।।14.6।।हे पापरहित अर्जुन ! उन गुणोंमें सत्त्वगुण निर्मल (स्वच्छ) होनेके कारण प्रकाशक और निर्विकार है। वह सुख और ज्ञानकी आसक्तिसे (देहीको) बाँधता है।'),
('180cf13d-20fd-51e6-89d6-4df623083da5'::uuid, '595f34ef-b382-54d9-a630-1deb1b6cf316'::uuid, 'tejomayananda', 'hindi', '।।14.6।। हे निष्पाप अर्जुन ! इन (तीनों) में, सत्त्वगुण निर्मल होने से प्रकाशक और अनामय (निरुपद्रव, निर्विकार या निरोग) है; (वह जीव को) सुख की आसक्ति से और ज्ञान की आसक्ति से बांध देता है।।
 '),
('faa117a1-6060-5c1e-8eb9-54a979b3dfa2'::uuid, 'e855623e-3365-5e49-9caa-782558de5a99'::uuid, 'ramsukhdas', 'hindi', '।।14.7।।हे कुन्तीनन्दन ! तृष्णा और आसक्तिको पैदा करनेवाले रजोगुणको तुम रागस्वरूप समझो। वह कर्मोंकी आसक्तिसे शरीरधारीको बाँधता है।'),
('d0658059-143e-5448-903b-9cb70718e5fc'::uuid, 'e855623e-3365-5e49-9caa-782558de5a99'::uuid, 'tejomayananda', 'hindi', '।।14.7।। हे कौन्तेय ! रजोगुण को रागस्वरूप जानो, जिससे तृष्णा और आसक्ति उत्पन्न होती है। वह देही आत्मा को कर्मों की आसक्ति से बांधता है।।
 '),
('1cb7fc6b-5f10-5866-9dfe-7511483fa7e2'::uuid, 'b629dcf6-0352-58d3-848c-87c9e55a1a28'::uuid, 'ramsukhdas', 'hindi', '।।14.8।।हे भरतवंशी अर्जुन ! सम्पूर्ण देहधारियोंको मोहित करनेवाले तमोगुणको तुम अज्ञानसे उत्पन्न होनेवाला समझो। वह प्रमाद, आलस्य और निद्राके द्वारा देहधारियोंको बाँधता है।'),
('e12b45cd-806e-57e8-b86f-47e596086056'::uuid, 'b629dcf6-0352-58d3-848c-87c9e55a1a28'::uuid, 'tejomayananda', 'hindi', '।।14.8।। और हे भारत ! तमोगुण को अज्ञान से उत्पन्न जानो; जो समस्त देहधारियों (जीवों) को मोहित करने वाला है। वह प्रमाद, आलस्य और निद्रा के द्वारा जीव को बांधता है।।
 '),
('cc4541da-6f68-5c22-b39e-9ece8d7c58de'::uuid, 'a1a11f9b-78df-590a-b785-080e0fd6a982'::uuid, 'ramsukhdas', 'hindi', '।।14.9।।हे भरतवंशोद्भव अर्जुन ! सत्त्वगुण सुखमें और रजोगुण कर्ममें लगाकर मनुष्यपर विजय करता है तथा तमोगुण ज्ञानको ढककर एवं प्रमादमें भी लगाकर मनुष्यपर विजंय करता है।'),
('1bbadbe9-0c64-542f-b436-2baeafcc3c16'::uuid, 'a1a11f9b-78df-590a-b785-080e0fd6a982'::uuid, 'tejomayananda', 'hindi', '।।14.9।। हे भारत ! सत्त्वगुण सुख में आसक्त कर देता है और रजोगुण कर्म में, किन्तु तमोगुण ज्ञान को आवृत्त करके जीव को प्रमाद से युक्त कर देता है।।
 '),
('7a1835da-12a2-545d-912c-b141811ebbd6'::uuid, '704e6bd1-354d-58f9-beeb-fd502170b917'::uuid, 'ramsukhdas', 'hindi', '।।14.10।।हे भरतवंशोद्भव अर्जुन ! रजोगुण और तमोगुणको दबाकर सत्त्वगुण सत्त्वगुण, और तमोगुणको दबाकर रजोगुण, वैसे ही सत्त्वगुण और रजोगुणको दबाकर तमोगुण बढ़ता है।'),
('5bce6b57-6625-5d21-aa2a-b7361ccb1250'::uuid, '704e6bd1-354d-58f9-beeb-fd502170b917'::uuid, 'tejomayananda', 'hindi', '।।14.10।। हे भारत ! कभी रज और तम को अभिभूत (दबा) करके सत्त्वगुण की वृद्धि होती है, कभी रज और सत्त्व को दबाकर तमोगुण की वृद्धि होती है, तो कभी तम और सत्त्व को अभिभूत कर रजोगुण की वृद्धि होती है।।
 '),
('977b5e1e-5594-509d-bb27-80f1efd6705d'::uuid, '5e260453-9835-5d7f-98b6-e9ba5e6f5d3f'::uuid, 'ramsukhdas', 'hindi', '।।14.11।।जब इस मनुष्यशरीरमें सब द्वारों-(इन्द्रियों और अन्तःकरण-) में प्रकाश (स्वच्छता) और ज्ञान (विवेक) प्रकट हो जाता है, तब जानना चाहिये कि सत्त्वगुण बढ़ा हुआ है।'),
('373e2cbb-5b13-5194-aff3-725cd601da39'::uuid, '5e260453-9835-5d7f-98b6-e9ba5e6f5d3f'::uuid, 'tejomayananda', 'hindi', '।।14.11।। जब इस देह के द्वारों अर्थात् समस्त इन्द्रियों में ज्ञानरूप प्रकाश उत्पन्न होता है, तब सत्त्वगुण को प्रवृद्ध हुआ जानो।।
 '),
('75a9a28e-bd90-5945-9db0-e47f27e8dc8a'::uuid, '15b065a1-af85-5564-938c-52c64c667ccf'::uuid, 'ramsukhdas', 'hindi', '।।14.12।।हे भरतवंशमें श्रेष्ठ अर्जुन ! रजोगुणके बढ़नेपर लोभ, प्रवृत्ति, कर्मोंका आरम्भ, अशान्ति और स्पृहा -- ये वृत्तियाँ पैदा होती हैं।'),
('04ab6ae2-b1bb-5ee2-b1af-1540873d3413'::uuid, '15b065a1-af85-5564-938c-52c64c667ccf'::uuid, 'tejomayananda', 'hindi', '।।14.12।। हे भरत-श्रेष्ठ ! रजोगुण के प्रवृद्ध होने पर लोभ, प्रवृत्ति (सामान्य चेष्टा) कर्मों का आरम्भ, शम का अभाव तथा स्पृहा, ये सब उत्पन्न होते हैं।।
 '),
('953cc6f5-9709-5a64-832d-e9065795af1f'::uuid, '6bb07e5f-6b70-5e92-8f9d-fe02e4dcb0d3'::uuid, 'ramsukhdas', 'hindi', '।।14.13।।हे कुरुनन्दन ! तमोगुणके बढ़नेपर अप्रकाश, अप्रवृत्ति, प्रमाद और मोह -- ये वृत्तियाँ भी पैदा होती हैं।'),
('765a786e-8702-5991-acd2-f7898cbe1fe3'::uuid, '6bb07e5f-6b70-5e92-8f9d-fe02e4dcb0d3'::uuid, 'tejomayananda', 'hindi', '।।14.13।। हे कुरुनन्दन ! तमोगुण के प्रवृद्ध होने पर अप्रकाश, अप्रवृत्ति, प्रमाद और मोह ये सब उत्पन्न होते हैं।।
 '),
('58147440-a793-5f32-a02a-fa17df2d9479'::uuid, 'b291ca93-dd01-52b0-95c2-44dc8992a08d'::uuid, 'ramsukhdas', 'hindi', '।।14.14।।जिस समय सत्त्वगुण बढ़ा हो, उस समय यदि देहधारी मनुष्य मर जाता है, तो वह,उत्तमवेत्ताओंके निर्मल लोकोंमें जाता है।'),
('a4a2eb9d-1469-5f0c-8455-4ed4b5b73d35'::uuid, 'b291ca93-dd01-52b0-95c2-44dc8992a08d'::uuid, 'tejomayananda', 'hindi', '।।14.14।। जब यह जीव (देहभृत्) सत्त्वगुण की प्रवृद्धि में मृत्यु को प्राप्त होता है, तब उत्तम कर्म करने वालों के निर्मल अर्थात् स्वर्गादि लोकों को प्राप्त होता है।।
 '),
('35586bee-22d4-5d30-8f1b-59166980ec39'::uuid, '4b519ef7-1365-55e0-bfc2-32365e90b85d'::uuid, 'ramsukhdas', 'hindi', '।।14.15।।रजोगुणके बढ़नेपर मरनेवाला प्राणी मनुष्ययोनिमें जन्म लेता है तथा तमोगुणके बढ़नेपर मरनेवाला मूढ़योनियोंमें जन्म लेता है।'),
('04dabd38-d872-5875-975b-da7e726f670b'::uuid, '4b519ef7-1365-55e0-bfc2-32365e90b85d'::uuid, 'tejomayananda', 'hindi', '।।14.15।। रजोगुण के प्रवृद्ध काल में मृत्यु को प्राप्त होकर कर्मासक्ति वाले (मनुष्य) लोक में वह जन्म लेता है तथा तमोगुण के प्रवृद्धकाल में (मरण होने पर) मूढ़योनि में जन्म लेता है।।'),
('8b8f8073-78bd-53b5-a6d3-1099f4f4ed77'::uuid, '4003b52a-9f9e-5fe3-b673-d0801139a377'::uuid, 'ramsukhdas', 'hindi', '।।14.16।।(विवेकी पुरुषोंने) शुभ-कर्मका तो सात्त्विक निर्मल फल कहा है, राजस कर्मका फल दुःख कहा है और तामस कर्मका फल अज्ञान (मूढ़ता) कहा है।'),
('cae2e170-f8c1-578b-8c35-f6f57234f1bb'::uuid, '4003b52a-9f9e-5fe3-b673-d0801139a377'::uuid, 'tejomayananda', 'hindi', '।।14.16।। शुभ कर्म का फल सात्विक और निर्मल कहा गया है; रजोगुण का फल दु;ख और तमोगुण का फल अज्ञान है।।
 '),
('bdd7b5e9-f544-5974-bf2b-2f2def89bcb2'::uuid, '2440892d-75fe-5a6f-85f5-699df601d4a1'::uuid, 'ramsukhdas', 'hindi', '।।14.17।।सत्त्वगुणसे ज्ञान और रजोगुणसे लोभ आदि ही उत्पन्न होते हैं; तमोगुणसे प्रमाद, मोह एवं अज्ञान भी उत्पन्न होता है।'),
('fab4f1a1-cd78-538d-9997-e22e1856c770'::uuid, '2440892d-75fe-5a6f-85f5-699df601d4a1'::uuid, 'tejomayananda', 'hindi', '।।14.17।। सत्त्वगुण से ज्ञान उत्पन्न होता है। रजोगुण से लोभ तथा तमोगुण से प्रमाद, मोह और अज्ञान उत्पन्न होता है।।
 '),
('c043cb7b-22db-5904-85ff-2fc056031370'::uuid, '01baba3e-ee6a-5950-8000-da5f7ac59528'::uuid, 'ramsukhdas', 'hindi', '।।14.18।।सत्त्वगुणमें स्थित मनुष्य ऊर्ध्वलोकोंमें जाते हैं, रजोगुणमें स्थित मनुष्य मृत्युलोकमें जन्म लेते हैं और निन्दनीय तमोगुणकी वृत्तिमें स्थित मनुष्य अधोगतिमें जाते हैं।'),
('3b6ef0b8-65c7-5ba1-a2cc-5f104e53435e'::uuid, '01baba3e-ee6a-5950-8000-da5f7ac59528'::uuid, 'tejomayananda', 'hindi', '।।14.18।। सत्त्वगुण में स्थित पुरुष उच्च (लोकों को) जाते हैं; राजस पुरुष मध्य (मनुष्य लोक) में रहते हैं और तमोगुण की अत्यन्त हीन प्रवृत्तियों में स्थित तामस लोग अधोगति को प्राप्त होते हैं।।
 '),
('da4cea31-1a25-53b7-baed-225fed1008e8'::uuid, 'aaddc709-5c25-51a5-9be1-a3d3613de255'::uuid, 'ramsukhdas', 'hindi', '।।14.19।।जब विवेकी (विचारकुशल) मनुष्य तीनों गुणोंके सिवाय अन्य किसीको कर्ता नहीं देखता और अपनेको गुणोंसे पर अनुभव करता है, तब वह मेरे स्वरूपको प्राप्त हो जाता है।'),
('92e0d531-f794-5abe-a10d-335622b1b18f'::uuid, 'aaddc709-5c25-51a5-9be1-a3d3613de255'::uuid, 'tejomayananda', 'hindi', '।।14.19।। जब द्रष्टा (साधक) पुरुष तीनों गुणों के अतिरिक्त किसी अन्य को कर्ता नहीं देखता, अर्थात् नहीं समझता है और तीनों गुणों से परे मेरे तत्व को जानता है, तब वह मेरे स्वरूप को प्राप्त होता है।।
 '),
('67aad231-9ac1-50ef-bfa0-bb152a4f6e4c'::uuid, '02666ffc-fd3a-5a68-91f5-d081a6c139fa'::uuid, 'ramsukhdas', 'hindi', '।।14.20।।देहधारी (विवेकी मनुष्य) देहको उत्पन्न करनेवाले इन तीनों गुणोंका अतिक्रमण करके जन्म, मृत्यु और वृद्धावस्थारूप दुःखोंसे रहित हुआ अमरताका अनुभव करता है।'),
('faa80efa-d08d-5a2a-877e-2ab49c636df3'::uuid, '02666ffc-fd3a-5a68-91f5-d081a6c139fa'::uuid, 'tejomayananda', 'hindi', '।।14.20।। यह देही पुरुष शरीर की उत्पत्ति के कारणरूप तीनों गुणों से अतीत होकर जन्म, मृत्यु, जरा और दु:खों से विमुक्त हुआ अमृतत्व को प्राप्त होता है।।
 '),
('9bb9fd94-f93b-5e82-adca-13b049a7216e'::uuid, 'f09ea791-acd2-5c87-851f-f1ae61bcdf06'::uuid, 'ramsukhdas', 'hindi', '।।14.21।।अर्जुन बोले -- हे प्रभो ! इन तीनों गुणोंसे अतीत हुआ मनुष्य किन लक्षणोंसे युक्त होता है? उसके आचरण कैसे होते हैं? और इन तीनों गुणोंका अतिक्रमण कैसे किया जा सकता है?'),
('ffa00094-8521-5d32-8869-2541bbe2a2fd'::uuid, 'f09ea791-acd2-5c87-851f-f1ae61bcdf06'::uuid, 'tejomayananda', 'hindi', '।।14.21।। अर्जुन ने कहा -- हे प्रभो ! इन तीनो गुणों से अतीत हुआ पुरुष किन लक्षणों से युक्त होता है ? वह किस प्रकार के आचरण वाला होता है ? और, वह किस उपाय से इन तीनों गुणों से अतीत होता है।।
 '),
('7ceb8822-a960-5dc3-be11-92bf016a55f8'::uuid, 'd7a56820-f559-55e6-9fab-c81af6ecb67c'::uuid, 'ramsukhdas', 'hindi', '।।14.22।।श्रीभगवान् बोले -- हे पाण्डव ! प्रकाश, प्रवृत्ति तथा मोह -- ये सभी अच्छी तरहसे प्रवृत्त हो जायँ तो भी गुणातीत मनुष्य इनसे द्वेष नहीं करता, और ये सभी निवृत्त हो जायँ तो इनकी इच्छा नहीं करता।'),
('7ce68700-1089-5810-8aab-0a16dddd56e8'::uuid, 'd7a56820-f559-55e6-9fab-c81af6ecb67c'::uuid, 'tejomayananda', 'hindi', '।।14.22।। श्रीभगवान् ने कहा -- हे पाण्डव ! (ज्ञानी पुरुष) प्रकाश, प्रवृत्ति और मोह के प्रवृत्त होने पर भी उनका द्वेष नहीं करता तथा निवृत्त होने पर उनकी आकांक्षा नहीं करता है।।
 '),
('c556ea01-f7a9-56fb-806d-64bd73cfcd0c'::uuid, 'dda9481c-23c6-5565-9055-ce989eb04602'::uuid, 'ramsukhdas', 'hindi', '।।14.23।।जो उदासीनकी तरह स्थित है और जो गुणोंके द्वारा विचलित नहीं किया जा सकता तथा गुण ही (गुणोंमें) बरत रहे हैं -- इस भावसे जो अपने स्वरूपमें ही स्थित रहता है और स्वयं कोई भी चेष्टा नहीं करता।'),
('35f85013-15d4-5962-aaa0-34b65b7a8fd8'::uuid, 'dda9481c-23c6-5565-9055-ce989eb04602'::uuid, 'tejomayananda', 'hindi', '।।14.23।। जो उदासीन के समान आसीन होकर गुणों के द्वारा विचलित नहीं किया जा सकता और "गुण ही व्यवहार करते हैं" ऐसा जानकर स्थित रहता है और उस स्थिति से विचलित नहीं होता।।
 '),
('7302d6d9-03d2-507c-b84a-7db77c1fe555'::uuid, '88ea8075-7b23-562f-b6f1-0738aeac2288'::uuid, 'ramsukhdas', 'hindi', '।।14.24।।जो धीर मनुष्य सुख-दुःखमें सम तथा अपने स्वरूपमें स्थित रहता है; जो मिट्टीके ढेले, पत्थर और सोनेमें सम रहता है जो प्रिय-अप्रियमें तथा अपनी निन्दा-स्तुतिमें सम रहता है; जो मान-अपमानमें तथा मित्र-शत्रुके पक्षमें सम रहता है जो सम्पूर्ण कर्मोंके आरम्भका त्यागी है, वह मनुष्य गुणातीत कहा जाता है।'),
('4d40dd86-d91a-5aa5-aaa9-d8387c7a10be'::uuid, '88ea8075-7b23-562f-b6f1-0738aeac2288'::uuid, 'tejomayananda', 'hindi', '।।14.24।। जो स्वस्थ (स्वरूप में स्थित), सुख-दु:ख में समान रहता है तथा मिट्टी, पत्थर और स्वर्ण में समदृष्टि रखता है; ऐसा वीर पुरुष प्रिय और अप्रिय को तथा निन्दा और आत्मस्तुति को तुल्य समझता है।।
 '),
('af27f41a-a68c-5c23-b9fc-44de8a0c015b'::uuid, '37a7ef21-7fac-58ad-a378-013ac979c7f0'::uuid, 'ramsukhdas', 'hindi', '।।14.25।।जो धीर मनुष्य सुख-दुःखमें सम तथा अपने स्वरूपमें स्थित रहता है; जो मिट्टीके ढेले, पत्थर और सोनेमें सम रहता है जो प्रिय-अप्रियमें तथा अपनी निन्दा-स्तुतिमें सम रहता है जो मान-अपमानमें तथा मित्र-शत्रुके पक्षमें सम रहता है; जो सम्पूर्ण कर्मोंके आरम्भका त्यागी है, वह मनुष्य गुणातीत कहा जाता है।'),
('7e794a89-71fb-52c4-9176-693536c401fb'::uuid, '37a7ef21-7fac-58ad-a378-013ac979c7f0'::uuid, 'tejomayananda', 'hindi', '।।14.25।। जो मान और अपमान में सम है; शत्रु और मित्र के पक्ष में भी सम है, ऐसा सर्वारम्भ परित्यागी पुरुष गुणातीत कहा जाता है।।
 '),
('58ae84b0-6a1e-58fa-9d62-b4c2f1bba302'::uuid, 'aec73186-508a-58d8-8e7b-6bc113dbde2a'::uuid, 'ramsukhdas', 'hindi', '।।14.26।।जो मनुष्य अव्यभिचारी भक्तियोगके द्वारा मेरा सेवन करता है, वह इन गुणोंका अतिक्रमण करके ब्रह्मप्राप्तिका पात्र हो जाता है।'),
('a6aa4573-1288-5187-9d37-cfd21c2eb660'::uuid, 'aec73186-508a-58d8-8e7b-6bc113dbde2a'::uuid, 'tejomayananda', 'hindi', '।।14.26।। जो पुरुष अव्यभिचारी भक्तियोग के द्वारा मेरी सेवा अर्थात् उपासना करता है, वह इन तीनों गुणों के अतीत होकर ब्रह्म बनने के लिये योग्य हो जाता है।।
 ')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('2588290d-b841-5c45-982c-21bd36c8b467'::uuid, '1cc99c2a-fc51-50f4-9034-20eca6cbcd11'::uuid, 'ramsukhdas', 'hindi', '।।14.27।।क्योंकि ब्रह्म, अविनाशी अमृत, शाश्वत धर्म और ऐकान्तिक सुखका आश्रय मैं ही हूँ।'),
('d77b54df-e43f-582f-b665-3d778c094a69'::uuid, '1cc99c2a-fc51-50f4-9034-20eca6cbcd11'::uuid, 'tejomayananda', 'hindi', '।।14.27।। क्योंकि मैं अमृत, अव्यय, ब्रह्म, शाश्वत धर्म और ऐकान्तिक अर्थात् पारमार्थिक सुख की प्रतिष्ठा हूँ।।'),
('d5537aa6-d583-5f53-b9f8-f0bbb35036a5'::uuid, '059071bd-9b23-5fc6-96f6-eb1941b58f87'::uuid, 'ramsukhdas', 'hindi', '।।15.1।। श्रीभगवान् बोले -- ऊपरकी ओर मूलवाले तथा नीचेकी ओर शाखावाले जिस संसाररूप अश्वत्थवृक्षको अव्यय कहते हैं और वेद जिसके पत्ते हैं, उस संसारवृक्षको जो जानता है, वह सम्पूर्ण वेदोंको जाननेवाला है।'),
('76432745-6f94-5410-8646-2d3240202007'::uuid, '059071bd-9b23-5fc6-96f6-eb1941b58f87'::uuid, 'tejomayananda', 'hindi', '।।15.1।। श्री भगवान् ने कहा -- (ज्ञानी पुरुष इस संसार वृक्ष को) ऊर्ध्वमूल और अध:शाखा वाला अश्वत्थ और अव्यय कहते हैं; जिसके पर्ण छन्द अर्थात् वेद हैं, ऐसे (संसार वृक्ष) को जो जानता है, वह वेदवित् है।।
 '),
('88edf1c8-a633-5d56-b1e3-1435737a6396'::uuid, '14c305d9-7774-5e86-8987-49b3f7621ae9'::uuid, 'ramsukhdas', 'hindi', '।।15.2।।उस संसारवृक्षकी गुणों-(सत्त्व, रज और तम-) के द्वारा बढ़ी हुई तथा विषयरूप कोंपलोंवाली शाखाएँ नीचे, मध्यमें और ऊपर सब जगह फैली हुई हैं। मनुष्यलोकमें कर्मोंके अनुसार बाँधनेवाले मूल भी नीचे और ऊपर (सभी लोकोंमें) व्याप्त हो रहे हैं।'),
('cc2cfbe3-a5ae-563b-91ac-89da95773394'::uuid, '14c305d9-7774-5e86-8987-49b3f7621ae9'::uuid, 'tejomayananda', 'hindi', '।।15.2।। उस वृक्ष की शाखाएं गुणों से प्रवृद्ध हुईं नीचे और ऊपर फैली हुईं हैं; (पंच) विषय इसके अंकुर हैं; मनुष्य लोक में कर्मों का अनुसरण करने वाली इसकी अन्य जड़ें नीचे फैली हुईं हैं।।
 '),
('6470f8e8-edfa-5fb4-b2ba-c2c48c687d2e'::uuid, '813c4de4-1839-50ea-a4d7-e9b27d2eca78'::uuid, 'ramsukhdas', 'hindi', '।।15.3।।इस संसारवृक्षका जैसा रूप देखनेमें आता है, वैसा यहाँ (विचार करनेपर) मिलता नहीं; क्योंकि इसका न तो आदि है, न अन्त है और न स्थिति ही है। इसलिये इस दृढ़ मूलोंवाले संसाररूप अश्वत्थवृक्षको दृढ़ असङ्गतारूप शस्त्रके द्वारा काटकर --'),
('37ad3715-f327-52e5-bdbb-2ba60f0f740d'::uuid, '813c4de4-1839-50ea-a4d7-e9b27d2eca78'::uuid, 'tejomayananda', 'hindi', '।।15.3।। इस (संसार वृक्ष) का स्वरूप जैसा कहा गया है वैसा यहाँ उपलब्ध नहीं होता है, क्योंकि इसका न आदि है और न अंत और न प्रतिष्ठा ही है। इस अति दृढ़ मूल वाले अश्वत्थ वृक्ष को दृढ़ असङ्ग शस्त्र से काटकर ...৷৷৷৷।।
 '),
('3fff795a-51fd-5616-bb13-538c18068d47'::uuid, '764cf22a-e5ad-521c-8cb3-c44ebf950199'::uuid, 'ramsukhdas', 'hindi', '।।15.4।।उसके बाद उस परमपद-(परमात्मा-) की खोज करनी चाहिये जिसको प्राप्त होनेपर मनुष्य फिर लौटकर संसारमें नहीं आते और जिससे अनादिकालसे चली आनेवाली यह सृष्टि विस्तारको प्राप्त हुई है, उस आदिपुरुष परमात्माके ही मैं शरण हूँ।'),
('76d73876-6764-5092-b8de-ea3c3b779dfc'::uuid, '764cf22a-e5ad-521c-8cb3-c44ebf950199'::uuid, 'tejomayananda', 'hindi', '।।15.4।। (तदुपरान्त) उस पद का अन्वेषण करना चाहिए जिसको प्राप्त हुए पुरुष पुन: संसार में नहीं लौटते हैं। "मैं उस आदि पुरुष की शरण हूँ, जिससे यह पुरातन प्रवृत्ति प्रसृत हुई है"।।
 '),
('33116a15-0dbd-57d6-b417-11279f4c7d42'::uuid, 'be2ee297-c202-521e-bc70-043c2518d84e'::uuid, 'ramsukhdas', 'hindi', '।।15.5।।जो मान और मोहसे रहित हो गये हैं, जिन्होंने आसक्तिसे होनेवाले दोषोंको जीत लिया है, जो नित्य-निरन्तर परमात्मामें ही लगे हुए हैं, जो (अपनी दृष्टिसे) सम्पूर्ण कामनाओंसे रहित हो गये हैं, जो सुख-दुःखरूप द्वन्द्वोंसे मुक्त हो गये हैं, ऐसे (ऊँची स्थितिवाले) मोहरहित साधक भक्त उस अविनाशी परमपद-(परमात्मा-) को प्राप्त होते हैं।'),
('c52c4c54-5791-5180-9fed-a48a2d3efa34'::uuid, 'be2ee297-c202-521e-bc70-043c2518d84e'::uuid, 'tejomayananda', 'hindi', '।।15.5।। जिनका मान और मोह निवृत्त हो गया है, जिन्होंने संगदोष को जीत लिया है, जो अध्यात्म में स्थित हैं जिनकी कामनाएं निवृत्त हो चुकी हैं और जो सुख-दु:ख नामक द्वन्द्वों से विमुक्त हो गये हैं, ऐसे सम्मोह रहित ज्ञानीजन उस अव्यय पद को प्राप्त होते हैं।।
 '),
('1dc835df-0732-53dc-baf1-d5b38478c19f'::uuid, 'c4e32aa4-aa7a-5864-b885-241797e1731e'::uuid, 'ramsukhdas', 'hindi', '।।15.6।।उस-(परमपद-) को न सूर्य, न चन्द्र और न अग्नि ही प्रकाशित कर सकती है; और जिसको प्राप्त होकर जीव लौटकर (संसारमें) नहीं आते, वही मेरा परमधाम है।'),
('0b480409-d9e6-564c-aaa0-68bec2424509'::uuid, 'c4e32aa4-aa7a-5864-b885-241797e1731e'::uuid, 'tejomayananda', 'hindi', '।।15.6।। उसे न सूर्य प्रकाशित कर सकता है और न चन्द्रमा और न अग्नि। जिसे प्राप्त कर मनुष्य पुन: (संसार को) नहीं लौटते हैं, वह मेरा परम धाम है।।
 '),
('288d5b70-41f5-5020-a292-7d45ef94df5d'::uuid, '3bd6ce47-4542-526b-9f6a-69c1ec7030de'::uuid, 'ramsukhdas', 'hindi', '।।15.7।।इस संसारमें जीव बना हुआ आत्मा मेरा ही सनातन अंश है; परन्तु वह प्रकृतिमें स्थित मन और पाँचों इन्द्रियोंको आकर्षित करता है (अपना मान लेता है)।'),
('a3031ba4-4c03-5649-9b0a-1eb83239f603'::uuid, '3bd6ce47-4542-526b-9f6a-69c1ec7030de'::uuid, 'tejomayananda', 'hindi', '।।15.7।। इस जीव लोक में मेरा ही एक सनातन अंश जीव बना है। वह प्रकृति में स्थित हुआ (देहत्याग के समय) पाँचो इन्द्रियों तथा मन को अपनी ओर खींच लेता है अर्थात् उन्हें एकत्रित कर लेता है।।'),
('c2b1b99e-2bc3-512a-b7c7-9204bdc6b598'::uuid, '21979f1f-586b-5b1c-9d9b-029c8e4bcd2d'::uuid, 'ramsukhdas', 'hindi', '।।15.8।।जैसे वायु गन्धके स्थानसे गन्धको ग्रहण करके ले जाती है, ऐसे ही शरीरादिका स्वामी बना हुआ जीवात्मा भी जिस शरीरको छोड़ता है, वहाँसे मनसहित इन्द्रियोंको ग्रहण करके फिर जिस शरीरको प्राप्त होता है, उसमें चला जाता है।'),
('3b4c6c3e-b52c-5286-9973-2a8b88d3196c'::uuid, '21979f1f-586b-5b1c-9d9b-029c8e4bcd2d'::uuid, 'tejomayananda', 'hindi', '।।15.8।। जब (देहादि का) ईश्वर (जीव) (एक शरीर से) उत्क्रमण करता है, तब इन (इन्द्रियों और मन) को ग्रहण कर अन्य शरीर में इस प्रकार ले जाता है, जैसे गन्ध के आश्रय (फूलादि) से गन्ध को वायु ले जाता है।।
 '),
('13c77079-982f-5260-be78-32fc5e7b94ac'::uuid, 'b89fde4b-3c2a-53a1-9928-dd76c8c005f5'::uuid, 'ramsukhdas', 'hindi', '।।15.9।।यह जीवात्मा मनका आश्रय लेकर श्रोत्र, नेत्र, त्वचा, रसना और घ्राण -- इन पाँचों इन्द्रियोंके द्वारा विषयोंका सेवन करता है।'),
('9ff220ac-bd9d-558e-902b-c7690a632330'::uuid, 'b89fde4b-3c2a-53a1-9928-dd76c8c005f5'::uuid, 'tejomayananda', 'hindi', '।।15.9।। (यह जीव) श्रोत्र, चक्षु, स्पर्शेन्द्रिय, रसना और घ्राण (नाक) इन इन्द्रियों तथा मन को आश्रय करके अर्थात् इनके द्वारा विषयों का सेवन करता है।।
 '),
('ab5ac21e-8488-5a61-9157-1d8a7dae5190'::uuid, 'e47d00bb-f01e-5493-ab08-1b87ae3a6641'::uuid, 'ramsukhdas', 'hindi', '।।15.10।।शरीरको छोड़कर जाते हुए या दूसरे शरीरमें स्थित हुए अथवा विषयोंको भोगते हुए भी गुणोंसे युक्त जीवात्माके स्वरूपको मूढ़ मनुष्य नहीं जानते, ज्ञानरूपी नेत्रोंवाले ज्ञानी मनुष्य ही जानते हैं।'),
('44c01e9c-2841-5af7-86ba-719860ea4598'::uuid, 'e47d00bb-f01e-5493-ab08-1b87ae3a6641'::uuid, 'tejomayananda', 'hindi', '।।15.10।। शरीर को त्यागते हुये, उसमें स्थित हुये अथवा (विषयों को) भोगते हुये, गुणों से समन्वित आत्मा को विमूढ़ लोग नहीं देखते हैं; (परन्तु) ज्ञानचक्षु वाले पुरुष उसे देखते हैं।।
 '),
('dc3fc0e8-3639-5cc4-973e-72d9a7651414'::uuid, '4e415eee-9fa6-55d8-bc7d-31c83e48d5af'::uuid, 'ramsukhdas', 'hindi', '।।15.11।।यत्न करनेवाले योगीलोग अपने-आपमें स्थित इस परमात्मतत्त्वका अनुभव करते हैं। परन्तु जिन्होंने अपना अन्तःकरण शुद्ध नहीं किया है, ऐसे अविवेकी मनुष्य यत्न करनेपर भी इस तत्त्वका अनुभव नहीं करते।'),
('3bf6d7e5-373e-5390-9ce6-43631847e09c'::uuid, '4e415eee-9fa6-55d8-bc7d-31c83e48d5af'::uuid, 'tejomayananda', 'hindi', '।।15.11।। योगीजन प्रयत्न करते हुये ही अपने हृदय में स्थित आत्मा को देखते हैं, जब कि अशुद्ध अन्त:करण वाले (अकृतात्मान:) और अविवेकी (अचेतस:) लोग यत्न करते हुये भी इसे नहीं देखते हैं।।
 '),
('e7988a4d-c307-54dd-aa4f-9152a7993b39'::uuid, '7268f639-de20-58c2-b2ef-056e4ab843b9'::uuid, 'ramsukhdas', 'hindi', '।।15.12।।सूर्यमें आया हुआ जो तेज सम्पूर्ण जगत् को प्रकाशित करता है और जो तेज चन्द्रमामें है तथा जो तेज अग्निमें है, उस तेजको मेरा ही जान।'),
('0eaaa5be-e8a2-52cd-a2a3-a7bd33606149'::uuid, '7268f639-de20-58c2-b2ef-056e4ab843b9'::uuid, 'tejomayananda', 'hindi', '।।15.12।। जो तेज सूर्य में स्थित होकर सम्पूर्ण जगत् को प्रकाशित करता है तथा जो तेज चन्द्रमा में है और अग्नि में है, उस तेज को तुम मेरा ही जानो।।
 '),
('ee3e277d-9ebd-5ce8-9979-588a55180d82'::uuid, '48729d23-58a3-57fd-9366-210980550377'::uuid, 'ramsukhdas', 'hindi', '।।15.13।।मैं ही पृथ्वीमें प्रविष्ट होकर अपनी शक्तिसे समस्त प्राणियोंको धारण करता हूँ; और मैं ही रसमय चन्द्रमाके रूपमें समस्त ओषधियों-(वनस्पतियों-) को पुष्ट करता हूँ।'),
('10f6df44-58a0-579f-84db-27cc8a3dddef'::uuid, '48729d23-58a3-57fd-9366-210980550377'::uuid, 'tejomayananda', 'hindi', '।।15.13।। मैं ही पृथ्वी में प्रवेश करके अपने ओज से भूतमात्र को धारण करता हूँ और रसस्वरूप चन्द्रमा बनकर समस्त औषधियों का अर्थात् वनस्पतियों का पोषण करता हूँ।।'),
('1ba3507c-a359-5d24-9da7-a7ab797c30aa'::uuid, 'bc26eedd-b0f9-5f9b-8b93-5052da2e1b9a'::uuid, 'ramsukhdas', 'hindi', '।।15.14।।प्राणियोंके शरीरमें रहनेवाला मैं प्राण-अपानसे युक्त वैश्वानर होकर चार प्रकारके अन्नको पचाता हूँ।'),
('59d9b4a2-47da-5d3a-8bd0-1e7bc2403b4d'::uuid, 'bc26eedd-b0f9-5f9b-8b93-5052da2e1b9a'::uuid, 'tejomayananda', 'hindi', '।।15.14।। मैं ही समस्त प्राणियों के देह में स्थित वैश्वानर अग्निरूप होकर प्राण और अपान से युक्त चार प्रकार के अन्न को पचाता हूँ।।'),
('7531723a-9f6a-52f9-8118-af6e380dbcea'::uuid, 'afd2c905-bfb8-59c7-98ec-b3610a68d578'::uuid, 'ramsukhdas', 'hindi', '।।15.15।।मैं सम्पूर्ण प्राणियोंके हृदयमें स्थित हूँ। मेरेसे ही स्मृति, ज्ञान और अपोहन (संशय आदि दोषोंका नाश) होता है। सम्पूर्ण वेदोंके द्वारा मैं ही जाननेयोग्य हूँ। वेदोंके तत्त्वका निर्णय करनेवाला और वेदोंको जाननेवाला भी मैं ही हूँ।'),
('665defed-c19e-5d15-be49-2a185e07a4d1'::uuid, 'afd2c905-bfb8-59c7-98ec-b3610a68d578'::uuid, 'tejomayananda', 'hindi', '।।15.15।। मैं ही समस्त प्राणियों के हृदय में स्थित हूँ। मुझसे ही स्मृति, ज्ञान और अपोहन (उनका अभाव) होता है। समस्त वेदों के द्वारा मैं ही वेद्य (जानने योग्य) वस्तु हूँ तथा वेदान्त का और वेदों का ज्ञाता भी मैं ही हूँ।।
 '),
('ced9ef1d-d5c2-5d4a-8e59-fa64bf5122f7'::uuid, '8ccb610e-cb9c-51d0-b3d4-df36ca437d44'::uuid, 'ramsukhdas', 'hindi', '।।15.16।।इस संसारमें क्षर (नाशवान्) और अक्षर (अविनाशी) -- ये दो प्रकारके पुरुष हैं। सम्पूर्ण प्राणियोंके शरीर नाशवान् और कूटस्थ (जीवात्मा) अविनाशी कहा जाता है।'),
('ddad7da9-a9e9-5c00-a51a-61e0376c52c3'::uuid, '8ccb610e-cb9c-51d0-b3d4-df36ca437d44'::uuid, 'tejomayananda', 'hindi', '।।15.16।। इस लोक में क्षर (नश्वर) और अक्षर (अनश्वर) ये दो पुरुष हैं, समस्त भूत क्षर हैं और ''कूटस्थ'' अक्षर कहलाता है।।
 '),
('87d464b3-7757-5cf3-af58-c3262ad7448b'::uuid, 'a14ae631-ea7b-5780-96a5-950f6eb537c8'::uuid, 'ramsukhdas', 'hindi', '।।15.17।।उत्तम पुरुष तो अन्य ही है, जो परमात्मा नामसे कहा गया है। वही अविनाशी ईश्वर तीनों लोकोंमें प्रविष्ट होकर सबका भरण-पोषण करता है।'),
('bb79be4f-fb48-50be-b18e-a0613e189040'::uuid, 'a14ae631-ea7b-5780-96a5-950f6eb537c8'::uuid, 'tejomayananda', 'hindi', '।।15.17।। परन्तु उत्तम पुरुष अन्य ही है, जो परमात्मा कहलाता है और जो तीनों लोकों में प्रवेश करके सबका धारण करने वाला अव्यय ईश्वर है।।
 '),
('8cd1953c-4184-58c0-8f0d-96e46f886df1'::uuid, '2c2ab205-1342-5db2-b2bd-e6856e426d11'::uuid, 'ramsukhdas', 'hindi', '।।15.18।।मैं क्षरसे अतीत हूँ और अक्षरसे भी उत्तम हूँ, इसलिये लोकमें और वेदमें पुरुषोत्तम नामसे प्रसिद्ध हूँ।'),
('fdc3f160-3c4a-5568-a9c1-4e1e72830ccc'::uuid, '2c2ab205-1342-5db2-b2bd-e6856e426d11'::uuid, 'tejomayananda', 'hindi', '।।15.18।। क्योंकि मैं क्षर से अतीत हूँ और अक्षर से भी उत्तम हूँ, इसलिये लोक में और वेद में भी पुरुषोत्तम के नाम से प्रसिद्ध हूँ।।
 '),
('71ef7047-0fab-5376-8d2a-e4babf71c1c1'::uuid, '81905a09-cba3-5b8a-bce8-a43f0f1ceb77'::uuid, 'ramsukhdas', 'hindi', '।।15.19।।हे भरतवंशी अर्जुन ! इस प्रकार जो मोहरहित मनुष्य मुझे पुरुषोत्तम जानता है, वह सर्वज्ञ सब प्रकारसे मेरा ही भजन करता है।'),
('81b92cdc-18d4-5ccd-8679-b95bf9da9291'::uuid, '81905a09-cba3-5b8a-bce8-a43f0f1ceb77'::uuid, 'tejomayananda', 'hindi', '।।15.19।। हे भारत ! इस प्रकार, जो, संमोहरहित, पुरुष मुझ पुरुषोत्तम को जानता है, वह सर्वज्ञ होकर सम्पूर्ण भाव से अर्थात् पूर्ण हृदय से मेरी भक्ति करता है।।
 '),
('0aa05ed6-0a3e-5030-9997-632b32eff473'::uuid, '868d3fea-ae92-5bd4-876e-8d49669892b8'::uuid, 'ramsukhdas', 'hindi', '।।15.20।।हे निष्पाप अर्जुन ! इस प्रकार यह अत्यन्त गोपनीय शास्त्र मेरे द्वारा कहा गया है। हे भरतवंशी अर्जुन ! इसको जानकर मनुष्य ज्ञानवान् (तथा प्राप्त-प्राप्तव्य) और कृतकृत्य हो जाता है।'),
('fd0407ef-37ef-56cc-8b57-6f6ebeb6cc0a'::uuid, '868d3fea-ae92-5bd4-876e-8d49669892b8'::uuid, 'tejomayananda', 'hindi', '।।15.20।। हे निष्पाप भारत ! इस प्रकार यह गुह्यतम शास्त्र मेरे द्वारा कहा गया, इसको जानकर मनुष्य बुद्धिमान और कृतकृत्य हो जाता है।।'),
('2f29bb5c-a85a-538c-a94a-5701333f641c'::uuid, 'edc758e4-b03b-5d3e-b77d-6119d6788ea5'::uuid, 'ramsukhdas', 'hindi', '।।16.1।।श्रीभगवान् बोले -- भयका सर्वथा अभाव; अन्तःकरणकी शुद्धि; ज्ञानके लिये योगमें दृढ़ स्थिति; सात्त्विक दान; इन्द्रियोंका दमन; यज्ञ; स्वाध्याय; कर्तव्य-पालनके लिये कष्ट सहना; शरीर-मन-वाणीकी सरलता।'),
('c7bb120d-b496-53e0-add2-efdb066d10bc'::uuid, 'edc758e4-b03b-5d3e-b77d-6119d6788ea5'::uuid, 'tejomayananda', 'hindi', '।।16.1।। श्री भगवान् ने कहा -- अभय, अन्त:करण की शुद्धि, ज्ञानयोग में दृढ़ स्थिति, दान, दम, यज्ञ, स्वाध्याय, तप और आर्जव।।
 '),
('d0bd93c0-4335-5ba5-9ff6-aed36410e415'::uuid, '0b69a6af-0b16-5a43-b214-2afd1081bb3f'::uuid, 'ramsukhdas', 'hindi', '।।16.2।।अहिंसा, सत्यभाषण; क्रोध न करना; संसारकी कामनाका त्याग; अन्तःकरणमें राग-द्वेषजनित हलचलका न होना; चुगली न करना; प्राणियोंपर दया करना सांसारिक विषयोंमें न ललचाना; अन्तःकरणकी कोमलता; अकर्तव्य करनेमें लज्जा; चपलताका अभाव।'),
('03bfad3a-fb11-533c-8490-72820c7283ef'::uuid, '0b69a6af-0b16-5a43-b214-2afd1081bb3f'::uuid, 'tejomayananda', 'hindi', '।।16.2।। अहिंसा, सत्य, क्रोध का अभाव, त्याग, शान्ति, अपैशुनम् (किसी की निन्दा न करना), भूतमात्र के प्रति दया, अलोलुपता , मार्दव (कोमलता), लज्जा, अचंचलता।।
 '),
('e21350b9-1279-5ded-ae97-0a83ff71da0d'::uuid, '33f7758d-ed19-5061-b841-ccca81125358'::uuid, 'ramsukhdas', 'hindi', '।।16.3।।तेज (प्रभाव), क्षमा, धैर्य, शरीरकी शुद्धि, वैरभावका न रहना और मानको न चाहना, हे भरतवंशी अर्जुन ! ये सभी दैवी सम्पदाको प्राप्त हुए मनुष्यके लक्षण हैं।'),
('770a50f8-0042-567d-ade7-b13739bf6503'::uuid, '33f7758d-ed19-5061-b841-ccca81125358'::uuid, 'tejomayananda', 'hindi', '।।16.3।। हे भारत ! तेज, क्षमा, धैर्य, शौच (शुद्धि), अद्रोह और अतिमान (गर्व) का अभाव ये सब दैवी संपदा को प्राप्त पुरुष के लक्षण हैं।।
 '),
('34d521ef-48d5-517d-b600-a1bc76d6accb'::uuid, '8920b850-00f8-52fd-91a7-a444ad0cca0d'::uuid, 'ramsukhdas', 'hindi', '।।16.4।।हे पृथानन्दन ! दम्भ करना, घमण्ड करना, अभिमान करना, क्रोध करना, कठोरता रखना और अविवेकका होना भी -- ये सभी आसुरीसम्पदाको प्राप्त हुए मनुष्यके लक्षण हैं।'),
('5cd7a244-6b2d-539a-a209-e7da639a377f'::uuid, '8920b850-00f8-52fd-91a7-a444ad0cca0d'::uuid, 'tejomayananda', 'hindi', '।।16.4।। हे पार्थ ! दम्भ, दर्प, अभिमान, क्रोध, कठोर वाणी (पारुष्य) और अज्ञान यह सब आसुरी सम्पदा है।।
 '),
('dd9201a1-d1a9-53a6-930b-c4eef109d6dc'::uuid, '35fbbcca-a025-5c87-81fc-78796730a723'::uuid, 'ramsukhdas', 'hindi', '।।16.5।।दैवी-सम्पत्ति मुक्तिके लिये और आसुरी-सम्पत्ति बन्धनके लिये है। हे पाण्डव तुम दैवी-सम्पत्तिको प्राप्त हुए हो, इसलिये तुम्हें शोक (चिन्ता) नहीं करना चाहिये।'),
('2a968424-01b6-5e07-aefb-50b73f5ac359'::uuid, '35fbbcca-a025-5c87-81fc-78796730a723'::uuid, 'tejomayananda', 'hindi', '।।16.5।। हे पाण्डव ! दैवी सम्पदा मोक्ष के लिए और आसुरी सम्पदा बन्धन के लिए मानी गयी है, तुम शोक मत करो, क्योंकि तुम दैवी सम्पदा को प्राप्त हुए हो।।
 '),
('baa59d87-390e-5227-b33b-d255fb062bb3'::uuid, '07096359-2da5-5e15-83a8-fd2d6e801fde'::uuid, 'ramsukhdas', 'hindi', '।।16.6।।इस लोकमें दो तरहके प्राणियोंकी सृष्टि है -- दैवी और आसुरी। दैवीका तो मैंने विस्तारसे वर्णन कर दिया, अब हे पार्थ ! तुम मेरेसे आसुरीका विस्तार सुनो।'),
('4467194a-02cf-59f1-ae8d-f48650b1f493'::uuid, '07096359-2da5-5e15-83a8-fd2d6e801fde'::uuid, 'tejomayananda', 'hindi', '।।16.6।। हे पार्थ ! इस लोक में दो प्रकार की भूतिसृष्टि है, दैवी और आसुरी। उनमें देवों का स्वभाव (दैवी सम्पदा) विस्तारपूर्वक कहा गया है; अब असुरों के स्वभाव को विस्तरश: मुझसे सुनो।।
 '),
('2ae2369f-9f27-5e84-82fd-cd25a87fa90e'::uuid, 'a2629eb4-66d9-5b6b-be63-e4a198d20cec'::uuid, 'ramsukhdas', 'hindi', '।।16.7।।आसुरी प्रकृतिवाले मनुष्य प्रवृत्ति और निवृत्तिको नहीं जानते और उनमें न बाह्यशुद्धि, न श्रेष्ठ आचरण तथा न सत्य-पालन ही होता है।'),
('b005504e-d96f-54fa-89e1-7fbe62ed3991'::uuid, 'a2629eb4-66d9-5b6b-be63-e4a198d20cec'::uuid, 'tejomayananda', 'hindi', '।।16.7।। आसुरी स्वभाव के लोग न प्रवृत्ति को; जानते हैं और न निवृत्ति को उनमें न शुद्धि होती है, न सदाचार और न सत्य ही होता है।।
 '),
('6625ca37-7dd0-56ae-8243-04d9411f45bc'::uuid, '38e94d6d-2816-5e1d-b72f-5913911805f8'::uuid, 'ramsukhdas', 'hindi', '।।16.8।।वे कहा करते हैं कि संसार असत्य, अप्रतिष्ठित और बिना ईश्वरके अपने-आप केवल स्त्री-पुरुषके संयोगसे पैदा हुआ है। इसलिये काम ही इसका कारण है, और कोई कारण नहीं है।'),
('704079f0-e136-5d61-bb6a-30024b3d68fb'::uuid, '38e94d6d-2816-5e1d-b72f-5913911805f8'::uuid, 'tejomayananda', 'hindi', '।।16.8।। वे कहते हैं कि यह जगत् आश्रयरहित, असत्य और ईश्वर रहित है, यह (स्त्रीपुरुष के) परस्पर कामुक संबंध से ही उत्पन्न हुआ है, और (इसका कारण) क्या हो सकता है? 
 '),
('3f6a2f25-104b-55c6-81b9-ddaed3e58396'::uuid, 'f3652837-8d14-57ee-86e3-4d4cc027e172'::uuid, 'ramsukhdas', 'hindi', '।।16.9।।उपर्युक्त (नास्तिक) दृष्टिका आश्रय लेनेवाले जो मनुष्य अपने नित्य स्वरूपको नहीं मानते, जिनकी बुद्धि तुच्छ है, जो उग्रकर्मा और संसारके शत्रु हैं, उन मनुष्योंकी सामर्थ्यका उपयोग जगत्का नाश करनेके लिये ही होता है।'),
('37a64bbe-866a-5434-80a7-33bc57264be2'::uuid, 'f3652837-8d14-57ee-86e3-4d4cc027e172'::uuid, 'tejomayananda', 'hindi', '।।16.9।। इस दृष्टि का अवलम्बन करके नष्टस्वभाव के अल्प बुद्धि वाले, घोर कर्म करने वाले लोग जगत् के शत्रु (अहित चाहने वाले) के रूप में उसका नाश करने के लिए उत्पन्न होते हैं।।
 '),
('e10d84b6-b340-517c-9b3f-cd1a8a843524'::uuid, '135218ed-a0df-5d01-9548-71a06f1aebe6'::uuid, 'ramsukhdas', 'hindi', '।।16.10।।कभी पूरी न होनेवाली कामनाओंका आश्रय लेकर दम्भ, अभिमान और मदमें चूर रहनेवाले तथा अपवित्र व्रत धारण करनेवाले मनुष्य मोहके कारण दुराग्रहोंको धारण करके संसारमें विचरते रहते हैं।'),
('f162f638-b2be-59cf-b4b2-6f7474e11175'::uuid, '135218ed-a0df-5d01-9548-71a06f1aebe6'::uuid, 'tejomayananda', 'hindi', '।।16.10।। दम्भ, मान और मद से युक्त कभी न पूर्ण होने वाली कामनाओं का आश्रय लिये, मोहवश मिथ्या धारणाओं को ग्रहण करके ये अशुद्ध संकल्पों के लोग जगत् में कार्य करते हैं।।
 '),
('8123dbbf-a3d9-5f51-9dbf-7111a671bd72'::uuid, '630a4963-e675-5e8e-92df-1cd64fdc2d11'::uuid, 'ramsukhdas', 'hindi', '।।16.11।।वे मृत्युपर्यन्त रहनेवाली अपार चिन्ताओंका आश्रय लेनेवाले, पदार्थोंका संग्रह और उनका भोग करनेमें ही लगे रहनेवाले और ''जो कुछ है, वह इतना ही है'' -- ऐसा निश्चय करनेवाले होते हैं।'),
('2a3790c9-abbc-5264-a6be-7198a1700ab2'::uuid, '630a4963-e675-5e8e-92df-1cd64fdc2d11'::uuid, 'tejomayananda', 'hindi', '।।16.11।। मरणपर्यन्त रहने वाली अपरिमित चिन्ताओं से ग्रस्त और विषयोपभोग को ही परम लक्ष्य मानने वाले ये आसुरी लोग इस निश्चित मत के होते हैं कि "इतना ही (सत्य, आनन्द) है"।।
 '),
('d25f3fdd-27f4-51b5-89c3-3aa9e35947ee'::uuid, '6d1c1cab-de17-53a8-adb4-6671cb8f917d'::uuid, 'ramsukhdas', 'hindi', '।।16.12।।वे आशाकी सैकड़ों फाँसियोंसे बँधे हुए मनुष्य काम-क्रोधके परायण होकर पदार्थोंका भोग करनेके लिये अन्यायपूर्वक धन-संचय करनेकी चेष्टा करते रहते हैं।'),
('9660caec-04fd-5fce-9e2b-fffa1a60b228'::uuid, '6d1c1cab-de17-53a8-adb4-6671cb8f917d'::uuid, 'tejomayananda', 'hindi', '।।16.12।। सैकड़ों आशापाशों से बन्धे हुये, काम और क्रोध के वश में ये लोग विषयभोगों की पूर्ति के लिये अन्यायपूर्वक धन का संग्रह करने के लिये चेष्टा करते हैं।।
 '),
('ccd30627-19b1-5f51-ae89-39025feb2cc9'::uuid, '3b837f4e-d9c7-5645-8d85-65ef9c65d77d'::uuid, 'ramsukhdas', 'hindi', '।।16.13।।इतनी वस्तुएँ तो हमने आज प्राप्त कर लीं और अब इस मनोरथको प्राप्त (पूरा) कर लेंगे।,इतना धन तो हमारे पास है ही, इतना धन फिर हो जायगा।'),
('9d587291-536d-5392-9815-8da54ee8e96b'::uuid, '3b837f4e-d9c7-5645-8d85-65ef9c65d77d'::uuid, 'tejomayananda', 'hindi', '।।16.13।। मैंने आज यह पाया है और इस मनोरथ को भी प्राप्त करूंगा, मेरे पास यह इतना धन है और इससे भी अधिक धन भविष्य में होगा।।
 '),
('dc488907-6143-5bf1-bcf3-0c805987c821'::uuid, '3b90b65c-2e4a-5885-9821-b731ce22368b'::uuid, 'ramsukhdas', 'hindi', '।।16.14।।वह शत्रु तो हमारे द्वारा मारा गया और उन दूसरे शत्रुओंको भी हम मार डालेंगे। हम सर्वसमर्थ हैं। हमारे पास भोग-सामग्री बहुत है। हम सिद्ध हैं। हम बड़े बलवान् और सुखी हैं।'),
('c5bd86a2-e3e3-504b-b7e8-48000f16c2ca'::uuid, '3b90b65c-2e4a-5885-9821-b731ce22368b'::uuid, 'tejomayananda', 'hindi', '।।16.14।। "यह शत्रु मेरे द्वारा मारा गया है और दूसरे शत्रुओं को भी मैं मारूंगा", "मैं ईश्वर हूँ और भोगी हूँ", "मैं सिद्ध पुरुष हूँ", "मैं बलवान और सुखी हूँ",।।
 '),
('8223306f-99d4-5507-932a-6b98ec54cdc3'::uuid, 'b1fee6d7-70be-518d-9910-d2646df559e5'::uuid, 'ramsukhdas', 'hindi', '।।16.15।।हम धनवान् हैं, बहुत-से मनुष्य हमारे पास हैं, हमारे समान और कौन है? हम खूब यज्ञ करेंगे, दान देंगे और मौज करेंगे -- इस तरह वे अज्ञानसे मोहित रहते हैं।'),
('2fea8371-ee97-5696-b27b-0cc1ffc9c80b'::uuid, 'b1fee6d7-70be-518d-9910-d2646df559e5'::uuid, 'tejomayananda', 'hindi', '।।16.15।। "मैं धनवान् और श्रेष्ठकुल में जन्मा हूँ। मेरे समान दूसरा कौन है?",''मैं यज्ञ करूंगा'', ''मैं दान दूँगा'', ''मैं मौज करूँगा'' - इस प्रकार के अज्ञान से वे मोहित होते हैं।।
 '),
('ffaafa3f-58f3-51af-80ef-43efe5b68ac9'::uuid, 'b62b25cc-b33f-593b-8ff2-e248488632d8'::uuid, 'ramsukhdas', 'hindi', '।।16.16।।कामनाओंके कारण तरह-तरहसे भ्रमित चित्तवाले, मोह-जालमें अच्छी तरहसे फँसे हुए तथा पदार्थों और भोगोंमें अत्यन्त आसक्त रहनेवाले मनुष्य भयङ्कर नरकोंमें गिरते हैं।'),
('3c00cf77-e5b6-5fcb-b1dc-913740217cf3'::uuid, 'b62b25cc-b33f-593b-8ff2-e248488632d8'::uuid, 'tejomayananda', 'hindi', '।।16.16।। अनेक प्रकार से भ्रमित चित्त वाले, मोह जाल में फँसे तथा विषयभोगों में आसक्त ये लोग घोर, अपवित्र नरक में गिरते हैं।।
 '),
('b2455548-b137-5b01-918e-7e2266a690ec'::uuid, '12d161b9-7f05-5f33-a315-187ac5d27ad8'::uuid, 'ramsukhdas', 'hindi', '।।16.17।।अपनेको सबसे अधिक पूज्य माननेवाले, अकड़ रखनेवाले तथा धन और मानके मदमें चूर रहनेवाले वे मनुष्य दम्भसे अविधिपूर्वक नाममात्रके यज्ञोंसे यजन करते हैं।'),
('64291bdd-7f6c-5508-9f8b-c55cc4d8d444'::uuid, '12d161b9-7f05-5f33-a315-187ac5d27ad8'::uuid, 'tejomayananda', 'hindi', '।।16.17।। अपने आप को ही श्रेष्ठ मानने वाले, स्तब्ध (गर्वयुक्त), धन और मान के मद से युक्त लोग शास्त्रविधि से रहित केवल नाममात्र के यज्ञों द्वारा दम्भपूर्वक यजन करते हैं।।
 '),
('4c28bcd6-7073-5d36-b134-d14213064a49'::uuid, 'd5908165-abd1-5a9c-b49b-0312b99f6920'::uuid, 'ramsukhdas', 'hindi', '।।16.18।।वे अहङ्कार, हठ, घमण्ड, कामना और क्रोधका आश्रय लेनेवाले मनुष्य अपने और दूसरोंके शरीरमें रहनेवाले मुझ अन्तर्यामीके साथ द्वेष करते हैं तथा (मेरे और दूसरोंके गुणोंमें) दोष-दृष्टि रखते हैं।'),
('7b402eaa-37c6-5c68-a86f-11146afda85a'::uuid, 'd5908165-abd1-5a9c-b49b-0312b99f6920'::uuid, 'tejomayananda', 'hindi', '।।16.18।। अहंकार, बल, दर्प, काम और क्रोध के वशीभूत हुए परनिन्दा करने वाले ये लोग अपने और दूसरों के शरीर में स्थित मुझ (परमात्मा) से द्वेष करने वाले होते हैं।।
 '),
('1127e6b0-d0bd-5a6c-b82b-7689cee0deae'::uuid, '59929e2a-a87e-555c-9f52-094f46f8b609'::uuid, 'ramsukhdas', 'hindi', '।।16.19।।उन द्वेष करनेवाले, क्रूर स्वभाववाले और संसारमें महान् नीच, अपवित्र मनुष्योंको मैं बार-बार आसुरी योनियोंमें गिराता ही रहता हूँ।'),
('91328c32-bbdc-5b2f-a075-abd5100d6374'::uuid, '59929e2a-a87e-555c-9f52-094f46f8b609'::uuid, 'tejomayananda', 'hindi', '।।16.19।। ऐसे उन द्वेष करने वाले,  क्रूरकर्मी और नराधमों को मैं संसार में बारम्बार (अजस्रम्) आसुरी योनियों में ही गिराता हूँ अर्थात् उत्पन्न करता हूँ।।
 '),
('8f11e315-1c7f-5961-a7cd-78ac134ac39f'::uuid, 'cc1ddb45-35f4-5ea9-aaf2-b2146d586e86'::uuid, 'ramsukhdas', 'hindi', '।।16.20।।हे कुन्तीनन्दन ! वे मूढ मनुष्य मेरेको प्राप्त न करके ही जन्म-जन्मान्तरमें आसुरी योनिको प्राप्त होते हैं, फिर उससे भी अधिक अधम गतिमें अर्थात् भयङ्कर नरकोंमें चले जाते हैं।'),
('0f3e3b41-0693-59a0-a980-0d50f58fd7f5'::uuid, 'cc1ddb45-35f4-5ea9-aaf2-b2146d586e86'::uuid, 'tejomayananda', 'hindi', '।।16.20।। हे कौन्तेय ! वे मूढ़ पुरुष जन्मजन्मान्तर में आसुरी योनि को प्राप्त होते हैं और ( इस प्रकार) मुझे प्राप्त न होकर अधम गति को प्राप्त होते है।।
 '),
('6d7c933e-ed61-5f63-9d92-05c1a29cdf84'::uuid, '3436d539-f84f-5486-be7b-9b4495716ad9'::uuid, 'ramsukhdas', 'hindi', '।।16.21।।काम, क्रोध और लोभ -- ये तीन प्रकारके नरकके दरवाजे जीवात्माका पतन करनेवाले हैं, इसलिये इन तीनोंका त्याग कर देना चाहिये।'),
('793813a0-c2dd-5aac-9b65-d23b7cdb9f3d'::uuid, '3436d539-f84f-5486-be7b-9b4495716ad9'::uuid, 'tejomayananda', 'hindi', '।।16.21।। काम, क्रोध और लोभ ये आत्मनाश के त्रिविध द्वार हैं, इसलिए इन तीनों को त्याग देना चाहिए।।
 '),
('192c4237-e4ab-567b-8f75-cb4abcd3640b'::uuid, '998b9008-9af7-5818-a276-3b817f8ce93c'::uuid, 'ramsukhdas', 'hindi', '।।16.22।।हे कुन्तीनन्दन ! इन नरकके तीनों दरवाजोंसे रहित हुआ जो मनुष्य अपने कल्याणका आचरण करता है, वह परमगतिको प्राप्त हो जाता है।'),
('e0909416-7885-52fa-947f-e840e4769e9b'::uuid, '998b9008-9af7-5818-a276-3b817f8ce93c'::uuid, 'tejomayananda', 'hindi', '।।16.22।। हे कौन्तेय ! नरक के इन तीनों द्वारों से विमुक्त पुरुष अपने कल्याण के साधन का आचरण करता है और इस प्रकार परा गति को प्राप्त होता है।।
 '),
('e5dd3640-2a2f-5d3e-b253-18616af4568e'::uuid, 'e0fcd722-65cd-5701-9b23-698b7e4ee232'::uuid, 'ramsukhdas', 'hindi', '।।16.23।। जो मनुष्य शास्त्रविधिको छोड़कर अपनी इच्छासे मनमाना आचरण करता है, वह न सिद्धि-(अन्तःकरणकी शुद्धि-) को, न सुखको और न परमगतिको ही प्राप्त होता है।'),
('4655ca0f-a0b2-5675-b5b2-879655feda1a'::uuid, 'e0fcd722-65cd-5701-9b23-698b7e4ee232'::uuid, 'tejomayananda', 'hindi', '।।16.23।। जो पुरुष शास्त्रविधि को त्यागकर अपनी कामना से प्रेरित होकर ही कार्य करता है, वह न पूर्णत्व की सिद्धि प्राप्त करता है, न सुख और न परा गति।।
 '),
('703bf8b1-9920-5c0e-979e-d56036ec1a2f'::uuid, 'a925fa88-a53c-5743-947c-f2b138c56f66'::uuid, 'ramsukhdas', 'hindi', '।।16.24।।अतः तेरे लिये कर्तव्य-अकर्तव्यकी व्यवस्थामें शास्त्र ही प्रमाण है -- ऐसा जानकर तू इस लोकमें शास्त्र-विधिसे नियत कर्तव्य कर्म करनेयोग्य है।'),
('c4067d82-686f-54e9-b1e5-17a87798c485'::uuid, 'a925fa88-a53c-5743-947c-f2b138c56f66'::uuid, 'tejomayananda', 'hindi', '।।16.24।। इसलिए तुम्हारे लिए कर्तव्य और अकर्तव्य की व्यवस्था (निर्णय) में शास्त्र ही प्रमाण है शास्त्रोक्त विधान को जानकर तुम्हें अपने कर्म करने चाहिए।।'),
('60af2058-3249-5cf3-9b74-301750b7aa30'::uuid, '7b0a4903-1a30-5580-bbbc-9c48ed82ad71'::uuid, 'ramsukhdas', 'hindi', '।।17.1।। अर्जुन बोले -- हे कृष्ण ! जो मनुष्य शास्त्र-विधिका त्याग करके श्रद्धापूर्वक देवता आदिका पूजन करते हैं, उनकी निष्ठा फिर कौन-सी है? सात्त्विकी है अथवा राजसी-तामसी?'),
('36a61ed4-a16a-5530-a2a7-42f08318f705'::uuid, '7b0a4903-1a30-5580-bbbc-9c48ed82ad71'::uuid, 'tejomayananda', 'hindi', '।।17.1।। अर्जुन ने कहा -- हे कृष्ण ! जो लोग शास्त्रविधि को त्यागकर (केवल) श्रद्धा युक्त यज्ञ (पूजा) करते हैं, उनकी स्थिति (निष्ठा) कौन सी है ?क्या वह सात्त्विक है अथवा राजसिक या तामसिक ?
 '),
('84b11574-a556-56e6-8cc4-3f484b9a19fe'::uuid, '0d90172a-27f2-5682-83ec-f7c9c39230f7'::uuid, 'ramsukhdas', 'hindi', '।।17.2।।श्रीभगवान् बोले -- मनुष्योंकी वह स्वभावसे उत्पन्न हुई श्रद्धा सात्त्विकी तथा राजसी और तामसी -- ऐसे तीन तरहकी ही होती है, उसको तुम मेरेसे सुनो।'),
('778d0bb9-08ed-5f7a-a09b-ce9b86a01abe'::uuid, '0d90172a-27f2-5682-83ec-f7c9c39230f7'::uuid, 'tejomayananda', 'hindi', '।।17.2।। श्री भगवान् ने कहा -- देहधारियों (मनुष्यों) की वह स्वाभाविक (ज्ञानरहित) श्रद्धा तीन प्रकार की - सात्त्विक, राजसिक और तामसिक - होती हैं, उसे तुम मुझसे सुनो।।
 '),
('f5c460d8-4b0e-514f-b714-c5ad7c692565'::uuid, '2b285c7c-cb2f-516f-aa2b-1f5543ad6b62'::uuid, 'ramsukhdas', 'hindi', '।।17.3।।हे भारत ! सभी मनुष्योंकी श्रद्धा अन्तःकरणके अनुरूप होती है। यह मनुष्य श्रद्धामय है। इसलिये जो जैसी श्रद्धावाला है, वही उसका स्वरूप है अर्थात् वही उसकी निष्ठा -- स्थिति है।'),
('bc01e5f8-2388-5e5f-abc8-59fd5f169b85'::uuid, '2b285c7c-cb2f-516f-aa2b-1f5543ad6b62'::uuid, 'tejomayananda', 'hindi', '।।17.3।। हे भारत सभी मनुष्यों की श्रद्धा उनके सत्त्व (स्वभाव, संस्कार) के अनुरूप होती है। यह पुरुष श्रद्धामय है, इसलिए जो पुरुष जिस श्रद्धा वाला है वह स्वयं भी वही है अर्थात् जैसी जिसकी श्रद्धा वैसा ही उसका स्वरूप होता है।।
 '),
('84243186-9aa1-57fd-a01d-78e3ce7a38dd'::uuid, '1e55bf10-c62e-519a-b980-62fa7c774ef8'::uuid, 'ramsukhdas', 'hindi', '।।17.4।।सात्त्विक मनुष्य देवताओंका पूजन करते हैं, राजस मनुष्य यक्षों और राक्षसोंका और दूसरे जो तामस मनुष्य हैं, वे प्रेतों और भूतगणोंका पूजन करते हैं।'),
('63cdccfb-f6ef-56e0-b8e9-faf61584900f'::uuid, '1e55bf10-c62e-519a-b980-62fa7c774ef8'::uuid, 'tejomayananda', 'hindi', '।।17.4।। सात्त्विक पुरुष देवताओं को पूजते हैं और राजस लोग यक्ष और राक्षसों को, तथा अन्य तामसी जन प्रेत और भूतगणों को पूजते हैं।।
 '),
('edcdab5d-1ae7-5872-83fd-1817d60baa6e'::uuid, '035821de-6113-5553-ad55-c8a3c280dda2'::uuid, 'ramsukhdas', 'hindi', '।।17.5।।जो मनुष्य शास्त्रविधिसे रहित घोर तप करते हैं; जो दम्भ और अहङ्कारसे अच्छी तरह युक्त हैं; जो भोग-पदार्थ, आसक्ति और हठसे युक्त हैं; जो शरीरमें स्थित पाँच भूतोंको अर्थात् पाञ्चभौतिक शरीरको तथा अन्तःकरणमें स्थित मुझ परमात्माको भी कृश करनेवाले हैं उन अज्ञानियोंको तू आसुर निश्चयवाले (आसुरी सम्पदावाले) समझ।'),
('f22a0c24-afa4-5e72-b3da-20559c21d72a'::uuid, '035821de-6113-5553-ad55-c8a3c280dda2'::uuid, 'tejomayananda', 'hindi', '।।17.5।। जो लोग शास्त्रविधि से रहित घोर तप करते हैं तथा दम्भ, अहंकार, काम और राग से भी युक्त होते हैं।।
 ')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('aee95f67-9799-5e0c-89f3-b16b071be31e'::uuid, 'a05fd1d0-d6a1-5e67-8a15-4d7f96560484'::uuid, 'ramsukhdas', 'hindi', '।।17.6।।जो मनुष्य शास्त्रविधिसे रहित घोर तप करते हैं; जो दम्भ और अहङ्कारसे अच्छी तरह युक्त हैं; जो भोग-पदार्थ, आसक्ति और हठसे युक्त हैं; जो शरीरमें स्थित पाँच भूतोंको अर्थात् पाञ्चभौतिक शरीरको तथा अन्तःकरणमें स्थित मुझ परमात्माको भी कृश करनेवाले हैं उन अज्ञानियोंको तू आसुर निश्चयवाले (आसुरी सम्पदावाले) समझ।'),
('351322b0-814b-5365-ab8f-b439bdd91d99'::uuid, 'a05fd1d0-d6a1-5e67-8a15-4d7f96560484'::uuid, 'tejomayananda', 'hindi', '।।17.6।। और शरीरस्थ भूतसमुदाय को तथा मुझ अन्तर्यामी को भी कृश करने वाले अर्थात् कष्ट पहुँचाने वाले जो अविवेकी लोग हैं, उन्हें तुम आसुरी निश्चय वाले जानो।।
 '),
('f1748baf-e96c-522e-9111-b131c8dd0f84'::uuid, 'a889f697-d314-5b0d-8669-0d135b72ef5e'::uuid, 'ramsukhdas', 'hindi', '।।17.7।।आहार भी सबको तीन प्रकारका प्रिय होता है और वैसे ही यज्ञ, दान और तप भी तीन प्रकारके होते हैं अर्थात् शास्त्रीय कर्मोंमें भी तीन प्रकारकी रुचि होती है, तू उनके इस भेदको सुन।'),
('fdd7cc08-16bb-5c64-8eb8-41245ddd08c2'::uuid, 'a889f697-d314-5b0d-8669-0d135b72ef5e'::uuid, 'tejomayananda', 'hindi', '।।17.7।। (अपनीअपनी प्रकृति के अनुसार) सब का प्रिय भोजन भी तीन प्रकार का होता है? उसी प्रकार यज्ञ? तप और दान भी तीन प्रकार के होते हैं? उनके भेद को तुम मुझसे सुनो।।'),
('1af8b46d-db24-590c-a36a-e467fd40bd95'::uuid, '09d55fa8-2f6a-58c3-90d7-4572ab1cf98d'::uuid, 'ramsukhdas', 'hindi', '।।17.8।।आयु, सत्त्वगुण, बल, आरोग्य, सुख और प्रसन्नता बढ़ानेवाले, स्थिर रहनेवाले, हृदयको शक्ति देनेवाले, रसयुक्त तथा चिकने -- ऐसे आहार अर्थात् भोजन करनेके पदार्थ सात्त्विक मनुष्यको प्रिय होते हैं।'),
('0e860d61-afcf-59cd-9cf4-42302910d9e6'::uuid, '09d55fa8-2f6a-58c3-90d7-4572ab1cf98d'::uuid, 'tejomayananda', 'hindi', '।।17.8।। आयु, सत्त्व (शुद्धि), बल, आरोग्य, सुख और प्रीति को प्रवृद्ध करने वाले एवं रसयुक्त, स्निग्ध ( घी आदि की चिकनाई से युक्त) स्थिर तथा मन को प्रसन्न करने वाले आहार अर्थात् भोज्य पदार्थ सात्त्विक पुरुषों को प्रिय होते हैं।।
 '),
('aa38fc79-91b6-56dd-b184-c68704998fab'::uuid, 'd4155bb2-6f67-5465-8c29-70fc5140226a'::uuid, 'ramsukhdas', 'hindi', '।।17.9।।अति कड़वे, अति खट्टे, अति नमकीन, अति गरम, अति तीखे, अति रूखे और अति दाहकारक आहार अर्थात् भोजनके पदार्थ राजस मनुष्यको प्रिय होते हैं, जो कि दुःख, शोक और रोगोंको देनेवाले हैं।'),
('92593433-5cae-5661-b778-3b4982a107b7'::uuid, 'd4155bb2-6f67-5465-8c29-70fc5140226a'::uuid, 'tejomayananda', 'hindi', '।।17.9।। कड़वे, खट्टे, लवणयुक्त, अति उष्ण, तीक्ष्ण (तीखे, मिर्च युक्त), रूखे. दाहकारक, दु:ख, शोक और रोग उत्पन्न कारक भोज्य पदार्थ राजस पुरुष को प्रिय होते हैं।।
 '),
('d88915a2-5571-5f15-bfa8-6710cf51bba5'::uuid, '00a06d6b-74b1-5eb4-8913-196b68f88f30'::uuid, 'ramsukhdas', 'hindi', '।।17.10।।जो भोजन अधपका, रसरहित, दुर्गन्धित, बासी और उच्छिष्ट है तथा जो महान् अपवित्र भी है, वह तामस मनुष्यको प्रिय होता है।'),
('8315d718-f542-5a74-8da1-96187d1b843e'::uuid, '00a06d6b-74b1-5eb4-8913-196b68f88f30'::uuid, 'tejomayananda', 'hindi', '।।17.10।। अर्धपक्व, रसरहित, दुर्गन्धयुक्त, बासी, उच्छिष्ट तथा अपवित्र (अमेध्य) अन्न तामस जनों को प्रिय होता है।।
 '),
('928cf8dc-136b-5c40-bf8b-347a8a10071f'::uuid, 'eb394f9c-4032-5958-acc1-41201a5febca'::uuid, 'ramsukhdas', 'hindi', '।।17.11।।यज्ञ करना कर्तव्य है -- इस तरह मनको समाधान करके फलेच्छारहित मनुष्योंद्वारा जो शास्त्रविधिसे नियत यज्ञ किया जाता है, वह सात्त्विक है।'),
('c0ca666e-45c0-5c1d-a812-315901fec26e'::uuid, 'eb394f9c-4032-5958-acc1-41201a5febca'::uuid, 'tejomayananda', 'hindi', '।।17.11।। जो यज्ञ शास्त्रविधि से नियन्त्रित किया हुआ तथा जिसे "यह मेरा कर्तव्य है" ऐसा मन का समाधान (निश्चय) कर फल की आकांक्षा नहीं रखने वाले लोगों के द्वारा किया जाता है, वह यज्ञ सात्त्विक है।।
 '),
('71d39659-660c-55cf-8d88-39928ba4703a'::uuid, '45754dc4-f635-5074-8257-6aa2925cfea8'::uuid, 'ramsukhdas', 'hindi', '।।17.12।।परन्तु हे भरतश्रेष्ठ अर्जुन ! जो यज्ञ फलकी इच्छाको लेकर अथवा दम्भ-(दिखावटीपन-) के लिये भी किया जाता है, उसको तुम राजस समझो।'),
('b1ed803e-13e2-5f67-bb1a-9b2534d330da'::uuid, '45754dc4-f635-5074-8257-6aa2925cfea8'::uuid, 'tejomayananda', 'hindi', '।।17.12।। हे भरतश्रेष्ठ अर्जुन ! जो यज्ञ दम्भ के लिए तथा फल की आकांक्षा रख कर किया जाता है, उस यज्ञ को तुम राजस समझो।।
 '),
('4ca695a0-a0df-5202-8e63-1a0b46f1a390'::uuid, '8dc98c4e-573d-5d37-8f89-6531f07bfba2'::uuid, 'ramsukhdas', 'hindi', '।।17.13।।शास्त्रविधिसे हीन, अन्न-दानसे रहित, बिना मन्त्रोंके, बिना दक्षिणाके और बिना श्रद्धाके किये जानेवाले यज्ञको तामस यज्ञ कहते हैं।'),
('3c451934-8c82-586f-beef-594368182453'::uuid, '8dc98c4e-573d-5d37-8f89-6531f07bfba2'::uuid, 'tejomayananda', 'hindi', '।।17.13।। शास्त्रविधि से रहित, अन्नदान से रहित, बिना मन्त्रों, बिना दक्षिणा और बिना श्रद्धा के किये हुए यज्ञ को तामस यज्ञ कहते हैं।।
 '),
('42e4743a-418e-5002-a40b-10dfa9a37015'::uuid, '276d6a1c-42d9-5b10-82c8-76e653545806'::uuid, 'ramsukhdas', 'hindi', '।।17.14।।देवता, ब्राह्मण, गुरुजन और जीवन्मुक्त महापुरुषका पूजन करना, शुद्धि रखना, सरलता, ब्रह्मचर्यका पालन करना और हिंसा न करना -- यह शरीरसम्बन्धी तप कहा जाता है।'),
('7b24856c-4806-5602-95b9-23fe60615f38'::uuid, '276d6a1c-42d9-5b10-82c8-76e653545806'::uuid, 'tejomayananda', 'hindi', '।।17.14।। देव, द्विज (ब्राह्मण), गुरु और ज्ञानी जनों का पूजन, शौच, आर्जव (सरलता), ब्रह्मचर्य और अहिंसा, यह शरीर संबंधी तप कहा जाता है।।
 '),
('086198e3-0ffe-5502-82ee-03fcb66ba6fe'::uuid, '4ff32e91-069f-5953-ad5a-80137e5482f9'::uuid, 'ramsukhdas', 'hindi', '।।17.15।।उद्वेग न करनेवाला, सत्य, प्रिय, हितकारक भाषण तथा स्वाध्याय और अभ्यास करना -- यह वाणी-सम्बन्धी तप कहा जाता है।'),
('4bec4c8b-9587-5605-9b55-911e70e92a58'::uuid, '4ff32e91-069f-5953-ad5a-80137e5482f9'::uuid, 'tejomayananda', 'hindi', '।।17.15।। जो वाक्य (भाषण) उद्वेग उत्पन्न करने वाला नहीं है, जो प्रिय, हितकारक और सत्य है तथा वेदों का स्वाध्याय अभ्यास वाङ्मय (वाणी का) तप कहलाता है।।
 '),
('421baccd-b6ae-59ad-a10e-5c28bfa61388'::uuid, '839b9d26-22fc-5a62-9e35-75d702d3d96a'::uuid, 'ramsukhdas', 'hindi', '।।17.16।।मनकी प्रसन्नता, सौम्य भाव, मननशीलता, मनका निग्रह और भावोंकी शुद्धि -- इस तरह यह मन-सम्बन्धी तप कहा जाता है।'),
('95d770b1-126e-5764-adcb-1f75fe742df2'::uuid, '839b9d26-22fc-5a62-9e35-75d702d3d96a'::uuid, 'tejomayananda', 'hindi', '।।17.16।। मन की प्रसन्नता, सौम्यभाव, मौन आत्मसंयम और अन्त:करण की शुद्धि यह सब मानस तप कहलाता है।।
 '),
('4ca2cd70-c5fc-5431-9985-caa7e3f62d31'::uuid, '1e1e3777-8805-5623-b91c-d1288b4b194b'::uuid, 'ramsukhdas', 'hindi', '।।17.17।।परम श्रद्धासे युक्त फलेच्छारहित मनुष्योंके द्वारा तीन प्रकार-(शरीर, वाणी और मन-) का तप किया जाता है, उसको सात्त्विक कहते हैं।'),
('389634d2-cbd1-5016-9ce7-cc2272973d92'::uuid, '1e1e3777-8805-5623-b91c-d1288b4b194b'::uuid, 'tejomayananda', 'hindi', '।।17.17।। फल की आकांक्षा न रखने वाले युक्त पुरुषों के द्वारा परम श्रद्धा से किये गये उस पूर्वोक्त त्रिविध तप को सात्त्विक कहते हैं।।'),
('61e9afb4-cd90-5331-98c2-da15c98c67b4'::uuid, 'd07e58a2-ddb7-50e3-9c55-c68d726cc030'::uuid, 'ramsukhdas', 'hindi', '।।17.18।।जो तप सत्कार, मान और पूजाके लिये तथा दिखानेके भावसे किया जाता है, वह इस लोकमें अनिश्चित और नाशवान् फल देनेवाला तप राजस कहा गया है।'),
('96aa7e5d-2d95-598b-b955-e26837e5e6da'::uuid, 'd07e58a2-ddb7-50e3-9c55-c68d726cc030'::uuid, 'tejomayananda', 'hindi', '।।17.18।। जो तप सत्कार, मान और पूजा के लिए अथवा केवल दम्भ (पाखण्ड) से ही किया जाता है, वह अनिश्चित और क्षणिक तप यहाँ राजस कहा गया है।।
 '),
('dbdc8666-edd5-5bf0-aafc-81a1b3fcba22'::uuid, '634af24e-63fa-5d21-9327-99169fcbe7fa'::uuid, 'ramsukhdas', 'hindi', '।।17.19।।जो तप मूढ़तापूर्वक हठसे अपनेको पीड़ा देकर अथवा दूसरोंको कष्ट देनेके लिये किया जाता है, वह तप तामस कहा गया है।'),
('3f58aacd-b32f-5e7b-afd5-f0eb15c5a243'::uuid, '634af24e-63fa-5d21-9327-99169fcbe7fa'::uuid, 'tejomayananda', 'hindi', '।।17.19।। जो तप मूढ़तापूर्वक स्वयं को पीड़ित करते हुए अथवा अन्य लोगों के नाश के लिए किया जाता है, वह तप तामस कहा गया है।।
 '),
('d982d2b1-47d4-548a-99ad-69dc3bb5b40a'::uuid, '397b935e-bd4c-5672-9423-7368cc3669b1'::uuid, 'ramsukhdas', 'hindi', '।।17.20।।दान देना कर्तव्य है -- ऐसे भावसे जो दान देश, काल और पात्रके प्राप्त होनेपर अनुपकारीको दिया जाता है, वह दान सात्त्विक कहा गया है।'),
('36e1af2b-34fd-5dbf-8664-d63ca9cfcc3c'::uuid, '397b935e-bd4c-5672-9423-7368cc3669b1'::uuid, 'tejomayananda', 'hindi', '।।17.20।। "दान देना ही कर्तव्य है" - इस भाव से जो दान योग्य देश, काल को देखकर ऐसे (योग्य) पात्र (व्यक्ति) को दिया जाता है, जिससे प्रत्युपकार की अपेक्षा नहीं होती है, वह दान सात्त्विक माना गया है।।
 '),
('f6ed2b35-98d5-54bf-b10e-6d6a291ca365'::uuid, 'e199f4e2-13c0-5399-b6d0-ac86f626ccde'::uuid, 'ramsukhdas', 'hindi', '।।17.21।।किन्तु जो दान प्रत्युपकारके लिये अथवा फलप्राप्तिका उद्देश्य बनाकर फिर क्लेशपूर्वक दिया जाता है, वह दान राजस कहा जाता है।'),
('b32fe670-db25-5ac8-bc4a-04c1c29567e3'::uuid, 'e199f4e2-13c0-5399-b6d0-ac86f626ccde'::uuid, 'tejomayananda', 'hindi', '।।17.21।। और जो दान क्लेशपूर्वक तथा प्रत्युपकार के उद्देश्य से अथवा फल की कामना रखकर दिया जाता हैं, वह दान राजस माना गया है।।
 '),
('d727f946-1f0e-5716-9fb2-6465a70b9556'::uuid, '0b3acaa9-6269-5369-8585-3e38c74f25f2'::uuid, 'ramsukhdas', 'hindi', '।।17.22।।जो दान बिना सत्कारके तथा अवज्ञापूर्वक अयोग्य देश और कालमें कुपात्रको दिया जाता है, वह दान तामस कहा गया है।'),
('139d0294-66f0-5c86-8985-cdc6930dfd15'::uuid, '0b3acaa9-6269-5369-8585-3e38c74f25f2'::uuid, 'tejomayananda', 'hindi', '।।17.22।। जो दान बिना सत्कार किये, अथवा तिरस्कारपूर्वक, अयोग्य देशकाल में, कुपात्रों के लिए दिया जाता है, वह दान तामस माना गया है।।
 '),
('1606fb4b-218e-5a87-8f45-81ccc016d897'::uuid, '160e8f79-4c4a-573b-b109-8808feac3fbf'::uuid, 'ramsukhdas', 'hindi', '।।17.23।। ऊँ, तत् और सत् -- इन तीनों नामोंसे जिस परमात्माका निर्देश किया गया है, उसी परमात्माने सृष्टिके आदिमें वेदों, ब्राह्मणों और यज्ञोंकी रचना की है।'),
('7e54a111-b966-5257-b683-23ad85fd0c02'::uuid, '160e8f79-4c4a-573b-b109-8808feac3fbf'::uuid, 'tejomayananda', 'hindi', '।।17.23।। ''ऊँ, तत् सत्'' ऐसा यह ब्रह्म का त्रिविध निर्देश (नाम) कहा गया है; उसी से आदिकाल में (पुरा) ब्राहम्ण, वेद और यज्ञ निर्मित हुए हैं।।
 '),
('a8e10381-c595-5faa-8fb2-23bb626ea5fd'::uuid, '39d056e3-384c-5356-977e-b985314f70e6'::uuid, 'ramsukhdas', 'hindi', '।।17.24।।इसलिये वैदिक सिद्धान्तोंको माननेवाले पुरुषोंकी शास्त्रविधिसे नियत यज्ञ, दान और तपरूप क्रियाएँ सदा ''ऊँ'' इस परमात्माके नामका उच्चारण करके ही आरम्भ होती हैं।'),
('b51fe3d3-e887-5e8c-96c4-77e05120876b'::uuid, '39d056e3-384c-5356-977e-b985314f70e6'::uuid, 'tejomayananda', 'hindi', '।।17.24।। इसलिए, ब्रह्मवादियों की शास्त्र प्रतिपादित यज्ञ, दान और तप की क्रियायें सदैव ओंकार के उच्चारण के साथ प्रारम्भ होती हैं।।
 '),
('2383c31c-0162-5e21-98f1-77a032d4ddf5'::uuid, '3141c2b6-ede0-5f64-a82a-af37566159f2'::uuid, 'ramsukhdas', 'hindi', '।।17.25।। ''तत्'' नामसे कहे जानेवाले परमात्माके लिये ही सब कुछ है -- ऐसा मानकर मुक्ति चाहनेवाले मनुष्योंद्वारा फलकी इच्छासे रहित होकर अनेक प्रकारकी यज्ञ और तपरूप क्रियाएँ तथा दानरूप क्रियाएँ की जाती हैं।'),
('a749048a-8d6b-5e07-9ad4-85bcc31ca024'::uuid, '3141c2b6-ede0-5f64-a82a-af37566159f2'::uuid, 'tejomayananda', 'hindi', '।।17.25।। ''तत्'' शब्द का उच्चारण कर, फल की इच्छा नहीं रखते हुए, मुमुक्षुजन यज्ञ, तप, दान आदि विविध कर्म करते हैं।।
 '),
('1f3eadba-9904-5410-9516-7c4f5d36eb8e'::uuid, 'c4a794c6-841c-5852-bb68-9287d189bfd6'::uuid, 'ramsukhdas', 'hindi', '।।17.26।।हे पार्थ ! परमात्माके ''सत्''--इस  नामका सत्तामात्रमें और श्रेष्ठ भावमें प्रयोग किया जाता है तथा प्रशंसनीय कर्मके साथ ''सत्'' शब्द जोड़ा जाता है।'),
('5445eb9c-3806-5198-91c8-39b37526130c'::uuid, 'c4a794c6-841c-5852-bb68-9287d189bfd6'::uuid, 'tejomayananda', 'hindi', '।।17.26।। हे पार्थ ! सत्य भाव व साधुभाव में ''सत्'' शब्द का प्रयोग किया जाता है, और प्रशस्त (श्रेष्ठ, शुभ) कर्म में ''सत्'' शब्द प्रयुक्त होता है।।
 '),
('effe1e00-f23b-5e1d-acaa-c9c43906897e'::uuid, '1c3be0f6-4a71-5f97-88b8-076799da3144'::uuid, 'ramsukhdas', 'hindi', '।।17.27।।यज्ञ, तप और दानरूप क्रियामें जो स्थिति (निष्ठा) है, वह भी ''सत्'' -- ऐसे कही जाती है और उस परमात्माके निमित्त किया जानेवाला कर्म भी ''सत्'' -- ऐसा ही कहा जाता है।'),
('7fc96894-5af9-54b6-9cb6-47e388c1fbf6'::uuid, '1c3be0f6-4a71-5f97-88b8-076799da3144'::uuid, 'tejomayananda', 'hindi', '।।17.27।। यज्ञ, तप और दान में दृढ़ स्थिति भी सत् कही जाती है, और उस (परमात्मा) के लिए किया गया कर्म भी सत् ही कहलाता है।।
 '),
('8920ce01-8bd2-5664-99ce-9423ea01ff63'::uuid, 'c571d489-334e-5c82-b77e-6b2985ecc4c8'::uuid, 'ramsukhdas', 'hindi', '।।17.28।।हे पार्थ ! अश्रद्धासे किया हुआ हवन, दिया हुआ दान और तपा हुआ तप तथा और भी जो,कुछ किया जाय, वह सब ''असत्'' -- ऐसा कहा जाता है। उसका फल न यहाँ होता है, न मरनेके बाद ही होता है अर्थात् उसका कहीं भी सत् फल नहीं होता।'),
('eb0686e3-e8bc-58e5-a3e6-6c7b71633fd7'::uuid, 'c571d489-334e-5c82-b77e-6b2985ecc4c8'::uuid, 'tejomayananda', 'hindi', '।।17.28।। हे पार्थ ! जो यज्ञ, दान, तप और कर्म अश्रद्धापूर्वक किया जाता है, वह ''असत्'' कहा जाता है; वह न इस लोक में (इह) और न मरण के पश्चात् (उस लोक में) लाभदायक होता है।।'),
('bf68c7de-646b-53b5-9e28-d1fc10897cb3'::uuid, '3dade9d2-6936-5e26-adad-826a86bd486d'::uuid, 'ramsukhdas', 'hindi', '।।18.1।। अर्जुन बोले -- हे महाबाहो ! हे हृषीकेश ! हे केशिनिषूदन ! मैं  संन्यास और त्यागका तत्त्व अलग-अलग जानना चाहता हूँ।'),
('ec8bca52-0c33-5369-89dd-0671c1d290f4'::uuid, '3dade9d2-6936-5e26-adad-826a86bd486d'::uuid, 'tejomayananda', 'hindi', '।।18.1।। अर्जुन ने कहा -- हे महाबाहो ! हे हृषीकेश ! हे केशनिषूदन ! मैं संन्यास और त्याग के तत्त्व को पृथक्-पृथक् जानना चाहता हूँ।।
 '),
('91ae66e4-c2ac-5a7a-bf64-582d4d8f4355'::uuid, '98cf4cf4-b04a-5273-a9ea-89cb94cf68dd'::uuid, 'ramsukhdas', 'hindi', 'Hindi Translation By Swami Ramsukhdas'),
('e3a1471f-e1bb-5b46-8a62-ef18da64d547'::uuid, '98cf4cf4-b04a-5273-a9ea-89cb94cf68dd'::uuid, 'tejomayananda', 'hindi', '।।18.2।। श्रीभगवान् ने कहा -- (कुछ) कवि (पण्डित) जन काम्य कर्मों के त्याग को "संन्यास" समझते हैं और विचारशील जन समस्त कर्मों के फलों के त्याग को "त्याग" कहते हैं।।


 '),
('b6999578-cc52-5225-9d5a-ab1cfac22efd'::uuid, 'e203772f-3263-560f-8d1b-5c4c4cfd6a55'::uuid, 'ramsukhdas', 'hindi', '।।18.3।।श्रीभगवान् बोले -- कई विद्वान् काम्य-कर्मोंके त्यागको संन्यास कहते हैं और कई विद्वान् सम्पूर्ण कर्मोंके फलके त्यागको त्याग कहते हैं। कई विद्वान् कहते हैं कि कर्मोंको दोषकी तरह छोड़ देना चाहिये और कई विद्वान् कहते हैं कि यज्ञ, दान और तप-रूप कर्मोंका त्याग नहीं करना चाहिये।'),
('797d357b-e53e-5735-a82f-7551c8446fac'::uuid, 'e203772f-3263-560f-8d1b-5c4c4cfd6a55'::uuid, 'tejomayananda', 'hindi', '।।18.3।। कुछ मनीषी जन कहते हैं कि समस्त कर्म दोषयुक्त होने के कारण त्याज्य हैं; और अन्य जन कहते हैं कि यज्ञ, दान और तपरूप कर्म त्याज्य नहीं हैं।।
 '),
('e218edf6-67da-5046-a6ef-f533a916fb4c'::uuid, 'ecca47ab-8c80-5a6f-92a6-6f10c58ed360'::uuid, 'ramsukhdas', 'hindi', '।।18.4।। हे भरतवंशियोंमें श्रेष्ठ अर्जुन ! तू संन्यास और त्याग -- इन दोनोंमेंसे पहले त्यागके विषयमें मेरा निश्चय सुन; क्योंकि हे पुरुषश्रेष्ठ ! त्याग तीन प्रकारका कहा गया है।'),
('d4c6af41-5839-56df-9a32-cbc1eec403f2'::uuid, 'ecca47ab-8c80-5a6f-92a6-6f10c58ed360'::uuid, 'tejomayananda', 'hindi', '।।18.4।। हे भरतसत्तम ! उस त्याग के विषय में तुम मेरे निर्णय को सुनो। हे पुरुष श्रेष्ठ ! वह त्याग तीन प्रकार का कहा गया है।।
 '),
('bfd42092-e876-5aa0-acf9-8a29cc99956e'::uuid, '394c6d50-d63b-50ef-9312-99f3207fa8f9'::uuid, 'ramsukhdas', 'hindi', '।।18.5।।यज्ञ, दान और तपरूप कर्मोंका त्याग नहीं करना चाहिये, प्रत्युत उनको तो करना ही चाहिये क्योंकि यज्ञ, दान और तप -- ये तीनों ही कर्म मनीषियोंको पवित्र करनेवाले हैं।'),
('60453b43-2cb6-56a0-9333-1c14b36163cd'::uuid, '394c6d50-d63b-50ef-9312-99f3207fa8f9'::uuid, 'tejomayananda', 'hindi', '।।18.5।। यज्ञ, दान और तपरूप कर्म त्याज्य नहीं है, किन्तु वह नि:सन्देह कर्तव्य है; यज्ञ, दान और तप ये मनीषियों (साधकों) को पवित्र करने वाले हैं।।
 '),
('4b742665-2430-5d7d-8506-45d934b72853'::uuid, 'a3d35297-4872-5d9f-a9ff-d05a3c588d42'::uuid, 'ramsukhdas', 'hindi', '।।18.6।।हे पार्थ ! (पूर्वोक्त यज्ञ, दान और तप -- ) इन कर्मोंको तथा दूसरे भी कर्मोंको आसक्ति और फलोंका त्याग करके करना चाहिये -- यह मेरा निश्चित किया हुआ उत्तम मत है।'),
('550e7363-b2b3-57fd-acb8-993a1d01e666'::uuid, 'a3d35297-4872-5d9f-a9ff-d05a3c588d42'::uuid, 'tejomayananda', 'hindi', '।।18.6।। हे पार्थ ! इन कर्मों को भी, फल और आसक्ति को त्यागकर करना चाहिए, यह मेरा निश्चय किया हुआ उत्तम मत है।।
 '),
('47b2d422-f518-5cc8-81db-d4780c8433d5'::uuid, 'bef97c55-b3a0-557b-8ca1-c56a1f645874'::uuid, 'ramsukhdas', 'hindi', '।।18.7।।नियत कर्मका तो त्याग करना उचित नहीं है। उसका मोहपूर्वक त्याग करना तामस कहा गया है।'),
('e03e77de-656b-5c34-a9f2-b3739a2cc878'::uuid, 'bef97c55-b3a0-557b-8ca1-c56a1f645874'::uuid, 'tejomayananda', 'hindi', '।।18.7।। नियत कर्म का त्याग उचित नहीं है; मोहवश उसका त्याग करना "तामस त्याग" कहा गया है।।
 '),
('3faedbd1-5a29-5597-a775-6e6706d018a4'::uuid, '00dda16d-0a0a-55a5-bed0-31d8fc49aa79'::uuid, 'ramsukhdas', 'hindi', '।।18.8।।जो कुछ कर्म है, वह दुःखरूप ही है -- ऐसा समझकर कोई शारीरिक क्लेशके भयसे उसका त्याग कर दे, तो वह राजस त्याग करके भी त्यागके फलको नहीं पाता।'),
('aa0c86fb-0556-5672-88dc-2efcc2aa3212'::uuid, '00dda16d-0a0a-55a5-bed0-31d8fc49aa79'::uuid, 'tejomayananda', 'hindi', '।।18.8।। जो मनुष्य, कर्म को दु:ख समझकर शारीरिक कष्ट के भय से त्याग देता है, वह पुरुष उस राजसिक त्याग को करके कदापि त्याग के फल को प्राप्त नहीं होता है।।
 '),
('b8515f45-fb94-59ee-b66e-aacb6fc477eb'::uuid, '0dab7010-6386-5352-a26f-85d3cdfedec9'::uuid, 'ramsukhdas', 'hindi', '।।18.9।।हे अर्जुन ! ''केवल कर्तव्यमात्र करना है'' -- ऐसा समझकर जो नियत कर्म आसक्ति और फलका त्याग करके किया जाता है, वही सात्त्विक त्याग माना गया है।'),
('d81f5136-0db7-5a87-b9a6-f15942a517c1'::uuid, '0dab7010-6386-5352-a26f-85d3cdfedec9'::uuid, 'tejomayananda', 'hindi', '।।18.9।। हे अर्जुन ! "कर्म करना कर्तव्य है" ऐसा समझकर जो नियत कर्म आसक्ति और फल को त्यागकर किया जाता है, वही सात्त्विक त्याग माना गया है।।
 '),
('720f7fd2-192f-52e5-8162-a6b1c6abb9e1'::uuid, 'c19fb4e5-ee91-5d2d-8d12-021f7730144d'::uuid, 'ramsukhdas', 'hindi', '।।18.10।।जो अकुशल कर्मसे द्वेष नहीं करता और कुशल कर्ममें आसक्त नहीं होता, वह त्यागी, बुद्धिमान्, सन्देहरहित और अपने स्वरूपमें स्थित है।'),
('c4bfaa39-701b-5789-bf93-f6512aa5ceab'::uuid, 'c19fb4e5-ee91-5d2d-8d12-021f7730144d'::uuid, 'tejomayananda', 'hindi', '।।18.10।। जो पुरुष अकुशल (अशुभ) कर्म से द्वेष नहीं करता और कुशल (शुभ) कर्म में आसक्त नहीं होता, वह सत्त्वगुण से सम्पन्न पुरुष संशयरहित, मेधावी (ज्ञानी) और त्यागी है।।
 '),
('4c1e917a-33ee-5e1d-8e42-2ac3c1c38fc2'::uuid, '87530d37-5128-50a9-9d75-80dd2c17c60e'::uuid, 'ramsukhdas', 'hindi', '।।18.11।।कारण कि देहधारी मनुष्यके द्वारा सम्पूर्ण कर्मोंका त्याग करना सम्भव नहीं है। इसलिये जो कर्मफलका त्यागी है, वही त्यागी है -- ऐसा कहा जाता है।'),
('b1d93cbc-9b09-5551-b8a0-9f58ed7d2791'::uuid, '87530d37-5128-50a9-9d75-80dd2c17c60e'::uuid, 'tejomayananda', 'hindi', '।।18.11।। क्योंकि देहधारी पुरुष के द्वारा अशेष कर्मों का त्याग संभव नहीं है, इसलिए जो कर्मफल त्यागी है, वही पुरुष त्यागी कहा जाता है।।
 '),
('a82a7344-0c7f-5bee-be69-a680b12d27bf'::uuid, 'a6b8a6be-5260-581b-b382-8233967cb345'::uuid, 'ramsukhdas', 'hindi', '।।18.12।।कर्मफलका त्याग न करनेवाले मनुष्योंको कर्मोंका इष्ट, अनिष्ट और मिश्रित -- ऐसे तीन प्रकारका फल मरनेके बाद भी होता है; परन्तु कर्मफलका त्याग करनेवालोंको कहीं भी नहीं होता।'),
('b0c12569-e7f3-5b94-a195-f974f9fd004d'::uuid, 'a6b8a6be-5260-581b-b382-8233967cb345'::uuid, 'tejomayananda', 'hindi', '।।18.12।। कर्मों के शुभ, अशुभ और मिश्र ये त्रिविध फल केवल अत्यागी जनों को मरण के पश्चात् भी प्राप्त होते हैं; परन्तु संन्यासी पुरुषों को कदापि नहीं।।
 '),
('08f94e6c-6405-5175-9dd2-664edb3f52dd'::uuid, '057e74a9-628b-591a-914f-931622ab954f'::uuid, 'ramsukhdas', 'hindi', '।।18.13।।हे महाबाहो ! कर्मोंका अन्त करनेवाले सांख्यसिद्धान्तमें सम्पूर्ण कर्मोंकी सिद्धिके लिये ये पाँच कारण बताये गये हैं, इनको तू मेरेसे समझ।'),
('dc50f1c9-8fcb-5e53-8947-1ebf1b0bbdac'::uuid, '057e74a9-628b-591a-914f-931622ab954f'::uuid, 'tejomayananda', 'hindi', '।।18.13।। हे महाबाहो ! समस्त कर्मों की सिद्धि के लिए ये पांच कारण सांख्य सिद्धांत में कहे गये हैं, जिनको तुम मुझसे भलीभांति जानो।।
 '),
('cd638538-7f3c-595c-a768-a98f0411ac7e'::uuid, '569b7b00-6c15-51a6-b80f-5ccbcf0ce9f6'::uuid, 'ramsukhdas', 'hindi', '।।18.14।।इसमें (कर्मोंकी सिद्धिमें) अधिष्ठान तथा कर्ता और अनेक प्रकारके करण एवं विविध प्रकारकी अलग-अलग चेष्टाएँ और वैसे ही पाँचवाँ कारण दैव (संस्कार) है।'),
('c823690d-541d-58b1-886c-f850c0a428bf'::uuid, '569b7b00-6c15-51a6-b80f-5ccbcf0ce9f6'::uuid, 'tejomayananda', 'hindi', '।।18.14।। अधिष्ठान (शरीर), कर्ता ,विविध करण (इन्द्रियादि) ,विविध और पृथक्-पृथक् चेष्टाएं तथा पाँचवा हेतु दैव है।।
 '),
('732d3d5c-cbeb-596f-9a3f-cb93567b281f'::uuid, '32784664-f60c-5a79-abd2-771c23737f01'::uuid, 'ramsukhdas', 'hindi', '।।18.15।।मनुष्य, शरीर वाणी और मनके द्वारा शास्त्रविहित अथवा शास्त्रविरुद्ध जो कुछ भी कर्म आरम्भ करता है, उसके ये (पूर्वोक्त) पाँचों हेतु होते हैं।'),
('737ec550-329b-5f14-9e6e-642fd58e21a9'::uuid, '32784664-f60c-5a79-abd2-771c23737f01'::uuid, 'tejomayananda', 'hindi', '।।18.15।। मनुष्य अपने शरीर, वाणी और मन से जो कोई न्याय्य (उचित) या विपरीत (अनुचित) कर्म करता है, उसके ये पाँच कारण ही हैं।।
 '),
('d1af553d-854f-5840-bf89-7384e1c9827f'::uuid, 'd56525d3-ac85-505f-8154-90a4d647c6df'::uuid, 'ramsukhdas', 'hindi', '।।18.16।।परन्तु ऐसे पाँच हेतुओंके होनेपर भी जो उस (कर्मोंके) विषयमें केवल (शुद्ध) आत्माको कर्ता मानता है, वह दुर्मति ठीक नहीं समझता; क्योंकि उसकी बुद्धि शुद्ध नहीं है।'),
('fcbf7bb0-585f-5277-ad55-60d2e70e5caf'::uuid, 'd56525d3-ac85-505f-8154-90a4d647c6df'::uuid, 'tejomayananda', 'hindi', '।।18.16।। अब इस स्थिति में जो पुरुष असंस्कृत बुद्धि होने के कारण, केवल शुद्ध आत्मा को कर्ता समझता हैं, वह दुर्मति पुरुष (यथार्थ) नहीं देखता है।।
 '),
('1ccb2666-da2b-5a47-a414-f24057a0f1e6'::uuid, 'cf4fdad2-5cd2-5efe-b75c-9b6409503be9'::uuid, 'ramsukhdas', 'hindi', '।।18.17।।जिसका अहंकृतभाव नहीं है और जिसकी बुद्धि लिप्त नहीं होती, वह इन सम्पूर्ण प्राणियोंको मारकर भी न मारता है और न बँधता है।'),
('ffb0c8bf-9506-588c-b5d4-1fd5a427ef08'::uuid, 'cf4fdad2-5cd2-5efe-b75c-9b6409503be9'::uuid, 'tejomayananda', 'hindi', '।।18.17।। जिस पुरुष में अहंकार का भाव नहीं है और बुद्धि किसी (गुण दोष) से लिप्त नहीं होती, वह पुरुष इन सब लोकों को मारकर भी वास्तव में न मरता है और न (पाप से) बँधता है।।
 '),
('3f547d6f-e925-55d6-907e-a416e19b9cd2'::uuid, '675f4942-fc02-503e-9ac0-e11f572ca437'::uuid, 'ramsukhdas', 'hindi', '।।18.18।।ज्ञान, ज्ञेय और परिज्ञाता -- इन तीनोंसे कर्मप्रेरणा होती है तथा करण, कर्म और कर्ता -- इन तीनोंसे कर्मसंग्रह होता है।'),
('0f541893-070c-5bf3-bd96-0ab12d01673b'::uuid, '675f4942-fc02-503e-9ac0-e11f572ca437'::uuid, 'tejomayananda', 'hindi', '।।18.18।। ज्ञान, ज्ञेय और परिज्ञाता ये त्रिविध कर्म प्रेरक हैं, और, करण, कर्म. कर्ता ये त्रिविध कर्म संग्रह हैं।।
 '),
('ddf3d72c-38e3-5861-ae66-9a7ac2ec907c'::uuid, 'ed8e02d5-6f43-53ec-9e33-955efec41b03'::uuid, 'ramsukhdas', 'hindi', '।।18.19।।गुणसंख्यान (गुणोंके सम्बन्धसे प्रत्येक पदार्थके भिन्न-भिन्न भेदोंकी गणना करनेवाले) शास्त्रमें गुणोंके भेदसे ज्ञान और कर्म तथा कर्ता तीन-तीन प्रकारसे ही कहे जाते हैं, उनको भी तुम यथार्थरूपसे सुनो।'),
('b8d4601f-224b-5970-9739-ab0e51bcac07'::uuid, 'ed8e02d5-6f43-53ec-9e33-955efec41b03'::uuid, 'tejomayananda', 'hindi', '।।18.19।। ज्ञान, कर्म और कर्ता भी गुणों के भेद से सांख्यशास्त्र (गुणसंख्याने) में त्रिविध ही कहे गये हैं; उनको भी तुम मुझ से यथावत् श्रवण करो।।
 '),
('4d301700-aeb5-5fba-b4e2-c9c73eb584e8'::uuid, '44fdf1b5-adfe-5ddb-ba9e-ae9ed9798e6f'::uuid, 'ramsukhdas', 'hindi', '।।18.20।।जिस ज्ञानके द्वारा साधक सम्पूर्ण विभक्त प्राणियोंमें विभागरहित एक अविनाशी भाव-(सत्ता-) को देखता है, उस ज्ञानको तुम सात्त्विक समझो।'),
('2fc442b7-581a-5cd9-ac7e-df2d834bd318'::uuid, '44fdf1b5-adfe-5ddb-ba9e-ae9ed9798e6f'::uuid, 'tejomayananda', 'hindi', '।।18.20।। जिस ज्ञान से मनुष्य, विभक्त रूप में स्थित समस्त भूतों में एक अविभक्त और अविनाशी (अव्यय) स्वरूप को देखता है, उस ज्ञान को तुम सात्त्विक जानो।।
 '),
('da852629-cf01-5c73-81ed-8fb260715bab'::uuid, '96794bb1-7e05-560e-937f-663d63ad25ff'::uuid, 'ramsukhdas', 'hindi', '।।18.21।।परन्तु जो ज्ञान अर्थात् जिस ज्ञानके द्वारा मनुष्य सम्पूर्ण प्राणियोंमें अलग-अलग अनेक भावोंको अलग-अलग रूपसे जानता है, उस ज्ञानको तुम राजस समझो।'),
('fe2968d5-69a4-52d6-b17c-eeb61da4f139'::uuid, '96794bb1-7e05-560e-937f-663d63ad25ff'::uuid, 'tejomayananda', 'hindi', '।।18.21।। जिस ज्ञान के द्वारा मनुष्य समस्त भूतों में नाना भावों को पृथक्-पृथक् जानता है, उस ज्ञान को तुम राजस जानो।।
 '),
('233becc3-e071-52ad-ba80-1d3b25448be5'::uuid, '98f97988-126e-557d-944c-0c0b8af6bd70'::uuid, 'ramsukhdas', 'hindi', '।।18.22।।किंतु जो (ज्ञान) एक कार्यरूप शरीरमें ही सम्पूर्णके तरह आसक्त है तथा जो युक्तिरहित, वास्तविक ज्ञानसे रहित और तुच्छ है, वह तामस कहा गया है।'),
('f3c18f5d-a763-50b4-bf20-e6c38368ea34'::uuid, '98f97988-126e-557d-944c-0c0b8af6bd70'::uuid, 'tejomayananda', 'hindi', '।।18.22।। और जिस ज्ञान के द्वारा मनुष्य एक कार्य (शरीर) में ही आसक्त हो जाता है, मानो वह (कार्य ही) पूर्ण वस्तु हो तथा जो (ज्ञान) हेतुरहित (अयुक्तिक), तत्त्वार्थ से रहित तथा संकुचित (अल्प) है, वह (ज्ञान) तामस है।।
 '),
('400c6196-c7b6-5e85-8f6e-5abe692261b9'::uuid, '2faf8ad1-5093-5d8a-a7b2-05f31d7615a7'::uuid, 'ramsukhdas', 'hindi', '।।18.23।।जो कर्म शास्त्रविधिसे नियत किया हुआ और कर्तृत्वाभिमानसे रहित हो तथा फलेच्छारहित मनुष्यके द्वारा बिना राग-द्वेषके किया हुआ हो, वह सात्त्विक कहा जाता है।'),
('68ee170f-d7ec-5847-b46b-0d5f883ecce2'::uuid, '2faf8ad1-5093-5d8a-a7b2-05f31d7615a7'::uuid, 'tejomayananda', 'hindi', '।।18.23।। जो कर्म (शास्त्रविधि से) नियत और संगरहित है, तथा फल को न चाहने वाले पुरुष के द्वारा बिना किसी राग द्वेष के किया गया है, वह (कर्म) सात्त्विक कहा जाता है।।
 '),
('d5bd3b3a-0eba-5643-b679-073a57eefc75'::uuid, 'd48a0b75-e9c1-5be5-a169-417a5ecde74f'::uuid, 'ramsukhdas', 'hindi', '।।18.24।।परन्तु जो कर्म भोगोंको चाहनेवाले मनुष्यके द्वारा अहंकार अथवा परिश्रमपूर्वक किया जाता है, वह राजस कहा गया है।'),
('18405105-da12-5783-987a-5f86c9ef1ab3'::uuid, 'd48a0b75-e9c1-5be5-a169-417a5ecde74f'::uuid, 'tejomayananda', 'hindi', '।।18.24।। और जो कर्म बहुत परिश्रम से युक्त है तथा फल की कामना वाले, अहंकारयुक्त पुरुष के द्वारा किया जाता है, वह कर्म राजस कहा गया है।।
 '),
('4ff307bb-5d45-5096-bead-d8b48847076a'::uuid, '21b88f31-ea7f-5c7c-8b6f-cbfd5616dc2f'::uuid, 'ramsukhdas', 'hindi', '।।18.25।।जो कर्म परिणाम, हानि, हिंसा और सामर्थ्यको न देखकर मोहपूर्वक आरम्भ किया जाता है, वह तामस कहा जाता है।'),
('b3f34c16-38db-5cd9-8d8a-83ea33ff260a'::uuid, '21b88f31-ea7f-5c7c-8b6f-cbfd5616dc2f'::uuid, 'tejomayananda', 'hindi', '।।18.25।। जो कर्म परिणाम, हानि, हिंसा और सार्मथ्य (पौरुषम्) का विचार न करके केवल मोहवश आरम्भ किया जाता है, वह कर्म तामस कहलाता है।।
 '),
('ab223157-4ebc-50bd-9ae9-6ab6826f8833'::uuid, '1dd67c1b-b285-5adf-be0b-240c4bac7a15'::uuid, 'ramsukhdas', 'hindi', '।।18.26।।जो कर्ता रागरहित, अनहंवादी, धैर्य और उत्साहयुक्त तथा सिद्धि और असिद्धिमें निर्विकार है, वह सात्त्विक कहा जाता है।'),
('a679a3bf-7765-5967-ba01-58f306206659'::uuid, '1dd67c1b-b285-5adf-be0b-240c4bac7a15'::uuid, 'tejomayananda', 'hindi', '।।18.26।। जो कर्ता संगरहित, अहंमन्यता से रहित, धैर्य और उत्साह से युक्त एवं कार्य की सिद्धि (सफलता) और असिद्धि (विफलता) में निर्विकार रहता है, वह कर्ता सात्त्विक कहा जाता है।।
 '),
('19b7725d-aab9-58b8-bf1c-10b8c1faf5c8'::uuid, 'c632a076-86a6-5a8e-9ab8-1b1b682d9b4e'::uuid, 'ramsukhdas', 'hindi', '।।18.27।।जो कर्ता रागी, कर्मफलकी इच्छावाला, लोभी, हिंसाके स्वभाववाला, अशुद्ध और हर्षशोकसे युक्त है, वह राजस कहा गया है।'),
('90fddd73-03c0-59af-a4dc-70cb59ea9cc1'::uuid, 'c632a076-86a6-5a8e-9ab8-1b1b682d9b4e'::uuid, 'tejomayananda', 'hindi', '।।18.27।। रागी, कर्मफल का इच्छुक, लोभी, हिंसक स्वभाव वाला, अशुद्ध और हर्षशोक से युक्त कर्ता राजस कहलाता है।।
 ')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('5c9b5c12-98e9-566d-8a9e-cea344078344'::uuid, '968836c8-3bb6-5dda-8e97-aacfe50c8d30'::uuid, 'ramsukhdas', 'hindi', '।।18.28।।जो कर्ता असावधान, अशिक्षित, ऐंठ-अकड़वाला, जिद्दी, उपकारीका अपकार करनेवाला, आलसी, विषादी और दीर्घसूत्री है, वह तामस कहा जाता है।'),
('ed780560-7c6c-5c5d-9fa4-6c53eac7051d'::uuid, '968836c8-3bb6-5dda-8e97-aacfe50c8d30'::uuid, 'tejomayananda', 'hindi', '।।18.28।। अयुक्त, प्राकृत, स्तब्ध, शठ, नैष्कृतिक, आलसी, विषादी और दीर्घसूत्री कर्ता तामस कहा जाता है।।
 '),
('04a5c787-e33f-5050-90b4-0c88520d259a'::uuid, '1fbe4cf7-949f-55c4-ba49-584f5f481750'::uuid, 'ramsukhdas', 'hindi', '।।18.29।।हे धनञ्जय ! अब तू गुणोंके अनुसार बुद्धि और धृतिके भी तीन प्रकारके भेद अलग-अलगरूपसे सुन, जो कि मेरे द्वारा पूर्णरूपसे कहे जा रहे हैं।'),
('ce61589c-2072-5a81-a03d-17afa62179e1'::uuid, '1fbe4cf7-949f-55c4-ba49-584f5f481750'::uuid, 'tejomayananda', 'hindi', '।।18.29।। हे धनंजय ! मेरे द्वारा अशेषत: और पृथकत: कहे जाने वाले, गुणों के कारण उत्पन्न हुए बुद्धि और धृति के त्रिविध भेद को सुनो।।
 '),
('79e4f307-a8fd-5ef7-a0fa-036d4da263c7'::uuid, '56d4dbf4-5ea5-53ed-a27a-064a66f1fc69'::uuid, 'ramsukhdas', 'hindi', '।।18.30।।हे पृथानन्दन ! जो बुद्धि प्रवृत्ति और निवृत्तिको, कर्तव्य और अकर्तव्यको, भय और अभयको तथा बन्धन और मोक्षको जानती है, वह बुद्धि सात्त्विकी है।'),
('aacdf083-4571-5c62-968c-8856a733d3a8'::uuid, '56d4dbf4-5ea5-53ed-a27a-064a66f1fc69'::uuid, 'tejomayananda', 'hindi', '।।18.30।। हे पार्थ ! जो बुद्धि प्रवृत्ति और निवृत्ति, कार्य और अकार्य, भय और अभय तथा बन्ध और मोक्ष को तत्त्वत जानती है, वह बुद्धि सात्विकी है।।
 '),
('cb64cfcb-4de6-5460-bddc-af252a2a8a54'::uuid, '6680c056-bada-5e2d-9459-cfba23c08dbb'::uuid, 'ramsukhdas', 'hindi', '।।18.31।।हे पार्थ ! मनुष्य जिसके द्वारा धर्म और अधर्मको, कर्तव्य और अकर्तव्यको भी ठीक तरहसे नहीं जानता, वह बुद्धि राजसी है।'),
('087fcedb-ca1d-5161-b75b-f4fe583606cb'::uuid, '6680c056-bada-5e2d-9459-cfba23c08dbb'::uuid, 'tejomayananda', 'hindi', '।।18.31।। हे पार्थ ! जिस बुद्धि के द्वारा मनुष्य धर्म और अधर्म को तथा कर्तव्य और अकर्तव्य को यथावत् नहीं जानता है, वह बुद्धि राजसी है।।
 '),
('8f0f5133-9141-550a-ab7b-540ba3f51a03'::uuid, '75a336b0-bcec-54b0-8fcd-335627321b79'::uuid, 'ramsukhdas', 'hindi', '।।18.32।।हे पृथानन्दन ! तमोगुणसे घिरी हुई जो बुद्धि अधर्मको धर्म और सम्पूर्ण चीजोंको उलटा मान लेती है, वह तामसी है।'),
('736a6a99-572b-522c-a2d6-8932245401cd'::uuid, '75a336b0-bcec-54b0-8fcd-335627321b79'::uuid, 'tejomayananda', 'hindi', '।।18.32।। हे पार्थ ! तमस् (अज्ञान अन्ध:कार) से आवृत जो बुद्धि अधर्म को ही धर्म मानती है और सभी पदार्थों को विपरीत रूप से जानती है, वह बुद्धि तामसी है।।
 '),
('5b7766e0-f606-5645-b28f-c3a395948ea8'::uuid, 'f23dc957-9bd3-52f8-90b8-1a5b565f186a'::uuid, 'ramsukhdas', 'hindi', '।।18.33।।हे पार्थ ! समतासे युक्त जिस अव्यभिचारिणी धृतिके द्वारा मनुष्य मन, प्राण और इन्द्रियोंकी क्रियाओंको धारण करता है, वह धृति सात्त्विकी है।'),
('9542bc03-5e56-5952-9b74-8d0fc0b13fd2'::uuid, 'f23dc957-9bd3-52f8-90b8-1a5b565f186a'::uuid, 'tejomayananda', 'hindi', '।।18.33।। सात्त्विकी है।।'),
('293047ef-4ab2-548c-a31f-a033ad0150ce'::uuid, 'cf8d5e88-c9aa-5a74-ba41-1c700eac559b'::uuid, 'ramsukhdas', 'hindi', '।।18.34।।हे पृथानन्दन अर्जुन ! फलकी इच्छावाला मनुष्य जिस धृतिके द्वारा धर्म, काम (भोग) और अर्थको अत्यन्त आसक्तिपूर्वक धारण करता है, वह धृति राजसी है।'),
('a8fa9159-0c63-53b0-883f-3755cdf6f6bf'::uuid, 'cf8d5e88-c9aa-5a74-ba41-1c700eac559b'::uuid, 'tejomayananda', 'hindi', '।।18.34।। हे पृथापुत्र अर्जुन ! कर्मफल का इच्छुक पुरुष अति आसक्ति (प्रसंग) से जिस धृति के द्वारा धर्म, अर्थ और काम (इन तीन पुरुषार्थों) को धारण करता है, वह धृति राजसी है।।
 '),
('ff3e35db-cefc-5560-843d-c1b84ee3127a'::uuid, '9591795e-51c1-5ac2-a198-08924f2fa35a'::uuid, 'ramsukhdas', 'hindi', '।।18.35।।हे पार्थ ! दुष्ट बुद्धिवाला मनुष्य जिस धृतिके द्वारा निद्रा, भय, चिन्ता, दुःख और घमण्डको भी नहीं छोड़ता, वह धृति तामसी है।'),
('157e0126-2b7f-557e-b6bf-8e8b9dda7e81'::uuid, '9591795e-51c1-5ac2-a198-08924f2fa35a'::uuid, 'tejomayananda', 'hindi', '।।18.35।। हो पार्थ ! दुर्बुद्धि पुरुष जिस धारणा के द्वारा, स्वप्न, भय, शोक, विषाद और मद को नहीं त्यागता है, वह धृति तामसी है।।
 '),
('5eb417e3-3dd5-52ad-8a02-18fa7064aeaa'::uuid, '46180403-2b37-5256-9739-a04c939c1b28'::uuid, 'ramsukhdas', 'hindi', '।।18.36।।हे भरतवंशियोंमें श्रेष्ठ अर्जुन ! अब तीन प्रकारके सुखको भी तुम मेरेसे सुनो। जिसमें अभ्याससे रमण होता है और जिससे दुःखोंका अन्त हो जाता है, ऐसा वह परमात्मविषयक बुद्धिकी प्रसन्नतासे पैदा होनेवाला जो सुख (सांसारिक आसक्तिके कारण) आरम्भमें विषकी तरह और परिणाममें अमृतकी तरह होता है, वह सुख सात्त्विक कहा गया है।'),
('a838ae8a-4b96-5bf9-ad6a-e87bd841f0bc'::uuid, '46180403-2b37-5256-9739-a04c939c1b28'::uuid, 'tejomayananda', 'hindi', '।।18.36।। हे भरतश्रेष्ठ ! अब तुम त्रिविध सुख को मुझसे सुनो, जिसमें (साधक पुरुष) अभ्यास से रमता है और दु:खों के अन्त को प्राप्त होता है (जहाँ उसके दु:खों का अन्त हो जाता है।)।।
 '),
('8595ffa1-ee96-50b6-ab5d-b9a087e15ae3'::uuid, 'bc9f3394-35bf-5ed6-9f81-e441fa926f6b'::uuid, 'ramsukhdas', 'hindi', '।।18.37।।हे भरतवंशियोंमें श्रेष्ठ अर्जुन ! अब तीन प्रकारके सुखको भी तुम मेरेसे सुनो। जिसमें अभ्याससे रमण होता है और जिससे दुःखोंका अन्त हो जाता है, ऐसा वह परमात्मविषयक बुद्धिकी प्रसन्नतासे पैदा होनेवाला जो सुख (सांसारिक आसक्तिके कारण) आरम्भमें विषकी तरह और परिणाममें अमृतकी तरह होता है, वह सुख सात्त्विक कहा गया है।'),
('7cc8e08f-b09b-51a2-9a3c-9436a4a489a5'::uuid, 'bc9f3394-35bf-5ed6-9f81-e441fa926f6b'::uuid, 'tejomayananda', 'hindi', '।।18.37।। जो सुख प्रथम (प्रारम्भ में) विष के समान (भासता) है, परन्तु परिणाम में अमृत के समान है, वह आत्मबुद्धि के प्रसाद से उत्पन्न सुख सात्त्विक कहा गया है।।
 '),
('a752b7bd-8769-5d19-9e8e-8b6bb0ce8ee1'::uuid, '976ca21b-f81d-51ce-a649-a656dc745aaf'::uuid, 'ramsukhdas', 'hindi', '।।18.38।।जो सुख इन्द्रियों और विषयोंके संयोगसे आरम्भमें अमृतकी तरह और परिणाममें विषकी तरह होता है, वह सुख राजस कहा गया है।'),
('ea6765ff-987c-55c3-938e-c419d5c5c9e2'::uuid, '976ca21b-f81d-51ce-a649-a656dc745aaf'::uuid, 'tejomayananda', 'hindi', '।।18.38।। जो सुख विषयों और इन्द्रियों के संयोग से उत्पन्न होता है, वह प्रथम तो अमृत के समान, परन्तु परिणाम में विष तुल्य होता है, वह सुख राजस कहा गया है।।
 '),
('2bfd0b2f-f911-5334-9e0c-892a641f6cbb'::uuid, '92a79653-6524-5093-9dbe-a013de3578df'::uuid, 'ramsukhdas', 'hindi', '।।18.39।।निद्रा, आलस्य और प्रमादसे उत्पन्न होनेवाला जो सुख आरम्भमें और परिणाममें अपनेको मोहित करनेवाला है, वह सुख तामस कहा गया है।'),
('00e08248-bcd2-599c-90a2-04b5f47e0095'::uuid, '92a79653-6524-5093-9dbe-a013de3578df'::uuid, 'tejomayananda', 'hindi', '।।18.39।। जो सुख प्रारम्भ में और परिणाम (अनुबन्ध) में भी आत्मा (मनुष्य) को मोहित करने वाला होता है, वह निद्रा, आलस्य और प्रमाद से उत्पन्न सुख तामस कहा जाता है।।
 '),
('d66d5b5f-e14a-557f-a664-634b2ac40d45'::uuid, '3ae8dc19-4f88-56ac-82f3-dcf3ea8ba9b7'::uuid, 'ramsukhdas', 'hindi', '।।18.40।।पृथ्वीमें या स्वर्गमें अथवा देवताओंमें तथा इनके सिवाय और कहीं भी वह ऐसी कोई वस्तु नहीं है, जो प्रकृतिसे उत्पन्न इन तीनों गुणोंसे रहित हो।'),
('17cf4907-5c80-5d22-ac71-7bca683e4191'::uuid, '3ae8dc19-4f88-56ac-82f3-dcf3ea8ba9b7'::uuid, 'tejomayananda', 'hindi', '।।18.40।। पृथ्वी पर अथवा स्वर्ग के देवताओं में ऐसा कोई प्राणी (सत्त्वं अर्थात् विद्यमान वस्तु) नहीं है जो प्रकृति से उत्पन्न इन तीन गुणों से मुक्त (रहित) हो।।'),
('aa10858c-4e78-5b88-ad32-0a35b865a488'::uuid, 'dc23c870-abc6-5e76-8a3b-5eb10e09e429'::uuid, 'ramsukhdas', 'hindi', '।।18.41।।हे परंतप ! ब्राह्मण, क्षत्रिय, वैश्य और शूद्रोंके कर्म स्वभावसे उत्पन्न हुए तीनों गुणोंके द्वारा विभक्त किये गये हैं।'),
('86fc0bc6-d4c3-5934-9013-0d722a5f0ef9'::uuid, 'dc23c870-abc6-5e76-8a3b-5eb10e09e429'::uuid, 'tejomayananda', 'hindi', '।।18.41।। हे परन्तप!  ब्राह्मणों, क्षत्रियों, वैश्यों और शूद्रों के कर्म, स्वभाव से उत्पन्न गुणों के अनुसार विभक्त किये गये हैं।।
 '),
('75bee525-427f-593d-9829-266b83b0cdfd'::uuid, 'b3f9f47d-db42-5460-a0ee-1baa0a80f39d'::uuid, 'ramsukhdas', 'hindi', '।।18.42।।मनका निग्रह करना इन्द्रियोंको वशमें करना; धर्मपालनके लिये कष्ट सहना; बाहर-भीतरसे शुद्ध रहना; दूसरोंके अपराधको क्षमा करना; शरीर, मन आदिमें सरलता रखना; वेद, शास्त्र आदिका ज्ञान होना; यज्ञविधिको अनुभवमें लाना; और परमात्मा, वेद आदिमें आस्तिक भाव रखना -- ये सब-के-सब ब्राह्मणके स्वाभाविक कर्म हैं।'),
('4a99460c-b0a7-5626-a873-7fef64c2337d'::uuid, 'b3f9f47d-db42-5460-a0ee-1baa0a80f39d'::uuid, 'tejomayananda', 'hindi', '।।18.42।। शम, दम, तप, शौच, क्षान्ति, आर्जव, ज्ञान, विज्ञान और आस्तिक्य - ये ब्राह्मण के स्वाभाविक कर्म हैं।।
 '),
('ec1f9da8-4e5a-5932-8f10-920b3fdb81ab'::uuid, '58f17d45-2394-5c64-8e01-61b485ed87c9'::uuid, 'ramsukhdas', 'hindi', '।।18.43।।शूरवीरता, तेज, धैर्य, प्रजाके संचालन आदिकी विशेष चतुरता, युद्धमें कभी पीठ न दिखाना, दान करना और शासन करनेका भाव -- ये सबकेसब क्षत्रियके स्वाभाविक कर्म हैं।'),
('2f19e475-2843-5f1b-ac33-4bf1e1fc7a9f'::uuid, '58f17d45-2394-5c64-8e01-61b485ed87c9'::uuid, 'tejomayananda', 'hindi', '।।18.43।। शौर्य, तेज, धृति, दाक्ष्य (दक्षता), युद्ध से पलायन न करना, दान और ईश्वर भाव (स्वामी भाव) - ये सब क्षत्रिय के स्वाभाविक कर्म हैं।।
 '),
('f778b755-051c-5dc8-9351-f8cace1f9988'::uuid, '3e2bb158-ffd0-5d7b-94c2-f3fbd1d22157'::uuid, 'ramsukhdas', 'hindi', '।।18.44।।खेती करना, गायोंकी रक्षा करना और शुद्ध व्यापार करना -- ये सब-के-सब वैश्यके स्वाभाविक कर्म हैं, तथा चारों वर्णोंकी सेवा करना शूद्रका भी स्वाभाविक कर्म है।'),
('9c80bc19-fb22-5ed2-93af-df25554ae66d'::uuid, '3e2bb158-ffd0-5d7b-94c2-f3fbd1d22157'::uuid, 'tejomayananda', 'hindi', '।।18.44।। कृषि, गौपालन तथा वाणिज्य - ये वैश्य के स्वाभाविक कर्म हैं, और शूद्र का स्वाभाविक कर्म है परिचर्या अर्थात् सेवा करना।।
 '),
('4d4bc16f-c772-53fa-9e60-1508d8598485'::uuid, 'c4915d7c-f98b-5b88-9570-1155cc7fb70f'::uuid, 'ramsukhdas', 'hindi', '।।18.45।।अपने-अपने कर्ममें तत्परतापूर्वक लगा हुआ मनुष्य सम्यक् सिद्धि-(परमात्मा-)को प्राप्त कर लेता है। अपने कर्ममें लगा हुआ मनुष्य जिस प्रकार सिद्धिको प्राप्त होता है? उस प्रकारको तू मेरेसे सुन।'),
('c9610d43-b950-5722-949d-96fd4923a412'::uuid, 'c4915d7c-f98b-5b88-9570-1155cc7fb70f'::uuid, 'tejomayananda', 'hindi', '।।18.45।। अपने-अपने स्वाभाविक कर्म में अभिरत मनुष्य संसिद्धि को प्राप्त कर लेता है। स्वकर्म में रत मनुष्य किस प्रकार सिद्धि प्राप्त करता है, उसे तुम सुनो।।
 '),
('ae67875c-e5de-5363-a6f5-3e78802fc546'::uuid, 'ba536cf9-9317-5d24-910e-d44f8adc9da1'::uuid, 'ramsukhdas', 'hindi', '।।18.46।।जिस परमात्मासे सम्पूर्ण प्राणियोंकी उत्पत्ति होती है और जिससे यह सम्पूर्ण संसार व्याप्त है, उस परमात्माका अपने कर्मके द्वारा पूजन करके मनुष्य सिद्धिको प्राप्त हो जाता है।'),
('7a814115-1426-5cf1-ac3b-4f3196dc1597'::uuid, 'ba536cf9-9317-5d24-910e-d44f8adc9da1'::uuid, 'tejomayananda', 'hindi', '।।18.46।। जिस (परमात्मा) से भूतमात्र की प्रवृत्ति अर्थात् उत्पत्ति हुई है और जिससे यह सम्पूर्ण जगत् व्याप्त है, उस (परमात्मा) की स्वकर्म द्वारा पूजा करके मनुष्य सिद्धि को प्राप्त होता है।।
 '),
('a850cc08-4297-5475-b2bd-6cc21696f74f'::uuid, 'ad717ff9-d2ea-5c9f-981a-db7901a4eaae'::uuid, 'ramsukhdas', 'hindi', '।।18.47।।अच्छी तरहसे अनुष्ठान किये हुए परधर्मसे गुणरहित अपना धर्म श्रेष्ठ है। कारण कि स्वभावसे नियत किये हुए स्वधर्मरूप कर्मको करता हुआ मनुष्य पापको प्राप्त नहीं होता।'),
('110ae694-17d1-5724-abd1-da908a3ffd48'::uuid, 'ad717ff9-d2ea-5c9f-981a-db7901a4eaae'::uuid, 'tejomayananda', 'hindi', '।।18.47।। सम्यक् अनुष्ठित परधर्म की अपेक्षा गुणरहित स्वधर्म श्रेष्ठ है। (क्योंकि) स्वभाव से नियत किये गये कर्म को करते हुए मनुष्य पाप को नहीं प्राप्त करता।।'),
('f0edd502-f357-5384-a7f3-702185671e28'::uuid, '03d1a633-ac3e-5dfd-8b5b-2fc9a2d30c38'::uuid, 'ramsukhdas', 'hindi', '।।18.48।।हे कुन्तीनन्दन ! दोषयुक्त होनेपर भी सहज कर्मका त्याग नहीं करना चाहिये; क्योंकि सम्पूर्ण कर्म धुएँसे अग्निकी तरह किसी-न-किसी दोषसे युक्त हैं।'),
('dfee0f15-88ff-55c4-913c-5100208ef492'::uuid, '03d1a633-ac3e-5dfd-8b5b-2fc9a2d30c38'::uuid, 'tejomayananda', 'hindi', '।।18.48।। हे कौन्तेय ! दोषयुक्त होने पर भी सहज कर्म को नहीं त्यागना चाहिए; क्योंकि सभी कर्म दोष से आवृत होते है, जैसे धुयें से अग्नि।।
 '),
('0f990fe5-035f-5578-8130-772278416954'::uuid, '0b64c096-e168-54ad-b107-571e2fd83aee'::uuid, 'ramsukhdas', 'hindi', '।।18.49।।जिसकी बुद्धि सब जगह आसक्तिरहित है, जिसने शरीरको वशमें कर रखा है, जो स्पृहारहित है, वह मनुष्य सांख्ययोगके द्वारा नैष्कर्म्य-सिद्धिको प्राप्त हो जाता है।'),
('444eb9cd-5ceb-58b7-990d-34a0b7102ad4'::uuid, '0b64c096-e168-54ad-b107-571e2fd83aee'::uuid, 'tejomayananda', 'hindi', '।।18.49।। सर्वत्र आसक्ति रहित बुद्धि वाला वह पुरुष जो स्पृहारहित तथा जितात्मा है, संन्यास के द्वारा परम नैर्ष्कम्य सिद्धि को प्राप्त होता है।।
 '),
('41f233aa-c244-5398-8570-a57eb37a2fab'::uuid, 'fb03c842-cec5-57c7-ae6e-b51554e201c8'::uuid, 'ramsukhdas', 'hindi', '।।18.50।।हे कौन्तेय ! सिद्धि-(अन्तःकरणकी शुद्धि-) को प्राप्त हुआ साधक ब्रह्मको, जो कि ज्ञानकी परा निष्ठा है, जिस प्रकारसे प्राप्त होता है, उस प्रकारको तुम मुझसे संक्षेपमें ही समझो।'),
('0eb33f08-14c5-5b3c-a9eb-5943611244c3'::uuid, 'fb03c842-cec5-57c7-ae6e-b51554e201c8'::uuid, 'tejomayananda', 'hindi', '।।18.50।। सिद्धि को प्राप्त पुरुष किस प्रकार ब्रह्म को प्राप्त होता है, तथा ज्ञान की परा निष्ठा को भी तुम मुझसे संक्षेप में जानो।।
 '),
('0af02918-f592-5420-8343-81d5183cfa9b'::uuid, '48032393-d926-543e-8576-b517b228ccc3'::uuid, 'ramsukhdas', 'hindi', '।।18.51।।जो विशुद्ध (सात्त्विकी) बुद्धिसे युक्त, वैराग्यके आश्रित, एकान्तका सेवन करनेवाला और नियमित भोजन करनेवाला साधक धैर्यपूर्वक इन्द्रियोंका नियमन करके, शरीर-वाणी-मनको वशमें करके, शब्दादि विषयोंका त्याग करके और राग-द्वेषको छोड़कर निरन्तर ध्यानयोगके परायण हो जाता है, वह अहंकार, बल, दर्प, काम, क्रोध और परिग्रहका त्याग करके एवं निर्मम तथा शान्त होकर ब्रह्मप्राप्तिका पात्र हो जाता है।'),
('de5fdb52-c64f-5075-8fb1-0f5255a1095c'::uuid, '48032393-d926-543e-8576-b517b228ccc3'::uuid, 'tejomayananda', 'hindi', '।।18.51।। विशुद्ध बुद्धि से युक्त, धृति से आत्मसंयम कर, शब्दादि विषयों को त्याग कर और राग-द्वेष का परित्याग कर....৷৷৷৷।।
 '),
('a036efeb-911a-59bd-b4da-7647df35812d'::uuid, 'd026c93b-cc7b-555b-8751-d933ebdb6b54'::uuid, 'ramsukhdas', 'hindi', '।।18.52।।जो विशुद्ध (सात्त्विकी) बुद्धिसे युक्त, वैराग्यके आश्रित, एकान्तका सेवन करनेवाला और नियमित भोजन करनेवाला साधक धैर्यपूर्वक इन्द्रियोंका नियमन करके, शरीर-वाणी-मनको वशमें करके, शब्दादि विषयोंका त्याग करके और राग-द्वेषको छोड़कर निरन्तर ध्यानयोगके परायण हो जाता है, वह अहंकार, बल, दर्प, काम, क्रोध और परिग्रहका त्याग करके एवं निर्मम तथा शान्त होकर ब्रह्मप्राप्तिका पात्र हो जाता है।'),
('548d8c8c-97a5-5dcb-9f75-f1fe030d4f03'::uuid, 'd026c93b-cc7b-555b-8751-d933ebdb6b54'::uuid, 'tejomayananda', 'hindi', '।।18.52।। विविक्त सेवी, लघ्वाशी (मिताहारी) जिसने अपने शरीर, वाणी और मन को संयत किया है, ध्यानयोग के अभ्यास में सदैव तत्पर तथा वैराग्य पर समाश्रित।।
 '),
('fffd0a32-aa92-595e-b545-f767799699bf'::uuid, 'c66eded3-fe89-504d-a33e-0bc722b8c32e'::uuid, 'ramsukhdas', 'hindi', '।।18.53।।जो विशुद्ध (सात्त्विकी) बुद्धिसे युक्त, वैराग्यके आश्रित, एकान्तका सेवन करनेवाला और नियमित भोजन करनेवाला साधक धैर्यपूर्वक इन्द्रियोंका नियमन करके, शरीर-वाणी-मनको वशमें करके, शब्दादि विषयोंका त्याग करके और राग-द्वेषको छोड़कर निरन्तर ध्यानयोगके परायण हो जाता है, वह अहंकार, बल, दर्प, काम, क्रोध और परिग्रहका त्याग करके एवं निर्मम तथा शान्त होकर ब्रह्मप्राप्तिका पात्र हो जाता है।'),
('f150b2bf-32b0-5650-93be-8744190b8acc'::uuid, 'c66eded3-fe89-504d-a33e-0bc722b8c32e'::uuid, 'tejomayananda', 'hindi', '।।18.53।। अहंकार, बल, दर्प, काम, क्रोध और परिग्रह को त्याग कर ममत्वभाव से रहित और शान्त पुरुष ब्रह्म प्राप्ति के योग्य बन जाता है।।
 '),
('55ef73a2-ac04-5976-9546-9a11c01d3b24'::uuid, '0bc23035-867c-5f09-a058-26486df3c47d'::uuid, 'ramsukhdas', 'hindi', '।।18.54।।वह ब्रह्मभूत-अवस्थाको प्राप्त प्रसन्न मनवाला साधक न तो किसीके लिये शोक करता है और न किसीकी इच्छा करता है। ऐसा सम्पूर्ण प्राणियोंमें समभाववाला साधक मेरी पराभक्तिको प्राप्त हो जाता है।'),
('c88b487c-9eeb-5302-9627-c32c57fcba15'::uuid, '0bc23035-867c-5f09-a058-26486df3c47d'::uuid, 'tejomayananda', 'hindi', '।।18.54।। ब्रह्मभूत (जो साधक ब्रह्म बन गया है), प्रसन्न मन वाला पुरुष न इच्छा करता है और न शोक, समस्त भूतों के प्रति सम होकर वह मेरी परा भक्ति को प्राप्त करता है।।
 '),
('d22e2f80-5f6d-52f1-a734-64029e70c4d8'::uuid, '1859b3b0-f11c-5156-a147-1d8e7e65f05a'::uuid, 'ramsukhdas', 'hindi', '।।18.55।।उस पराभक्तिसे मेरेको, मैं जितना हूँ और जो हूँ -- इसको तत्त्वसे जान लेता है तथा मेरेको तत्त्वसे जानकर फिर तत्काल मेरेमें प्रविष्ट हो जाता है।'),
('0b4e3cdc-b0f6-5ead-9921-3cf5d51ddefd'::uuid, '1859b3b0-f11c-5156-a147-1d8e7e65f05a'::uuid, 'tejomayananda', 'hindi', '।।18.55।। (उस परा) भक्ति के द्वारा मुझे वह तत्त्वत: जानता है कि मैं कितना (व्यापक) हूँ तथा मैं क्या हूँ। (इस प्रकार) तत्त्वत: जानने के पश्चात् तत्काल ही वह मुझमें प्रवेश कर जाता है, अर्थात् मत्स्वरूप बन जाता है।।
 '),
('6fcf565b-cf01-5b83-86eb-7db71ea1a550'::uuid, '6cb2b09a-1dd6-5e8c-8fe8-e0cd16687f3d'::uuid, 'ramsukhdas', 'hindi', '।।18.56।।मेरा आश्रय लेनेवाला भक्त सदा सब कर्म करता हुआ भी मेरी कृपासे शाश्वत अविनाशी पदको प्राप्त हो जाता है।'),
('5cbb2c53-b507-5d1a-87ab-80aebdc6b63f'::uuid, '6cb2b09a-1dd6-5e8c-8fe8-e0cd16687f3d'::uuid, 'tejomayananda', 'hindi', '।।18.56।। जो पुरुष मदाश्रित होकर सदैव समस्त कर्मों को करता है, वह मेरे प्रसाद (अनुग्रह) से शाश्वत, अव्यय पद को प्राप्त कर लेता है।।
 '),
('908dcd7a-bb70-5427-9b0e-fab1f394e63f'::uuid, '31a3a9f0-a75d-5b36-8f42-12ccbe43c915'::uuid, 'ramsukhdas', 'hindi', '।।18.57।।चित्तसे सम्पूर्ण कर्म मुझमें अर्पण करके, मेरे परायण होकर तथा समताका आश्रय लेकर निरन्तर मुझमें चित्तवाला हो जा।'),
('d3ab6bed-9cb3-5c0e-b1aa-7b80788900a6'::uuid, '31a3a9f0-a75d-5b36-8f42-12ccbe43c915'::uuid, 'tejomayananda', 'hindi', '।।18.57।। मन से समस्त कर्मों का संन्यास मुझमें करके मत्परायण होकर बुद्धियोग का आश्रय लेकर तुम सतत मच्चित्त बनो।।'),
('f150958d-da92-580b-aa2d-03f75fe2660d'::uuid, 'a880de33-b6ec-5514-b87f-ed0a6ebda995'::uuid, 'ramsukhdas', 'hindi', '।।18.58।।मेरेमें चित्तवाला होकर तू मेरी कृपासे सम्पूर्ण विघ्नोंको तर जायगा और यदि तू अहंकारके कारण मेरी बात नहीं सुनेगा तो तेरा पतन हो जायगा।'),
('6bb472c3-cb5e-5c7d-9f5f-65afd6ad30eb'::uuid, 'a880de33-b6ec-5514-b87f-ed0a6ebda995'::uuid, 'tejomayananda', 'hindi', '।।18.58।। मच्चित्त होकर तुम मेरी कृपा से समस्त कठिनाइयों (सर्वदुर्गाणि) को पार कर जाओगे; और यदि अहंकारवश (इस उपदेश को) नहीं सुनोगे, तो तुम नष्ट हो जाओगे।।
 '),
('fad5b1aa-8435-50e8-b0a1-17b2a4d5e9aa'::uuid, '6292110c-df66-5538-a07f-4d41c3089dc1'::uuid, 'ramsukhdas', 'hindi', '।।18.59।।अहंकारका आश्रय लेकर तू जो ऐसा मान रहा है कि मैं युद्ध नहीं करूँगा, तेरा यह निश्चय मिथ्या (झूठा) है; क्योंकि तेरी क्षात्र-प्रकृति तेरेको युद्धमें लगा देगी।'),
('d15ea016-e156-5819-8895-03f85d6f5489'::uuid, '6292110c-df66-5538-a07f-4d41c3089dc1'::uuid, 'tejomayananda', 'hindi', '।।18.59।। और अहंकारवश तुम जो यह सोच रहे हो, "मैं युद्ध नहीं करूंगा", यह तुम्हारा निश्चय मिथ्या है, (क्योंकि) प्रकृति (तुम्हारा स्वभाव) ही तुम्हें (बलात् कर्म में) प्रवृत्त करेगी।।
 '),
('9661acef-d231-5609-89dd-cd442affff55'::uuid, 'b45448ce-f5b2-5652-8138-6282c3bb5366'::uuid, 'ramsukhdas', 'hindi', '।।18.60।।हे कुन्तीनन्दन ! अपने स्वभावजन्य कर्मसे बँधा हुआ तू मोहके कारण जो नहीं करना चाहता, उसको तू (क्षात्र-प्रकृतिके) परवश होकर करेगा।'),
('cc3276f6-a15e-5a56-a6e8-f0cf91c0a6fb'::uuid, 'b45448ce-f5b2-5652-8138-6282c3bb5366'::uuid, 'tejomayananda', 'hindi', '।।18.60।। हे कौन्तेय ! तुम अपने स्वाभाविक कर्मों से बंधे हो, (अत:) मोहवशात् जिस कर्म को तुम करना नहीं चाहते हो, वही तुम विवश होकर करोगे।।
 '),
('de5f5d3d-66a9-5f31-879a-4ab41e100947'::uuid, '87f3e1b1-5a5d-5c16-834b-afe93999beaa'::uuid, 'ramsukhdas', 'hindi', '।।18.61।।हे अर्जुन ! ईश्वर सम्पूर्ण प्राणियोंके हृदयमें रहता है और अपनी मायासे शरीररूपी यन्त्रपर आरूढ़ हुए सम्पूर्ण प्राणियोंको (उनके स्वभावके अनुसार) भ्रमण कराता रहता है।'),
('d6117172-d5b1-5460-951d-08aa32447a42'::uuid, '87f3e1b1-5a5d-5c16-834b-afe93999beaa'::uuid, 'tejomayananda', 'hindi', '।।18.61।। हे अर्जुन (मानों किसी) यन्त्र पर आरूढ़ समस्त भूतों को ईश्वर अपनी माया से घुमाता हुआ (भ्रामयन्) भूतमात्र के हृदय में स्थित रहता है।।'),
('e18eb289-27d0-59b5-a533-b9ba3f1bb080'::uuid, 'f0152c09-3827-5ad6-bc79-50ce2f80afc8'::uuid, 'ramsukhdas', 'hindi', '।।18.62।।हे भरतवंशोद्भव अर्जुन ! तू सर्वभावसे उस ईश्वरकी ही शरणमें चला जा। उसकी कृपासे तू परमशान्ति-(संसारसे सर्वथा उपरति-) को और अविनाशी परमपदको प्राप्त हो जायगा।'),
('ae20fe22-9c7b-55e9-8f51-769796d1cc79'::uuid, 'f0152c09-3827-5ad6-bc79-50ce2f80afc8'::uuid, 'tejomayananda', 'hindi', '।।18.62।। हे भारत ! तुम सम्पूर्ण भाव से उसी (ईश्वर) की शरण में जाओ। उसके प्रसाद से तुम परम शान्ति और शाश्वत स्थान को प्राप्त करोगे।।
 '),
('15a67b43-f0cc-5896-94ee-cebe9fa48eb2'::uuid, 'e063c739-2aa6-5e73-80fa-1feeff5aa04e'::uuid, 'ramsukhdas', 'hindi', '।।18.63।।यह गुह्यसे भी गुह्यतर (शरणागतिरूप) ज्ञान मैंने तुझे कह दिया। अब तू इसपर अच्छी तरहसे विचार करके जैसा चाहता है, वैसा कर।'),
('32a18d5a-25a8-5e38-ae59-062a762df6ba'::uuid, 'e063c739-2aa6-5e73-80fa-1feeff5aa04e'::uuid, 'tejomayananda', 'hindi', '।।18.63।। इस प्रकार समस्त गोपनीयों से अधिक गुह्य ज्ञान मैंने तुमसे कहा; इस पर पूर्ण विचार (विमृश्य) करने के पश्चात् तुम्हारी जैसी इच्छा हो, वैसा तुम करो।।
 '),
('50d8b49a-65ec-5392-8f40-9a0433522484'::uuid, 'b733a82a-53e5-5059-98a4-c4cfbe336026'::uuid, 'ramsukhdas', 'hindi', '।।18.64।।सबसे अत्यन्त गोपनीय वचन तू फिर मेरेसे सुन। तू मेरा अत्यन्त प्रिय है, इसलिये मैं तेरे हितकी बात कहूँगा।'),
('44fd0c06-5cbc-5f88-8d13-ccac695abe36'::uuid, 'b733a82a-53e5-5059-98a4-c4cfbe336026'::uuid, 'tejomayananda', 'hindi', '।।18.64।। पुन: एक बार तुम मुझसे समस्त गुह्यों में गुह्यतम परम वचन (उपदेश) को सुनो। तुम मुझे अतिशय प्रिय हो, इसलिए मैं तुम्हें तुम्हारे हित की बात कहूंगा।।
 '),
('9da2217f-7a0a-512b-8210-3c6e85bf0c08'::uuid, 'c65e783d-5615-590a-9499-b901df609df1'::uuid, 'ramsukhdas', 'hindi', '।।18.65।।तू मेरा भक्त हो जा, मेरेमें मनवाला हो जा, मेरा पूजन करनेवाला हो जा और मेरेको नमस्कार कर। ऐसा करनेसे तू मेरेको ही प्राप्त हो जायगा -- यह मैं तेरे सामने सत्य प्रतिज्ञा करता हूँ; क्योंकि तू मेरा अत्यन्त प्रिय है।'),
('7396ce14-75de-53f8-ba2a-32292e47528e'::uuid, 'c65e783d-5615-590a-9499-b901df609df1'::uuid, 'tejomayananda', 'hindi', '।।18.65।। तुम मच्चित, मद्भक्त और मेरे पूजक (मद्याजी) बनो और मुझे नमस्कार करो; (इस प्रकार) तुम मुझे ही प्राप्त होगे; यह मैं तुम्हे सत्य वचन देता हूँ,(क्योंकि) तुम मेरे प्रिय हो।।
 '),
('8b6a42d8-b631-501d-b8c7-dbea0ce757f4'::uuid, '9e52590f-0112-5726-87b1-e059dd963fcc'::uuid, 'ramsukhdas', 'hindi', '।।18.66।।सम्पूर्ण धर्मोंका आश्रय छोड़कर तू केवल मेरी शरणमें आ जा। मैं तुझे सम्पूर्ण पापोंसे मुक्त कर दूँगा, चिन्ता मत कर।'),
('b756adff-5305-5ac0-a7ba-39658bcaa5f6'::uuid, '9e52590f-0112-5726-87b1-e059dd963fcc'::uuid, 'tejomayananda', 'hindi', '।।18.66।। सब धर्मों का परित्याग करके तुम एक मेरी ही शरण में आओ, मैं तुम्हें समस्त पापों से मुक्त कर दूँगा, तुम शोक मत करो।।
 '),
('0b2904fa-7429-572f-aedb-434e8aa2f4a3'::uuid, 'c7923de5-b237-5145-88be-87f1b7093152'::uuid, 'ramsukhdas', 'hindi', '।।18.67।।यह सर्वगुह्यतम वचन अतपस्वीको मत कहना; अभक्तको कभी मत कहना; जो सुनना नहीं चाहता, उसको मत कहना; और जो मेरेमें दोषदृष्टि करता है, उससे भी मत कहना।'),
('1e3789ed-3d7f-5fe5-b90d-d5f4eabc596b'::uuid, 'c7923de5-b237-5145-88be-87f1b7093152'::uuid, 'tejomayananda', 'hindi', '।।18.67।। यह ज्ञान ऐसे पुरुष से नहीं कहना चाहिए, जो अतपस्क (तपरहित) है, और न उसे जो अभक्त है; उसे भी नहीं जो अशुश्रुषु (सेवा में अतत्पर) है और उस पुरुष से भी नहीं कहना चाहिए, जो मुझ (ईश्वर) से असूया करता है, अर्थात् मुझ में दोष देखता है।।
 '),
('bf1299b4-f459-553b-9356-06816b6b6c11'::uuid, '69092e4b-fb5f-5804-947c-a0c303835bf3'::uuid, 'ramsukhdas', 'hindi', '।।18.68।।मेरेमें पराभक्ति करके जो इस परम गोपनीय संवाद-(गीता-ग्रन्थ) को मेरे भक्तोंमें कहेगा, वह मुझे ही प्राप्त होगा -- इसमें कोई सन्देह नहीं है।'),
('5fdfceac-06ec-5e75-b1cb-24060948ce20'::uuid, '69092e4b-fb5f-5804-947c-a0c303835bf3'::uuid, 'tejomayananda', 'hindi', '।।18.68।। जो पुरुष मुझसे परम प्रेम (परा भक्ति) करके इस परम गुह्य ज्ञान का उपदेश मेरे भक्तों को देता है, वह नि:सन्देह मुझे ही प्राप्त होता है।।
 '),
('f51780cf-488f-573c-b80c-6dcdf898be01'::uuid, '2c6a75de-f720-5cac-97e5-83d42c9470e8'::uuid, 'ramsukhdas', 'hindi', '।।18.69।।उसके समान मेरा अत्यन्त प्रिय कार्य करनेवाला मनुष्योंमें कोई भी नहीं है और इस भूमण्डलपर उसके समान मेरा दूसरा कोई प्रियतर होगा भी नहीं।'),
('1a1a0cd6-5eb4-57a3-bfc9-62fa4a1b79df'::uuid, '2c6a75de-f720-5cac-97e5-83d42c9470e8'::uuid, 'tejomayananda', 'hindi', '।।18.69।। न तो उससे बढ़कर मेरा अतिशय प्रिय कार्य करने वाला मनुष्यों में कोई है और न उससे बढ़कर मेरा प्रिय इस पृथ्वी पर दूसरा कोई होगा।।'),
('3ddb7521-a18e-5e18-8b50-a6622cfb5d83'::uuid, '4cb138d6-2512-5845-85da-5256ca34410f'::uuid, 'ramsukhdas', 'hindi', '।।18.70।।जो मनुष्य हम दोनोंके इस धर्ममय संवादका अध्ययन करेगा, उसके द्वारा भी मैं ज्ञानयज्ञसे पूजित होऊँगा -- ऐसा मेरा मत है।'),
('5e0486ae-1ff7-5ff6-b401-fdd3f343d2d0'::uuid, '4cb138d6-2512-5845-85da-5256ca34410f'::uuid, 'tejomayananda', 'hindi', '।।18.70।। जो पुरुष, हम दोनों के इस धर्ममय संवाद का पठन करेगा, उसके द्वारा मैं ज्ञानयज्ञ से पूजित होऊँगा - ऐसा मेरा मत है।।
 '),
('4bd9df97-7c35-558b-a821-1370f7725fd3'::uuid, '78434cc0-151d-5dbf-9d2f-ac34b26bf80e'::uuid, 'ramsukhdas', 'hindi', '।।18.71।।श्रद्धावान् और दोषदृष्टिसे रहित जो मनुष्य इस गीता-ग्रन्थको सुन भी लेगा, वह भी सम्पूर्ण पापोंसे मुक्त होकर पुण्यकारियोंके शुभ लोकोंको प्राप्त हो जायगा।'),
('c157fbb5-c4a8-5431-90b4-05f5c9001129'::uuid, '78434cc0-151d-5dbf-9d2f-ac34b26bf80e'::uuid, 'tejomayananda', 'hindi', '।।18.71।। तथा जो श्रद्धावान् और अनसुयु (दोषदृष्टि रहित) पुरुष इसका श्रवणमात्र भी करेगा, वह भी (पापों से) मुक्त होकर पुण्यकर्मियों के शुभ (श्रेष्ठ) लोकों को प्राप्त कर लेगा।।
 '),
('c25f1c3b-ed08-5a49-ad2b-4f5ac16e1155'::uuid, '7c2f1705-8a5f-534c-a3bd-95ae0f240cde'::uuid, 'ramsukhdas', 'hindi', '।।18.72।।हे पृथानन्दन ! क्या तुमने एकाग्र-चित्तसे इसको सुना ?और हे धनञ्जय ! क्या तुम्हारा अज्ञानसे उत्पन्न मोह नष्ट हुआ ?'),
('6a9d674a-617d-5a7a-a08d-ad8103673a3b'::uuid, '7c2f1705-8a5f-534c-a3bd-95ae0f240cde'::uuid, 'tejomayananda', 'hindi', '।।18.72।। हे पार्थ ! क्या इसे (मेरे उपदेश को) तुमने एकाग्रचित्त होकर श्रवण किया ? और हे धनञ्जय ! क्या तुम्हारा अज्ञान जनित संमोह पूर्णतया नष्ट हुआ ?
 '),
('9f6804ed-fc32-5e86-85d9-168d5acab07d'::uuid, '5cbd4e23-1643-5c6b-8ad3-5a615d962817'::uuid, 'ramsukhdas', 'hindi', '।।18.73।।अर्जुन बोले -- हे अच्युत ! आपकी कृपासे मेरा मोह नष्ट हो गया है और स्मृति प्राप्त हो गयी है। मैं सन्देहरहित होकर स्थित हूँ। अब मैं आपकी आज्ञाका पालन करूँगा।'),
('99ae799a-c1cf-5ac2-bc05-9e34b2ffb4eb'::uuid, '5cbd4e23-1643-5c6b-8ad3-5a615d962817'::uuid, 'tejomayananda', 'hindi', '।।18.73।। अर्जुन ने कहा -- हे अच्युत ! आपके कृपाप्रसाद से मेरा मोह नष्ट हो गया है, और मुझे स्मृति (ज्ञान) प्राप्त हो गयी है? अब मैं संशयरहित हो गया हूँ और मैं आपके वचन (आज्ञा) का पालन करूँगा।।
 '),
('ada1144e-0904-5ffe-9dd3-660be439c316'::uuid, '11f0e294-f1f8-56f2-939e-303e76c52135'::uuid, 'ramsukhdas', 'hindi', '।।18.74।।सञ्जय बोले -- इस प्रकार मैंने भगवान् वासुदेव और महात्मा पृथानन्दन अर्जुनका यह रोमाञ्चित करनेवाला अद्भुत संवाद सुना।'),
('523118b6-ad31-53ba-8967-9fa7bc44e568'::uuid, '11f0e294-f1f8-56f2-939e-303e76c52135'::uuid, 'tejomayananda', 'hindi', '।।18.74।। संजय ने कहा -- इस प्रकार मैंने भगवान् वासुदेव और महात्मा अर्जुन के इस अद्भुत और रोमान्चक संवाद का वर्णन किया।।'),
('3c4b1d85-cd49-5b49-a1fd-41014e11395e'::uuid, 'bd06a7ef-88c5-5695-a6f4-7bc372b3388f'::uuid, 'ramsukhdas', 'hindi', '।।18.75।।व्यासजीकी कृपासे मैंने स्वयं इस परम गोपनीय योग (गीता-ग्रन्थ) को कहते हुए साक्षात् योगेश्वर भगवान् श्रीकृष्णसे सुना है।'),
('1de07d95-93f2-5110-bbef-09c186c0a443'::uuid, 'bd06a7ef-88c5-5695-a6f4-7bc372b3388f'::uuid, 'tejomayananda', 'hindi', '।।18.75।। व्यास जी की कृपा से मैंने इस परम् गुह्य योग को साक्षात् कहते हुए स्वयं योगोश्वर श्रीकृष्ण भगवान् से सुना।।'),
('753d5925-0615-55f3-b06d-f6b8bbf2d9d3'::uuid, '043cccf4-4335-55b2-86d5-52b75086d7b4'::uuid, 'ramsukhdas', 'hindi', '।।18.76।।हे राजन् ! भगवान् श्रीकृष्ण और अर्जुनके इस पवित्र और अद्भुत संवादको याद कर-करके मैं बार-बार हर्षित हो रहा हूँ।'),
('649e97e2-490f-5801-9c75-9c37a2b57d43'::uuid, '043cccf4-4335-55b2-86d5-52b75086d7b4'::uuid, 'tejomayananda', 'hindi', '।।18.76।। हे राजन् ! भगवान् केशव और अर्जुन के इस अद्भुत और पुण्य (पवित्र) संवाद को स्मरण करके मैं बारम्बार हर्षित होता हूँ।।
 '),
('35673536-9182-563e-9175-e45ccfb4c506'::uuid, '0a116bc7-c286-56e5-a807-fa6f4677db42'::uuid, 'ramsukhdas', 'hindi', '।।18.77।।हे राजन् ! भगवान् श्रीकृष्णके उस अत्यन्त अद्भुत विराट्रूपको याद कर-करके मेरेको बड़ा भारी आश्चर्य हो रहा है और मैं बार-बार हर्षित हो रहा हूँ।'),
('e70c59e4-f607-54fe-a2db-1a6a588d0226'::uuid, '0a116bc7-c286-56e5-a807-fa6f4677db42'::uuid, 'tejomayananda', 'hindi', '।।18.77।। हे राजन ! श्री हरि के अति अद्भुत रूप को भी पुन: पुन: स्मरण करके मुझे महान् विस्मय होता है और मैं बारम्बार हर्षित हो रहा हूँ।।
 ')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;

INSERT INTO public.gita_translations (id, verse_id, source_id, language, translation_text) VALUES
('90c34c51-e17d-5cbb-b6b1-1d551b582195'::uuid, 'eeb1dc40-a63a-5262-817b-3c4e81cf483c'::uuid, 'ramsukhdas', 'hindi', '।।18.78।।जहाँ योगेश्वर भगवान् श्रीकृष्ण हैं और जहाँ गाण्डीवधनुषधारी अर्जुन हैं, वहाँ ही श्री, विजय, विभूति और अचल नीति है -- ऐसा मेरा मत है।'),
('f0659004-95d0-5faf-99a1-e1f3ad00dfda'::uuid, 'eeb1dc40-a63a-5262-817b-3c4e81cf483c'::uuid, 'tejomayananda', 'hindi', '।।18.78।। जहाँ योगेश्वर श्रीकृष्ण हैं और जहाँ धनुर्धारी अर्जुन है वहीं पर श्री, विजय, विभूति और ध्रुव नीति है, ऐसा मेरा मत है।।')
ON CONFLICT (verse_id, source_id) DO UPDATE SET translation_text = EXCLUDED.translation_text;
